INSERT INTO `risk_sablonlari` (`user_id`, `ad`, `sektor`, `sektor_adi`, `yontem`, `maddeler`, `paylasildi`, `kullanim_sayisi`, `created_at`, `updated_at`)
SELECT u.`id`, 'Hastane — Birim: HASTANE GENELİ', 'saglik', NULL, 'fine_kinney', '[{\"anahtar\":\"hst-19923\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Kapalı alanlarda sigara içilmesi\",\"risk\":\"1-Yangın çıkması sonucu yaralnma\",\"mevcut_onlem\":\"1- Duman dedektörleri mevcuttur.\\n2- Yangın söndürme sistemleri mevcuttur.\",\"oneri\":\"1- Hastane içinde ve kapalı alanlarda sigara içilmemelidir.                                                                                                             2- Özellikle acil çıkış merdivenlerinde sigara içilmesi yasaklanmalı, acil çıkış kapılarında bulunan manyetik tutucular aktif hale getirilmelidir.                                                                                       2- Duman dedektörleri çalışanlar ya da hastalar tarafından iptal edilmemelidir.                                                                                                                                          3- Kapalı alanda sigara içenlere ve yangın ihbar sistemini iptal edenlere idari yaptırım, disiplin cezaları uygulanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-19924\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Yüksekten düşmeye sebep olabilecek alanlar\",\"risk\":\"1-Sarkma, atlama,  fiziksel şiddet vb. hareketler sonucu yüksekten düşme\",\"mevcut_onlem\":\"1-Korkuluklar mevcuttur ve sağlam yapıdadır.\",\"oneri\":\"1- Çalışanların yüksekten düşme riskine sebep olabilecek açıklıklar TS EN 1263-1  ve TS EN 1263-2 standardına uygun olarak güvenlik filesi vb. sistemler ile kapatılmalıdır.                                                                                    \\n2- Ankraj noktaları,  betonarme kolon, kiriş vb. yük taşıyabilecek sağlam  yapısal elemanlara takılmalı, alçıpan gibi zayıf taşıyıcı sistemlere takılmamalıdır. \\n3-Güvenlik filelerinin halatları yüksek mukavemetli, doğru gerginlikte ve düşüş mesafesine uygun olarak kurulmalıdır.                                     \\n4-Ankraj sistemleri, vida, dübel, kanca ve halkalar yüksek dayanımlı paslanmaz çelik malzemeden olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-19925\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Ortam ölçümlerinin yapılmamış olması\",\"risk\":\"1- İş kazlarında, Meslek hastalıklarında artış\",\"mevcut_onlem\":null,\"oneri\":\"1-Hastanede toz, voc, gürültü, aydınlatma, termal konfor ölçümleri akreditasyonu olan firmalara yaptırılmalıdır.                                 \\n2- Ortam ölçümü yapılırken çalışan maruziyetleri de ölçülmelidir.\\n3-Çıkan sonuçlara göre gereken tedbirler alınmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-19926\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Halojen free özellikte olmayan elektrik kabloların kullanılması\",\"risk\":\"1- Elektrik yangını çıkması sonucu, yaralanma, boğulma, ölüm\",\"mevcut_onlem\":\"1-Hastane tesisatında ki elektrik kabloları halojen free özelliktedir.                                     2- 300 MA yangın yangın röleleri mevcuttur.\",\"oneri\":\"1-Hastane de kullanılan tüm elektrik, uzatma (3\'lü) vb. kablolar halojen free (geç yanan, zehirli gaz çıkarmayan) özellikte olmalıdır.                                                                                                                                                           2- Halojen free olmayan uzatma kablolalarının kulllanımı yasaklanmalı, toplatılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-19927\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Elektrikli mutfak aletleri (çay, kahve, microdalga fırın, airfryer vb.) kullanılması\",\"risk\":\"1- Elektrik yangını çıkması sonucu, yaralanma\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.                                   2-300 MA yangın röleleri mevcuttur.\",\"oneri\":\"1- Hastane de mutfak olarak belirlenmiş alanlar dışında hiçbir yerde elektrikli mutfak aletleri kullanılmamalıdır.                                          \\n2- Mutfak olarak tanımlanmış alanlarda sadece çay ve kahve makinesi kullanılmalı, bunların dışındaki aletlerin kullanımı yasaklanmalıdır.                                                                                                          3- Sadece çift termostatlı çay kahve makineleri makineleri kullanılmalıdır.                                                                                                                         4- Çay kahve makineleri direk fişe takılmalı, uzatma kablolarına takılmamalıdır.                                                                                                                5- Çay kahve makineleri kullanıldıktan sonra fişten çıkarılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-19928\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Elektrik kabloların da aşırı yükleme olması\",\"risk\":\"1- Elektrik yangını çıkması sonucu, yaralanma, boğulma, ölüm\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.                                   2-300 MA yangın röleleri mevcuttur.\",\"oneri\":\"1- 3 lü uzatma kablolarına, 3 lü uzatma kablosu kullanarak kullanılmamalıdır.                                                                                                     2- Yüsek akım çeken cihazlar (kettle çay makinesi vb.) beslemesi ayrı fişlerden yapılmalı, uzatma kabloları kullanılmamalıdır.                                                                                                             3- Çalışanların dışarıdan uzatma kablosu getirmesi yasaklanmalıdır.                                                                                                                                   4- Konu ile ilgili kontrol denetim sağlanmalı ,uygun olmayan cihaz ve kablolar toplatılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-19929\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Çalışan hasta ve hasta yakınları iletişim problemleri, fiziksel sözlü şiddet,\",\"risk\":\"1- Hasta ya da yakınları tarafından fiziksel ya da sözlü şiddete maruz kalma sonucu yaralanma,\",\"mevcut_onlem\":\"1-Bir çok alanda  panik butonları mevcuttur.\",\"oneri\":\"1- Hasta ve hasta yakınları tarafından çalışanların şiddete uğrayabileceği tüm alanlara sabit panik butonları ya da yaka butonları temin edilmelidir.                                                                                        \\n 2- Özellikle şiddet riskinin yoğun olduğu alanlarda ( hasta hakları, psikayatri acil vb.) alanlarda ilave butonlar konulmalıdır.                                                                                                                3- Şiddet riskinin yoğun olduğu alanlarda butonlara ilave olarak sabit güvenlik personeli  bulundurulmalıdır.                   \\n4- Çalışanlara iletişim, stres yönetimi ve öfke kontrolü ile mesleki bilgi ve becerilerini arttırıcı eğitimler verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-19930\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Çalışanların fazla mesai ile çalışması                                                          2- İş yükünün fazla olması\",\"risk\":\"1-Dikkatin azalması, yorgunluk, uykusuzluk, sonucunda iş kazalarının oluşması\",\"mevcut_onlem\":null,\"oneri\":\"1-Fazla mesai süreleri yasal sınırlarla En fazla 130 saat olmalıdır.                                                                                                                                             2- 24 saatlik nöbetten sonra çalışanlara en az 24 saat dinlenme süresi verilmelidir.                               \\n3- Gün aşırı nöbet sayısı azaltılmalıdır.                                                                                                            4-Çalışanların düzenli sağlık kontrolleri yapılmalı ve yeterli dinlenme süreleri sağlanmalıdır.                                                                                                                                                                                                                                                                                                                                                    5- Yorgunluk ve stres yönetimi için psikososyal destek programları sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-19931\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Bina dış cephe karolarının düşmesi, kopması\",\"risk\":\"1-Karoların düşmesi sonucu, yaralanma, ölüm\",\"mevcut_onlem\":null,\"oneri\":\"1-  Dış cephe karolarında çatlak, kabarma ayrılma vb. olup olmadığı, drone, sepetli platform ya da termal kamera ile yılda bir kez kontrol edilmeli, hasarlı, ayrılmış olan karolar değiştirilmelidir.                                                                                                                              2- Dış cephe karolarını tutan tırnak ve vidalar da paslanma olmamalıdır.                                                                                                                                 3- Şiddetli rüzgar ya da deprem sonrası bina karoları kontrol edilmeli, hasarlı olanlar değiştirilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":40,\"frekans\":2},{\"anahtar\":\"hst-19932\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Kurşun önlüklerin, tiroid koruyucuların vb. ekipmanların kırılması, bozulması, yeterli sayıda olmaması\",\"risk\":\"1-Radyasyona maruziyet sonucu meslek hastalıkları oluşması\",\"mevcut_onlem\":\"1- Özel askı aparatları mevcuttur.\",\"oneri\":\"1- Çalışanların radyasyona maruz kaldıkları bölümlerde, her bölüm için maruz kalabilecek tüm çalışanlara yetecek kadar kurşun önlük tiroid koruyucu vb. ekipmanlar temin edilmelidir.   \\n2- Kurşun önlükler ve diğer koruyucular kullanıldıktan sonra özel askılıklara asılmalı, kırılması önlenmelidir.                                                                                                                  3- Kırılan, bozulan kurşun önlük vb. ekipmanlar yerine yenileri temin edilmelidir.                                                                                                                                                                     4- Kurşun önlükler ve diğer koruyucular kullanıldıktan sonra dezenfekte edilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-19933\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Taşınabilir röntgen cihazlarının kullanımı sonucu X ışınlarına maruziyet\",\"risk\":\"1-Meslek hastalıkları, mesleki kanserler oluşması\",\"mevcut_onlem\":\"1- Kurşun önlükler mevcuttur.\",\"oneri\":\"1- Taşınabilir röntgen cihazı ile yapılan çekimler de kurşun paravan kullanılmalıdır.                                                                                                                                                               2- Çekim yapılan alanda hasta ve çekim yapan çalışan dışında kimse olmamalı, zorunlu hallerde bulunulması gerekirse(TS EN 61331 standardında kurşun önlük troid koruyucu vb.kişisel koruyucu ekipmanlar kullanılmalıdır.                                                                                                       3- Çekim yapılan odaların kapıları kapatılmalıdır.                                                                                           4- Açık alanlarda yapılan çekimlerde çalışanlar en az 2 metre uzakta durmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-19934\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Defibilatörün emniyetsiz kullanımı\",\"risk\":\"1-Defibrilatör kullanımı sırasında elektrik çarpması, elektrik yanıkları oluşması\",\"mevcut_onlem\":null,\"oneri\":\"1-Defibrilasyon esnasında hastaya elektrotlara ve diğer iletken nesnelere dokunulmamalıdır.\\n2-Hastaya ıslak  ve iletken ortamlarda defibrilasyon uygulanmamalı, hastanın göğsünde ıslaklık, jel, ter olmamalı, hastanın göğüsü kurulanmalıdır.\\n3-Defibrilatör cihazı oksijen tüpü, alkol vb. yanıcı sıvı ve gazların bulunduğu ortamlarda kullanılmamalıdır.                       \\n4- Hastanın ve defibilatörü kullanan çalışanın üzerinde metal eşyalar bulunmamalıdır.                                                                                           \\n5- Ortamda bulunan diğer çalışanlar en az 1 metre uzakta bulunmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-19935\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Acil çıkış yollarının, kapılarının malzemeler ile kapatılması\",\"risk\":\"1-Acil durumlarda hızlı tahliyenin sağlanamaması sonucunda durumun etkisinin ve şiddetinin artması\",\"mevcut_onlem\":\"1- Acil çıkış yönlendirmeleri mevcuttur.\",\"oneri\":\"1-Acil çıkış kapıları ve acil çıkış yolları açıkça görülebilir olmalı ve acil çıkış kapılarnın ve yollarının önüne ve üzerine saksı, malzeme vb. konulmamalıdır.  \\n2- Acil çıkış yönlendirmelerinin önleri kapatılmamalı, kaçış yolu üzerinde bütün erişim noktalarından görülebilir olmalı, yönlendirmeler 200-240 cm yüksekliğe asılı olmalıdır.                                                                         \\n3- Acil çıkış yollarında en az 150 cm genişliğinde mesafe olması sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-19936\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Oksijen tüplerinin ve diğer basınçlı tüplerin paslı ve korozyonlu olması\",\"risk\":\"1- Tüplerinin yapısal bütünlüğünün bozulması sonucu gaz kaçağı, patlama meydana gelmesi\",\"mevcut_onlem\":\"1- Birçok alanda tüp sabitleme aparatları bulunmaktadır.\",\"oneri\":\"1- Paslı ve korozyonlu tüpler kullanım dışı bırakılmalıdır.                     \\n2- Bu tüplerin tedarikçi firma tarafından hidrostatik test ve ultrasonik kalnlık ölçümleri yapılmalıdır.                                                                            \\n3- Gaz sızıntısı durumunda hiçbir onarım yapmadan tüp açık bir alana çıkarılarak tedarikçi firmaya haber verilmelidir.                                                                                                             4- Basınçlı tüpler elektrik ısı kıvılcım kaynaklarından en az 3 metre uzakta bulundurulmalı, en az iki noktadan dik konumda sabitlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-19937\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Oksijen ve basınçlı tüplerin uygunsuz taşınması\",\"risk\":\"1- Tüplerin düşmesi, devrilmesi sonucu patlama meydana gelmesi\",\"mevcut_onlem\":\"1- Sabitleme aparatı bulunmaktadır.\",\"oneri\":\"1- Hasta yatakları, taşıma araçları vb. basınçlı tüp taşınan ekipmanlarda tüpleri sabitlemek için aparatlar bulunmalı, tüpler en az iki noktadan sabitlenerek taşınmalıdır.                                                                                                                         2- Tüplerin taşınması esnasında vanaları kapalı olmalı, dik taşınmalı, kapağı kapalı olmalıdır.                                                                                 \\n3- Taşıma esnasında tüplerin başka cisimlere çarpması engellenmelidir.  \\n4- Hastaneye kendi oksijen tüpü ile gelen hastalar için sedye ve tekerlekli sandalye için sabitleme aparatı verilmeldir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-19938\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Özel politika grupları uygulamalarının yetersiz olması\",\"risk\":\"1-İş kazası ve meslek hastalıklarının artması\",\"mevcut_onlem\":\"1- Refakatçiler belirlenmiştir.\",\"oneri\":\"1- Acil durumlarda özel politika gruplarına tahliye esnasında refakat edilmesi için refakatçiler belirlenmeli, refakatçi listesi sürekli güncel tutulmalıdır.\\n2-Engelliler sadece sağlık raporunda belirtilen ve engel durumuna uygun işlerde  çalıştırılmalıdır.  \\n3-Özel politika gruplarına kendi istekleri dışında fazla mesai yaptırılmamalı, gece vardiyalarında çalıştırılmamalıdır.\\n4-Bu gruplar uzun süre ayakta çalıştırılmamalı, ağır yük taşıtılmamalıdır.                                                                                                                                     5-Özel politika gruplarına özel olarak eğitim verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-19939\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Makinelerin gövde topraklama ölçümlerinin yapılmamaış olması.                                              2-Yıpranmış, ezilmiş kablolar\",\"risk\":\"1-Elektrik çarpması sonucu kalp ritim bozuklukları, elektrik yanıkları, ölüm,\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.\",\"oneri\":\"1-Makinelerin gövde topraklama ölçümleri yaptırılmalı, belgelendirilmelidir.\\n2-Cihazlar durdurulmadan ve akım kesilmeden bakım, arıza onarım ve müdahaleler yapılmamalıdır.\\n3-Yıpranmış, ezilmiş, soyulmuş ve izolasyonsuz kablolar değiştirilmelidir.                                                                                                                           4- Makikenelerin elektrik kabloları çift izolasyonlu olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-19940\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-KKD’lerin eksik olması,                           2- KKD\'lerin çalışanlar tarafından kullanılmaması\",\"risk\":\"1-KKD’lerin kullanılmaması sonucunda iş kazaları, meslek hastalıkları oluması\",\"mevcut_onlem\":\"1-KKD\'ler çalışanlara zimmetlenmektedir.\",\"oneri\":\"1-KKD’ler CE belgeli ve ilgili standartlara uygun olmalı, eksik olan kkd\'ler temin edilmelidir.\\n2- Çalışanların maskeleri TS EN149 A1 standardında uygun olmalıdır.                                                                                                                     3-Çalışanların göz koruyucuları TS EN 166 standardına uygun ve tam kapalı tip olmalıdır.                                                                                                                             4-Çalışanların iş eldivenleri kimyasallara karşı TS EN 374 standartı, kesilmelere dayanıklı TS EN 388 standartı, radyoaktif maddelere karşı TS EN 421 standartı elektrik tehlikelerine karşı TSE EN 60903 standartına uygun olmalıdır.                                                                                                                                5- Çalışanların iş tulumları kimyasal maddelere karşı TS EN 14126 standartına, radyoaktif maddelere karşı  TS EN 1073-2 standartına uygun olmalıdır.\\n6-Çalışanların iş ayakkabıları, koruyucu burun ve taban TS EN 12568 standardına ve kaymayı önleyici TS EN 13287 standartı, kimyasallara ve radyokaktif maddelere karşı EN ISO 20347, elektrik tehlikelerine karşı TS EN 50321 standartına uygun olmalıdır.\\n7-Çalışanlar sahada kişisel koruyucu ekipmanlarını eksiksiz şekilde kullanmalıdırlar.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-19941\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Elektrik kablolarında yırtık, izolasyon bozukluğu olması,                                                                                   2- Ekli kabloların kullanılması\",\"risk\":\"1-Elektrik çarpması sonucu kalp ritim bozuklukları, ölüm\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.\",\"oneri\":\"1- Elektrik kablolarında yırtık, izolasyon bozlukluğu vb. olmamalı, olan kablolar kullanılmamalı değiştirilmelidir.                          \\n2- Elektrik kabloları ağır malzeme ya da ekipmanların altına konulmamalı, kabloların ezilmesi önlenmelidir.                                            \\n3- Kablolarda olan izolasyon açıklıkları izole bant ile kapatılmamalı, ekli kablolar değiştirilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-19942\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Taşınabilir elektrikli aletlerin PAT testlerinin yapılmaması\",\"risk\":\"1-Elektrik çarpması sonucu kalp ritim bozuklukları, ölüm\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.\",\"oneri\":\"1- Taşınabilir elektrikli cihazların (çay kahve makineleri, bilgisyar, yazıcı, monitörler, fotokopi makineleri vb. aletlerin)en az yılda bir kez topraklama direnci, izolasyon seviyesi ve kaçak akım gibi temel elektriksel değerlerini ölçülmesini sağlayan PAT testleri yapılmalıdır.                                                                                                                               2- PAT testinden geçen cihazlar etiketlenmeli, diğerlerinin kullanımı eksiklikler tamamlanana kadar  önlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-19943\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Oksijen ya da basınçlı tüplerin uygunsuz kullanılması\",\"risk\":\"1-Fiziksel olarak patlaması sonucu vücut bölümlerinin yaralanması\",\"mevcut_onlem\":null,\"oneri\":\"1- Oksijen tüplerine yağlı, kremli eller ile temas edilmemeli, vanaları yağlanmamalıdır.                                                                                                                                   2- Tüpler ısı kaynaklarından ve güneşin etkisinden uzak tutulmalıdır.                                                                                                                                    3- Manometreler sağlam olmalı, kırık olanlar değiştirilmelidir.                                       \\n4- Basınçlı tüpler zeminde sabitlenmeden bırakılmamalı, sabitleme aparatlarına takılmalı ve 2 noktadan zincir ya da halatla bağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-19944\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Elektrik kablolarının, priz vb. elektrik sistemlerinin su ya da sıvı maddeler ile temas etmesi\",\"risk\":\"1-Elektrik çarpması sonucu kalp ritim bozuklukları, ölüm\",\"mevcut_onlem\":\"1-30 MA kaçak akım rölesi mevcuttur.\",\"oneri\":\"1-Su ya da sıvı maddeler bulunduran cihazların bağlantı yerlerinde ve hortumlarında hiç bir sızıntı olmamalıdır.                                                                                2- Cihazların elektrik kablolarında izole bant ile bantlanmış ekler olmamalıdır.                                                                                                                          3- Elektrik kabloları çift izolasyonlu olmalıdır.                                                                                                                4- Su ya da sıvı sızdırabilecek cihazlar fiş priz vb. elektrik sistemlerinden uzakta tutulmalı, suyun elektrik ile temas etmesi önlenmelidir.                                                                                                               5- Cihazların bakım ve kalibrasyonları  yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-19945\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Hastalardan inhalasyon yoluyla hastalık bulaşması\",\"risk\":\"1-Enfeksiyon, bulaşıcı hastalıklara yakalanma\",\"mevcut_onlem\":\"1-KKD\'ler mevcuttur.                                         2- Çalışanlara KKD önemi ve kullanımı konusunda eğitim verilmektedir.\",\"oneri\":\"1-Bulaşıcı hastalık şüphesi olan hastalar, sonuçları çıkana kadar tek kişilik izolasyon odalarında tutulmalıdır.                                                                                           2- Şüpheli hastaların bulunduğu alanın teması bittikten sonra hemen dezenfekte edilmelidir.                                                                                                                          3- Bulaşıcı hastalıkların yayılma ihtimali yüksek olan bölümlerde (acil servis, poliklinik, görüntüleme vb.) hepa filtreler kullanılmalıdır.                                                                                                                                              4-Tanı konulmuş hastalar negatif basınçlı odalara alınarak izole edilmelidir.                                                                                                                        5-Çalışanlar N95 ya da TS EN 149 standrtdında FFP2 filtreli maske, yüz siperi, TS EN 455  standardında eldiven kullanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-19946\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Tehlikeli kimyasalların yanlış depolanması\",\"risk\":\"1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması                                 2- Yangın meydana gelmesi\",\"mevcut_onlem\":\"1- Kimyasallar depo alanında depolanmaktadır.\",\"oneri\":\"1- Kimyasal maddeler depolama matirsine göre depolanmalıdır.                                                        \\n2- Yanıcı kimyasallar elektrik kaynaklarından uzak depolanmalıdır.                                                                               3- Kimyasal maddelerin ağzı açık olmamalı, dik olarak istiflenmelidir.\\n 4- Ağzı açılmış kimyasal madde kaplarının altına taşma kapları konulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-19947\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Kimyasal madde deposunda göz duşu ve döküntü kiti bulunmaması                                               2- Çalışanların kimyasallar hakkında bilgi sahibi olmaması\",\"risk\":\"1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması\",\"mevcut_onlem\":\"1- Kimyasallar depo alanında depolanmaktadır.\",\"oneri\":\"1- Kimyasalların dökülme riskine karşı döküntü kitleri bulundurulmalıdır.                                         \\n2- Göze kaçma riskine karşı göz duşu solüsyonu bulundurulmalıdır.  \\n3- Kimyasal maddelere gözlük, eldiven olmadan temas edilmemelidir.                                                               \\n4-Kimyasal maddelerin malzeme güvenlik bilgi formları depoda asılı olmalıdır.                              \\n5- Çalışanlara MSDS ve kimyasalların güvenli kullanımı konusunda eğitimler verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-19948\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Yangın algılama ihbar ve söndürme sistemlerinin periyodik kontrollerinin tekrarlanmaması\",\"risk\":\"1- Yangına müdahale edilememesi sonucu şiddetin artması\",\"mevcut_onlem\":\"1- Periyodik kontroller mevcuttur.\",\"oneri\":\"1-Yangın söndürme tüplerinin, sprinklerin, yangın hortumlarının, yangın alarmlarının, duman algılama dedektörlerinin, yangın panellerinin, yangın pompalarının vb. yangın söndürme ile ilgili tüm tesisatların periyodik kontrolleri, risk değerlendirmesinin yangın söndürme sistemleri bölümünde belirtilen standartlara ve sürelere göre periyodik kontrolleri tekrarlanmaldır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-19949\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Hastane camlarının açılması\",\"risk\":\"1-Düşme ya da intihar sonucu yaralanma, ölüm\",\"mevcut_onlem\":\"1-Camların bir çoğu tam açılmamaktadır.\",\"oneri\":\"1- Hastane de tüm camlar kontrol edilmeli, tam açılabilen camlar en fazla açıklık 15 cm açılacak şekilde ayarlanmalı ve sabitlenmelidir.                                                                                                  2- Pencere kilitleri sadece yetkili bölüm sorumlularında bulunmalı, sadece acil ihtiyaç halinde açılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":40,\"frekans\":3},{\"anahtar\":\"hst-19950\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Özel izin gerektiren işlerin belirlenmemiş olması\",\"risk\":\"1-Emniyetsiz çalışma sonucunda iş kazaları yaşanması\\n2- Parlama, patlama, yangın çıkması\",\"mevcut_onlem\":null,\"oneri\":\"1-Yüksekte çalışma, genel bakımlar, trafo işleri, çatı işleri, büyük kaynak işleri, taşıma işleri, kapalı alanlarda çalışma gibi işler özel izinle yapılmalıdır.\\n2-İzin veren birim bütün tedbirlerin alındığından emin olmalı, sürekli kontrol ve denetim sağlanmalıdır.\\n3-Tüm tedbirler alınıp izin formu imzalandıktan sonra çalışmaya başlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":40,\"frekans\":3},{\"anahtar\":\"hst-19951\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Taşeron firma ve çalışanların iş güvenliği kurallarına uymaması, güvenlik tedbirlerini almaması\",\"risk\":\"1-Emniyetsiz çalışma sonucunda iş kazaları, vücut bölümlerinin yaralanması, ezilmesi, uzuv kayıpları ve ölüm                        2 -Yangın çıkması\",\"mevcut_onlem\":null,\"oneri\":\"1-Taşeron firmadan gelen çalışanlardan ağır ve tehlikeli işlerde çalışabilir sağlık raporu temin edilmeli, sağlık durumu uygun olmayan çalışanlar çalıştırılmamalıdır.\\n1-Taşeron çalışanların 16 saatlik güncel iş güvenliği eğitim sertifikaları temin edilmelidir.\\n2-Taşeron firma çalışanlarından yaptıkları işe uygun mesleki eğitim belgeleri temin edilmeli, mesleki eğitim belgesi olmayan kişiler çalıştırılmamalıdır.\\n3-Taşeron firma çalışanlarının yaptıkları işe uygun kkd’leri eksiksiz olmalı, kkd zimmet belgeleri temin edilmelidir.\\n4-Taşeron firma çalışanlarına ilk girişlerde hastane ile ilgili oryantasyon eğitimi verilmelidir.\\n5-Taşeron firma ve çalışanlar hastane içinde kendi iş güvenliği önlemlerini almalı, ayrıca işyeri içindeki iş güvenliği kurallarına uymalı, diğer çalışanların güvenliklerini tehlikeye düşürecek durum ve davranışlarda bulunmamalıdırlar.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":40,\"frekans\":3},{\"anahtar\":\"hst-19952\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- İş kazası olması\",\"risk\":\"1-Vücut bölümlerinin yaralanması, uzuv kayıpları, ölüm\",\"mevcut_onlem\":\"1- Çalışanlara ilk işe girişte temel isg eğitimlerinde iş kazası yaşamaları durumunda yapılacaklar ile ilgili eğitim verilmektedir.\",\"oneri\":\"1-Risk değerlendirmesinde ve tespit öneri defterinde yazan hususlar eksiksiz yerine getirilmelidir.\\n2-Çalışanlar geçirdikleri iş kazalarını en geç 3 iş günü içerisinde İSG birimine bildirmeli ve SGK bildirimi yapılmalıdır.                                       \\n3-İş kazası sonrası çalışanlara kaza sonrası iş güvenliği eğitimi verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-19953\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Stajer öğrencilerin tek başına iş ve işlem yapması\",\"risk\":\"1-İş kazası sonucu ele iğne batması, yaralanma\",\"mevcut_onlem\":\"1-Stajer öğrencilere iş güvenliği eğitimi verilmektedir.\",\"oneri\":\"1- Lise stajeri öğrencilerine invaziv (iğne, kan alma vb.)işlemler kesinlikle yaptırılmamalıdır.                                                                   \\n2- Üniversite öğrencilerine yaptırılan invaziv işlemler mutlaka bir gözlemci çalışan eşliğinde yaptırılmalıdır.                                                          \\n3- Stajer öğrenciler yetkisiz hiç bir iş ve işlem yapmamalı, cihaz ve makineleri kullanmamalıdır.\\n4- Stajer öğrenciler, hastanede çalışırken gözlük ya da yüz siperi, maske, eldiven, kaymaz tabanlı ayakkabı kullanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-19954\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Panik butonlarının çalışmaması, yaka butonlarının pilinin bitmesi\",\"risk\":\"1- Beyaz kod durumunda güvenlik görevlilerine ulaşılamaması sonucu durumun kötüleşmesi\",\"mevcut_onlem\":\"1-Bir çok alanda  panik butonları mevcuttur.\",\"oneri\":\"1- Panik butonları her zaman çalışır durumda olmalıdır.                    \\n2- Panik butonlarının haftalık fonksiyon testleri yapılmalı, yılda en az bir kez periyodik kontrol yapılmalıdır.                                       \\n3- Panik butonlarında arıza olması halinde en fazla 2 saat içinde arıza giderilmeli, giderilemiyorsa, çalışanlara yaka butonları verilmelidir.                                                                                                                                 4- Yaka butonları kontrol edilmeli pilleri bitmeden değiştirilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-19955\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Kesici delici aletlerin emniyetsiz kullanılması\",\"risk\":\"1- Kullanılmış aletlere temas sonucu el kol yaralanmaları, enfeksiyon, bulaşıcı hastalıklara yakalanma\",\"mevcut_onlem\":\"1- Kesici delici alet kutuları mevcttur.                2-Çalışanlara kesici delici aletlerin güvenli kullanımı konusunda eğitim verilmektedir.\",\"oneri\":\"1- Kullanılmış iğne ve kesici aletler, kesici delici alet kutusuna atılmalıdır.                                                                                                                           2- Çalışanlar tedavi tepsisi kullanmalı, iğne kapağı kapatılmadan kesici delici alet kutusuna atılmalıdır.                                                                                                                                 3- Kesici delici alet kutuları en fazla 2/3 dolduğunda yenisi ile değiştirilmeli, kutuların kapakları açık bırakılmamalıdır.                                                                                                                   4-  Kesici delici alet kutuları devrilmeyecek şekilde konumlandırılmalıdır.                                                                                                                                5- Çalışanlar TS EN 455 standardında çift eldiven kullanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-19956\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Kan ve vücut sıvılarının göz ve cilde temas etmesi\",\"risk\":\"1-Temas sonucu enfeksiyon, bulaşıcı hastalıklara yakalanma\",\"mevcut_onlem\":\"1-KKD\'ler mevcuttur.                                         2- Çalışanlara KKD önemi ve kullanımı konusunda eğitim verilmektedir.\",\"oneri\":\"1-Çalışanlar TS EN 455  standardında eldiven, TS EN 166 standardında tam kapalı gözlük ya da yüz siperi, uzun kollu koruyucu önlük  EN 14683 standardında maske vb. gibi kişisel koruyucu donanımlar kullanılmalıdır.                                                                                                                         2- Temas durumunda bölgenin bol su ve sabunla yıkanması sağlanmalıdır.                                                                                                                                    3- Kan ve vücut sıvıları sıçramasına maruz kalma sonrası çalışanın, bulaş kaynağının durumuna göre muayene ve tetkikleri yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-19957\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Steril olmayan, kontamine olmuş aletlerin açıkta bırakılması\",\"risk\":\"1-Steril olmayan aletlere temas sonucu iş kazaları enfeksiyon, bulaşıcı hastalık\",\"mevcut_onlem\":\"1-KKD\'ler mevcuttur.                                         2- Atık kutuları mevcuttur.\",\"oneri\":\"1-Kullanılan, kontamine olmuş aletler bekletilmeden hemen kapaklı ve renk kodlu atık kutularına atılmalıdır.                                                                                                                           2- Sterilazyona gidecek aletlere TS EN 388 standardında kesilme ve delinmeye dayanıklı eldiven olmadan temas edilmemeli, çelik, kapaklı kutulara konulmalıdır.                                                                                                                                                        3- Tek kullanımlık olmayan aletler her kullanımdan sonra dezenfekte edilmelidir. \\n 4- Kontamine olmuş aletler, çarşaf, yatak, yorgan vb. yere saplanmamalı, yere atılmamalıdır.                                                                                                                                                          5- Temas edilmesi durumunda, bölge bol su ve sabunla yıkanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-19958\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Makine ve cihazların kullanım talimatlarının bulunmaması\",\"risk\":\"1- İş kazları meydana gelmesi\",\"mevcut_onlem\":null,\"oneri\":\"1- Hastane de kullanılan tüm makine ve cihazların güvenli kullanım talimatları hazırlanmaldır.\\n2- Kullanım talimatları makine ve cihazlar ile birlikte bulundurulmalıdır.\\n3- Kullanım talimatlarında üreticinin tavsiyelerine uyulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-19959\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Atık varillerin kapaklarının açık bırakılması\",\"risk\":\"1-Zehirlenme, toksik maddelere maruz kalma\",\"mevcut_onlem\":\"1-Renk kodlarına göre atık varilleri mevcuttur.\",\"oneri\":\"1- Atık varillerinin kapağı sürekli olarak kapalı halde tutulmalıdır,                                                                  2- Atıklar karıştırılmamalı, her atık türü için (Tıbbi, Tehlikeli, Evsel)belirlenmiş renk kodlu atık kutularına atılmalıdır.                                                                                                                                                    3- Kesici delici aletler sadece kesici delici alet kutusuna atılmalıdır.                                                                                                                           4- Atık varilleri en fazla 3/4 oranında dolduğunda değiştirilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-19960\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Lateks eldivenlerinin kullanılması\",\"risk\":\"1- Ciltte alerji meydana gelmesi\",\"mevcut_onlem\":null,\"oneri\":\"1- Pudralı eldivenler kullanılmamalı, pudrasız eldivenler temin edilmelidir.\\n2- Daha az alerjik reaksiyona sebep olan eldivenler tercih edilmelidir.\\n3- Koruyucu el kremleri kullanılmalıdır.\\n4- Eldiven kullanımından sonra eller bol su ve sabun ile yıkanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-19961\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Elektrik tesisatının, topraklamaların, kaçak akım rölelerinin, yangın rölelerinin periyodik kontrollerinin tekrarlanmaması\",\"risk\":\"1- Elektrik çarpması sonucu yaralanma\\n2- Elektrik yangınları  meydana gelmesi\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.\",\"oneri\":\"1- Elektrik tesisatının, topraklamaların, kaçak akım rölelerinin, yangın rölelerinin periyodik kontrolleri TS EN 60079 serisi, TS HD 60364-4 serisi, TS HD 60364-5 Serisi, TS HD 60364-6 standartlarına uygun olarak en geç yılda bir kez tekrarlanmalıdır.\\n2- Her elektrik panosu için ayrı test ve ölçüm yaptırılmalıdır.\\n3- Tüm bakım ve kontroller kayıt altına alınmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-19962\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Periyodik sağlık kontrollerinin ve sağlık taramalarının yılda bir tekrarlanmaması\",\"risk\":\"1-Meslek hastalığının gerçekleşmesi erken tanı konulamaması müdahaleye geç kalınması\",\"mevcut_onlem\":\"1- Periyodik muayeneler yapılmaktadır.\",\"oneri\":\"1- Çalışanların, akciğer grafileri, göz muayeneleri, solunum fonksiyon testleri ekg, odyometri ölçümleri, kan ve idrar tahlilleri, ppd testleri  ve işyeri hekiminin talep edeceği diğer tıbbi tetkikler yılda bir kez yapılmalıdır.                                                                                                                                               2- İşe yeni başlayan çalışanlara gerekli tahliller yaptırılmadan işbaşı verilmemelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-19963\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Etiketleme kilitleme sisteminin uygulanmaması\",\"risk\":\"1- Elektrik çarpması sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- İşyerinde elektrik ile yapılacak çalışma ya da tamir bakım işleri için etiketleme kilitleme sistemi kurulmalıdır.\\n2- Çalışma sırasında yetkili kişiler tarafından ekipmanın çalışmasını önleyecek şekilde kilitlenmeli ve pano üzerine çalışma yapıldığına dair etiket asılmalıdır.\\n3- Kilitleme işleminden sonra enerjinin kesildiği kontrol edilmeden çalışma yapılmamalıdır.\\n4- Diğer çalışanlar etiketleme kilitleme yapılacağı konusunda uyarılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-19964\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Basınçlı kapların periyodik kontrollerinin tekrarlanmaması\",\"risk\":\"1- Basınçlı kapların patlaması sonucu yaralanma\",\"mevcut_onlem\":\"1- Basınçlı kapların periyodik kontrol raporları mevcuttur.\",\"oneri\":\"1- Basınçlı hava ve gaz tanklarının periyodik kontrolleri TS 1203 EN 286-1, TS EN 13445-5, TS EN 764-7 standartlarında, Buhar ve sıcak su kazanlarının periyodik kontrolleri TS EN 12952 serisi, TS EN 12953 ve TS 497 standartlarında, Boyler ve akümülasyon tankları periyodik kontrolleri TS 736, TS EN 12897+A1 standartlarında, Oksijen tanklarının periyodik kontrolleri TS EN 13445-5, TS 1446, TS EN 12817 ve TS EN standartlarında en geç yılda bir kez tekrarlanmalıdır.\\n2-  Basınçlı kapların basınç testleri belirlenmiş ise işletme basıncı ile belirlenmemiş ise en yüksek çalışma basınç değerinin 1,5 katı ile hidrostatik test yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-19965\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Narkotik İlaç dolaplarının açık olması, kilitlerinin üzerinde bırakılması\",\"risk\":\"1-Narkotik ilaç kullanımına bağlı zehirlenme, bağımlılık oluşması, ölüm\",\"mevcut_onlem\":\"1-Narkotik ilaç dolaplarının anahtarları mevcuttur.\",\"oneri\":\"1- Narkotik ilaç dolapları her zaman kilitli olmalıdır.                                    \\n2- Narkotik ilaç dolaplarının üzerinde anahtar bırakılmamalı, anahtarlar bölüm sorumlularına zimmetlenmelidir.                                                                                                                            3- Bölümlere gelen narkotik ilaçlar kayıt altına alınmalı, her vardiya değişiminde sayım yapılmalı, eksik çıkması durumunda yetkililere haber verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":40,\"frekans\":2},{\"anahtar\":\"hst-19966\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Çalışanların temel iş güvenliği eğitimlerine katılmamaları\",\"risk\":\"1-İş kazası ve meslek hastalıklarının artması\",\"mevcut_onlem\":\"1- Eğitim planı ve eğitim tarihleri çalışanlar ile paylaşılmıştır.\",\"oneri\":\"1-İşe yeni başlayan çalışanlara hastane tehlike sınıfına göre 16 saat temel iş sağlığı güvenliği eğitimi verilmelidir.\\n2-Mevcut çalışanların eğitimleri yılda bir kez tekrarlanmalıdır.\\n3-İş güvenliği eğitimi aldırılmayan kişilere iş başı verilmemelidir.\\n4-İşe yeni başlayan çalışanlara bölüm sorumluları tarafından en az 2 saat iş başı eğitimi verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-19967\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Pendatlarda gaz kaçağı(oksijen, azot, azotprotoksit, karbondioksit) olması\",\"risk\":\"1-Baş dönmesi, sersemlik, uyku hali bulantı, konsatrasyon bozukluğu oluşması\",\"mevcut_onlem\":null,\"oneri\":\"1- Çalışanlar pendant sistemi üzerinde gaz kaçağı (tıslama hava çıkış sesi vb.) tespit edilmesi durumunda hemen yetkililere haber vermeli, terminal çıkışı kapatılmalıdır.                                                                                         \\n2- Kaçak olan pendant da tüm gazlar kesilmelidir.  \\n3- Gaz kaçağı olan alanda elektrikli hiç bir alet kullanılmamalı, ateş kıvılcım kaynağı bulundurulmamalıdır.                                                                       \\n4-Gaz kaçak kaynağı (conta, hasarlı hortum, bağlantı eleamanlarında gevşeme ) tespit edilmelidir.                                                        \\n5- Arıza giderildikten sonra sızdırmazlık testi yapılmadan pendant aktif hale getirilmememlidir.                                                                                            \\n6- Pendatların en az yılda bir kez mekanik, sızdırmazlık ve basınç testleri yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-19968\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-EKG cihazının kablo ve elektrotlarda izolasyon açıklıkları olması                                            2- Şarj işlemi sonrası kabloların fişe takılı bırakılması\",\"risk\":\"1-Ekg kullanımı sırasında elektrik çarpması, elektrik yanıkları oluşması\",\"mevcut_onlem\":null,\"oneri\":\"1-EKG cihazı kullanılmadan önce kablolar, elektrotlar ve cihaz gövdesi kontrol edilmelidir.                \\n2- EKG kullanılacak alanda yanıcı sıvı gaz ve ıslak yüzeyler bulunmamalıdır.                                                                                                                                             3- Her işlemden sonra cihaz ve elektrotlar yanıcı olmayan malzemeler ile dezenfekte edilmelidir. Tek kullanımlık elektrotlar tıbbi atık kutusuna atılmalıdır.                                                                                        \\n4- EKG cihazı ya da kablosu şarj edildikten sonra fişe takılı bırakılmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-19969\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Elektrik panolarının, pano odalarının yangın dolaplarının önlerinin kapatılmış olması\",\"risk\":\"1-Acil durumlarda hızlı müdahalenin sağlanamaması sonucunda durumun etkisinin ve şiddetinin artması\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.\",\"oneri\":\"1- Malzeme, makine, temizlik arabası vb. pano ve  yangın dolaplarının önlerini kapatmaması sağlanmalıdır.\\n2-Panolara erişim için en az 80 cm genişlikte ulaşım yolları sağlanmalıdır.\\n3-Pano üzerlerine uyarı etiket ve işaretleri asılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-19970\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Aydınlatma yetersizliği, bozulması, titremesi\",\"risk\":\"1- Görme bozukluklarının oluşması ve ilerlemesi, ş kazalarında artış\",\"mevcut_onlem\":\"1- Suni aydınlatma sistemleri yeterli sayıdadır.\",\"oneri\":\"1-Özellikle gece çalışmalarında olmak üzere, suni ışık ihtiyacında çalışma alanı ve diğer eklentiler, yollar en az 300 lüks şiddetinde aydınlatılmalıdır.                                                                                                                      2-Aydınlatma sistemleri sağlam yapıda olmalı, bozulan, yanmayan titreyen aydınlatmalar değiştirilmelidir.\\n3-Periyodik göz muayeneleri yılda bir kez yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-19971\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Elle taşıma işlerinin yük kaldırma prensiplerine uygun yapılmaması\",\"risk\":\"1-Kas iskelet sistemi hastalıkları oluşması,                                    2-Malzeme düşmesi, devrilmesi sonucu yaralanma\",\"mevcut_onlem\":\"1- Çalışanlara elle taşıma işleri hakkında eğitim verilmektedir.\",\"oneri\":\"1-Erkek çalışanlar için 25 kg’dan, kadın çalışanlar için 15 kg\'dan ağır yükler mümkün olan hallerde bir taşıma aracıyla ya da birden fazla kişi ile  taşınmalıdır.\\n2- Dengesiz devrilme riski olan yükler sabitlenerek taşınmalıdır.\\n3-Yükler taşıma teknikleri kullanılarak taşınmalıdır.\\n4-Yükler görüş alanını kapatmayacak şekilde taşınmalıdır.\\n5-Kaldırma, indirme ve yerleştirme esnasında el, ayak ve vücut bölümlerinin sıkışmayacağı şekilde ara destekler, ya da teknikler kullanılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-19972\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Buat kapaklarının açık olması, kapakların kırık olması\",\"risk\":\"1-Elektrik çarpması sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Buat kapakları kapalı tutulmalıdır.                                                                         2- Kırık buat kapakları değiştirilmeli, vidalar ile tutturulmamalıdır.                                                                                                  3- Buatlara L tipi fişler kullanılmalı,  buatların açık kalması önlenmelidir.                                                                                                                             4- Buatların üzerinde ki masalarda bir şey yenilip içilmemelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":3},{\"anahtar\":\"hst-19973\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Pendatların üzerine sıvı malzemeler konulması\",\"risk\":\"1- Elektriğin su ile teması sonucu çarpılma, yangın çıkması\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.\",\"oneri\":\"1-Pendatlar üzerine sıvı malzemeler bırakılmamalıdır.                                                    2- Pendant üzerine sıvı dökülmesi halinde kağıt havlu ile hemen silinmeli, priz veya valflere sıvı girmesi önlenmelidir.                                                                                                                          3- Prizlere sıvı kaçması durumunda hemen yetkililere haber verilmeli, pendant kullanılmamalı, gerekirse elektrik akımı kesilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":3},{\"anahtar\":\"hst-19974\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Transformatör, jeneratör, akümülatörlerin periyodik kontrollerinin tekrarlanmaması\",\"risk\":\"1- Fiziksel patlama meydana gelmesi sonucu iş kazaları yaşanması\",\"mevcut_onlem\":\"1- Periyodik kontrol raporları mevcuttur.\",\"oneri\":\"1- Jeneratörlerin periyodik kontrolleri TS ISO 8528 standartında, Transformatörlerin periyodik kontrolleri üreticinin belirlediği kriterlere göre, Akümülatörlerin periyodik kontrolleri TS EN IEC 62485-1 standartında en geç yılda bir tekrarlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":1},{\"anahtar\":\"hst-19975\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Sabitlenmemiş dolap ve raflar\",\"risk\":\"1-Devrilme, düşme ya da çarpma sonucunda vücut bölümlerinin sıkışması, yaralanması\",\"mevcut_onlem\":\"1-Hastanede bir çok alanda dolaplar sabitlenmiştir.\",\"oneri\":\"1-Sabitlenmemiş doalp ve raflar en az iki noktadan sabitlenmelidir.\\n2-Düşme, devrilme riski olan bütün malzemeler düşmeyecek şekilde sabitlenmelidir.\\n3-Ağır malzeme ve ekipmanlar yüksek istiflenmemelidir.   \\n4- Sabitlenemeyen dolap ve raflar kapılardan uzak, çalışanların üzerine düşmeyecek şekilde konumlandırılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":2},{\"anahtar\":\"hst-19976\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Pendant üzerindeki prizlerin ya da jakların yerinden çıkması\",\"risk\":\"1- Elektrik çarpması ya da gaz sızıntısı sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Bozuk yerinden çıkmış priz ve jaklar kullanılmamalı, değiştirilmelidir.\\n2- Fişler prizlerden çekilirken kablodan asılarak çekilmemeli, fişten tutarak çıkarılmalıdır.                                                              \\n3- Gaz hortumları zorlanarak takılmamalı, jaka dik oturtularak takılmalıdır.  \\n4- Jaklar kullanılmadığında tam kapatılmalıdır. \\n5- Hortum ağırlığının jakları zorlamaması için destekler kullanılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":2},{\"anahtar\":\"hst-19977\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Pano önlerinde yalıtkan paspas olmaması,                                                         2-Uyarı levhası olmaması,\",\"risk\":\"1-Elektrik çarpması sonucu kalp ritim bozuklukları, ölüm\",\"mevcut_onlem\":\"1-Pano odalarında kartlı giriş sistemi mevcuttur.\",\"oneri\":\"1-Pano altlarına yalıtkan paspas yerleştirilmelidir.\\n2-Panolara ve pano odalarında eksik olan yerlere tehlike uyarı ve işaretleri asılmalıdır.                              \\n3-Elektrik pano odalarında ve panolar ile çalışma yapılırken TS EN 50321 standartında yaltkan ayakkabı, TSE EN 60903 standartında yalıtkan eldiven kullanılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":2},{\"anahtar\":\"hst-19978\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Elektrikli ısıtıcıların kullanılması\",\"risk\":\"1- Elektrik yangını çıkması sonucu, yaralanma, boğulma, ölüm\",\"mevcut_onlem\":\"1- İklimlendirme sistemi mevcuttur.\",\"oneri\":\"1- Hastane de soğuk havalarda elektrik ısıtıcılar kullanılmamalı, ısınma amaçlı sadece iklimlendirme sistemi kullanılmalıdır.                                                                                                          2- Çalışanların otomatik açılan kapılardan soğuk havaya maruz kaldıkları alanlara hava perdeleri yapılmalıdır.                                                                                                                                3- İstisnai durumlarda idareden özel izin alınmalı, ısıtıcıların prizlerden beslenmesi sağlanmalı, yanıcı malzemelerden uzak tutulmalı,kullanım sonrası fiş prizden çekilmelidir.                                                                                                                     4- İzinsiz kullanılan tüm ısıtıcılar toplatılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":2},{\"anahtar\":\"hst-19979\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Kaygan zemin oluşması                                                                  2- Bozuk zemin yüzeyi\",\"risk\":\"1-Düşme, denge kaybı sonucunda vücut bölümlerinin yaralanması\",\"mevcut_onlem\":\"1- Temizlik işlerinde kaygan zemin levhaları konulmaktadır.\",\"oneri\":\"1- Bozulan zeminin tamir ve tadilatı yapılmalıdır.\\n2- Temizlik işlemi sırasında zemin kurulanmalı temizlik esnasında uyarı tabelaları konulmalıdır.                                                                                                     3- Kaymaya sebep olacak maddelerinin zeminde birikmesi önlenmeli, hemen temizlenmelidir.\\n4-  Çalışanlar kaymaz tabanlı ayakkabı giymelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-19980\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Sivri, delici, kesici, paslı makine ve ekipmanlar\",\"risk\":\"1-Yaralanma sonucu tetanos hastalığına yakalanma\",\"mevcut_onlem\":\"1- Tetanos aşıları yapılmaktadır.\",\"oneri\":\"1-Paslı alet ve ekipmanlar yenileriyle değiştirilmeli, paslanmaz malzemeler kullanılmalıdır.\\n2-Sivri, delici, kesici, paslı makine ve ekipmanlara eldivensiz temas edilmemelidir.\\n3-Yeni başlayan ya da aşısı eksik olan çalışanlara tetanos aşısı yapılmalı, 5 yılda bir ya da yaralanma durumunda tekrar aşı yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":2},{\"anahtar\":\"hst-19981\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Havalandırma sisteminin periyodik kontrollerinin tekrarlanmaması\",\"risk\":\"1-Zararlı partiküllerin solunması sonucunda meslek hastalıklarının oluşması\",\"mevcut_onlem\":\"1- Havalandırma sisteminin periyodik kontrolleri mevcuttur.\",\"oneri\":\"1- Havalandırma sisteminin periyodik kontrolleri havalandırma tesisat projesinde yer alan kriterlere göre en geç yılda bir tekrarlanmalıdır. \\n2- Hava değişim sayısı ölçümleri yaptırılmalıdır.\\n3- Otomatik sıcaklık, nem izleme sistemleri bulunmalı, çalışır durumda olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-19982\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Termal konfor takibinin yapılmaması\",\"risk\":\"1- Dikkat kaybı, iş kazası ve meslek hastalıklarında artışlar\",\"mevcut_onlem\":\"1- İklimlendirme sistemi mevcuttur.\",\"oneri\":\"1-Çalışma ortamı %35-%75 nem oranında ve 18-24 C derece arasında olması sağlanmalıdır.                                                                                  \\n2- Ofislerde çalışan başına 10m3 temiz hava sağlanmalıdır.\\n3-Hava akım hızının 0,5 m/sn ortalamada olması sağlanmalıdır.\\n4-Çalışma ortamının saatte en az 6-10 kez havalandırılması sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":3},{\"anahtar\":\"hst-19983\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Sivri keskin yüzeylerin bulunması\",\"risk\":\"1- Temas sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Keskin ya da sivri yüzeyler oval hale getirilmelidir.\\n2- Keskin ya da sivri yüzeyler yumuşak bir malzeme ile kaplanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":3},{\"anahtar\":\"hst-19984\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Otomatik kayar kapıların sensörlerinin bozulması, periyodik kontrollerinin tekrarlanmaması\",\"risk\":\"1-Hareket sensörlerinin bozulması sonucu sıkışma yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Otomatik kayar kapıların hareket sensörleri ayda bir kontrol edilmeli en geç yılda bir kez periyodik kontrolleri yapılmalıdır. \\n2-Çalışanlar kapı kapanırken el, kol ya da bacaklarını kapı arasına sokmamalı, kapının tamamen kapanmasını beklemelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-19985\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: HASTANE GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Çalışanların yöneticileri ya da hasta hasta yakınları tarafından mobing uygulanması\",\"risk\":\"1-Sinirlilik, stres, depresyon, tükenmişlik sendromu, iş kazalarında artış\",\"mevcut_onlem\":\"1-Çalışan hakları birimi mevcuttur.                                         2-Çalışan memnuniyet anketleri yapılmaktadır.\",\"oneri\":\"1-Çalışanlara gereğinde psikolojik destek ve danışmanlık sağlanmalıdır.                                                                                                                                         2- Mobing bildirimi alındığında tarafsız inceleme süreci başlatılmalı, taraflar ayrı ayrı dinlenmeli, ve somut veriler ile kayıt tutulmalıdır.                                                                                                                            3- Tükenmişlik yaşayan çalışanlar düşük yoğunluklu birimlere kaydırılmalıdır.                                                                                                                              4- Şikayet konusu yönetici ise, yönetici davranış düzeltme sürecine (eğitim, gözlem vb.) alınmalıdır.                                                                           \\n5- Sürekli sorun çıkaran çalışanlar için eğitim, görev değişikliği ya da disiplin süreçleri başlatılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":null,\"siddet\":null,\"frekans\":null}]', 0, 0, NOW(), NOW()
