SELECT u.`id`, 'Hastane — Birim: DİYALİZ', 'saglik', NULL, 'fine_kinney', '[{\"anahtar\":\"hst-20034\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DİYALİZ\",\"faaliyet\":null,\"tehlike\":\"1-Diyaliz/portable cihazlardan sıvı dökülmesi/sızması\",\"risk\":\"1-Kayma/düşme                                                 2-Elektrik çarpması\",\"mevcut_onlem\":\"1-Giderler mevcuttur.                                      2-Cihaz bakımlarını firma yapmaktadır.\",\"oneri\":\"1- Cihazlar kullanılmadan önce hortumların gözle kontrolü yapılmalı herhangi bir arıza, zedelenme, bükülme ,ek yapılma durumu söz konusu ise onarım veya değişimi yapılmalıdır.                                                                                                                                                           2- Sıvı sızıntısı tespit edilen diyaliz cihazı derhal kullanım dışı bırakılmalı ve teknik servise bildirilmelidir.                                   \\n3- Cihazların periyodik bakım ve sızdırmazlık kontrolleri 3 ayda bir yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20035\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DİYALİZ\",\"faaliyet\":null,\"tehlike\":\"1-Diyaliz cihazlarının hortumlarında deformasyon                         2-Bağlantılarında su sızıntısı olması\",\"risk\":\"1-Elektrik çarpması                           2-Kayma düşme                                                3-Yangın\",\"mevcut_onlem\":\"1- Bakımları firma tarafından yapılmaktadır.                           2- Kaçak akım röleleri mevcuttur.\",\"oneri\":\"1- Diyaliz cihazlarının hortum ve kablolarında hiçbir şekilde ek ve deformasyon olmamalıdır.                                                                                                                                                             2- Kablolar ve hortumlar çift izolasyonlu olmalıdır.                                                                                     3- Hortumlar elektrik bulunan alanlardan (prizlerden) uzakta konumlandırılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20036\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DİYALİZ\",\"faaliyet\":null,\"tehlike\":\"1-Su numunesi alınan vanaların altında elektrik panosu olması, ekli kabloların bulunması\",\"risk\":\"1-Elektrik çarpması                                                       2-Kıvılcımlanma ile yangın riski\",\"mevcut_onlem\":\"1- Kaçak akım röleleri mevcuttur.\",\"oneri\":\"1- Numune alma vanalarının altında pano, hidrofor vb. hiç bir elektrik ekipman ve elektrik kablosu bulunmamalıdır.                                                                                                                          2-Numıune vanalarında ki basınçlı suyun ortama yayılmasını önlemek için vana zemine yakın bir alana taşınmalı, vana altına büyük kaplar konulmalıdır.                                                                                                                                                                                3-Çalışanlara TS EN 50321 stardadında yalıtkan ayakkabı temin edilmeli ve zimmetlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20037\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DİYALİZ\",\"faaliyet\":null,\"tehlike\":\"1-Cihazlarda elektrik kaçağı olması\",\"risk\":\"1-Elektrik çarpması sonucu kalp ritim bozuklukları, ölüm\",\"mevcut_onlem\":\"1- Kaçak akım röleleri mevcuttur.\",\"oneri\":\"1- Cihaz kabloları çift izolasyonlu olmalı herhangi bir ek ya da zedelenme olmamalıdır.                                                                                                                                                                     2- Elektirikli araç ve gereçler olası su (kirli-temiz) basmaları olabilecek alanlardan uzakta muhafaza edilmelidir.\\n3- Elektirikle çalışan cihazlarda arızalar olduğunda ilgili bölüm sorumlusu tarafından ilgili firma çalışanları bilgilendirilmeli ve arızalar en kısa sürede giderilmelidir.                                                                                                                                                                                        4- Elektirik güvenliği ile ilgili eğitim verilmeli, Arızalı araç gereç kullanımdan çekilmeli,  bakım ve onarımı sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20038\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DİYALİZ\",\"faaliyet\":null,\"tehlike\":\"1-Diyaliz cihazı temizleme sırasında oluşabilecek su kaçakları/cihazın boşta durması\",\"risk\":\"1-Yangın                              2-Su kaçağı                     3-Elektrik çarpması\",\"mevcut_onlem\":\"1-Bakımları yapılmaktadır.\",\"oneri\":\"1-Cihazların hortumlarıve bağlantı yerleri su sızıntısına karşı kontrol edilmeli su kaçağı olmamalıdır.                                                                                                                                                2-Fiş kabloları kontrol edilmeli herhangi bir deformasyon ek yeri olmamalıdır.                                    3-İşlemi biten cihaz fişte tutulmamalı, fiş çıkarılıp kuru bir yere sabitlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20039\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DİYALİZ\",\"faaliyet\":null,\"tehlike\":\"1-Buatlara 3\'lü priz takılması sonucu aşırı yükleme\",\"risk\":\"1-Elektrik kaçağı    2-Yangın riski\",\"mevcut_onlem\":null,\"oneri\":\"1- Buat içlerine 3 lü priz takılması kesinlikle engellenmelİ ve halojen free olmalıdır.\\n2- Priz ihtiyaçları için buat yapılmalıdır.\\n3- Elektrik tesisatı ve kaçak akım röleleri düzenli olarak yetkili çalışanlar tarafından kontrol edilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20040\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DİYALİZ\",\"faaliyet\":null,\"tehlike\":\"1-Yatan hastaların yataklarında radyolojik\\ngrafilerinin çekilmesi ( portable çekim)\",\"risk\":\"1-Meslek hastalığı (Kanser)\",\"mevcut_onlem\":\"1- Çekim yapan çalışanların KKD leri mevcuttur.\",\"oneri\":\"1- Portable radyoloji çekimleri yalnızca tıbben zorunlu hallerde diyaliz bölümü içerisinde yapılmalıdır.\\n2- Çekim esnasında kurşun paravan kullanılmalıdır.                                                                                                                      3- Çalışanlar kişisel koruyucu donanım (kurşun önlük, tiroid koruyucu vb.) (TS EN 61331) kullanmalıdır.                                                                                                                                            4- Çekim sırasında hasta dışındaki kişilerin ( çalışan, refakatçi, diğer hastalar) en az 2 metre radyasyon alanından uzaklaştırılması sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20041\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DİYALİZ\",\"faaliyet\":null,\"tehlike\":\"1-KKD eksikliği                      2-KKD kullanılmaması          3-KKD zimmeti olmaması\",\"risk\":\"1-İş kazaları                                   2-Meslek hastalıkları\",\"mevcut_onlem\":\"1-KKD mevcuttur.                                                                  2-Çalışanlara KKD kullanımı konusunda eğitim verilmiştir.\",\"oneri\":\"1- Çalışanlara kişisel koruyucu donanım Eldiven (EN 455) - Koruyucu Gözlük , Yüz Siperliği (EN 166) - Cerrahi Maske (EN14683) - Solunum Maskesi (EN149) sağlanmalı ve zamanında temin edilmelidir.\\n2- KKD kullanımı bölüm sorumlusu tarafından sürekli denetlenmelidir.                                                                      \\n3- Çalışanlara teslim edilen tüm KKD ler zimmetlenmelidir.\\n4- Eksik veya hasarlı KKD hızla yenilenmeli, kullanılabilir durumda olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20042\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DİYALİZ\",\"faaliyet\":null,\"tehlike\":\"1-Basınçlı oksijen tüplerinin hatalı kullanılması\",\"risk\":\"1-Yaralanma ve yanık\",\"mevcut_onlem\":\"1- Çalışanlara basınçlı tüplerin doğru kullanımı hakkında eğitim verilmiştir.\",\"oneri\":\"1- Oksijen tüpleri alanda sabitleme aparatına en az iki noktadan bağlanmalıdır.                                               \\n2- Tüp çıkış valfleri özellikle yağ ve su gibi kirleticilerden uzak ve temiz tutulmalı, yağlı ekipman (conta, regülatör vb.). kesinlikle kullanılmamalıdır.                                                                                                                                         3- Oksijen tüplerinin manometreleri sağlam olmalıdır.                                          \\n4- Yanıcı maddeler oksijen tüpleri ile temas etmemelidir.                                                                               5- Eldivensiz oksijen tüpüne dokunulmamalı yağlı eldiven veya kremli ellerle dokunulmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20043\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DİYALİZ\",\"faaliyet\":null,\"tehlike\":\"1-Hastalardan temas ve inhalasyon yolu ile bulaş\",\"risk\":\"1-Solunum yolu hastalıkları                                                                                  2- Temas yolu ile bulaşan hastalıklar\",\"mevcut_onlem\":\"1- Havalandırma sistemi mevcuttur.                                                              2-KKD\'ler mevcuttur.\",\"oneri\":\"1- Çalışanlar, temas ve inhalasyon yoluyla bulaş riski olan hastalarla çalışırken kişisel koruyucu donanım (Eldiven (EN 455) - Koruyucu Gözlük , Yüz Siperliği (EN 166) - Cerrahi Maske (EN14683) - Solunum Maskesi (EN149)) kullanmalıdır.\\n2- El hijyenine azami özen gösterilmeli, sıvı sabun ve alkol bazlı antiseptik kullanımı sağlanmalıdır.\\n3- Çalışanlar hastalardan bulaşma yolları ve korunma yöntemleri konusunda düzenli olarak eğitilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20044\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DİYALİZ\",\"faaliyet\":null,\"tehlike\":\"1-Kan ve vücut sıvılarının cilde teması\",\"risk\":\"1-Enfekte hastadan bulaş                                                                     2-Enfeksiyon riski\",\"mevcut_onlem\":\"1-KKD mevcuttur.\",\"oneri\":\"1- KKD (Eldiven (EN 455) - Koruyucu Gözlük , Yüz Siperliği (EN 166) - Cerrahi Maske (EN14683) - Solunum Maskesi (EN149)) kullanılmalıdır.\\n2- Temas sonrası cilt hemen su ve sabunla yıkanmalı, gerekirse antiseptik uygulanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20045\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DİYALİZ\",\"faaliyet\":null,\"tehlike\":\"1-Kesici ve delici aletlerin emniyetsiz kullanımı\",\"risk\":\"1-Enfeksiyon, enfekte hastadan bulaş\",\"mevcut_onlem\":\"1- Sharpbox ve KKD mevcuttur.\",\"oneri\":\"1- Kullanılmış iğne ve kesici delici aletler mutlaka delinmeye dayanıklı, kapaklı atık kutularına atılmalıdır.                                                                                                                                     2- Kesici ve delici aletlerle çalışırken kişisel koruyucu donanım mutlaka kullanılmalıdır.                                             \\n3- İlaç arabalarının rafları kapalı ve kilitli olmalıdır.                                                                                                                                                                    4- Atık kutularının doluluk durumu düzenli kontrol edilmeli,2/3 ü dolan atık kutuları boşaltılmalıdır.\\n5- Kesici ve delici aletler dikkatli ve uygun şekilde kullanılmalı, gereksiz temaslardan kaçınılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20046\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DİYALİZ\",\"faaliyet\":null,\"tehlike\":\"1-Tehlikeli davranışlar (Ucu açık iğne uçları,\\nKKD kullanılmaması, stajyer öğrencilerin tek\\nbaşına iş yapması)\",\"risk\":\"1-Meslek hastalığı                                            2-İş kazası                                              3-Enfeksiyon riski\",\"mevcut_onlem\":\"1- Sharpbox ve KKD mevcuttur.\",\"oneri\":\"1- Kullanılmış iğne uçları hemen ve güvenli şekilde uygun atık kutularına atılmalıdır.\\n2- KKD (Eldiven (EN 455) - Koruyucu Gözlük , Yüz Siperliği (EN 166) - Cerrahi Maske (EN14683) - Solunum Maskesi (EN149)) her zaman ve doğru şekilde kullanılmalıdır.\\n3- Stajyer öğrenciler kesinlikle tek başına riskli işlerde çalıştırılmamalı, mutlaka deneyimli çalışanların gözetiminde bulunmalıdır.\\n4- Çalışanlar ve stajyerlere tehlikeli davranışların riskleri hakkında düzenli eğitim verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20047\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DİYALİZ\",\"faaliyet\":null,\"tehlike\":\"1-Açıkta bırakılan kontamine araç gereçler\",\"risk\":\"1-Enfeksiyon riski\",\"mevcut_onlem\":\"1- 1616’dan talep açıldığında kontamine araç gereçler sterilizasyon firması tarafından toplanmaktadır.\",\"oneri\":\"1- Kontamine araç gereçler hemen uygun kapalı kaplarda muhafaza edilmelidir.\\n2- Kullanılan araç gereçler temizlenmeli, dezenfekte edilmeli veya sterilize edilmelidir.\\n3- Atık yönetimi prosedürlerine göre kontamine malzemeler bertaraf edilmelidir.                                                                       4- Araç gereçlerin açıkta bırakılması engellenmeli, uygun depolama alanları sağlanmalıdır.                                                                                                                                                                             5- Kontamine malzemelerle temas önlenmeli ve hijyen kurallarına uyulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20048\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DİYALİZ\",\"faaliyet\":null,\"tehlike\":\"1-Diyaliz kimyasallarının dökülme ve sıçramasına bağlı kazalar\",\"risk\":\"1-İş kazaları riski    2-Solunum yolu hastalıkları                                       3-Düşme riski                                                                  4-Elektrik çarpması\",\"mevcut_onlem\":\"1- KKD mevcuttur.\",\"oneri\":\"1- Kimyasalların taşınması sırasında dökülme/sıçrama riskini önleyecek uygun taşıma ekipmanları (kapaklı bidonlar, sızdırmaz kaplar vb.) kullanılmalıdır.\\n2- Kimyasallar kullanılırken kişisel koruyucu donanımlar (Eldiven (EN 455) - Koruyucu Gözlük , Yüz Siperliği (EN 166) - Cerrahi Maske (EN14683) - Solunum Maskesi (EN149)) mutlaka kullanılmalıdır.\\n3- Kimyasal dökülme durumları için uygun temizlik ve müdahale kitleri (absorban malzemeler vb.) kolay ulaşılabilir yerlerde bulundurulmalıdır.                                        \\n4- Kimyasal maddeler ve dezenfektanlar depolanırken üst üste konulmamalıdır.      5- Dökülmeye karşı zemin temizlenmeli, temizlik sonrası havalandırma sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20049\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DİYALİZ\",\"faaliyet\":null,\"tehlike\":\"1-Portable kullanılan cihazların (Diyaliz, Usg, Röntgen, EKG  Vb.) temizlik ve dezenfeksiyonunun yapılmaması\",\"risk\":\"1-Enfeksiyon riski\",\"mevcut_onlem\":\"1- Firma tarafından takipleri yapılmaktadır.\",\"oneri\":\"1-Tüm portable cihazlar (Diyaliz, USG, Röntgen, EKG  vb.) kullanım sonrası mutlaka temizlenmeli ve dezenfekte edilmelidir.\\n2-Cihazların temizliği ve dezenfeksiyonu periyodik olarak denetlenmeli ve kayıt altına alınmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20050\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DİYALİZ\",\"faaliyet\":null,\"tehlike\":\"1-Kan ve vücut sıvılarının göze teması ile bulaş\",\"risk\":\"1-Enfeksiyon riski\",\"mevcut_onlem\":\"1- Çalışanların KKD leri mevcuttur.\",\"oneri\":\"1-Kan ve vücut sıvıları ile çalışılırken mutlaka kişisel koruyucu donanım (Koruyucu Gözlük , Yüz Siperliği (EN 166)) kullanılmalıdır.                                     \\n2-Çalışma alanlarında acil durumlarda gözün hızlıca yıkanabileceği göz duşu solüsyonu bulundurulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20051\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DİYALİZ\",\"faaliyet\":null,\"tehlike\":\"1-Bulaş tehlikesi olan hastaların ayrı alanlarda tedavi alması\",\"risk\":\"1-Meslek hastalığı                          2-Enfeksiyon riski\",\"mevcut_onlem\":\"1- Ayrı işlem odaları mevcuttur.\",\"oneri\":\"1- Hasta nakli sırasında enfeksiyon kontrol protokollerine uyulmalı, kişisel koruyucu ekipmanlar mutlaka kullanılmalıdır.                                                                                                                          2- Bulaşıcı hastalık riski taşıyan hastalar, diğer hastalardan ayrı izole odalarda tedavi edilmelidir.                                          \\n3- Ortak kullanım alanlarında (tuvalet, bekleme salonu vb.) düzenli dezenfeksiyon işlemleri yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20052\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DİYALİZ\",\"faaliyet\":null,\"tehlike\":\"1-Çıkış kapısından alana soğuk hava girişi\",\"risk\":\"1-Termal konfor koşullarının sağlanamaması sonucunda hastalıklara yakalanma\",\"mevcut_onlem\":\"1- Havalandırma iklimlendirme sistemi mevcuttur.\",\"oneri\":\"1- Kapı girişlerine hava perdesi sistemi kurulmalıdır.\\n2- Kapılarda herhangi bir arıza durumunda talep açılıp onarımı sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20053\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DİYALİZ\",\"faaliyet\":null,\"tehlike\":\"1-Su numunesi alınan teknik mahallerin girişleri ve yollarında alçak tavan ve havalandırma sistemleri sebebiyle baş çarpması/yaralanması\",\"risk\":\"1-Baş yaralanması\",\"mevcut_onlem\":\"Uyarı işaretleri mevcuttur.\",\"oneri\":\"1- Çalışanların baret  (EN 397+A1 )  ve iş ayakkabısı (EN ISO 20345) temin edilmelidir. kullanılmalıdır.                                                                                                                                             2- Uyarı işaretleri ( DİKKAT ALÇAK TAVAN vb.) gibi konulmalıdır.                                                3- Tavanda bulunan vidalar tehlike yaratmayacak şekilde körlenmeli ya da uçlarına mantarlar takılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20054\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DİYALİZ\",\"faaliyet\":null,\"tehlike\":\"1-Diyaliz setinin takılması ve sökülmesi esnasında kan ve vücut sıvılarının dökülmesi sonucu bulaş ve kayma\",\"risk\":\"1-Enfeksiyon riski  2-Kayma, düşme\",\"mevcut_onlem\":\"1- Çalışanların KKD leri mevcuttur.\",\"oneri\":\"1- İşlem öncesi ve sonrası alan temizliği ve dezenfeksiyonu yapılmalıdır.                            2- Kişisel koruyucu ekipman (Eldiven (EN 455) - Koruyucu Gözlük , Yüz Siperliği (EN 166) - Solunum Maskesi (EN149)) kullanılmalıdır.\\n3- Kaymayı önleyici ayakkabı (EN ISO 20345) ve emici paspaslar kullanılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":2},{\"anahtar\":\"hst-20055\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DİYALİZ\",\"faaliyet\":null,\"tehlike\":\"1-Kesici delici aletlerin ortalıkta bulunması (Makas, enjektör vb.)\",\"risk\":\"1-Çalışan hasta ve yakınları için kesici delici alet yaralanması\",\"mevcut_onlem\":\"1- Çalışanların zimmetleri vardır.\",\"oneri\":\"1- Kesici delici aletler sadece belirlenen alanlarda bulundurulmalıdır.\\n2- Kullanım sonrası hemen toplanmalı ve güvenli şekilde saklanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":2},{\"anahtar\":\"hst-20056\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DİYALİZ\",\"faaliyet\":null,\"tehlike\":\"1-Kullanılan kimyasalların malzeme güvenlik bilgi\\nformlarının (MSDS) alanda olmaması\",\"risk\":\"1-Parlama, patlama, yangın ve iş kazası riski\",\"mevcut_onlem\":\"1- MSDS mevcuttur.\",\"oneri\":\"1- Kullanılan tüm kimyasal maddeler belirlenmelidir.\\n2- Her kimyasal maddeye ait güncel Malzeme Güvenlik Bilgi Formları (MSDS) temin edilmelidir.\\n3- MSDS belgeleri kolay erişilebilir bir yerde bulundurulmalı ve çalışanların ulaşabileceği şekilde düzenlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":2},{\"anahtar\":\"hst-20057\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DİYALİZ\",\"faaliyet\":null,\"tehlike\":\"1-Lavabolarda bulaş ve ergonomi\",\"risk\":\"1-Enfeksiyon yayılımı                                                                    2-Ergonomi problemleri\",\"mevcut_onlem\":\"1- Lavabolar mevcuttur.\",\"oneri\":\"1- El ile açılan musluklar fotoselli musluklar ile değiştirilmelidir.\\n2- El hijyen ekipmanları kolay erişilebilir konumda olmalıdır.                                                             \\n3- Musluk ve lavabo yüzeyleri düzenli olarak dezenfekte edilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":2}]', 0, 0, NOW(), NOW()
