SELECT u.`id`, 'Hastane — Birim: TEMİZLİK', 'saglik', NULL, 'fine_kinney', '[{\"anahtar\":\"hst-20058\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: TEMİZLİK İŞLERİ\",\"faaliyet\":null,\"tehlike\":\"1-Yüzeylerin yanlış bez ya da ekipman ile temizlenmesi\",\"risk\":\"1-Çapraz Bulaşma (Çapraz Kontaminasyon)         2-Hijyen Kurallarının İhlali\",\"mevcut_onlem\":\"1-Bölgelere göre bezler paspaslar ayrılmıştır.\",\"oneri\":\"1-Her alan için ayrı temizlik ekipmanı (bez, kova, süpürge vs.) kullanılmalıdır.\\n2-Temizlik arabalarında bezler renk kodlarına göre işaretlenmelidir.\\n3- Temizlik işleri, temizlenecek yüzeye göre belirlenmiş renkteki bezler ile yapılmalı, bezler kesinlikle karıştırılmamalıdır.                                                                                                                   Kırmızı bez-Klozet, klozet kapağı, pisuvar                                                                                              Yeşil bez-Mobilya, yatak, raf, havalandırma, aydınlatma                                                                      Mavi bez-Ofis, oda toz alımlarında                                                                                                       Sarı bez-WC lerdeki lavabo, fayans, sifon, wc aparatları, ayna, duşakabin                                                             4-Bezler ve kovalar her kullanımdan sonra  dezenfekte edilmelidir.                                                               5-Alan sorumluları tarafından sürekli kontrol denetim sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20059\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: TEMİZLİK İŞLERİ\",\"faaliyet\":null,\"tehlike\":\"1-Ortak alanların rutin temizliğinin uygun yapılmaması\",\"risk\":\"1-Çapraz Bulaşma (Çapraz Kontaminasyon)\",\"mevcut_onlem\":null,\"oneri\":\"1- Çalışanlar için enfeksiyon hastalıklarına yol açabilecek ortak alanlar asansörler, yürüyen merdivenler, kapı kolları vb. temizliği günlük düzenli olarak yapmalıdır.                                                                                                                                                                         2- Temizlenecek yüzeye göre belirlenmiş bezler ve dezenfektanlar kullanılmalıdır.                                                                                                                                              3- Sorumlular tarafından yapılan temizlik kontrol edilmelidir.                                                                 4- Temizlik formları, hem temizlik yapanlar hem de kontrol edenler tarafından her temizlik sonrası imzalanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20060\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: TEMİZLİK İŞLERİ\",\"faaliyet\":null,\"tehlike\":\"1-Tıbbi cihazların                              ( röntgen, ultrason, mr, tomografi, diyaliz vb.) temizlik ve dezenfeksiyonun yapılmaması ya da yanlış yapılması\",\"risk\":\"1-Enfeksiyon, bulaşıcı hastalıkları oluşması\",\"mevcut_onlem\":null,\"oneri\":\"1- Temizlik mavi kodlu bezlerle yapılmalı herhangi bir kan veya vücut sıvısı bulaşı yoksa saf su ile eğer kan ve vücut sıvısı var ise yüzey dezenfektanıyla temizlenmelidir.                                                                                                                                                                                                           2- Temizlik arabalarında cihaz temizliği için kullanılan kimyasallar ve ekipmanlar bulundurulmalıdır.                                                                                                                                         3-Çalışanlara konu hakkında eğitimler verilmelidir.                                                                       4- Alan sorumluları tarafından sürekli kontrol denetim sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20061\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: TEMİZLİK İŞLERİ\",\"faaliyet\":null,\"tehlike\":\"1- Acil çıkış yolları üzerinde temizlik arabalarının bırakılması\",\"risk\":\"1-Acil durum karşısında tahliyenin zorlaşması                           2-Kargaşaya sebebiyet verme\",\"mevcut_onlem\":\"1-Çalışanlar uyarılmakta ve denetlenmektedir.\",\"oneri\":\"1-Temizlik ekipmanları ve arabaları, belirlenmiş depolama alanlarında muhafaza edilmelidir.                                                         \\n2-Acil çıkış yolları ve koridorlar kesinlikle herhangi bir eşya veya temizlik arabası ile engellenmemelidir.\\n3-Temizlik çalışanlarına acil çıkış yollarının önemi ve bu alanlarda araç bulundurulmaması konusunda eğitim verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20062\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: TEMİZLİK İŞLERİ\",\"faaliyet\":null,\"tehlike\":\"1-Temizlik arabalarının yangın dolapları ve söndürücüleri, elektrik panoları önünde bulundurulması\",\"risk\":\"1-Yangın durumunda dolaplara ve tüplere erişimi zorlaştırma\",\"mevcut_onlem\":\"1-Çalışanlar uyarılmakta ve denetlenmektedir.\",\"oneri\":\"1-Yangın dolaplarının, tüplerinin, elektrik panolarının ve pano odalarının önünde hiçbir şekilde temizlik arabası bulundurulmamalıdır.                                                                                                                                                                              2-Çalışan bu konuda sürekli kontrol edilmeli ve eğitimleri verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20063\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: TEMİZLİK İŞLERİ\",\"faaliyet\":null,\"tehlike\":\"1-Temizlik arabalarında kimyasal döküntü kitinin olmaması\",\"risk\":\"1-Kimyasal buharının ortama  yayılıması sonucu maruziyet\",\"mevcut_onlem\":\"1-Bazı temizlik arabalarında döküntü kiti mevcuttur.\",\"oneri\":\"1-Kimyasal dökülmelerine karşı her araçta kimyasal döküntü kiti bulundurulmalıdır.                                                                                                                                       2-Çalışanlara kimyasal döküntü kitinin nasıl kullanılması gerektiği anlatılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20064\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: TEMİZLİK İŞLERİ\",\"faaliyet\":null,\"tehlike\":\"1-Biyolojik vücut sıvılarının dökülmesi\",\"risk\":\"1-Bulaşıçı hastalıklar\",\"mevcut_onlem\":\"1-Havalandırma sistemi mevcut ve aktif olarak çalışmaktadır.\",\"oneri\":\"1-Çalışanlar KKD kullanmalıdır.                                                                                                                       2-Döküntü fazla ise emdirilip tıbbi atık kutusuna atılmalıdır.                                              3-Yüzey klorlu temizleyicilerle temizlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20065\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: TEMİZLİK İŞLERİ\",\"faaliyet\":null,\"tehlike\":\"1-El hijyeni sağlamak için lavabo (sıvı sabun, kağıt havlu vb.) ve alkol bazlı el antiseptiğinin bulunmaması\",\"risk\":\"1-Enfeksiyon\",\"mevcut_onlem\":\"1-Lavabo ve temizlik dejenfeksiyon malzemeleri alanda mevcuttur.\",\"oneri\":\"1-Çalışma alanlarında lavabolar sürekli kullanıma hazır olmalıdır.\\n2-Lavabolarda sıvı sabun, kağıt havlu ve hijyenik kurutma malzemeleri bulundurulmalıdır.\\n3-Alkol bazlı el antiseptikleri erişilebilir olmalıdır.\\n4-El hijyeni için gerekli malzemelerin düzenli olarak kontrolü ve temini sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20066\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: TEMİZLİK İŞLERİ\",\"faaliyet\":null,\"tehlike\":\"1-Yüksekte çalışma faaliyetleri, dış cephe temizlenmesi\",\"risk\":\"1-Yüksekten malzeme düşmesi sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1-Dış cephe temizliği çalışma izin formu ile yapılmalıdır.                                                                                                                                                2-Malzeme ve ekipman düşmelerine karşı güvenlik çemberi oluşturulmalıdır.                                                                      3-Yüksekte yapılan çalışmalarda kullanılan malzeme ve aletlerin düşmemesi için Çapa noktaları (EN 795), Emniyet halatları (EN 354), Bağlantı elemanları (EN 362) ile sabitlenmelidir.                                                                                                                                     4-Dış cephe temizliğinde, Tam vücut emniyet kemerleri (EN 361) Bağlantı halatları (lanyard) (EN 354) Şok emici bağlantı sistemleri (EN 355) Kendiliğinden geri sarımlı düşüş durdurucular (EN 360) Karabinalar (EN 362) Ankraj sistemleri (yaşam hatları vb.) (EN 795) Endüstriyel baretler (EN 397) Kurtarma kaldırma ekipmanları (EN 1496) İniş sistemleri (acil iniş) (EN 341) Dikey düşüş durdurucu sistemler (EN 353-1/2) standartlarında yüksekten düşmeyi önleyici ekipmanlar ve KKD\'ler kullanılmalıdır.\\n5-Temizlik kovaları ankraj sistemine bağlanmadan kullanılmamalıdır.                                                                                                     6-Çalışanlara yüksekte çalışma eğitimi ve güvenlik kuralları mutlaka verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":1},{\"anahtar\":\"hst-20067\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: TEMİZLİK İŞLERİ\",\"faaliyet\":null,\"tehlike\":\"1-Islak ve kaygan zemin\",\"risk\":\"1-Düşme, yaralanma, çarpma, burkulma\",\"mevcut_onlem\":\"1-Nemli temizlik yapılmaktadır.                  2-Uyarı levhaları mevcuttur\",\"oneri\":\"1-Islak ve kaygan zeminler uyarı levhalarıyla işaretlenmelidir.\\n2-Zeminler mümkün olan en kısa sürede kurutulmalıdır.\\n3-Islak zemin oluşumuna neden olan kaynaklar (sızıntı, temizlik vb.) belirlenerek önleyici tedbirler alınmalıdır.                                                                                                                                                                                4-Çalışanlar, kaygan zeminlerde kaymaz ayakkabı (EN 13287) kullanımı konusunda bilgilendirilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":3},{\"anahtar\":\"hst-20068\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: TEMİZLİK İŞLERİ\",\"faaliyet\":null,\"tehlike\":\"1-Temizlik kat arabalarında bulunan kimyasalların düzensizliği\",\"risk\":\"1-Yere kimyasal dökülmesi\",\"mevcut_onlem\":\"1-Taşma kapları mevcuttur.\",\"oneri\":\"1-Kimyasalların temizlik arabalarında yerleştirilmesi kimyasal matrisine uygun şekilde düzenlenmelidir.\\n2-Temizlik kimyasalları birbirine karıştırılarak kullanılmamalıdır.                                                              3-Kimyasallar taşma kaplarına konularak sızıntı ve akma durumunda taşma kabı dışına çıkmamalıdır.                                                                                                                                                                                                                                                                                                   4-Kullanıcılar kimyasal maddelerin doğru kullanımı ve güvenliği konusunda eğitilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20069\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: TEMİZLİK İŞLERİ\",\"faaliyet\":null,\"tehlike\":\"1-Cam ya da camdan oluşan kapıların kırılma ve çatlamaları\",\"risk\":\"1-Parçalanma, kesilme, yaralanma\",\"mevcut_onlem\":\"1-KKD mevcuttur.\",\"oneri\":\"1-Camlar ve cam kapılar, dayanıklı ve kırılmaya karşı güvenlik camı (lamine veya temperli cam) olmalıdır.\\n2-Cam kapılar ve büyük cam yüzeyler görünürlük işaretler (frost, bant, sticker vb.) sağlam olmalı, yıpranan ya da çıkan işaretler yenilenmelidir.\\n4-Cam ve cam kapılar düzenli olarak kontrol edilmeli, çatlak veya hasarlı camlar derhal yenilenmelidir.\\n5-Cam kırılması durumunda etrafı çevrelenmeli, hızlıca temizlik yapılmalı, çalışanların ve hastaların korunması sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":2},{\"anahtar\":\"hst-20070\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: TEMİZLİK İŞLERİ\",\"faaliyet\":null,\"tehlike\":\"1-Temizlik arabalarının dikkatsiz kullanımı\",\"risk\":\"1-Cam ve kapı kırılmaları, çarpmalar ve iş kazaları\",\"mevcut_onlem\":\"1-Çalışanlara eğitim verilmiştir.\",\"oneri\":\"1-Temizlik arabalarının frenleri düzenli olarak kontrol edilmelidir.                                          2-Araçların düzenli bakım ve kontrolü sağlanmalıdır.\\n3-Kullanım alanı ve çevre koşulları sürekli gözlemlenerek riskler azaltılmalıdır.                                                                        4-Kullanıcılar dikkatli kullanım ve güvenlik konularında eğitilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":3}]', 0, 0, NOW(), NOW()
