SELECT u.`id`, 'Hastane — Birim: NÜKLEER TIP', 'saglik', NULL, 'fine_kinney', '[{\"anahtar\":\"hst-20071\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ\",\"faaliyet\":null,\"tehlike\":\"1- Yeterli sayıda kişisel koruyucu ekipman olmaması                              2- Kişisel koruyucu ekipmanın deforme olması\",\"risk\":\"1- Radyasyona maruziyet sonucu meslek hastalıkları oluşması\",\"mevcut_onlem\":\"1- Her çalışanın kişisel tiroid koruyucusu vardır.\",\"oneri\":\"1-Nükleer tıp bölümünde tüm çalışanlara ts en 61331-1 standartında kurşun yelek,kurşun tiroid koruyucu donanımlardan eksik olanlar verilmelidir.                                                           2-Özellikli(kurşun kaplı) kişisel koruyucu donanımların kırılma vb. kontrolü günlük olarak çalışanlar tarafından yapılmalıdır.                                                                                                                     3-Koruyucu önlükler sandalye ve koltuk üzerine buruşuk bir şekilde koyulmamalıdır,özel askılıklarda tutulmalıdır.                                                                                                                                                                                  4-Dezenfeksiyon ve temizliğinde alkol içerikli temizleme maddesi kullanılmamalıdır.                                                                                                                                                      5-Tüm koruyucular yılda en az bir kez veya ihtiyaç görüldüğü hallerde (Deforme olmuş,bozulmuş,kırılmış,düşmüş) sorumluya bilgi verilip skopi ile kontrol edilerek ayrılmalı ve kullanılmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20072\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ\",\"faaliyet\":null,\"tehlike\":\"1-Çalışan dinlenme odasının radyasyonlu alana yakın olması\",\"risk\":\"1- Radyasyona maruziyet sonucu meslek hastalıkları oluşması\",\"mevcut_onlem\":null,\"oneri\":\"1-Gözetimli alanlar içerisinde bulunan hasta bekleme,doktor,personel dinlenme odası gibi alanların radayoaktif ölçümü en az altı ayda bir yapılmalı ve belgelendirilmelidir.                                                                                                                               2- Alan ölçüm değeri 0,5 µSv/h  değerini geçmemelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20073\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ\",\"faaliyet\":null,\"tehlike\":\"1- Hastaya radyoaktif madde uygulaması yapılması\",\"risk\":\"1- Radyasyona maruziyet sonucu meslek hastalıkları oluşması\",\"mevcut_onlem\":\"1- Her çalışanın kişisel tiroid koruyucusu vardır.\",\"oneri\":\"1-Hastaya ilaç uygulanacağı zaman çalışanlar eldiven,kurşun önlük,boyun koruyucu,maske,tam yüz koruma gözlüklerini giymiş olmalıdır.                                                                                                       2-İlaçlar hasta odasına taşınırken kurşun zırhla kaplı kutularda taşınmalıdır.                                                      3-Enjeksiyon işlemi bittikten sonra atıklar kurşun zırhlı atık kutularına atılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20074\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ\",\"faaliyet\":null,\"tehlike\":\"1- Atıkların uzun süreli bekletme sonucu sineklenme olması\",\"risk\":\"1- Enfeksiyon bulaşı\",\"mevcut_onlem\":\"1- Evsel atıklar kilitli tehlikeli atık varillerinde bekletilmektedir.\",\"oneri\":\"1-Atık poşetleri sağlam olmalı, poşetlerde yırtık delik olmamalıdır.                                                                                                  2- Atık poşetlerinin ağızları sıkıca bağlanmalı kilitli kutularda saklanmalıdır.                                                                                                                           3-Ortam ısısı düşürülmelidir.                                                                                                                                   4-En geç ayda bir ilaçlama yapılmalıdır.                                                                                                                     5- Atık odasının kapısı açık bırakılmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20075\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ\",\"faaliyet\":null,\"tehlike\":\"1- Radyasyonlu hastanın ve hasta yakınının çalışana teması yada yakın mesafede bulunması\",\"risk\":\"1-Radyasyona maruziyet sonucu meslek hastalıkları oluşması\",\"mevcut_onlem\":\"1- Hastalara tedavi öncesi eğitim verilmektedir.\",\"oneri\":\"1-İşlem yapılmadan önce hasta ve hasta yakınlarına işlem bitimini takiben diğer insanlarla en az 2 metre radyosyon güvenli mesafesi bırakılması gerektiğinin bilgisi verilmelidir.                                                                                                                                                                 2-İşlem öncesi,sırası ve sonrasında yapılacaklar hastaya detaylı bir şekilde anlatılmalıdır.                                                                                                                                                                         3-Çalışanlar kurşun yelek,kurşun tiroid koruyucu,maske , gözlük ve eldiven kullanarak çalışmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20076\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ\",\"faaliyet\":null,\"tehlike\":\"1- İlaç hazırlama ünitesi arkasında ekli kabloların olması\",\"risk\":\"1-Elektirik çarpması sonucu yanık,sinir kas ya da organ kaybı\",\"mevcut_onlem\":\"1-Panolarda 30 MA kaçak akım rölesi mevcuttur.\",\"oneri\":\"1-Elektirik kabloları sağlam yapıda,çift izolasyonlu  olmalıdır.                                                                                   2-Kablolarda deformasyon olmamalıdır.                                                                                           3-Deformasyon olan kablolar değiştirilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20077\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ\",\"faaliyet\":null,\"tehlike\":\"1- MON.FDG (18F) Enjeksiyonluk Çözelti kullanılması\",\"risk\":\"1- Maruziyet durumunda göz cilt iritasyonu\",\"mevcut_onlem\":\"1- Radyoaktif ilaçlar sıcak odada çeker ocak altında hazırlanmaktadır.\",\"oneri\":\"1-Bulaşma olan alana emici bir materyal koyarak maddenin dağılmasını önlenmeli, dıştan merkeze dogru temizlenmelidir.                                                                                                                                                                                                                                                                     2-Dekontaminasyon çözeltisi ile, sonrasında su ve sabun ile temizleyip ortam havalandırılmalıdır.                                                                                                                                              3-Kontamine olmuş tüm kullanılan materyaller ve atıklar radyasyon güvenliği sorumlusunun talimatına göre, kalıntı, kir bırakmayacak şekilde toplanmalıdır.                                                                      4-İmhası için, yarılanma ömrünü dikkate alarak uygun kapalı radyoaktif atik kabında toplanmalıdır.                                                                                                                                                5-Göze temas durumunda En az 15 dakika bol su ile yıkanmalıdır.\\n6-Yutma durumunda ağız su ile çalkalanmalıdır. Bilinci kapalı ise ağız yolu ile hiçbir şey verilmemeli, acile başvurulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20078\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ\",\"faaliyet\":null,\"tehlike\":\"1- MON.Tek Jeneratör\",\"risk\":\"1- Maruziyet durumunda gözde irritasyon,alerjik reaksiyon,kronik maruziyette genetik ve teratojenik etkiler\",\"mevcut_onlem\":\"1- Radyoaktif ilaçlar sıcak odada çeker ocak altında hazırlanmaktadır.\",\"oneri\":\"1-İnhalasyon durumunda inhale edilen miktar kaydedilmeli ve değerlendirilmelidir.                                                                                                                                        2-Yutma durumunda yutulan miktar kaydedilmeli ve değerlendirilmelidir. Kusturmadan bilinç kapalı ise ağız yolundan hiçbirşey vermeden doktora danışılmalıdır.                                                                                                                                                    3-Cilde temas durumunda radyoaktif madde dekontaminasyon çözeltileri ile veya sabun ve bol su ile bu iş düzenlenmiş lavaboda yıkanmalıdır. Cilt sertçe ovuşturularak tahriş edilmemelidir.                                                                                                                                                                                                                               4-Bulaşma olan giysi ayakkabı vs. çıkartılmalı ve radyoaktivitesi belli bir seviyeye inene kadar uygun alanda bekletilmelidir.                                                                                                                                                                5-Göze temas durumunda radyoaktif madde bulaşı kalmayana kadar en az 15 dakika bol su ile yıkanmalıdır.Yıkanma esnasında göz açık tutulmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20079\",\"kaynak\":\"ekip\",