SELECT u.`id`, 'Hastane — Birim: MUTFAK YEMEKHANE', 'saglik', NULL, 'fine_kinney', '[{\"anahtar\":\"hst-20101\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: MUTFAK YEMEKHANE\",\"faaliyet\":null,\"tehlike\":\"1-Yangın alarm butonlarının yetersiz olması                                                           2-Acil yönlendirmelerin net görülmemesi\",\"risk\":\"1-Acil durumlarda hızlı müdahalenin sağlanamaması sonucunda durumun etkisinin ve şiddetinin artması\",\"mevcut_onlem\":\"1-Yangın sirenleri mevcuttur.                     2-Yönlendirmeler mevcuttur.\",\"oneri\":\"1-Mutfak alanı içerisinde her koridorda en fazla  60m mesafe için en az 1 tane yangın alarm butonu ve ışıklı ve sesli ikaz sireni bulunmalı, alarm sesi ortam sesinin en az 15 db üstünde olmalıdır.                                                                                                                                                                          2- Yönlendirmeler kapıdan çıkınca direkt görülecek pozisyonda olmalı ve yerden 150 cm yüksekliğe asılmalıdır.                                                                                                                                         3- Yangın algılama sisteminin, yönlendirme sisteminin ve acil anons sisteminin bakımları 6 ayda ve yılda bir periyodik kontrolleri tekrarlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":100,\"frekans\":3},{\"anahtar\":\"hst-20102\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: MUTFAK YEMEKHANE\",\"faaliyet\":null,\"tehlike\":\"1-Acil çıkış kapılarının önüne engel konulması                                              2-Acil çıkış kapılarının iptal edilmesi\",\"risk\":\"1-Acil durumlarda hızlı tahliyenin sağlanamaması sonucunda durumun etkisinin ve şiddetinin artması\",\"mevcut_onlem\":\"1- Acil çıkış kapıları mevcuttur.\",\"oneri\":\"1-Kapıların önüne engel konulmamalıdır.                                                                                                       2- Ana yemekhanede kapatılan acil çıkış kapısı aktif edilmelidir ve ne maksatla olusa  olsun acil çıkış kapıları kullanıma kapatılmamalıdır.                                                                                                                                                                                      3- Panoların, şaftların, pano odalarının,butonların ve sirenlerin  rahat görünmesini engelleyecek hiçbir malzeme bu cihazların odaların önüne -yanına - yakınına konulmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":100,\"frekans\":3},{\"anahtar\":\"hst-20103\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: MUTFAK YEMEKHANE\",\"faaliyet\":null,\"tehlike\":\"1-Topraklama ölçümlerinin yapılmaması, tekrarlanmaması\",\"risk\":\"1- Elektrik çarpması   sonucu yaralanma, ölüm\",\"mevcut_onlem\":\"1-Topraklama ölçümleri yapılmaktadır.                                  2- 30 MA kaçak akım röleleri mevcuttur.\",\"oneri\":\"1- Elektrik tesisatının, panoların, fiş priz sistemlerinin topraklama ölçümleri yıllık olarak yetkili elektrik mühendislerine yaptırılmalıdır.                                                                                                                                                         2- Benmariler dahil tüm elektrikli mutfak ve yemekhane cihazlarının ve taşıma araçlarının gövde topraklama ölçümleri yıllık olarak yaptırılmalı ve kayıt altına alınmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20104\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: MUTFAK YEMEKHANE\",\"faaliyet\":null,\"tehlike\":\"1-Davlumbazlarda yağ birikmesi\",\"risk\":\"1-Yağ birikimi sonucu yangın çıkması\",\"mevcut_onlem\":\"1-Davlumbazlar düzenli aralıkla temizlenmektedir.\",\"oneri\":\"1-Davlumbazlarda yağ ve kir birikimi olmayacak şekilde  davlumbazlar  günlük temizlenerek yağ ve benzeri yanmaya sebep olabilecek maddelerin birikmesi önlenmelidir.                                                                                                                                                                                       2- Ayda en az bir kez davlumbazlar ve bacaları detaylı temizlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20105\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: MUTFAK YEMEKHANE\",\"faaliyet\":null,\"tehlike\":\"1-Ocaklarda açık alev kullanılması\",\"risk\":\"1- Yangın çıkması\",\"mevcut_onlem\":null,\"oneri\":\"1-Ocak etrafında herhangi yanıcı bir madde bulundurulmamalıdır.                                                                             2- Günlük temizlik yapılarak yağ ve benzeri yanmaya sebep olabilecek maddelerin birikmesi önlenmelidir.                                                                                                                                              3- Açık aleve fazla yaklaşılmadan çalışılmalı, elbise tutuşma ihtimali göz önünde bulundurulmalıdır.                                                                                                                                           4- Gaz detektörlerin bakım ve kontrolleri yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20106\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: MUTFAK YEMEKHANE\",\"faaliyet\":null,\"tehlike\":\"1- Seksiyonel kapıda fotosel olmaması\",\"risk\":\"1-Kapının düşmesi sonucu vücut bölümlerinin ezilmesi, yaralanma\",\"mevcut_onlem\":\"1- Periyodik kontrol raporu mevcuttur.\",\"oneri\":\"1-Seksiyonel kapıya altından çalışan geçerken çalışmasını durduracak şekilde fotosel tertibatı yaptırılmalıdır. \\n2-Kapı indirilip kaldırılırken 1 metreden yakın içeride ve dışarıda hiç kimse bulunmamalıdır.\\n3-En geç yılda bir kez TS EN 13241+A2, TS EN 12453, TS EN 12604+A1 standartlarına uygun olarak periyodik bakımları tekrarlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20107\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: MUTFAK YEMEKHANE\",\"faaliyet\":null,\"tehlike\":\"1- Yemek Taşımada kullanılan termoboxların kirli olması\",\"risk\":\"1-Enfeksiyon hastalıklarına yakalanma\",\"mevcut_onlem\":\"1- Termoboxların temizliği günlük yapılmaktadır.\",\"oneri\":\"1- Yemek taşıma için kullanılan  termoboxların içi, dışı günlük temizlenmelidir.                                            2- Termoboxların üzerinde yağ, kir ve toz birikimi önlenmelidir.                                                                    3- Termoboxlar taşıma esnasında streç film ile sarılmalıdır.                                                                                                                        4- Termoboxları taşımak için kullanılan araçlar kirli olmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20108\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: MUTFAK YEMEKHANE\",\"faaliyet\":null,\"tehlike\":\"1-Davlumbaz  söndürme sisteminin periyodik kontrollerinin yapılmaması\",\"risk\":\"1-Yangın çıkması\",\"mevcut_onlem\":\"1-Davlumbazlarda otomatik yangın söndürme sistemi mevcuttur.\",\"oneri\":\"1-Davlumbazlardaki otomatik söndürme sisteminin aylık kontrolleri yapılmalı, en geç yılda bir kez TS ISO 11602-2 standardına göre periyodik kontrol yapılmalıdır.\\n2- 4 yılda bir hidrostatik basınç testi yapılmalı, içindeki söndürme maddeleri yenilenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":40,\"frekans\":2},{\"anahtar\":\"hst-20109\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: MUTFAK YEMEKHANE\",\"faaliyet\":null,\"tehlike\":\"1-Yangın tüp sayısının yetersiz olması\",\"risk\":\"1-Yangın çıkması\",\"mevcut_onlem\":\"1-Koridorlardaki yangın dolaplarında yangın tüpü mevcuttur.\",\"oneri\":\"1- Yağ bulunan depoların önünde ve yağ kullanılan alanların önünde  köpüklü ya da kuru kimyevi tozlu söndürme cihazları konulmalıdır.                                                                                              2- Yağ ya da sıvı madde yangınlarında su kesinlikle kullanılmamalıdır.                                                                                                                                                                        3-Yangın dolaplarının kontrolleri  ve su testi Ayda 1 düzenli olarak yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":40,\"frekans\":2},{\"anahtar\":\"hst-20110\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: MUTFAK YEMEKHANE\",\"faaliyet\":null,\"tehlike\":\"1-Mutfak ve Yemekhane personelinin aynı kıyafeti hastane genelinde kullanması\",\"risk\":\"1-Enfeksiyon hastalıklarına yakalanma\",\"mevcut_onlem\":\"1-Yemekhane ve mutfak  personeli önlük, maske ve bone kullanmaktadır.\",\"oneri\":\"1-Yemekhane ve mutfak  personeli  iş kıyafetini ve ayakkabı/terliğini sadece çalışma alanında kullanmalı, bu ekipmanlar ile çalışma alanı dışına çıkılmamalıdır.                                                                                                                                                  2- Yemekhane ve mutfak  personeli önlük bone ve eldiven kullanmadan çalışmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":10},{\"anahtar\":\"hst-20111\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: MUTFAK YEMEKHANE\",\"faaliyet\":null,\"tehlike\":\"1-Kaygan zemin\",\"risk\":\"1-Kayma, düşme sonucu yaralanma\",\"mevcut_onlem\":\"1-Zemin kayma veya düşmeyi önleyecek şekilde uygun malzeme ile kaplanmıştır.\",\"oneri\":\"1-Çalışma alanlarında dökülen malzemeler veya diğer sebeplerden ötürü kayganlaşmış zeminler ya da geçitler derhal temizlenmeli ve kurulanmalıdır.                                                        2-Temizlik sonrası uyarı levhaları konulmalıdır.                                                                                             3-Çalışanlar ve mutfağa giren ilgili tüm personel kauçuk tabanlı kaymaz ayakkabı giymelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20112\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: MUTFAK YEMEKHANE\",\"faaliyet\":null,\"tehlike\":\"1- Soğuk hava deposunda acil kapı açma butonunun olmaması\",\"risk\":\"1-Mahsur kalma sonucu hipotermi geçirme\",\"mevcut_onlem\":\"1-Soğuk odaların içerisinde alarm butonu mevcuttur.\",\"oneri\":\"1-Soğuk hava depolarında  kapı kolunun arızalanmasına karşı, içeriden açılabillir ilave acil kapı açma butonu takılmalıdır.                                                                                                                                                                                                   2- Acil kapı açma butonu ve alarm butonu erişilebilir yükseklikte olmalı ve önüne malzeme konulmamalıdır.                                                                                                                                           3- Acil kapı açma butonu ve alarm sistemi karanlıkta görülebilir şekilde işaretlenmiş olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20113\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: MUTFAK YEMEKHANE\",\"faaliyet\":null,\"tehlike\":\"1-Yemek yapılan ve dağıtılan alanların kirli olması, yağ birikimi olması\",\"risk\":\"1-Enfeksiyon hastalıklarına yakalanma\",\"mevcut_onlem\":\"1-Ortam temizliği günlük yapılmaktadır.\",\"oneri\":\"1-Paslanmaz tezhgahlar, benmariler ve kullanılan aletler günlük olarak temizlenmelidir.                                                                                                                                                     2-Zemin günlük olarak düzenli temizlenmeli , duvar yüzeyleri haftalık olarak düzenli  temizlenmeli  ve  asma tavan aylık olarak  düzenli temizlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20114\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: MUTFAK YEMEKHANE\",\"faaliyet\":null,\"tehlike\":\"1-Fayansların kirli olması\\n2-Fayansların kırık olması\",\"risk\":\"1-Enfeksiyon          2-Yaralanma\",\"mevcut_onlem\":\"1-Duvarlar kolay temizlenebilir malzemeden yapılmıştır.\",\"oneri\":\"1-Pişirme alanı arkası paslı duvar fayansları yenilenmelidir. Fayans derzlerinde yağ birikimini önlemek için fayans ebatları maksimum büyüklükte seçilip  fayans derz sayıları minumuma indirilmelidir.                                                                                                         2- Kırık fayanslar değiştirilmelidir.                                                                                                               3-Rutubetli duvar yüzeyleri boyanmalıdır.                                                                                                               4- Fayanslarda yağ birikimi önlenmeli günlük oralak temizlenmeldir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20115\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: MUTFAK YEMEKHANE\",\"faaliyet\":null,\"tehlike\":\"1-Prizlerin etanj olmaması\",\"risk\":\"1- Elektrik çarpması                       2-yangın\",\"mevcut_onlem\":\"1-Kaçak akım koruma  rölesi mevcuttur.\",\"oneri\":\"1- Elektriğin su, nem ve buhar ile temas ettiği tüm alanlarda elektrik sistemleri, aydınlatmar ve prizler etanj özellikte olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20116\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: MUTFAK YEMEKHANE\",\"faaliyet\":null,\"tehlike\":\"1-Makina ve ekipmanların elektrik aksamına su veya diğer sıvıların temas etmesi\",\"risk\":\"1- Elektrik çarpması                       2-Ölüm\",\"mevcut_onlem\":\"1-Kaçak akım koruma  rölesi mevcuttur.\",\"oneri\":\"1-Mutfakta kullanılan tüm elektrikli aletlerin kabloları çift izalasyonlu olmalıdır.                                        2- Sabit kablolar kablo kanalı içerisine alınmalıdır.                                                                                                         3- Elektrik kabloları sağlam olmalı, ek ya da izole bant ile bantlanmış kısımlar bulunmamalıdır.                                                                                                                                                    4- Elektrikli ekipmanlar su ve kimyasal içerikli ürünlerden uzakta saklanmalı ve kuru elle kullanılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20117\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: MUTFAK YEMEKHANE\",\"faaliyet\":null,\"tehlike\":\"1-Yükleme rampası (platform asansör) bakımı olmaması\",\"risk\":\"1-Sıkışma                     2- Yaralanma\",\"mevcut_onlem\":\"Yükleme için kullanılan  platform asansör bakımları yapılmaktadır.\",\"oneri\":\"1-Yükleme rampalarının en geç yılda bir kez TS EN 1398 standardına göre yapılmalıdır.                                                                                                                                                                                           2- Yükleme rampalarına araç yanaşırken boşluk kalmamalı, bariyer, kilit sistemi vb. ekipmanlar konulmalıdır.                                                                                                                                       3- Araçlar rampaya yanaşırken kör noktalarda çalışan bulunmamalıdır.                                                     4- Yük indirme, yükleme işleri sırasında yetkisiz kişilerin alana girmesi engellenmeli,  set, bariyer vb. ile alan çevrelenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20118\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: MUTFAK YEMEKHANE\",\"faaliyet\":null,\"tehlike\":\"1-Kızgın yağ, kaynar su kullanılması\",\"risk\":\"1-Devrilme, dökülme sonucunda el, kol ve ciltte yanıklar oluşması\",\"mevcut_onlem\":null,\"oneri\":\"1-Kaplar devrilmeyecek şekilde dengeli konulmalıdır.\\n2-Kızgın yağ ya da sıcak su kaplarına ısıya dayanıklı eldiven olmadan temas edilmemelidir.\\n3-Yağ üzerine su sıçratılmamalıdır.\\n4-Önlük, kaymaz tabanlı çizme, ısıya dayanıklı eldiven gibi kişisel koruyucular kullanılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20119\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: MUTFAK YEMEKHANE\",\"faaliyet\":null,\"tehlike\":\"1-Çöp kovalarının açık olması\",\"risk\":\"1-Enfeksiyon\",\"mevcut_onlem\":\"1-Çöp kovaları mevcuttur.\",\"oneri\":\"1-Çöp kovalarının kapağı her daim kapalı olmalı, sineklenme olmayacak şekilde düzenli boşaltılmalıdır.                                                                                                                                      2-Pedalı bozuk olan çöp kovaları onarılmalı veya değiştirilmelidir.                                           3-Atık odalarının kapıları kapalı tutulmalıdır. Kapıya ait hidrolik yay sistemleri sökülmemelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20120\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: MUTFAK YEMEKHANE\",\"faaliyet\":null,\"tehlike\":\"1-Mutfak çalışanlarının  sağlık kontrollerinin yapılmamış olması\",\"risk\":\"1- Bulaşıcı hastalıklar ve salgın hastalıkların diğer çalışanlara bulaştırma\",\"mevcut_onlem\":\"1-Çalışanların işe giriş raporları ve periyodik kontrolleri yaptırılmaktadır.\",\"oneri\":\"1-Mutfak ve yemekhane çalışanlarının 6 ayda 1 portör muayeneleri yapılmalıdır.\\n2- Hepatit taramaları ve akciğer grafileri yılda bir tekrarlanmalıdır.   \\n3- Bölüme yeni başlayan çalışanlar sağlık taramaları yapılmadan işe başlatılmamalıdır.                                                                                                                                                                                                           4-Sonucu uygun olmayanlar çalışanlar mutfak yemekhane bölümünde çalıştırılmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20121\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: MUTFAK YEMEKHANE\",\"faaliyet\":null,\"tehlike\":\"1-Atık yağlar için yeterli kapasitede taşma havuzu olmaması\",\"risk\":\"1-Kayma, düşme sonucu yaralanma\",\"mevcut_onlem\":\"1-Atık yağlar yükseltilmiş zemindedir.\",\"oneri\":\"1-Atık yağlar için uygun derinlikte ve sızdırmaz, yanmaz ve kıvılcım çıkarmayan malzemeden yapılmış taşma havuzu temin  edilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":40,\"frekans\":1},{\"anahtar\":\"hst-20122\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: MUTFAK YEMEKHANE\",\"faaliyet\":null,\"tehlike\":\"1-Yetersiz aydınlatma\",\"risk\":\"1- Çarpma düşme ya da sıcak yüzeylere temas sonucu yaralanma\",\"mevcut_onlem\":\"1-Aydınlatma ve acil aydınlatmalar mevcuttur.\",\"oneri\":\"1-TS EN  12464-1 standardına göre mutfak aydınlatması 500 lux şiddetinde olması sağlanmalıdır.                                                                                                                                                    2-Aydınlatma sisteminin devre dışı kalmasının çalışanlar için risk oluşturabileceği yerlerde keninden beslemeli acil aydınlatma sistemi bulunmalıdır ve bakımları düzenli olarak yapılmalı ve test edilmelidir.                                                                                                                                                                      3- Yemek pişirme ve hazırlık alanlarında her bir ocak için ve her bir tezgah için   en az 1 acil aydınlatma olacak şekilde acil aydınlatma sayısı arttırılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20123\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: MUTFAK YEMEKHANE\",\"faaliyet\":null,\"tehlike\":\"1-Sıcak yüzeylere temas\",\"risk\":\"1-Cilt yanıklarının oluşması\",\"mevcut_onlem\":null,\"oneri\":\"1-Sıcak yüzeyler izole edilmelidir.\\n2-Sıcak aletlerin üzerinde uyarı işaretleri bulundurulmalıdır.                                                                                                        3-Sıcak mutfak malzemelerinin taşınmasında ısıya dayanıklı eldivenler kullanılmalı, kızartma v.b. Yapılırken yağ sıçramasına karşı önlem alınmalıdır.                                                                                          4- Kızgın yağa su temas etmemesine özen gösterilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":1},{\"anahtar\":\"hst-20124\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: MUTFAK YEMEKHANE\",\"faaliyet\":null,\"tehlike\":\"1-Kuru gıda depolarında haşere ilaçlamasının olmaması\",\"risk\":\"1-Sinek, böcek, fare gibi zararlı canlıların çoğalması ve hastalık yayması\",\"mevcut_onlem\":\"1-Bir çok alanda ilaçlama kutuları mevcuttur.\",\"oneri\":\"1-İlaçlama kutusu olmayan kuru gıda depolarına kutular konulmalıdır.                                                        2- 3 ayda 1 zararlının türüne göre ilaçlama yapılmalıdır.\\n3- Zararlı canlıların yemekhane ve mutfağa ulaşabilecekleri delik ve açıklıklar kapatılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":1},{\"anahtar\":\"hst-20125\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: MUTFAK YEMEKHANE\",\"faaliyet\":null,\"tehlike\":\"1-Gıda maddelerinin ve yemeklerin uygunsuz şartlarda muhafazası, bekletilmesi\",\"risk\":\"1-Gıda zehirlenmesi\",\"mevcut_onlem\":\"1-Bozulma riski olan gıdalar soğuk hava depolarında tutulmaktadır.\",\"oneri\":\"1-Bozulma riski yüksek olan gıda maddeleri (tavuk et vb.), soğuk hava depolarında muhafaza edilmeli, dış alanda fazla bekletilmemelidir.                                                                                                            \\n2-Son kullanma tarihi geçmiş, ambalajı okunmayan, yırtılmış, bombeleşmiş, gözle kontrol edildiğinde hatası bulunan,   etiketsiz, imal ve son kullanma tarihi bulunmayan, etiketi üzerinde ithalat veya üretim izin tarih ve sayısı bulunmayan gıda maddeleri imha edilmeli, kullanılmamalıdır.                                                                                           \\n3-Gıda maddeleri kontrol edilmeden kullanılmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20126\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: MUTFAK YEMEKHANE\",\"faaliyet\":null,\"tehlike\":\"1-Deforme olmuş zemin\",\"risk\":\"1-Düşme sonucu yaralanma\",\"mevcut_onlem\":\"1- Mutfak alanında epoksi zemin mevcuttur\",\"oneri\":\"1-Yemek pişirme  alanı içerisindeki deforme olmuş zemindeki epoksi yüzeyler tamir edilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":2},{\"anahtar\":\"hst-20127\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: MUTFAK YEMEKHANE\",\"faaliyet\":null,\"tehlike\":\"1-Ortamın çok soğuk veya çok sıcak olması\",\"risk\":\"1- Dikkat kaybı, iş kazası ve meslek hastalıklarında artışlar\",\"mevcut_onlem\":\"Çalışma ortamı sıcaklığı çok soğuk ya da çok sıcak değildir.\",\"oneri\":\"1-Çalışma ortamı %35-%75 nem oranında ve 18-24 C derece arasında olması sağlanmalıdır.                                                                                 \\n2-Hava akım hızının 0,5 m/sn ortalamada olması sağlanmalıdır.\\n3-Çalışma ortamının saatte en az 6-10 kez havalandırılması sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":2}]', 0, 0, NOW(), NOW()
