SELECT u.`id`, 'Hastane — Birim: LABORATUVAR', 'saglik', NULL, 'fine_kinney', '[{\"anahtar\":\"hst-20128\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: PATOLOJİ LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- Patoloji Laboratuvarında havalandırma sisteminin yetersiz olması\",\"risk\":\"1-Kimyasal madde buharlarının solunması sonucunda meslek hastalıklarının oluşması\",\"mevcut_onlem\":\"1-Aspirasyon sistemi mevcuttur.\\n2-Havalandırma sisteminin periyodik kontrolü mevcuttur.\",\"oneri\":\"1-Formaldehit, Ksilen kullanılan odalara saatlik temiz hava giriş debi ve saysı  arttırılmalı, kimyasal solunum bölgesine ulaşmadan zeminden atılmalıdır.     \\n2- Havalandırma sisteminin periyodik kontrolleri havalandırma tesisat projesinde yer alan kriterlere göre en geç yılda bir tekrarlanmalıdır.                                                                                                           3-  Kimyasal buharı ve partiküllere karşı kullanılan hepa filtreler ve karbon filtreler en geç yılda bir kez değiştirilmelidir.                                                                                                                                                                                                             4- Patoloji laboratuvarında formaldehit ve ksilen kullanılan bölümlerin kapıları açık bırakılmamalı, kimyasal madde buharının diğer bölümlere yayılması önlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20129\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: PATOLOJİ LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- Patoloji Laboratuvarında Formaldehitin uygunsuz kullanılması\",\"risk\":\"1-Kimyasal madde buharlarının solunması ya da teması  sonucunda meslek hastalıklarının oluşması\",\"mevcut_onlem\":\"1-Çeker ocaklar mevcuttur.\",\"oneri\":\"1- Formaldehit ile yapılan çalışmalar sadece çeker ocak altında yapılmalıdır.                                                                                                                            2- Formadehit kaplarının ağızları kapalı tutulmalı, sadece çeker ocak altında açılmalıdır.                                                                                                                                                              3- Formaldehitin dökülmesi durumunda hemen döküntü kiti kullanılmalı, absorban madde kullanılarak formaldehit buharının çalışma ortamına yayılması önlenmelidir.                                                                                                                                                        4- Formaldehit kullanılan bölümlerde TS EN 143 standadın da ABEK filtreli maske, TS EN 166 gözlük TS EN 13034 Tip 6 kimyasal koruyucu tulum, TS EN 374  nitril eldiven,sıvı geçirmeyen ayakkabı kullanılmalıdır.   \\n5- Eksik KKD\'ler temin edilmeli, çalışanlar tarafından eksiksiz kullanılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20130\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: PATOLOJİ LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- Patoloji Laboratuvarında Formaldehit, Ksilen vb. yanıcı parlayıcı kimyasalların kullanılması\",\"risk\":\"1-Kimyasal maddelerinin elektrikle teması sonucunda parlama, patlama, yangın çıkması\",\"mevcut_onlem\":\"1-Yangın algılama ihbar sistemleri mevcuttur.\",\"oneri\":\"1- Ksilen, Formaldehit vb. parlayıcı kimyasalların bulunduğu bölümlerde fiş, priz,  aydınlatma vb. tüm elektrik tesisatı ve fan motorları kıvılcım çıkarmayan (exproof) özellikte olmalıdır.                                                                                                                                                         2- Bu alanlarda kullanılması zorunlu olmayan hiçbir elektrikli ekipman bulundurulmamalıdır.                                                                                                        \\n3- Elektrik kabloları yanmaz kablo kanalı içerisine alınmalıdır.                                                                                                                                                        4- Parlama, yangın oluşmasını engellemek için belirli periyotlarla VOC ölçümleri yaptırılmalıdır.                                                                                                                             \\n5-Parlama, yangın oluşabilecek alanlar “Ateşle Yaklaşma” vb. levhalar ile işaretlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20131\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: PATOLOJİ LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1-Formaldehit, Ksilen vb. kimyasalların kullandığı alanlarda sulu söndürme sistemleri kullanılması\",\"risk\":\"1-Yangının büyümesi sonucu\",\"mevcut_onlem\":\"1-Yangın algılama ihbar sistemleri mevcuttur.\",\"oneri\":\"1- Ksilen, Formaldehit vb. kimyasal madde yangınlarında söndürme sistemleri (sprink, yangın dolabı) köpüklü sistem olmalıdır.                                                                                                        2-Kimyasal madde yangınlarında su kesinlikle kullanılmamalıdır.                                                 3- Bölüme 50 kg\'lik köpüklü ya da kuru kimyevi tozlu yangın söndürücü konulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20132\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: PATOLOJİ LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- Formaldehit kullanmına bağlı maruziyet\",\"risk\":\"1- Maruziyet durumunda göz cilt iritasyonu\",\"mevcut_onlem\":\"1-Bir çok kkd mevcuttur.\",\"oneri\":\"1-Gözlerle Temas: Lens takılı ise çıkarmalıdır. Göz kapaklarını iyice açarak, derhal ve bol su ile en az 15 dakika yıkanmalıdır.\\n2- Ciltle Temas: Kirlenmiş giysiler çıkarılmalı hemen bol su ile yıkanamlıdır. Tahriş devam ediyorsa, doktora danışıılmalıdır. Kirlenmiş giysiler tekrar kullanmadan önce yıkanmalıdır.\\n3-Solunum: Kişi açık havaya çıkarılmalıdır. Solunum zorluğu çekilmesi halinde, derhal tıbbi yardım aldırılmalıdır.\\nYutma: Sadece doktor tavsiyesi üzerine kusturmaya çalışılmalı bir doktor tarafından izin verilmedikçe, bilinçsiz bir kişiye asla ağızdan bir şey vermemelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20133\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: PATOLOJİ LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1-Patoloji laboratuvarından diğer bölümlere porsiyonlanmadan gönderilmesi\",\"risk\":\"1-Kimyasal madde buharlarının solunması ya da teması  sonucunda meslek hastalıklarının oluşması\",\"mevcut_onlem\":null,\"oneri\":\"1- 21.10.2025 tarihinde hazırlanan Yöntem Beyan\'ına göre firma tarafından bölümlerde kullanılan formaldehit, patoloji laboratuvarında porsiyonlanarak alanlara  gönderilmelidir.                                                                                                     \\n2- Porsiyonlanmış formaldehit kapları, kapalı kaplarda olmalı, kapakları sağlam olmalı, taşıma esnasında açılmamalıdır. \\n3- Formaldehit taşıma arabalarında döküntü kiti bulundurulmalıdır. \\n4- Sürekli kontrol denetim sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20134\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: PATOLOJİ LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- Kişisel Koruyucu ekipmanların eksik olması, kullanılmaması\",\"risk\":\"1-KKD’lerin kullanılmaması sonucunda iş kazaları, meslek hastalıkları oluşması\",\"mevcut_onlem\":\"1- Düzenli aralıklarla ortam temizliği yapılmaktadır.\",\"oneri\":\"1- Kimyasal kullanılan bölümlerde TS EN 143 standardın da ABEK filtreli maske, TS EN 166 gözlük TS EN 13034 Tip 6 anti statik kimyasal koruyucu tulum, TS EN 374  nitril eldiven, sıvı geçirmeyen ayakkabı kullanılmalıdır.                                                                                2- Kan ve vücut sıvıları ile temas olacak uygulamalarda cerrahi eldiven kullanılmalıdır. \\n3- Çalışanlara KKD kullanımı ve önemi hakkında eğitim verilmelidir.\\n4- Laboratuvar komisyonu tarafından kontrol ve denetim sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20135\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: PATOLOJİ LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- Statik elektrik tedbirlerinin yetersiz olması\",\"risk\":\"1-Parlama, patlama, yangın çıkması\",\"mevcut_onlem\":null,\"oneri\":\"1- Bölüm girişine nötralizatör takılmalı, vücuttaki statik elektrik boşaltılarak giriş yapılmalıdır.                                                                                                                                             2- Statik elektriğe sebep olabilecek metal raf, dolap çeker ocak, makine ekipmanlar vb. metal kısımları statik elektriğe karşı topraklanmalıdır.                                                                       3- Çalışanların kişisel koruyucu ekipmanları anti statik özellikte olmalı, statik elektrik oluşturabilecek yünlü vb. kıyafetler giyilmemelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":40,\"frekans\":6},{\"anahtar\":\"hst-20136\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: PATOLOJİ LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- Patoloji arşivi Kimyasal maddelerin dökülme, saçılması\",\"risk\":\"1- Cilt yanıkları ve göz hasarı, \\n2- Alerjik cilt reaksiyonları,                    3- Solunum yolu tahrişi,\\n4- Uzun dönemde kansorejen/ mutajen\",\"mevcut_onlem\":\"1- Patoloji laboratuvarında numunelerin saklandığı odada metal dolaplar bulunmaktadır.\",\"oneri\":\"1- Atık kapakları kontrol edilmeli bozuk, tam kapanmayan kaplar kullanılmamalıdır.\\n2- Numune saklama alanlarında numuneler havalandırmalı dolaplara ağır olanlar alt raflara, hafif olanlar üst raflara olacak şekilde konulmalıdır.\\n3- Atık varillerinin altlarına taşma kapları konulmalıdır.                                                                                                                     4- Numunelerin kaplara boşaltılması esnasında kkdler eksiksiz kullanılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20137\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: PATOLOJİ LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- Patoloji arşiv odasında örneklerin açık raflarda ya da zeminde istiflenmesi\",\"risk\":\"1-Kimyasal madde buharlarının solunması sonucunda meslek hastalıklarının oluşması\",\"mevcut_onlem\":\"1- Patoloji laboratuvarında numunelerin saklandığı odada metal dolaplar bulunmaktadır.\",\"oneri\":\"1- Patoloji örnekleri sadece havalandırması olan, kapaklı metal dolaplarda saklanmalıdır.                                                                                                                                                 2- Eksik metal dolaplar temin edilmelidir.                                                                                                            3-Açık raflara ya da zemine patoloji örnek kapları bırakılmamalıdır.                                                   4- Metal dolaplar duvara en az iki noktadan sabitlenmelidir.                                                                        5- Metal dolapların statik elektrik topraklamaları yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20138\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: PATOLOJİ LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- Delici Kesici Alet Kullanımı\",\"risk\":\"1- Kesilme sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1 Mikrotom bıçağı kullanılma esnasında EN 388 2016 standartlarına uygun kesilmeye dayanıklı eldiven kullanılmalıdır. \\n2- Cerrahi aletlerin temizliğinde malzemeler sterilizasyon birimi tarafından yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20139\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: PATOLOJİ LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- VOC ortam ve kişisel maruziyet ölçümlerinin yapılmamış olması\",\"risk\":\"1- İş kazlarında, Meslek hastalıklarında artış\",\"mevcut_onlem\":null,\"oneri\":\"1- VOC ortam ölçümleri akredite kuruluşlara yaptırılmalıdır.                                                                                        2- Ortam ölçümleri yapılırken kişi maruziyetleri de ölçülmelidir.                                                                                               3- Çıkan sonuçlara göre gereken tedbirler alınmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20140\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: PATOLOJİ LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- Kimyasal madde depolarının uygun olmaması\",\"risk\":\"1-Devrilme dökülme sızıntı durumunda elektrik, kıvılcım kaynağıyla temas parlama, yangın çıkması\",\"mevcut_onlem\":\"1-  MSDS\'ler mevcuttur.                                        2- Yangına dayanıklı dolap mevcuttur.                                       3- Depo girişinde döküntü kiti mevcuttur.\",\"oneri\":\"1- Kimyasal madde deposunda, kimyasal maddeler sızdırmaz toplama hazneli plastik paletler üzerine konulmalı, eksik paletler temin edilmelidir.                                                                                                                                                                    2- Kimyasal madde dolabının statik elektrik topraklaması yapılmalıdır.                                                         3- Kimyasal madde dolabında kimyasallar taşma kaplarının içinde muhafaza edilmelidir.                                                                                                                                                        4- Kimyasallar paletlerin üzerine yüksek istiflenmemeli, dengeli devrilmeyecek şekilde istifleme yapılmalı, en fazla 3 kutu üst üste istiflenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":40,\"frekans\":3},{\"anahtar\":\"hst-20141\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: PATOLOJİ LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- Patoloji laboratuvarında firma tarafından iş güvenliği önlemlerinin yeterince alınmaması\",\"risk\":\"1-İş kazaları ve meslek hastalıkları meydana gelmesi\",\"mevcut_onlem\":\"1-Laboratuvar komisyonu tarafından kontroller yapılmaktadır.\",\"oneri\":\"1-21.10.2025 tarihinde hazırlanan Yöntem Beyanı\'na göre firma tarafından                                                                                                                             - İşe yeni başlayan çalışanların laboratuvarda maruz kalabilecekleri riskler  ve  bölümde kullanılan cihazlar hakkında eğitim alıp almadıkları,                                                                                                                             - Labaratuvar çalışanlarının kişisel koruyucu ekipmanlarının eksiksiz olarak temin edilip edilmediği,                                                                                                                                         - Labaratuvarda yapılması gereken ortam ölçümlerinin yapılıp yapılmadığı                                                                                                                                    - Çalışanlara periyodik olarak yapılması gereken aşı ve muyayenelerinin yapılıp yapılmadığı kontrol edilmelidir.                                                                                                                2- Sürekli saha denetimi kontrol ve gözetim sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20142\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: PATOLOJİ LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- Periyodik sağlık kontrollerinin ve sağlık taramalarının yılda bir tekrarlanmaması\",\"risk\":\"1-Meslek hastalığının gerçekleşmesi erken tanı konulamaması müdahaleye geç kalınması\",\"mevcut_onlem\":\"1- Periyodik muayeneler yapılmaktadır.\",\"oneri\":\"1- Çalışanların, akciğer grafileri, göz muayeneleri, solunum fonksiyon testleri ekg, odyometri ölçümleri, kan ve idrar tahlilleri, ppd testleri  ve işyeri hekiminin talep edeceği diğer tıbbi tetkikler yılda bir kez yapılmalıdır.                                                                                                                                               2- İşe yeni başlayan çalışanlara gerekli tahliller yaptırılmadan işbaşı verilmemelidir.                                                                                                                                   3- Tahlil sonuçları uygun olmayan çalışanlar gerekli tedaviyi alana ve tam iyileşene kadar bölümde çalıştırılmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20143\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: PATOLOJİ LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- Ksilen kullanımına bağlı maruziyet\",\"risk\":\"1- Maruziyet durumunda göz cilt iritasyonu\",\"mevcut_onlem\":\"1-Bir çok kkd mevcuttur.\",\"oneri\":\"1-Gözlerle Temas: Lens takılı ise çıkarmalıdır. Göz kapaklarını iyice açarak, derhal ve bol su ile en az 15 dakika yıkanmalıdır.\\n2- Ciltle Temas: Kirlenmiş giysiler çıkarılmalı hemen bol su ile yıkanamlıdır. Tahriş devam ediyorsa, doktora danışıılmalıdır. Kirlenmiş giysiler tekrar kullanmadan önce yıkanmalıdır.\\n3-Solunum: Kişi açık havaya çıkarılmalıdır. Solunum zorluğu çekilmesi halinde, derhal tıbbi yardım aldırılmalıdır.\\nYutma: Sadece doktor tavsiyesi üzerine kusturmaya çalışılmalı bir doktor tarafından izin verilmedikçe, bilinçsiz bir kişiye asla ağızdan bir şey vermemelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20144\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: TBC LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- TBC Labrotuvarında AARB boyama işlerinde havalandırma sistemi olarak davlumbaz kullanılması\",\"risk\":\"1-Kimyasal madde buharlarının solunması sonucunda meslek hastalıklarının oluşması\",\"mevcut_onlem\":null,\"oneri\":\"1- AARB boyama işleminde, boya havadan ağır olduğu için kirli hava zeminden atılmalı, temiz hava üstten verilecek şekilde aspirasyon sistemi yapılmalıdır.                                                     2-Kimyasal madde buharının çalışma ortamına yayılması önlenmeli,  kimyasal madde buharı solunum bölgesine ulaşmadan zeminden atılmalıdır.                                                                                                    3- Çalışanlar  TS EN 143 standardın da ABEK filtreli maske, TS EN 166 gözlük TS EN 13034 Tip 6 anti statik kimyasal koruyucu tulum, TS EN 374  nitril eldiven, sıvı geçirmeyen aykkabı kullanılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20145\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: TBC LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- TBC Labrotuvarında AARB yanıcı parlayıcı boya kullanılması\",\"risk\":\"1-Kimyasal maddelerinin elektrikle teması sonucunda parlama, patlama, yangın çıkması\",\"mevcut_onlem\":\"1-Yangın algılama ihbar sistemleri mevcuttur.\",\"oneri\":\"1- AARB boyasının kullanıldığı bölümde fiş, priz,  aydınlatma vb. tüm elektrik tesisatı ve fan motorları kıvılcım çıkarmayan (exproof) özellikte olmalıdır.                                                                                                                                                         2- Bütün metal yüzey ve ekipmanların statik elektrik topraklamaları yapılmalıdır.                                                                                                                                                       3- Elektrik kabloları yanmaz kablo kanalı içerisine alınmalıdır.                                                                                                                                                        4- Parlama, yangın oluşmasını engellemek için belirli periyotlarla VOC ölçümleri yaptırılmalıdır.                                                                                                                                      5-Parlama, yangın oluşabilecek alanlar “Ateşle Yaklaşma” vb. levhalar ile işaretlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20146\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: TBC LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- TBC Labrotuvarında AARB boyama işlerinde çakmak kullanımı\",\"risk\":\"1- Yangın çıkması\",\"mevcut_onlem\":null,\"oneri\":\"1- AARB boyama işleminde açık alev (çakmak )kullanılmamalıdır.    \\n2- Elektrikli lam ısıtıcı, Kimyasal fiksatif , su banyosu vb. kullanılmalıdr.\\n3- Kimyasal maddelerin kullanıldığı alanlarda kimyasal maddenin özelliğine göre köpüklü yangın söndürücü veya KKT yangın söndürücü bulundurulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20147\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: TBC LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- AARB boya kullanmına bağlı maruziyet\",\"risk\":\"1- Maruziyet durumunda göz cilt iritasyonu\",\"mevcut_onlem\":\"1-Bir çok kkd mevcuttur.\",\"oneri\":\"1-Gözlerle Temas: Lens takılı ise çıkarmalıdır. Göz kapaklarını iyice açarak, derhal ve bol su ile en az 15 dakika yıkanmalıdır.\\n2- Ciltle Temas: Kirlenmiş giysiler çıkarılmalı hemen bol su ile yıkanamlıdır. Tahriş devam ediyorsa, doktora danışıılmalıdır. Kirlenmiş giysiler tekrar kullanmadan önce yıkanmalıdır.\\n3-Solunum: Kişi açık havaya çıkarılmalıdır. Solunum zorluğu çekilmesi halinde, derhal tıbbi yardım aldırılmalıdır.\\nYutma: Sadece doktor tavsiyesi üzerine kusturmaya çalışılmalı bir doktor tarafından izin verilmedikçe, bilinçsiz bir kişiye asla ağızdan bir şey vermemelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20148\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: TBC LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1-  TBC Labrotuvarında çay, kahve, su içilmesi, gıda maddeleri bulundurulması\",\"risk\":\"1-Meslek hastalıklarına yakalanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Çalışma ortamında yiyecek ve içecek tüketilmemelidir                                                                                2- TBC malzemelerin saklandığı buzdolaplarına yiyecek içecek konulmamalıdır.                                                                                                                                                 3- Sürekli saha gözetimi kontrol ve denetim sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20149\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: TBC LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- TBC Labrotuvarında AARB boyama işlerinde yanıcı kimyasalların lavaboda zeminde birikmesi\",\"risk\":\"1-Yangın meydana gelmesi durumunda şiddetinin artması\",\"mevcut_onlem\":\"1-Yangın algılama ihbar sistemleri mevcuttur.\",\"oneri\":\"1- Atık boya varillerinin altında taşma kapları bulundurlmalı, atık varilleri kilitli olmalıdır.                                                                                                                                                            2-AARB boya bölümüne döküntü kiti temin edilmeli, dökülen boya absorban kullanılarak buharın çalışma ortamına yayılması önlenmelidir.                                                                                    3-  Dökülen boyalar hemen temizlenmeli, lavabo yüzeylerinde ve zeminde birikmesi önlenmelidir.                                                                                                                                 4- Tüm temizlik ekipmanları anti statik özellikte olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20150\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: TBC LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- Kişisel Koruyucu ekipmanların eksik olması, kullanılmaması\",\"risk\":\"1-KKD’lerin kullanılmaması sonucunda iş kazaları, meslek hastalıkları oluşması\",\"mevcut_onlem\":\"1- Düzenli aralıklarla ortam temizliği yapılmaktadır.\",\"oneri\":\"1- Kimyasal kullanılan bölümlerde TS EN 143 standardın da ABEK filtreli maske, TS EN 166 gözlük TS EN 13034 Tip 6 anti statik kimyasal koruyucu tulum, TS EN 374  nitril eldiven,sıvı geçirmeyen ayakkabı kullanılmalıdır.                                                                                2- Kan ve vücut sıvıları ile temas olacak uygulamalarda cerrahi eldiven kullanılmalıdır.                                                                                                                                               3- KKD\'ler bölüme girilmeden giyilmelidir.\\n4- Çalışanlara KKD kullanımı ve önemi hakkında eğitim verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20151\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: TBC LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1-TBC Labrotuvarında numune ekim odasında partiküllerin çalışma ortamına yayılması\",\"risk\":\"1- TBC partiküllerinin yayılması sonucu hastalıklara yakalanma\",\"mevcut_onlem\":\"1-Oda negatif basınçlıdır.\",\"oneri\":\"1- Negatif basınçlı odanın, oda içinde ki hava basınç debisi en az yılda bir kez ölçülmelidir.                                                                                                                                            2- Negatif odanın basıncı, kapı açık olduğunda bile dış ortamdan daha düşük olmalıdır.                                                                                                                                                     3- Numune tüplerinin kapakları sürekli kapalı tutulmalıdır.                                                                4- Makineler çalışırken kapakları açılmamalıdır.                                                                                                                  5- Çalışanlar KKD\'lerini eksiksiz kullanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20152\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: TBC LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- Otoklavın periyodik kontrollerinin yapılmaması\",\"risk\":\"1-Patlama sonucu yangın, uzuv kaybı, kalıcı sağırlık\",\"mevcut_onlem\":null,\"oneri\":\"1- Otoklavın periyodik kontrolü TS EN 285+A1 ve TS EN 13060+A1 standartlarına göre en geç yılda bir kez yapılmalıdır.                                                                                                                     2- Otoklavın hidrolik basınç deneyleri, en yüksek çalışma basıncının 1,5 katı ile yapılmalıdır.                                                                                                                                                    3- Otoklavın kapı switchleri her zaman aktif olmalı, otoklav çalışırken kapıları açılmamalıdır.                                                                                                                                            4- Otoklav dolum ve boşaltılmasında ısıya dayanıklı eldiven kullanılmalı, eldiven yerde bırakılmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20153\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: TBC LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- Periyodik sağlık kontrollerinin ve sağlık taramalarının yılda bir tekrarlanmaması\",\"risk\":\"1-Meslek hastalığının gerçekleşmesi erken tanı konulamaması müdahaleye geç kalınması\",\"mevcut_onlem\":\"1-Çalışanların periyodik sağlık kontrolleri yapılmaktadır.\",\"oneri\":\"1- TBC çalışanlarının QuantiFERON testi,TDT, İGST, Akciğer filmi, Balgam yayma, Balgam kültürü, Klinik muayeneleri en geç yılda bir kez yapılmalıdır.                                                   2- Tahlil sonuçları uygun olmayan çalışanlar gerekli tedaviyi alana ve tam iyileşene kadar bölümde çalıştırılmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20154\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: TBC LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- TBC Labrotuvarında steril olmayan tüplerin açık poşette bırakılması\",\"risk\":\"1-Meslek hastalıklarına yakalanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Steril olmayan tüpler için kapaklı atık kutuları temin edilmelidir.                                         2- Otoklav poşetleri atık kutularına konulmalı, açıkta bekletilmemeli ve kapakları kapalı tutulmalıdır.      \\n3- Kirli tüplerin atık kutularına temas etmemesine dikkat edilmeli, her kullanımdan sonra atık kutusu dezenfekte edilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20155\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: TBC LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1-TBC Labrotuvarına giriş alanında negatif basıncın ölçülmemesi\",\"risk\":\"1- TBC partiküllerinin diğer alanlara yayılması sonucu hastalıklara yakalanma\",\"mevcut_onlem\":\"1- Çift kapı giriş sistemi mevcuttur.\",\"oneri\":\"1- Bölüm giriş alanında negatif basıncın hava basınç debisi en az yılda bir kez ölçülmelidir.                                                                                                                                            2- Negatif basınç, kapı açık olduğunda bile dış ortamdan daha düşük olmalıdır.                                                                                                                                                  3- İlk kapı tam kapanmadan, ikinci kapının açılmama sistemi sürekli aktif olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20156\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: TBC LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- TBC Laboratuvarında Havalandırma sisteminin periyodik kontrollerinin tekrarlanmaması\",\"risk\":\"1-Kimyasal madde buharlarının solunması sonucunda meslek hastalıklarının oluşması\",\"mevcut_onlem\":\"1-Havalandırma sisteminin periyodik kontrolü mevcuttur.\",\"oneri\":\"1- Havalandırma sisteminin periyodik kontrolleri havalandırma tesisat projesinde yer alan kriterlere göre en geç yılda bir tekrarlanmalıdır. \\n2- Partiküllere karşı kullanılan hepa filtreler en geç yılda bir kez değiştirilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20157\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: TBC LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- Ultraviole ışınlarına maruziyet\",\"risk\":\"1- Yanık,\\n2- Cilt kanseri, \\n3- Gözde katarakt\",\"mevcut_onlem\":\"1-  UV lambalarının altında kapak bulunmaktadır.\",\"oneri\":\"1- UV lambaları sayaçlı olmalıdır. Sayaç ömrü tamamladığında değişimi yapılmalıdır.\\n2-  UV lambalarının kapakları her zaman takılı olmalıdır. \\n3-  UV Lambaları çalışanlar bölümdeyken çalıştırılmamalı, mesai bitiminden sonra çalıştırılmalıdır.                                                                  \\n4-UV lambasını kapatmak için odaya girildiğinde kişisel koruyucu ekipmanları kullanılmalıdır.                                                                                                                                        5- UV lambaları Ultraviyole lamba kullanımı hakkında eğitim verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20158\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 3: MİCROBİYOLOJİ LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- Gram boya bölümünde havalandırma sisteminin yetersiz olması\",\"risk\":\"1-Kimyasal madde buharlarının solunması sonucunda meslek hastalıklarının oluşması\",\"mevcut_onlem\":\"1-Havalandırma sisteminin periyodik kontrolü mevcuttur.\",\"oneri\":\"1- Gram boyama işleminde, boya havadan ağır olduğu için kirli hava zeminden atılmalı, temiz hava üstten verilecek şekilde aspirasyon sistemi yapılmalıdır.                                                                                                                                                2-Kimyasal madde buharının çalışma ortamına yayılması önlenmeli,  kimyasal madde buharı solunum bölgesine ulaşmadan zeminden atılmalıdır.                                                                                                                                                                                3- Gram boya bölümünün kapısı açık bırakılmamalıdır.                                                                           4- Çalışanlar  TS EN 143 standardın da ABEK filtreli maske, TS EN 166 gözlük TS EN 13034 Tip 6 anti statik kimyasal koruyucu tulum, TS EN 374  nitril eldiven, sıvı geçirmeyen ayakkabı kullanılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20159\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 3: MİCROBİYOLOJİ LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1-Gram boyama işlerinde yanıcı kimyasalların lavaboda zeminde birikmesi\",\"risk\":\"1-Yangın meydana gelmesi durumunda şiddetinin artması\",\"mevcut_onlem\":\"1-Yangın algılama ihbar sistemleri mevcuttur.\",\"oneri\":\"1- Atık boya varillerinin altında taşma kapları bulundurlmalı, atık varilleri kilitli olmalıdır.                                                                                                                                                                                      2-Gram boya bölümüne döküntü kiti temin edilmeli, dökülen boya absorban kullanılarak buharın çalışma ortamına yayılması önlenmelidir.                                                                                    3-  Dökülen boyalar hemen temizlenmeli, lavabo yüzeylerinde ve zeminde birikmesi önlenmelidir.                       \\n4- Tüm temizlik ekipmanları anti statik özellikte olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20160\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 3: MİCROBİYOLOJİ LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- Gram boya işlerinde yanıcı parlayıcı boya kullanılması\",\"risk\":\"1-Kimyasal maddelerinin elektrikle teması sonucunda parlama, patlama, yangın çıkması\",\"mevcut_onlem\":\"1-Yangın algılama ihbar sistemleri mevcuttur.\",\"oneri\":\"1- Gram boya kullanıldığı bölümde fiş, priz,  aydınlatma vb. tüm elektrik tesisatı ve fan motorları kıvılcım çıkarmayan (exproof) özellikte olmalıdır.                                                                                                                                                         2- Bütün metal yüzey ve ekipmanların statik elektrik topraklamaları yapılmalıdır.                                                                                                                                                                                         3- Elektrik kabloları yanmaz kablo kanalı içerisine alınmalıdır.                                                                                                                                                        4- Parlama, yangın oluşmasını engellemek için belirli periyotlarla VOC ölçümleri yaptırılmalıdır.                                                                                                                                      5-Parlama, yangın oluşabilecek alanlar “Ateşle Yaklaşma” vb. levhalar ile işaretlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20161\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 3: MİCROBİYOLOJİ LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- Gram boyama işlerinde çakmak kullanımı\",\"risk\":\"1- Yangın çıkması\",\"mevcut_onlem\":null,\"oneri\":\"1- Gram boyama işleminde açık alev (çakmak )kullanılmamalıdır.           \\n2- Elektrikli lam ısıtıcı, Kimyasal fiksatif , su banyosu vb. kullanılmalıdr.\\n3- Kimyasal maddelerin kullanıldığı alanlarda kimyasal maddenin özelliğine göre köpüklü yangın söndürücü veya KKT yangın söndürücü bulundurulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20162\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 3: MİCROBİYOLOJİ LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- Kişisel Koruyucu ekipmanların eksik olması, kullanılmaması\",\"risk\":\"1-KKD’lerin kullanılmaması sonucunda iş kazaları, meslek hastalıkları oluşması\",\"mevcut_onlem\":\"1- Düzenli aralıklarla ortam temizliği yapılmaktadır.\",\"oneri\":\"1- Kimyasal kullanılan bölümlerde TS EN 143 standardın da ABEK filtreli maske, TS EN 166 gözlük TS EN 13034 Tip 6 anti statik kimyasal koruyucu tulum, TS EN 374  nitril eldiven, sıvı geçirmeyen ayakkabı kullanılmalıdır.                                                                                2- Kan ve vücut sıvıları ile temas olacak uygulamalarda cerrahi eldiven kullanılmalıdır. \\n3- Çalışanlara KKD kullanımı ve önemi hakkında eğitim verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20163\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 3: MİCROBİYOLOJİ LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- Mikrobiyoloji laboratuvarında göz duşu istasyonun etrafının çevrili olmaması\",\"risk\":\"1- Suyun elektrik ile teması sonucu çarpılma\",\"mevcut_onlem\":null,\"oneri\":\"1- Göz duşu istasyonu, elektrikli cihazlardan uzak korunaklı bir alana taşınmalıdır.                                                                                                                                              2- Göz duşu istasyonun olduğu alana gider yapılmalı, suyun yayılması önlenmelidir.                                                                                                                                                      3-Duşlara sürekli göz ve cilt yıkamaya su sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":40,\"frekans\":1},{\"anahtar\":\"hst-20164\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 3: MİCROBİYOLOJİ LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- Kan transfüzyon merkezinde Elektrik kablolarının uygunsuz olması\",\"risk\":\"1- Elektrik çarpması\",\"mevcut_onlem\":\"1-  Topraklama ölçümleri yaptırılmıştır.\",\"oneri\":\"1- Topraklama ölçümleri yılda bir kez tekrarlanmlaıdır. \\n2- Laboratuvarda makinelerin gövde topraklama ölçümleri yıllık yapılmalıdır.\\n3- Üçlü priz kullanılmamalı, kullanılacaksa eğer halojen free özellikte kullanılmalıdır.\\n4-  Üçlü prizlere üçlü priz takılarak kullanılmamalıdır.                                                                            5- Elektrik kabloları ekli olmamalı, izole bant ile bantlanmış kablolar kullanılmamalıdır.\\n6- Cihazların bakım ve kalibrasyonu yılda bir kez  yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20165\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 3: MİCROBİYOLOJİ LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- Gram boya bölümünde kimyasal madde dolabının statik elektrik topraklamasının olmaması\",\"risk\":\"1-Statik elektrik oluşması sonucu parlama, yangın meydana gelmesi\",\"mevcut_onlem\":\"1- Kimyasal madde dolabı yangına dayanıklı malzemeden yapılmıştır.\",\"oneri\":\"1- Kimyasal madde dolabına statik elektrik topraklaması yapılmalıdır.                                       2- Dolap içine boyalar taşma kaplarının üzerine konulmalıdır.                                                 3- Dolap üzerinde boya birikmesi önlenmeli, dökülen boyalar kurumadan temizlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20166\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 3: MİCROBİYOLOJİ LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- Periyodik sağlık kontrollerinin ve sağlık taramalarının yılda bir tekrarlanmaması\",\"risk\":\"1-Meslek hastalıklarına yakalanma\",\"mevcut_onlem\":\"1-Çalışanların periyodik sağlık kontrolleri yapılmaktadır.\",\"oneri\":\"1- Çalışanların, akciğer grafileri, göz muayeneleri, solunum fonksiyon testleri ekg, odyometri ölçümleri, kan ve idrar tahlilleri, ppd testleri  ve işyeri hekiminin talep edeceği diğer tıbbi tetkikler yılda bir kez yapılmalıdır.                                                                                                                                               2- İşe yeni başlayan çalışanlara gerekli tahliller yaptırılmadan işbaşı verilmemelidir.                                                                                                                                   3- Tahlil sonuçları uygun olmayan çalışanlar gerekli tedaviyi alana ve tam iyileşene kadar bölümde çalıştırılmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20167\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 3: MİCROBİYOLOJİ LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- Mikrobiyoloji laboratuvarında firma tarafından iş güvenliği önlemlerinin yeterince alınmaması\",\"risk\":\"1-İş kazaları ve meslek hastalıkları meydana gelmesi\",\"mevcut_onlem\":\"1-Laboratuvar komisyonu tarafından kontroller yapılmaktadır.\",\"oneri\":\"1-21.10.2025 tarihinde hazırlanan Yöntem Beyanı\'na göre firma tarafından                                                                                                                             - İşe yeni başlayan çalışanların laboratuvarda maruz kalabilecekleri riskler  ve  bölümde kullanılan cihazlar hakkında eğitim alıp almadıkları,                                                                                                                             - Labaratuvar çalışanlarının kişisel koruyucu ekipmanlarının eksiksiz olarak temin edilip edilmediği,                                                                                                                                         - Labaratuvarda yapılması gereken ortam ölçümlerinin yapılıp yapılmadığı                                                                                                                                    - Çalışanlara periyodik olarak yapılması gereken aşı ve muyayenelerinin yapılıp yapılmadığı kontrol edilmelidir.                                                                                                                2- Sürekli saha denetimi kontrol ve gözetim sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20168\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 3: MİCROBİYOLOJİ LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- Mikrobiyoloji laboratuvarı girişindeki kapının temas ile açılması\",\"risk\":\"1- Enfeksiyon ve bulaşıcı hastalıklara yakalanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Laboratuvar kapıları çalışanların açmak için temas etmeyeceği şekilde değiştirlmeli, kayar kapı vb. sistemler kullanılmalıdır.      \\n2-Yetkisiz kişilerin giriş çıkışları engellenmelidir.           \\n3- Laboratuvar kapıları her gün dezenfekte edilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20169\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 3: MİCROBİYOLOJİ LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- Çalışanların kullanılan kimyasallar hakkında bilgi sahibi olmaması\",\"risk\":\"1- İş kazlarına doğru müdahale edilememesi sonucu şiddetin artması\",\"mevcut_onlem\":\"1-MSDS\'ler asılmıştır.\",\"oneri\":\"1- Kullanılan tüm kimyaslların malzeme güvenlik bilgi formları çalışanların görebileceği şekilde asılı olmalı, yıpranan okunmayan msds ler değiştirilmelidir. \\n2- Yeni kimyasal madde eklenmesi durumunda msds asılmalı, çalışanlar bilgilendirilmelidir.                                                                                                                                   3- Çalışanlar malzeme güvenlik bilgi formları hakkında eğitim verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20170\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 3: MİCROBİYOLOJİ LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- Elektrikli cihazların koruyucularının yetersiz olması\",\"risk\":\"1- Hareketli kısımlara kapılma sonucu el kol parmak yaralanmaları\",\"mevcut_onlem\":\"1- Bir çok cihazda akım kesici switch bulunmaktadır.\",\"oneri\":\"1- Mikrobiyoloji laboratuvarında kullanılan tüm elektrikli cihazların kapı akım kesici switchleri aktif olmalıdır.                                                                                                                             2- Çalışanların cihazların operasyon bölgelerine ellerini sokabilecekleri alanlara switchli kapaklar takılmalıdır.                                                                                                                                    3- Cihazın içindeki numune kaplarının devrilmesi, sıkışması vb. durumlarda elektrik akımı kesilmeden müdahale edilmemelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20171\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 3: MİCROBİYOLOJİ LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1- Genetik laboratuvarında giriş alanında sivri uçlu yapıların bulunması\",\"risk\":\"1- Sivri kısımlara çarpma sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Keskin ya da sivri yüzeyler oval hale getirilmelidir.\\n2- Keskin ya da sivri yüzeyler yumuşak bir malzeme ile kaplanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20172\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 3: MİCROBİYOLOJİ LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1-Dinlenme alanının olmaması\",\"risk\":\"1- Psikososyal Risk\",\"mevcut_onlem\":null,\"oneri\":\"1- İcap nöbeti tutan personellere ait dinlenme odası oluşturulmalıdır\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20173\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 3: MİCROBİYOLOJİ LABORATUVARI\",\"faaliyet\":null,\"tehlike\":\"1-Ergonominin yetersiz oluşu\",\"risk\":\"1-Postür bozuklukları sonucunda kas-iskelet sistemi hastalıkları,  sırt, boyun, bel ve baş ağrıları\",\"mevcut_onlem\":\"1- Genetik kan alma ünitesinde kan alma koltuğu mevcut\",\"oneri\":\"1- Kan alma ünitesine bebek ve çocuk hastalardan kan alım esnasında çalışanın uygun pozisyon alabilecek şekilde sedye vb. kullanılmalıdır.       \\n2- Sedye yüksekliği çalışanın rahatsız edici göz ve baş hareketleri ihtiyacını en aza indirecek şekilde olmalıdır.                      \\n3- Sandalyeler ergonomik tasarıma sahip olmalı, gerekli hallerde ayak desteği kullanılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":7,\"frekans\":6}]', 0, 0, NOW(), NOW()
FROM `users` u WHERE u.`email` = 'mozdemir2816@gmail.com' AND NOT EXISTS (SELECT 1 FROM `risk_sablonlari` s WHERE s.`user_id` = u.`id` AND s.`ad` = 'Hastane — Birim: LABORATUVAR');

INSERT INTO `risk_sablonlari` (`user_id`, `ad`, `sektor`, `sektor_adi`, `yontem`, `maddeler`, `paylasildi`, `kullanim_sayisi`, `created_at`, `updated_at`)
SELECT u.`id`, 'Hastane — Birim: ATIK', 'saglik', NULL, 'fine_kinney', '[{\"anahtar\":\"hst-20174\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ATIK\",\"faaliyet\":null,\"tehlike\":\"1-Atık araçlarının hızlı kullanılması\",\"risk\":\"1-Atık araçlarının çalışanlara  çarpması sonucu yaralanma\",\"mevcut_onlem\":\"1-Atık araçları kapalı kasadır.\",\"oneri\":\"1-Atık araçlarına hız sınırlayıcılar takılmalıdır. \\n2-Tıbbi atıkları toplayan araç sayısı arttırılmalıdır.                                                                        3- Otopark içi ve kapalı alanlarda 20 km/s ve hastane bahçesinde 30 km/s hız sınırı limitleri aşılmamalıdır.\\n3-Trafik kurallarına riayet edilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20175\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ATIK\",\"faaliyet\":null,\"tehlike\":\"1-Atık toplayan çalışanların mesleki yeterliliklerinin olmaması\",\"risk\":\"1- Enfeksiyon kapma sonucu hastalıklara yakalanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Atık toplayan çalışanlar \\\"Sağlık Kuruluşları Kaynaklı Tıbbi Atık Toplayıcısı (Seviye 3)\\\"mesleki yeterlilik belgesine sahip olmalıdır.                                                                                              2- Mesleki yeterlilik belgesi eksik olan çalışanlar mesleki yeterlilik merkezlerine gönderilerek belge almaları sağlanmalıdır.                                                                                                                      3- İşe yeni alınan çalışanlar mesleki yeterlilik belgesine sahip olan kişilerden seçilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20176\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ATIK\",\"faaliyet\":null,\"tehlike\":\"1-Atık bekleme odalarının ve geçici atık depolarının kapılarının açık bırakılması\",\"risk\":\"1- Enfeksiyon kapma sonucu hastalıklara yakalanma\",\"mevcut_onlem\":\"1.Uyarı tabelaları bulunmaktadır.\",\"oneri\":\"1- Atık bekleme odalarının kapıları açık bırakılmamalı her zaman kilitli olmalıdır. \\n2- Atık bekleme odalarına kartlı giriş sistemi yapılmalı, yetkisiz kişilerin girişi önlenmelidir.\\n3- Düşen, okunmayan uyarı levhaları değiştirilmelidir.                                                                                                    4- Sürekli saha gözetimi, kontrol ve denetim sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20177\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ATIK\",\"faaliyet\":null,\"tehlike\":\"1- Atık toplayan çalışanların kişisel koruyucu ekipman kullanmaması, ekipmanların uygun olmaması\",\"risk\":\"1-Atık toplayan çalışanların, diğer çalışanlar tarafından fark edilememesi\",\"mevcut_onlem\":null,\"oneri\":\"1- Atıkların toplanması, taşınmasında görevlendirilen çalışanlar, çalışma sırasında eldiven, koruyucu gözlük, maske kullanır, çizme ve turuncu renkli özel koruyucu kıyafet giymelidir.                                                                                                                                                       2- Eksik malzemeler temin edilmeli, çalışanlar tarafından kullanılması sağlanmalıdır.                                                                                                                                                                     3- Tulumlar çalışan başına en az 2 adet temin edilmeli, kullanılan tulum yıkamya gönderilmeli, temiz olan kullanılmalıdır.                                                                                                            4- Tulumlar üzerinde  \\\"TIBBİ ATIK ÇALIŞANI\\\" yazısı bulunmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20178\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ATIK\",\"faaliyet\":null,\"tehlike\":\"1-Atık taşıma araçlarının belirlenmiş güzergahları kullanmaması\",\"risk\":\"1- Enfeksiyon kapma sonucu hastalıklara yakalanma\",\"mevcut_onlem\":\"1. Atık konteynırların da renkli kodlama mevcuttur.\",\"oneri\":\"1- Atıkların bekleme odalarından, geçici depolama alanlarına götürülürken sadece atık asaönsörleri kullanılmalıdır.\\n2-Atık konteynırları temiz alanlardan, insan ve hasta trafiğinin yoğun olduğu bölgelerden taşınmamalıdır.\\n3- Atık asansörleri işaretlenmeli, uyarı levhaları asılmalıdır.\\n4- Atıklar geçici depolama alanlarından, merkez atık depolama alanına taşınırken sadece Yöntem Beyan\'ında belirlenmiş güzergah kullanılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20179\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ATIK\",\"faaliyet\":null,\"tehlike\":\"1- Atık araçların geri gidişlerde sesli ışıklı sinyallarinin çalışmaması\",\"risk\":\"1- Atık araçlarının çalışanlara  çarpması sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1-Atık toplayan araçların geri gidişlerde sesli ışıklı sinyalleri her zaman aktif olmalıdır.                                                                                                                                                                       2-Şoför geri gidişlerde aynalardan mutlaka kör noktaları kontrol etmeli etrafta hiç kimsenin olmadığından emin olmalıdır.                                                                                                                 3-Hastane içinde belirlenen hız limitlerine uyulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20180\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ATIK\",\"faaliyet\":null,\"tehlike\":\"1- Merkez geçici depolama alanında atıkların dışarıda bırakılması\",\"risk\":\"1- Sabotaj sonucu yaralanma, ölüm\",\"mevcut_onlem\":\"1- Evsel atık, Tıbbi atık ve geri dönüşüm atıkları günlük toplanmaktadır.\",\"oneri\":\"1- Tehlikeli atıklar geçici depolama alanı dışında kesinlikle depolanmamalıdır.   \\n2- Tehlikeli atıklar geçici depolama alanında en fazla 180 gün süreyle geçici olarak depolanacak büyüklükte olmalıdır.\\n3-Merkez geçici depolama alanında gece vardiyası için güvenlik görevlisi tarafından kontrolü sağlanmalıdır.\\n4-Her atık türünün depolanacağı bölme üzerinde; atık türünü belirten levhalar hasar görmesi durumunda yenilenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20181\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ATIK\",\"faaliyet\":null,\"tehlike\":\"1- Atık konteynırlarının geçici atık depolarının dışında bırakılması\",\"risk\":\"1- Enfeksiyon kapma sonucu hastalıklara yakalanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Atık konteynırları, asansör önlerinde, koridorlarda vb. yerlerde bekletilmemeli, geçici atık depolarına konulmalıdır.                                                                                                                                     2- Konteynırların kapakları açık bırakılmamalıdır.                                                                                             3- Atık konteynırlarının kapı, duvar asansör vb. yüzeylere temas etmemesine özen gösterilmelidir.                                                                                                                                                                 4-Temas eden yerler hemen dezenfekte edilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20182\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ATIK\",\"faaliyet\":null,\"tehlike\":\"1- Atık bekleme odalarının ve geçici depolama alanlarının temiz olmaması\",\"risk\":\"1- Enfeksiyon kapma sonucu hastalıklara yakalanma\",\"mevcut_onlem\":\"1-Günlük temizlik yapılmaktadır.\",\"oneri\":\"1- Atık bekleme odalarında  ve geçici depolama alanlarının atıklar 48 saatten fazla bekletilmemelidir.                                                                                                                                                                        2- Atık bekleme odalarında  ve geçici depolama alanlarının atıklar poşetler yere bırakılmamalı, atık tipine uygun konteynırlara atılmalıdır.                                                                          3- Atık bekleme odaları   ve geçici depolama alanlarının yüzeyleri, kapıları, kapı kolları, duvarları her gün dezenfektanlar ile temizlenmelidir.                                                                                 4- Geçici depolama alanında oda ısısı +4 °C olması sağlanamalıdır.                                                                     5- Atık bekleme odalarında havalandırma sistemi her zaman aktif olmalı, koku oluşması önlenmeldir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20183\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ATIK\",\"faaliyet\":null,\"tehlike\":\"1- Firmanın atıkların toplanması, depolanması, taşınması vb. işlerde iş güvenliği tedbirlerini almaması\",\"risk\":\"1- İş kazası ve bulaşıcı hastalıklarda artış\",\"mevcut_onlem\":\"1-Atık türüne uygun konteynır ve torbalar mevcuttur.   2- Atık bekleme odaları ve geçici depolama alanları mevcuttur.\",\"oneri\":\"1-Atık odalarının günlük olarak temizlenip, dezenfekte edildiği kontrol edilmelidir. \\n2- Bekleme odasından alınan atıkların belirlenmiş güzergah ve asansörlerden geçici depolama alanlarına götürüldüğü kontrol edilmelidir. \\n3- Atık konteynırlarının boşaltıldıktan sonra dezenfekte edilip edilmediği kontrol edilmelidir. \\n4- Atıkların hergün belirlenmiş zaman aralığında toplanıp toplanmadığı kontrol edilmelidir.\\n5-Atık işlerinin iş güvenliği kurallarına uygunluğunu sağlamak için sürekli saha gözetimi kontrol ve denetim sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20184\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ATIK\",\"faaliyet\":null,\"tehlike\":\"1- Tehlikeli atık geçici depolama alanının uygunsuz olması\",\"risk\":\"1.Parlama , patlama yangın meydana gelmesi\",\"mevcut_onlem\":\"1- Aydınlatma exproof özelliktedir.\",\"oneri\":\"1- Yanıcı tehlikeli atık depolama odasında kullanılan tüm elektrik sistemleri exproof özellikte olmalıdır.\\n2- Patlamadan korunma dokümanı hazırlanmalıdır.\\n3- Metal kısımların kapı vs. statik elektrik topraklamaları yapılmalıdır.\\n4- Elektrik kabloları, yanmaz kablo kanalı içine alınmalıdır.\\n5- Exproof ekipmanların periyodik kontrolleri en geç yılda bir yapılmalı ve belgelenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20185\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ATIK\",\"faaliyet\":null,\"tehlike\":\"1-Tehlikeli atıkların uygunsuz taşınması\",\"risk\":\"1-Tehlikeli atıkların dökülmesi devrilmesi sonucu iş kazaları meydana gelmesi\",\"mevcut_onlem\":null,\"oneri\":\"1-Tehlikeli atık varil ya da kaplarının ağızları kapalı tutulmalı, kilitleri varsa kilitlenmelidir.                                                                                                                                                                 2- Tehlikeli atıklar toplandıktan sonra araçta ya da diğer alanlarda bekletilmemeli hemen merkez geçici depolama alanına götürülmelidir.                                                                                          3- Tehlikeli atıklar etrafı kapalı kasalarda taşınmalı, kasaların yanında döküntü kiti bulunmalıdır.                                                                                                                                                                            4-Tehlikeli atıklar sabitlenerek taşınmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20186\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ATIK\",\"faaliyet\":null,\"tehlike\":\"1- Atık konteynırlarının dezenfekte edilmeden tekrar kullanıma gönderilmesi\",\"risk\":\"1- Enfeksiyon kapma sonucu hastalıklara yakalanma\",\"mevcut_onlem\":null,\"oneri\":\"1-Atık konteynırları boşaltıkdıtan sonra dezenfektanlarla yıkanmalıdır.\\n2- Yıkanmış konteynerlar kimyasaldan arındırılmış şekilde alana temiz ve kokusuz teslim edilmelidir.\\n3- Atık komisyonunun kontrolünden geçmeyen temizlenmiş konteynerlar alana verilmemelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20187\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ATIK\",\"faaliyet\":null,\"tehlike\":\"1- Merkez geçici depolama alanında tehlikeli atıkların uygunsuz yerleşimi\",\"risk\":\"1-Yangın meydana gelmesi\",\"mevcut_onlem\":\"1- Döküntü kiti mevcuttur.                                                              2- Oda girişinde 50 kg\'lik yangın söndürme tüpü mevcuttur.\",\"oneri\":\"1. Odada havalandırma sistemi olmalıdır.\\n2. Yanıcı atıkları yüksek istiflenmemelidir. En fazla 2 varil üst üste konmalıdır.\\n3. Zemine dökülen atıklar bekletilmemeli, hemen temizlenmelidir.\\n4. Dökülme Kiti bulundurulmalıdır.\\n5. Tehlikeli atıklar paletlerin üzerine istiflenmemeli, atık kapları taşkan havuzlarına konulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20188\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ATIK\",\"faaliyet\":null,\"tehlike\":\"1- Atıkların karıştırılması\",\"risk\":\"1- Enfeksiyon kapma sonucu hastalıklara yakalanma\",\"mevcut_onlem\":\"1. Atık konteynırların da renkli kodlama mevcuttur.\",\"oneri\":\"1- Atıklar renk kodlarına göre ayrıştırılmalıdır.\\nMAVİ: Kâğıt / Karton atıkları için,\\nSARI: Plastik atıklar için sarı,\\nYEŞİL: Cam atıklar için,\\nGRİ: Metal atıklar için,\\nKAHVERENGİ: Organik atıklar için,\\nSİYAH: Geri dönüşemeyen atıklar için,\\nTURUNCU: Tıbbi atıklar için poşetlerde kırmızı, kova konteynerlerde turuncu,\\nŞEFFAF: Tehlikeli atıklar ve elektronik atıklar için                                                                             2- Atık ayrıştırılması konusunda tüm çalışanlara eğitim verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":3}]', 0, 0, NOW(), NOW()
FROM `users` u WHERE u.`email` = 'mozdemir2816@gmail.com' AND NOT EXISTS (SELECT 1 FROM `risk_sablonlari` s WHERE s.`user_id` = u.`id` AND s.`ad` = 'Hastane — Birim: ATIK');

INSERT INTO `risk_sablonlari` (`user_id`, `ad`, `sektor`, `sektor_adi`, `yontem`, `maddeler`, `paylasildi`, `kullanim_sayisi`, `created_at`, `updated_at`)
SELECT u.`id`, 'Hastane — Birim: YOĞUN BAKIM ve PACU', 'saglik', NULL, 'fine_kinney', '[{\"anahtar\":\"hst-20189\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: YOĞUN BAKIMLAR ve PACU\",\"faaliyet\":null,\"tehlike\":\"1-Çalışanların fazla mesai ile çalışması                                                          2- İş yükünün fazla olması\",\"risk\":\"1-Dikkatin azalması, yorgunluk, uykusuzluk, sonucunda iş kazalarının oluşması\",\"mevcut_onlem\":null,\"oneri\":\"1-Tüm yoğun bakım ve PACU ünitesinde  fazla mesai süreleri uygun koşullarda planlamalıdır.                                                                                                                                             2- 24 saatlik nöbetten sonra çalışanlara en az 24 saat dinlenme süresi verilmelidir.                               3- Yoğun bakımlarda 3. basamak için her iki hastaya bir çalışan, 2. basamak için her üç hastaya bir çalışan, 1. basamak için her dört hastaya bir çalışan görevlendirilmelidir. (Hekimdışı personel)                                                                                                                                                  4-Çalışanların düzenli sağlık kontrolleri yapılmalı ve yeterli dinlenme süreleri sağlanmalıdır.                                                                                                                                                                                                                                                                                                                                                    5- Yorgunluk ve stres yönetimi için psikososyal destek programları sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20190\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: YOĞUN BAKIMLAR ve PACU\",\"faaliyet\":null,\"tehlike\":\"1- Pendant üzerindeki prizlerin ya da jakların yerinden çıkması\",\"risk\":\"1- Elektrik çarpması ya da gaz sızıntısı sonucu yaralanma\",\"mevcut_onlem\":\"1-Talep halinde arızalar için kurum içerisinde firma teknik birim tarafından takip edilmektedir.\",\"oneri\":\"1- Bozuk yerinden çıkmış priz ve jaklar kullanılmamalı, değiştirilmelidir.                                                                                                              2- Fişler prizlerden çekilirken kablodan asılarak çekilmemeli, fişten tutarak çıkarılmalıdır.                                                                                                                                                                         3- Gaz hortumları zorlanarak takılmamalı, jaka dik oturtularak takılmalıdır.                                                                                                                       4- Jaklar kullanılmadığında tam kapatılmalıdır.      \\n5- Hortum ağırlığının jakları zorlamaması için destekler kullanılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20191\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: YOĞUN BAKIMLAR ve PACU\",\"faaliyet\":null,\"tehlike\":\"1-Elektrikli medikal cihazlarda (Mekanik ventilatör ,CPAP/BiPAP cihazları,Aspiratör cihazı,Hasta monitörü, İnfüzyon pompaları, Defibrilatör vb.) kablolarının hasarlı veya dağınık olması\",\"risk\":\"1- Kablolara takılıp düşme sonucu yaralanma                                2- Elektrik çarpması\",\"mevcut_onlem\":\"1-Cihazların yılda bir kez kalibrasyonları yapılmaktadır.                                      2-30 MA kaçak akım röleleri mevcuttur.\",\"oneri\":\"1-Tüm yoğun bakım ve PACU ünitesinde cihazların periyodik bakım ve kalibrasyonların yapılmalı, yılda bir kez tekrarlanmalıdır.                                                                                                                                                       2- Cihazların gövde topraklama ölçümleri yapılmalıdır.                                                                             3- Kullanım öncesi kablo ve priz kontrolleri yapılmalı, hasarlı izalasyonu bozulmuş kablolar, kırk yerinden çıkmış prizler değiştirilmelidir.                                                                                                                                                                                                                                                                                                                                                                                                                                               4- Cihazlar yeterli mesafeye yerleştirilmeli, kablolar dağınık olmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20192\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: YOĞUN BAKIMLAR ve PACU\",\"faaliyet\":null,\"tehlike\":\"1-Çalışanların mutfak/dinlenme alanlarında elektrikli ev aletleri kullanımı\",\"risk\":\"1-Yangın sonucu yaralanma                                                  2-Elektrik çarpması\",\"mevcut_onlem\":\"1-30 mA kaçak akım röleleri mevcuttur.                           2-Elektrik tesisatı ve topraklama ölçümü mevcuttur.\",\"oneri\":\"1- Mutfak olarak tanımlanmış alanlarda sadece çay ve kahve makinesi kullanılmalı, bunların dışındaki aletlerin kullanımı yasaklanmalıdır.                                                                                                          2- Sadece çift termostatlı çay kahve makineleri makineleri kullanılmalıdır.                                                                                                                         3- Çay kahve makineleri direk fişe takılmalı, uzatma kablolarına takılmamalıdır.                                                                                                                4- Çay kahve makineleri kullanıldıktan sonra fişten çıkarılmalıdır.                                                                                  5- Elektrikli cihazlara ıslak elle temas edilmemelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20193\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: YOĞUN BAKIMLAR ve PACU\",\"faaliyet\":null,\"tehlike\":\"1-KKD’lerin eksik olması,                           2- KKD\'lerin çalışanlar tarafından kullanılmaması\",\"risk\":\"1-KKD’lerin kullanılmaması sonucunda iş kazaları, meslek hastalıkları oluması\",\"mevcut_onlem\":\"1-Yeterli KKD mevcuttur.                     2-Çalışanlara KKD eğitimi verilmektedir.\",\"oneri\":\"1-KKD’ler CE belgeli ve ilgili standartlara uygun olmalı, eksik olan kkd\'ler temin edilmelidir.\\n2- Çalışanların maskeleri N95 ya da TS EN149 A1 standardında,göz koruyucuları TS EN 166 standardına uygun ve tam kapalı tip, iş eldivenleri TS EN 455 standardına, kesilmelere dayanıklı TS EN 388 standardına, çalışanların önlükleri sıvı geçirmez önlük/ cerrahi önlük TS EN ISO 13688 ve TS EN 13795 standartlarında iş ayakkabıları kaymaz tabanlı olmalıdır.                                                                                                                                                                                                 3- Bütün kişisel koruyucular çalışanlara zimmetlenmelidir.                                                                       4- Kişisel koruyucu donanımlar çalışanlar tarafından eksiksiz kullanılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20194\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: YOĞUN BAKIMLAR ve PACU\",\"faaliyet\":null,\"tehlike\":\"1-Tehlikeli kimyasalların yanlış depolanması\",\"risk\":\"1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması                                 2- Yangın meydana gelmesi\",\"mevcut_onlem\":\"1- Kimyasallar depo alanında depolanmaktadır.\",\"oneri\":\"1- Kimyasal maddeler depolama matirsine göre depolanmalıdır.                                                        2- Yanıcı kimyasallar elektrik kaynaklarından uzak depolanmalıdır.                                                                               3- Kimyasal maddelerin ağzı açık olmamalı, dik olarak istiflenmelidir.                                              4- Ağzı açılmış kimyasal madde kaplarının altına taşma kapları konulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20195\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: YOĞUN BAKIMLAR ve PACU\",\"faaliyet\":null,\"tehlike\":\"1- Kimyasal madde deposunda göz duşu ve döküntü kiti bulunmaması                                               2- Çalışanların kimyasallar hakkında bilgi sahibi olmaması\",\"risk\":\"1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması\",\"mevcut_onlem\":\"1- Kimyasallar depo alanında depolanmaktadır.\",\"oneri\":\"1- Kimyasalların dökülme riskine karşı döküntü kitleri bulundurulmalıdır.                                         2- Göze kaçma riskine karşı göz duşu solüsyonu bulundurulmalıdır.                                              3- Kimyasal maddelere gözlük, eldiven olmadan temas edilmemelidir.                                                               4-Kimyasal maddelerin malzeme güvenlik bilgi formları depoda asılı olmalıdır.                              5- Çalışanlara MSDS ve kimyasalların güvenli kullanımı konusunda eğitimler verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20196\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: YOĞUN BAKIMLAR ve PACU\",\"faaliyet\":null,\"tehlike\":\"1-Basınçlı tüplerin hatalı kullanılması\",\"risk\":\"1- Tüplerin düşmesi, devrilmesi sonucu patlama meydana gelmesi\",\"mevcut_onlem\":\"1-Oksijen tüpü sabitleme aparatları bulunmaktadır.                            2-Çalışanlara basınçlı tüplerin güvenli kullanımı konusunda eğitim verilmektedir.\",\"oneri\":\"1-Tüm yoğun bakım ve PACU alanlarında tüpler dikey ve zincir/kelepçe ile en az 2 noktadan sabitlenmelidir.                                                                                                                                2- Basınç göstergeleri ve vanaların her kullanımdan önce kontrol edilmelidir.                                    3- Oksijen tüpleri ısı, kıvılcım ve yanıcı maddelerden uzakta depolanmalıdır.                                            4- Tüp vanalarının yavaşça açılmalı, ani basınç değişiminden kaçınılmalıdır.                                                                                                                               5-Oksijen tüplerine yağlı el, yağlı eldiven, gres yağı ile temas edilmemelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20197\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: YOĞUN BAKIMLAR ve PACU\",\"faaliyet\":null,\"tehlike\":\"1-Yoğun bakım ve Pacu alanlarında hijyen tedbirlerinin yeterli olmaması\",\"risk\":\"1-Enfeksiyon hastalıklarına yakalanma, meslek hastalıkları\",\"mevcut_onlem\":\"1-KKD\' ler mevcuttur.\",\"oneri\":\"1- Yoğun bakımların havalandırılması ve temizliği denetlenmelidir.\\n2- Tıbbi ve medikal cihazların her kullanımdan sonra belirlenmiş olan kimyasallar ile dezenfekte edilip edilmediği kontrol edilmelidir.\\n3- Çalışanlar tarafından KKD kullanımı denetlenmelidir.\\n4- Çalışanların hijyen kurallarına uyup uymadıkları ve el hijyeni malzemelerinin yeterli miktarda olup olmadığı denetlenmelidir.\\n5- Çalışanlara el hijyeni eğitimleri verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20198\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: YOĞUN BAKIMLAR ve PACU\",\"faaliyet\":null,\"tehlike\":\"1-Hastaların taşınması ve pozisyon verilmesi\",\"risk\":\"1-Düşme ve travma                                       2-Kas-iskelet yaralanmaları\",\"mevcut_onlem\":\"1-Hastalar birden fazla kişi tarafından taşınmaktadır.                                      2- Çalışanlara elle kaldırma ve taşıma eğitimi verilmektedir.\",\"oneri\":\"1- Tüm yoğun bakım ve PACU alanlarında hasta taşıma için kaydırma örtüsü, hasta kaldırma lifti, tekerlekli sandalye, sedye gibi ekipmanlar kullanılmalıdır.     \\n2- Yatak kenarlıkları kaldırılmalı, frenlerin kilitlenmelidir. Kateter, dren ve monitör bağlantılarının sabitlenmelidir. \\n3- Hastalara pozisyon verme ve taşıma esnasında en az 2 kişi tarafından yapılmalıdır. Zemin kuru ve güvenli olmalıdır. \\n 4- Çalışanlara elle kaldırma ve taşıma için eğitim verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20199\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: YOĞUN BAKIMLAR ve PACU\",\"faaliyet\":null,\"tehlike\":\"1- Kan ve vücut sıvılarının göz ve cilde temas etmesi\",\"risk\":\"1-Temas sonucu enfeksiyon, bulaşıcı hastalıklara yakalanma\",\"mevcut_onlem\":\"1-KKD\' ler mevcuttur.                                   2-Çalışanlara KKD\'lerin kullanımı ve önemi hakkında eğitimler verilmektedir .\",\"oneri\":\"1-Çalışanlar TS EN 455  standardında eldiven, N95 ya da TS EN 149 standardında maske, TS EN 166 standardında tam kapalı gözlük ya da yüz siperi, uzun kollu koruyucu önlük  EN 14683 standardında vb. gibi kişisel koruyucu donanımlar kullanılmalıdır.                                                                                                                                                                                      2- Temas durumunda bölgenin bol su ve sabunla yıkanması sağlanmalıdır.                                                                                                                                    3- Kan ve vücut sıvıları sıçramasına maruz kalma sonrası çalışanın, bulaş kaynağının durumuna göre muayene ve tetkikleri yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20200\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: YOĞUN BAKIMLAR ve PACU\",\"faaliyet\":null,\"tehlike\":\"1- Kesici delici aletlerin emniyetsiz kullanılması\",\"risk\":\"1- Kullanılmış aletlere temas sonucu el kol yaralanmaları, enfeksiyon, bulaşıcı hastalıklara yakalanma\",\"mevcut_onlem\":\"1- Kesici delici alet kutuları mevcttur.                2-Çalışanlara kesici delici aletlerin güvenli kullanımı konusunda eğitim verilmektedir.\",\"oneri\":\"1- Kullanılmış iğne ve kesici aletler, kesici delici alet kutusuna atılmalıdır.                                                                                                                           2- Çalışanlar tedavi tepsisi kullanmalı, iğne kapağı kapatılmadan kesici delici alet kutusuna atılmalıdır.                                                                                                                               3- Kesici delici alet kutuları en fazla 2/3 dolduğunda yenisi ile değiştirilmeli, kutuların kapakları açık bırakılmamalıdır.                                                                                                                   4-  Kesici delici alet kutuları devrilmeyecek şekilde konumlandırılmalıdır.                                                             5- Çalışanlar TS EN 455 standardında çift eldiven kullanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20201\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: YOĞUN BAKIMLAR ve PACU\",\"faaliyet\":null,\"tehlike\":\"1-Steril olmayan, kontamine olmuş aletlerin açıkta bırakılması\",\"risk\":\"1-Steril olmayan aletlere temas sonucu iş kazaları enfeksiyon, bulaşıcı hastalık\",\"mevcut_onlem\":\"1-KKD\'ler mevcuttur.                                         2- Atık kutuları mevcuttur.\",\"oneri\":\"1-Kullanılan, kontamine olmuş aletler bekletilmeden hemen kapaklı ve renk kodlu atık kutularına atılmalıdır.                                                                                                                           2- Sterilazyona gidecek aletlere TS EN 388 standardında kesilme ve delinmeye dayanıklı eldiven olmadan temas edilmemeli, çelik, kapaklı kutulara konulmalıdır.                                                                                                                                                        3- Tek kullanımlık olmayan aletler her kullanımdan sonra dezenfekte edilmelidir.                                                                                                                                                                                     4- Kontamine olmuş aletler, çarşaf, yatak, yorgan vb. yere saplanmamalı, yere atılmamalıdır.                                                                                                                                                          5- Temas edilmesi durumunda, bölge bol su ve sabunla yıkanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20202\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: YOĞUN BAKIMLAR ve PACU\",\"faaliyet\":null,\"tehlike\":\"1-Defibralatörün hatalı kullanılması\",\"risk\":\"1-Defibrilatör kullanımı sırasında elektrik çarpması, elektrik yanıkları oluşması\",\"mevcut_onlem\":\"1-Defibralatörün periyodik kontrolü yapılmaktadır.\",\"oneri\":\"1-Defibrilasyon esnasında hastaya elektrotlara ve diğer iletken nesnelere dokunulmamalıdır.\\n2-Hastaya ıslak  ve iletken ortamlarda defibrilasyon uygulanmamalı, hastanın göğsünde ıslaklık, jel, ter olmamalı, hastanın göğüsü kurulanmalıdır.\\n3-Defibrilatör cihazı oksijen tüpü, alkol vb. yanıcı sıvı ve gazların bulunduğu ortamlarda kullanılmamalıdır.                                                                                                                                                            4- Hastanın ve defibilatörü kullanan çalışanın üzerinde metal eşyalar bulunmamalıdır.                                                                                                                                                                                  5- Ortamda bulunan diğer çalışanlar en az 1 metre uzakta bulunmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20203\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: YOĞUN BAKIMLAR ve PACU\",\"faaliyet\":null,\"tehlike\":\"1-Pendatlarda gaz kaçağı(oksijen, azot, azotprotoksit, karbondioksit) olması\",\"risk\":\"1-Baş dönmesi, sersemlik, uyku hali bulantı, konsatrasyon bozukluğu oluşması\",\"mevcut_onlem\":\"1-Talep halinde arızalar için kurum içerisinde firma teknik birim tarafından takip edilmektedir.\",\"oneri\":\"1- Çalışanlar pendant sistemi üzerinde gaz kaçağı (tıslama hava çıkış sesi vb.) tespit edilmesi durumunda hemen yetkililere haber vermeli, terminal çıkışı kapatılmalıdır.                                                                                                                                                  2- Kaçak olan pendant da tüm gazlar kesilmelidir.                                                                                           3- Gaz kaçağı olan alanda elektrikli hiç bir alet kullanılmamalı, ateş kıvılcım kaynağı bulundurulmamalıdır.                                                                                                                                                4-Gaz kaçak kaynağı (conta, hasarlı hortum, bağlantı eleamanlarında gevşeme ) tespit edilmelidir.                                                                                                                                            5- Arıza giderildikten sonra sızdırmazlık testi yapılmadan pendant aktif hale getirilmememlidir.                                                                                                                                                                                                6- Pendatların en az yılda bir kez mekanik, sızdırmazlık ve basınç testleri yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20204\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: YOĞUN BAKIMLAR ve PACU\",\"faaliyet\":null,\"tehlike\":\"1-Pendantların üzerine sıvı konulması ve serum askılarının kırık olması\",\"risk\":\"1-Elektrik çarpması\",\"mevcut_onlem\":\"1-Talep halinde arızalar için kurum içerisinde firma teknik birim tarafından takip edilmektedir.\",\"oneri\":\"1-Pendatlar üzerine sıvı malzemeler bırakılmamalıdır.                                                                                                                               2- Pendant üzerine sıvı dökülmesi halinde kağıt havlu ile hemen silinmeli, priz veya valflere sıvı girmesi önlenmelidir.                                                                                                                          3- Prizlere sıvı kaçması durumunda hemen yetkililere haber verilmeli, pendant kullanılmamalı, gerekirse elektrik akımı kesilmelidir.                                                                                    4- Kırık olan serum askıları yenileri ile değiştirilmeli ve sabitlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20205\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: YOĞUN BAKIMLAR ve PACU\",\"faaliyet\":null,\"tehlike\":\"1-Diyaliz atık giderlerinin tıkanması/taşması\",\"risk\":\"1-Kontamine atık suların zemine taşması  sonucu kayma, düşme ve yaralanma, temas sonucu elektrik çarpması\",\"mevcut_onlem\":\"1-Atıklar için ayrı bir gider bulunmaktadır.\",\"oneri\":\"1- Diyaliz giderlerinde tıkanma, taşma olması durumunda hemen cihazın elektrik bağlantıları kesilmeli, suyun elektrik ile temas etmesi önlenmelidir.                                                                                       2-Taşma sonrasında yüzey ve zeminler derhal dezenfektanlarla temizlenmeli, taşma sırasında oluşabilecek biyolojik atık,  atık torbaları atılmalıdır.                                                          3- Diyaliz makinesi filtreleri düzenli aralıklar ile değiştirilmelidir.                                                                  4-Giderler düzenli aralıklar ile kontrol edilmeli tıkanması önlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20206\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: YOĞUN BAKIMLAR ve PACU\",\"faaliyet\":null,\"tehlike\":\"1-Yoğun bakım acil çıkış kapılarından yetkisiz giriş yapılması\",\"risk\":\"1-Güvenlik ihlali, hırsızlık, sabotaj\",\"mevcut_onlem\":\"1- Yoğun bakımlarda manyetik kilit sistemi mevcuttur.\",\"oneri\":\"1-Otopark katından direk yoğun bakım bölümlerine yetkisiz giriş ve çıkışlar engellenmelidir önlenmelidir.                                                                                                                                                             2-Manyetik tutucular periyodik olarak kontrol edilmeli, aktif olması sağlanmalıdır.                                                            3- Yoğun bakımlara yetkisiz giriş görüldüğünde derhal güvenliğe haber verilmelidir.                                                                                                                                                                                      4- Güvenlik birimi tarafından düzenli devriye ve denetim yapılmalıdır.                                              5-Panik butonları her zaman çalışır durumda olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20207\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: YOĞUN BAKIMLAR ve PACU\",\"faaliyet\":null,\"tehlike\":\"1-Kesici delici aletlerin ortalıkta bulunması (Makas, enjektör vb.)\",\"risk\":\"1-Çalışan hasta ve yakınları için kesici delici alet yaralanması\",\"mevcut_onlem\":\"1- Çalışanların zimmetleri vardır.\",\"oneri\":\"1- Kesici delici aletler sadece belirlenen alanlarda bulundurulmalıdır.\\n2- Kullanım sonrası hemen toplanmalı ve güvenli şekilde saklanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":2},{\"anahtar\":\"hst-20208\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: YOĞUN BAKIMLAR ve PACU\",\"faaliyet\":null,\"tehlike\":\"1-Hastalardan inhalasyon yoluyla hastalık bulaşması\",\"risk\":\"1-Enfeksiyon, bulaşıcı hastalıklara yakalanma\",\"mevcut_onlem\":\"1-KKD\'ler mevcuttur.                                         2- Çalışanlara KKD önemi ve kullanımı konusunda eğitim verilmektedir.\",\"oneri\":\"1-Bulaşıcı hastalık şüphesi olan hastalar, sonuçları çıkana kadar tek kişilik izolasyon odalarında tutulmalıdır.                                                                                                                                                                                              2- Şüpheli hastaların bulunduğu alanın teması bittikten sonra hemen dezenfekte edilmelidir.                                                                                                                                                                                                                                                                                                         4-Tanı konulmuş hastalar negatif basınçlı odalara alınarak izole edilmelidir.                                                                                                                        5-Çalışanlar N95 ya da TS EN 149 standrtdında FFP2 filtreli maske, yüz siperi, TS EN 455  standardında eldiven kullanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20209\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: YOĞUN BAKIMLAR ve PACU\",\"faaliyet\":null,\"tehlike\":\"1-Röntgen çekimi esnasında kurşun paravan kullanılmaması\",\"risk\":\"1-Radyasyon maruziyeti\",\"mevcut_onlem\":\"1-Kurşun önlükler mevcuttur.\",\"oneri\":\"1- Taşınabilir röntgen cihazı ile yapılan çekimler de kurşun paravan kullanılmalıdır.                                                                                                                                                               2- Çekim yapılan alanda hasta ve çekim yapan çalışan dışında kimse olmamalı, zorunlu hallerde bulunulması gerekirse(TS EN 61331 standardında kurşun önlük troid koruyucu vb.kişisel koruyucu ekipmanlar kullanılmalıdır.                                                                                                       3- Çekim yapılan odaların kapıları kapatılmalıdır.                                                                                           4- Açık alanlarda yapılan çekimlerde çalışanlar en az 2 metre uzakta durmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20210\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: YOĞUN BAKIMLAR ve PACU\",\"faaliyet\":null,\"tehlike\":\"1-Hasta yataklarının mekanizmalarının bozulması\",\"risk\":\"1-El kol parmak sıkışmaları                                            2- Ayak yaralanmaları\",\"mevcut_onlem\":\"1-Arıza olması halinde onarılmaktadır.\",\"oneri\":\"1-Tüm yoğun bakım ve PACU ünitesinde hasta yataklarının düzenli bakım ve periyodik kontrolleri yapılmalıdır.                                                                                                                         2- Yatak frenleri sağlam olmalıdır.                                                                                                                                                                               3- Elektrikli/motorlu yataklarda kablo ve kumanda sistemlerinin kontrol edilmeli hasarlı kablolar değiştirilmelidir.                                                                                                                                                                                4-Korkuluklar her zaman sağlam ve kilitli pozisyonda tutulmalıdır.                                                                            5- Arızalı yataklar kullanım dışı bırakılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20211\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: YOĞUN BAKIMLAR ve PACU\",\"faaliyet\":null,\"tehlike\":\"1-Hasta bölmeleri arası  mahremiyet perdeleri kullanımı ve temizliği\",\"risk\":\"1-Enfeksiyon, bulaşıcı hastalıklara yakalanma\",\"mevcut_onlem\":\"1-Ayda bir kere perde değişimi yapılmaktadır.\",\"oneri\":\"1-Hastalar arası bölmeler  için Sabit Duvar/Modüler Kabin Sistemleri yapılmalıdır.\\n2-Yırtık veya bozuk perdeler hemen yenisiyle değiştirilmelidir.     \\n3- Tüm yoğun bakım ve PACU ünitesinde perdeler en geç ayda bir kere  (Bulaş ve hasta değişiminde hemen) ve kontaminasyon durumunda hemen yıkanmalı/dezenfekte edilmelidir.                                                                                                                                                                                                                                 4-Perdeler çıkarılırken kirli yüzeyin çalışanla temas etmesi önlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20212\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: YOĞUN BAKIMLAR ve PACU\",\"faaliyet\":null,\"tehlike\":\"1-Çalışma alanında yiyecek-içecek tüketilmesi\",\"risk\":\"1-Meslek hastalıklarının oluşması\\n2-Çalışan sağlığının bozulması\",\"mevcut_onlem\":\"1-Tanımlı mutfak alanı mevcuttur.\",\"oneri\":\"1-Tüm yoğun bakım ve PACU alanlarında ilaç hazırlama odaları, hasta bakım alanları gibi bölümlerde yiyecek–içecek kesinlikle tüketilmemelidir.         \\n2-Yemek ve çay saatlerinden önce el, yüz ve vücut temizliği sağlanmalıdır.                                                                                                                                                                                                                                                                                                                                                                                                      3-Çalışanlara, yiyecek–içecek tüketiminin hastane enfeksiyonlarına, kimyasal/biyolojik madde bulaşına ve çalışan sağlığına yönelik risklerine karşı eğitim verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20213\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: YOĞUN BAKIMLAR ve PACU\",\"faaliyet\":null,\"tehlike\":\"1- Havalandırma sisteminin periyodik kontrollerinin tekrarlanmaması                                            2- Hepa filtrelerin yılda bir değiştirilmemesi\",\"risk\":\"1-Enfeksiyon, bulaşıcı hastalıklara yakalanma\",\"mevcut_onlem\":\"1- Havalandırma tesisatının periyodik kontrolü mevcuttur.\",\"oneri\":\"1- Havalandırma sisteminin periyodik kontrolleri havalandırma tesisat projesinde yer alan kriterlere göre en geç yılda bir tekrarlanmalıdır. \\n2- Partiküllere karşı kullanılan hepa filtreler en geç yılda bir kez değiştirilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20214\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM: YOĞUN BAKIMLAR ve PACU\",\"faaliyet\":null,\"tehlike\":\"1-Hasta odalarında bulunan çeşmelerin sensörsüz olması\",\"risk\":\"1-Bulaş sonucu enfeksiyon hastalıkları\",\"mevcut_onlem\":\"1-Çalışanlara biyolijik riskler hakkında eğitim verilmektedir.\",\"oneri\":\"1- El ile açılan musluklar fotoselli musluklar ile değiştirilmelidir.\\n2- El hijyen ekipmanları yeterli miktarda ve kolay erişilebilir konumda olmalıdır.                                                           \\n3- Musluklar kapatılırken temas edilmemeli, kağıt havlu kullanılmalıdır.        \\n4- Musluk ve lavabo yüzeyleri düzenli olarak dezenfekte edilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":3}]', 0, 0, NOW(), NOW()
FROM `users` u WHERE u.`email` = 'mozdemir2816@gmail.com' AND NOT EXISTS (SELECT 1 FROM `risk_sablonlari` s WHERE s.`user_id` = u.`id` AND s.`ad` = 'Hastane — Birim: YOĞUN BAKIM ve PACU');

INSERT INTO `risk_sablonlari` (`user_id`, `ad`, `sektor`, `sektor_adi`, `yontem`, `maddeler`, `paylasildi`, `kullanim_sayisi`, `created_at`, `updated_at`)
SELECT u.`id`, 'Hastane — Birim: KEMOTERAPİ', 'saglik', NULL, 'fine_kinney', '[{\"anahtar\":\"hst-20215\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: KEMOTERAPİ TEDAVİ ALANLARI\",\"faaliyet\":null,\"tehlike\":\"1-Diyaliz sıvılarının Elektrik pano odalarının önüne depolanması\",\"risk\":\"1-Acil durumlarda hızlı müdahalenin sağlanamaması sonucunda durumun etkisinin ve şiddetinin artması\",\"mevcut_onlem\":\"1- 30 MA kaçak akım rölesi mevcuttur.\",\"oneri\":\"1- Elektrik pano odalarının önüne  malzeme depolanmamalıdır.     \\n2- Panolara erişim için en az 80 cm genişlikte ulaşım yolları sağlanmalıdır.                                                                                    3- Diyaliz sıvıları ayrı depolama alanlarında (serin, kuru, iyi havalandırılmış, güneş görmeyen) muhafaza edilmelidir.                                                                                                                    4-Birim sorumlusu tarafından düzenli kontrol yapılmalıdır. Uygunsuz depolama tespit edildiğinde anında raporlama ve düzeltici faaliyet uygulanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20216\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: KEMOTERAPİ TEDAVİ ALANLARI\",\"faaliyet\":null,\"tehlike\":\"1-KKD’lerin eksik olması,                           2- KKD\'lerin çalışanlar tarafından kullanılmaması\",\"risk\":\"1-KKD’lerin kullanılmaması sonucunda iş kazaları, meslek hastalıkları oluması\",\"mevcut_onlem\":\"1-Yeterli KKD mevcuttur.                     2-Çalışanlara KKD eğitimi verilmektedir.\",\"oneri\":\"1-KKD’ler CE belgeli ve ilgili standartlara uygun olmalı, eksik olan KKD\'ler temin edilmelidir.\\n2- Çalışanların maskeleri N95 ya da TS EN149 A1 standardında,göz koruyucuları TS EN 166 standardına uygun ve tam kapalı tip iş eldivenleri TS EN 455 standardı, kesilmelere dayanıklı TS EN 388 standartına çalışanların önlükleri sıvı geçirmez önlük/ cerrahi önlük TS EN ISO 13688 ve TS EN 13795 standartlarında iş ayakkabıları kaymaz tabanlı olmalıdır.                                                                                                                                                                                                 3- Bütün kişisel koruyucular çalışanlara zimmetlenmelidir.                                                                       4- Kişisel koruyucu donanımlar çalışanlar tarafından eksiksiz kullanılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20217\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: KEMOTERAPİ TEDAVİ ALANLARI\",\"faaliyet\":null,\"tehlike\":\"1-Kemoterapi alanında kullanılan hasta koltuklarının kabloların dağınıklığı\",\"risk\":\"1-İş kazası, yaralanma                                                2-Takılma,düşme                                            3- Kabloların zarar görmesi\",\"mevcut_onlem\":\"1- 30 MA kaçak akım rölesi mevcuttur.\",\"oneri\":\"1-Kablo düzenleyiciler, spiral borular veya kablo kanalları kullanılarak dağınık kablolar düzenlenmelidir.                                 \\n2-Elektrik prizleri, medikal cihazların konumuna uygun şekilde, zeminden yüksekte ve erişilebilir yerlerde olmalıdır.                                                                                                                           3-Elektrik kablolarının hasar görmesi durumunda cihaz hemen kullanımdan çıkarılmalıdır.   \\n4- Çalışanlar geçiş amaçlı kabloların bulunduğu kısmı kullanmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20218\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: KEMOTERAPİ TEDAVİ ALANLARI\",\"faaliyet\":null,\"tehlike\":\"1-Kemoterapi alanında kullanılan hasta koltuklarının devrilmesi,düşmesi\",\"risk\":\"1-Koltuğun devrilmesi sonucu yaralanma\",\"mevcut_onlem\":\"1- Koltuklar sabitlenme aparatı ile tek yönden zemine sabitlenmiştir.\",\"oneri\":\"1-Kemoterapi koltukları iki noktadan zemine devrilmeyecek şekilde sabitlenmelidir.                                                                           \\n2- Koltuk kolçakları her zaman sağlam ve kilitli pozisyonda tutulmalıdır.     \\n3- Koltukların elektrikli mekanizmaları çalışır durumda olmalı, düzenli kontrol ve bakımları yapılmalıdır. \\n4- Koltuğa hasta transferleri en az 2 çalışan ile yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20219\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: KEMOTERAPİ TEDAVİ ALANLARI\",\"faaliyet\":null,\"tehlike\":\"1-Kemoterapi uygulama alanında hijyen tedbirlerinin yeterli olmaması\",\"risk\":\"1-Enfeksiyon hastalıklarına yakalanma, meslek hastalıkları\",\"mevcut_onlem\":\"1-KKD\' ler mevcuttur.\",\"oneri\":\"1- Kemoterapi sonrası hasta alanlarının havalandırılması ve temizliği denetlenmelidir.\\n2- Tıbbi ve medikal cihazların her kullanımdan sonra belirlenmiş olan kimyasallar ile dezenfekte edilip edilmediği kontrol edilmelidir.\\n3- Çalışanlar tarafından KKD kullanımı denetlenmelidir.\\n4- Çalışanların hijyen kurallarına uyup uymadıkları ve el hijyeni malzemelerinin yeterli miktarda olup olmadığı denetlenmelidir.\\n5- Çalışanlara el hijyeni eğitimleri verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20220\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: KEMOTERAPİ TEDAVİ ALANLARI\",\"faaliyet\":null,\"tehlike\":\"1- Kan ve vücut sıvılarının göz ve cilde temas etmesi\",\"risk\":\"1-Temas sonucu enfeksiyon, bulaşıcı hastalıklara yakalanma\",\"mevcut_onlem\":\"1-KKD\' ler mevcuttur.                                   2-Çalışanlara KKD\'lerin kullanımı ve önemi hakkında eğitimler verilmektedir .\",\"oneri\":\"1-Çalışanlar TS EN 455  standardında eldiven, N95 ya da TS EN 149 standardında maske, TS EN 166 standardında tam kapalı gözlük ya da yüz siperi, uzun kollu koruyucu önlük  EN 14683 standardında vb. gibi kişisel koruyucu donanımlar kullanılmalıdır.                                                                                                                         2- Temas durumunda bölgenin bol su ve sabunla yıkanması sağlanmalıdır.                                                                                                                                    3- Kan ve vücut sıvıları sıçramasına maruz kalma sonrası çalışanın, bulaş kaynağının durumuna göre muayene ve tetkikleri yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20221\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: KEMOTERAPİ TEDAVİ ALANLARI\",\"faaliyet\":null,\"tehlike\":\"1-Sitotoksik ilaçların dökülmesi sonucu maruziyet\",\"risk\":\"1-Temas sonucu  cilt, göz iritasyonu\",\"mevcut_onlem\":\"1-KKD\' ler mevcuttur.                                   2-Çalışanlara KKD\'lerin kullanımı ve önemi hakkında eğitimler verilmektedir .\",\"oneri\":\"1-Gözlerle Temas: Lens takılı ise çıkarmalıdır. Göz kapaklarını iyice açarak, derhal ve bol su ile en az 15 dakika yıkanmalıdır.\\n2- Ciltle Temas: Kirlenmiş giysiler çıkarılmalı hemen bol su ile yıkanamlıdır. Tahriş devam ediyorsa, doktora danışılmalıdır. Kirlenmiş giysiler tekrar kullanmadan önce yıkanmalıdır.\\n3-Solunum: Kişi açık havaya çıkarılmalıdır. Solunum zorluğu çekilmesi halinde, derhal tıbbi yardım aldırılmalıdır.\\nYutma: Yutulması durumunda medikal tavsiye alınmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20222\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: KEMOTERAPİ TEDAVİ ALANLARI\",\"faaliyet\":null,\"tehlike\":\"1- Kesici delici aletlerin emniyetsiz kullanılması\",\"risk\":\"1- Kullanılmış aletlere temas sonucu el kol yaralanmaları, enfeksiyon, bulaşıcı hastalıklara yakalanma\",\"mevcut_onlem\":\"1- Kesici delici alet kutuları mevcttur.                2-Çalışanlara kesici delici aletlerin güvenli kullanımı konusunda eğitim verilmektedir.\",\"oneri\":\"1- Kullanılmış iğne ve kesici aletler, kesici delici alet kutusuna atılmalıdır.                                                                                                                           2- Çalışanlar tedavi tepsisi kullanmalı, iğne kapağı kapatılmadan kesici delici alet kutusuna atılmalıdır.                                                                                                                               3- Kesici delici alet kutuları en fazla 2/3 dolduğunda yenisi ile değiştirilmeli, kutuların kapakları açık bırakılmamalıdır.                                                                                                                   4-  Kesici delici alet kutuları devrilmeyecek şekilde konumlandırılmalıdır.                                                             5- Çalışanlar TS EN 455 standardında çift eldiven kullanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20223\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: KEMOTERAPİ TEDAVİ ALANLARI\",\"faaliyet\":null,\"tehlike\":\"1-Sitotoksik ilaçların, serumların ortama yayılması, dökülmesi, sonucu maruziyet\",\"risk\":\"1-Sitotoksik ilaca maruz kalma sonucu iş kazası meydana gelmesi\",\"mevcut_onlem\":\"1-Kimyasal atık varilleri bulunmaktadır.                           2-Kimyasal müdahale kitleri bulunmaktadır.\",\"oneri\":\"1-Sitotoksik ilaçlar ve serumlar sızdırmaz, darbeye dayanıklı olmalıdır.                                                                             2- Sitotoksik ilaç serumları elde değil kap içerisinde taşınmalıdır.                                                        3- Hazırlık ve uygulama alanlarında dökülme kiti her zaman hazır bulundurulmalıdır.                                                                                                                                                  4- Dökülme olması durumunda alan hemen izole edilmeli, absorban kullanılarak sitotoksik ilacın çalışma ortamına yayılması önlenmelidir.                                                                         5- Döküntü olan yüzey deterjan ve su ile iki kere temizlenmelidir.                                                                                                               6- Döküntü atıkları atık poşetlerine atılarak ağızları sıkıca bağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20224\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: KEMOTERAPİ TEDAVİ ALANLARI\",\"faaliyet\":null,\"tehlike\":\"1-Bölüme özel eğitimler\",\"risk\":\"1-İş kazası, meslek hastalığı                                        2-Sitotoksik ilaç maruziyeti\",\"mevcut_onlem\":\"1- Çalışanlar Temel İSG Eğitimlerine Katılmaktadır.\",\"oneri\":\"1-Sitotoksik ilaç güvenliği ile ilgili olarak   hazırlama, taşıma, uygulama sırasında riskler ve önlemler için yılda bir kere eğitim verilmelidir.                                                                                                                                 2- Atık yönetimi için  Sitotoksik atıkların ayrı toplanması ve imhası ile ilgili olarak yılda bir eğitim verilmelidir.                                                                                                                                                                                                                                                                                                                                                                                                                                                         3-Dökülme  kiti kullanımı eğitimleri verilmeli ve uygulamalı olarak  tatbikatı yapılmalıdır.\\n4-Acil durum simülasyonları (ilaç dökülmesi, sitotoksik ilaç maruziyeti vb.)için eğitim düzenlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20225\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: KEMOTERAPİ TEDAVİ ALANLARI\",\"faaliyet\":null,\"tehlike\":\"1-Çalışma alanında yiyecek-içecek tüketilmesi\",\"risk\":\"1-Meslek hastalıklarının oluşması\\n2-Çalışan sağlığının bozulması\",\"mevcut_onlem\":\"1-Tanımlı mutfak alanı mevcuttur.\",\"oneri\":\"1-Kemoterapi alanlarında ilaç hazırlama odaları, hasta bakım alanları gibi bölümlerde yiyecek–içecek kesinlikle tüketilmemelidir. \\n2-Yemek ve çay saatlerinden önce el, yüz ve vücut temizliği sağlanmalıdır.                                                                                                                                                                                                                                                                                                                                                                                                      3-Çalışanlara, yiyecek–içecek tüketiminin hastane enfeksiyonlarına, kimyasal/biyolojik madde bulaşına ve çalışan sağlığına yönelik risklerine karşı eğitim verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20226\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: KEMOTERAPİ TEDAVİ ALANLARI\",\"faaliyet\":null,\"tehlike\":\"1-Sitotoksik ilaçların ilaç hazırlama ünitesinden tedavi alanlarına taşınması\",\"risk\":\"1-Sitotoksik ilaçlara maruziyet sonucu iş kazaları meydana gelmesi\",\"mevcut_onlem\":\"1-Taşıma araçlarında müdahale kiti bulunmaktadır.\",\"oneri\":\"1- Sitotoksik ilaçlar sızdırmaz kaplarda taşınmalı ve etiketlenmelidir.\\n2- Taşıma araçlarında dökülme ve saçılmalara karşı müdahale kitleri bulunmalıdır. \\n3- Müdahale kiti bulaş olma ihtimaline karşı taşıma kabini dışında tutulmalıdır.                        4- Taşıma güzergâhı önceden belirlenmeli, insan ve hasta trafiğinin yoğun olduğu bölgelerden taşınmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20227\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: KEMOTERAPİ TEDAVİ ALANLARI\",\"faaliyet\":null,\"tehlike\":\"1-Göz duşu solüsyonlarının yenilenmemesi\",\"risk\":\"1-Göze sitotoksik ilaç kaçması sonucu iş kazası meydana gelmesi\",\"mevcut_onlem\":\"1-Göz duşu bulunmaktadır.\",\"oneri\":\"1-Tüm kemotetapi tedavi alanlarında sitotoksik ilaç maruziyetine karşı göz duşu bulundurulmalıdır.                                                                                                                                                      2-Göz duşları solüsyonları kullanıldıktan sonra yenisi tekrar konulmalıdır.                                                      3- Göz duşu kullanım talimatları asılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20228\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: KEMOTERAPİ İLAÇ HAZIRLAMA VE DEPOLAMA ALANI\",\"faaliyet\":null,\"tehlike\":\"1-Sitotoksik ilaç hazırlama işlerinde çeker ocak kullanılmaması\",\"risk\":\"1-Sitotksik ilaçlara maruz kalma, sonucu iş kazası, meslek hastalığı\",\"mevcut_onlem\":\"1- Bazı ilaçlar kabinde hazırlanmaktadır.      2-Negatif basınçlı oda mevcuttur.\",\"oneri\":\"1--Sitotoksik ilaç hazırlama işleri, sadece çeker ocak altında yapılmalı, açık masalarda ilaç hazırlanmamalıdır.         \\n2-Eksik çeker ocak temin edilmelidir.                                                                                                                                                                                                                                                                                                                                                         3-Çeker ocak yanlarında  tek kullanımlık emici, sıvı geçirmez pedler bulundurulmaldır.                                                                                                                                                                                             4- Dökülme kitleri (spill kit) ilaç hazırlık alanında bulundurulmalıdır.                                                                                                                      5- Nitril eldiven(EN 455), sıvı geçirmez uzun kollu önlük veya tek kullanımlık kaplamalı önlük(EN ISO 13688),koruyucu gözlük/ siperlik(EN 166), N95,bone(EN 14126) ve galoş(EN ISO 13688) kullanılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20229\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: KEMOTERAPİ İLAÇ HAZIRLAMA VE DEPOLAMA ALANI\",\"faaliyet\":null,\"tehlike\":\"1-Sitotoksik ilaç hazırlama kabininde hava sirkülasyonunun engellenmesi\",\"risk\":\"1-Sitotoksik ilaç hazırlarken aerosol/solunum maruziyeti\",\"mevcut_onlem\":\"1-Negatif basınç mevcuttur.\",\"oneri\":\"1-Kirli havayı zeminden atan aspirasyon sisteminin önü raf malzeme vb. ekipmanlar ile kapatılmamalı, emiş sistemi her zaman aktif olmalıdır.\\n2-Sitotoksik ilaç  buharının çalışma ortamına yayılması önlenmeli,  buhar solunum bölgesine ulaşmadan zeminden atılmalıdır.\\n3-İlaç hazırlama işleri sadece çeker ocak altında yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20230\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: KEMOTERAPİ İLAÇ HAZIRLAMA VE DEPOLAMA ALANI\",\"faaliyet\":null,\"tehlike\":\"1-Sitotoksik ilaç hazırlama kabininde acil kapı açma butonunun olmaması\",\"risk\":\"1- Acil durumlarda tahliyenin sağlanamaması\",\"mevcut_onlem\":\"1- Mevcutta ilaç hazırlama ünitesi kapıları içe doğru açılmaktadır.\",\"oneri\":\"1-Sitotoksik ilaç hazırlama kabininde  kapı kolunun arızalanmasına karşı, içeriden açılabillir ilave acil kapı açma butonu takılmalıdır.                                                                                                                                                                                                   2- Acil kapı açma butonu ve alarm butonu erişilebilir yükseklikte olmalı ve önüne malzeme konulmamalıdır.                                                                                                                                           3- Acil kapı açma butonu ve alarm sistemi karanlıkta görülebilir şekilde işaretlenmiş olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20231\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: KEMOTERAPİ İLAÇ HAZIRLAMA VE DEPOLAMA ALANI\",\"faaliyet\":null,\"tehlike\":\"1-Eczane içerisinde sitotoksik ilaçların depolanması\",\"risk\":\"1-Sitotksik ilaçlara maruz kalma sonucu                                                                           İş kazası, meslek hastalığı meydana gelmesi\",\"mevcut_onlem\":\"1-Sitotoksik ilaçlar ayrı bir alanda depolanmaktadır.\\n2-Yetkili kişiler tarafından kontrollü dağıtımı mevcuttur.                          .\",\"oneri\":\"1-Sitotoksik ilaçların  depolama alanı kilitli ve yetkisiz girişlere kapalı olmalıdır.  2- Depolama alanında yeterli havalandırma bulunmalıdır.\\n3- Raflarda ilaçlar düşme, devrilme, ezilme riski olmayacak şekilde yerleştirilmeli, raflar en az iki noktadan duvara sabitlenmiş olmalıdır.                                                                                         \\n4-Olası dökülme veya sızıntılara karşı absorban pedler, koruyucu eldiven, maskeler kolay erişilebilir olmalıdır.                                                                                                           5-Depoya giriş yapan personel koruyucu  eldiven(EN 455), sıvı geçirmez önlük(EN ISO 13688), maske(EN 14683), koruyucu gözlük/ siperlik(EN 166) kullanmalıdır.                                                                                                                                                                                                                                                         6-Personel, sitotoksik ilaçların depolanması sırasında kimyasal riskler ve acil durum prosedürleri konusunda düzenli olarak eğitilmelidir. Yılda en az bir kez tatbikat yapılmalı, acil durum senaryoları test edilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20232\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: KEMOTERAPİ İLAÇ HAZIRLAMA VE DEPOLAMA ALANI\",\"faaliyet\":null,\"tehlike\":\"1-Sitotoksik ilaç hazırlama kabininde  havalandırma sisteminin periyodik kontrollerinin tekrarlanmaması\",\"risk\":\"1-Kimyasal madde buharlarının solunması sonucunda meslek hastalıklarının oluşması\",\"mevcut_onlem\":\"1-Havalandırma sisteminin periyodik kontrolü mevcuttur.\",\"oneri\":\"1- Havalandırma sisteminin periyodik kontrolleri havalandırma tesisat projesinde yer alan kriterlere göre en geç yılda bir tekrarlanmalıdır. \\n2- Partiküllere karşı kullanılan hepa filtreler en geç yılda bir kez değiştirilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20233\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: KEMOTERAPİ İLAÇ HAZIRLAMA VE DEPOLAMA ALANI\",\"faaliyet\":null,\"tehlike\":\"1-Dökülme sonrası alanın yanlış dekontaminasyonu\",\"risk\":\"1- Hatalı temizlik nedeniyle aerosollerin yeniden ortama yayılması\",\"mevcut_onlem\":\"1-Alanda dökülme kiti mevcuttur.                2-KKD\'ler mevcuttur.\",\"oneri\":\"1 -Hazırlık alanında standart dökülme kiti (spill kit) bulundurulmalıdır.                                                                                                                                                                         2-Yüzeylerin sitotoksik ilaçlara uygun dekontaminanlarla (örn. sodyum hipoklorit, ardından nötral temizleyici) temizlenmeli, temizleme işlemi temiz alandan kirli alana doğu yapılmalı, dökülme sonrası alan geçici olarak kapatılmalıdır.\\n3- Dökülme temizliği sırasında eldiven (EN 455), su geçirmez önlük (EN ISO 13688), N95/FFP3 maske (EN149:2001+A1:2009), gözlük/siperlik (EN 166 )giyilmelidir.                                                                                                                                                                       3- Dekontaminasyon sonrası KKD’ler çıkarılıp sitotoksik atık kutusuna atılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20234\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: KEMOTERAPİ İLAÇ HAZIRLAMA VE DEPOLAMA ALANI\",\"faaliyet\":null,\"tehlike\":\"1-Sitotoksik ilaçların eczaneden  ilaç hazırlama ünitesine taşınması\",\"risk\":\"1-Sitotoksik ilaçlara maruziyet sonucu iş kazaları meydana gelmesi\",\"mevcut_onlem\":\"1- Taşıma personeli bulunmaktadır.                       2-Dökülme kiti bulunmaktadır.\",\"oneri\":\"1- Sitotoksik ilaçlar sızdırmaz kaplarda taşınmalı ve etiketlenmelidir.\\n2- Taşıma araçlarında dökülme ve saçılmalara karşı müdahale kitleri bulunmalıdır. \\n3- Müdahale kiti bulaş olma ihtimaline karşı taşıma kabini dışında tutulmalıdır.                        4- Taşıma güzergâhı önceden belirlenmeli, insan ve hasta trafiğinin yoğun olduğu bölgelerden taşınmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20235\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: KEMOTERAPİ İLAÇ HAZIRLAMA VE DEPOLAMA ALANI\",\"faaliyet\":null,\"tehlike\":\"1-İlaç hazırlama alanında göz duşu bulunmaması\",\"risk\":\"1-Sitotoksik ilaçlaraın göze kaçması sonucu iş kazaları meydana gelmesi\",\"mevcut_onlem\":\"1-İlaç hazırlama alanı dışında göz duşu bulunmaktadır.\",\"oneri\":\"1- İlaç hazırlama alanında dökülme saçılmalara karşı göz duşu bulunmalıdır. Göz duşları tek kullanımlık olmalı, kullanıldıktan sonra yenisi tekrar konulmalıdır.                    \\n2- Gözduşu kullanma talimatı asılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":6}]', 0, 0, NOW(), NOW()
FROM `users` u WHERE u.`email` = 'mozdemir2816@gmail.com' AND NOT EXISTS (SELECT 1 FROM `risk_sablonlari` s WHERE s.`user_id` = u.`id` AND s.`ad` = 'Hastane — Birim: KEMOTERAPİ');

