SELECT u.`id`, 'Hastane — Birim: İDARİ BİRİMLER', 'saglik', NULL, 'fine_kinney', '[{\"anahtar\":\"hst-20236\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: İDARİ BİRİMLER\",\"faaliyet\":null,\"tehlike\":\"1-Çalışan hasta ve hasta yakınları iletişim problemleri, fiziksel sözlü şiddet\",\"risk\":\"1- Hasta ya da yakınları tarafından fiziksel ya da sözlü şiddete maruz kalma sonucu yaralanma,\",\"mevcut_onlem\":\"1- Panik butonları mevcuttur.\",\"oneri\":\"1- Hasta ve hasta yakınları tarafından çalışanların şiddete uğrayabileceği tüm alanlara sabit panik butonları ya da yaka butonları temin edilmelidir.                                                                                         2- Özellikle şiddet riskinin yoğun olduğu alanlarda ( hasta hakları vb.) alanlarda  masalarının altında bir adet, yakalarında bir adet olamak üzere iki adet panik butonu temin edilmelidir.                                                                                                                                                                                                                                                                                3- Şiddet riskinin yoğun olduğu alanlarda sabit güvenlik personeli  bulundurulmalıdır.                                                                                                                                   4- Çalışanlara iletişim, stres yönetimi ve öfke kontrolü ile mesleki bilgi ve becerilerini arttırıcı eğitimler verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20237\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: İDARİ BİRİMLER\",\"faaliyet\":null,\"tehlike\":\"1- Buat bulunan zemin üzerinde buatların kapaklarının açık olması                                       2- Buat kapaklarının olmaması\",\"risk\":\"1-Elektrik çarpması sonucu kalp ritim bozuklukları, elektrik yanıkları\",\"mevcut_onlem\":\"1- Topraklama mevcuttur.                                                             2- Kaçak akım rölesi kullanılmaktadır.\",\"oneri\":\"1- Tüm buatlar kapaklı ve kapakları kapalı olmalıdır.                                                                                                           2- Buatlara takılan prizler kapakların tam kapatılabilmesi için yatay özellikte olmalı, dikey fişler kullanılmamalıdır.                                                                                                                                       3- Kablolar buat kablo kanallarından geçirilmelidir.                                                                                                       4- Islak elle veya çıplak ayakla elektrikli aletlere dokunulmamalıdır.                                                                                       5- Buat üzerinde bulunan masalarda sıvı gıdalar tüketilmemelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20238\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: İDARİ BİRİMLER\",\"faaliyet\":null,\"tehlike\":\"1- Ofislerde kullanılan elektrikli cihazların kablo, priz veya fişlerinin hasarlı olması\",\"risk\":\"1- Elektrik çapması.               2- yangın kaynaklı yanıklar ve duman zehirlenmesi\",\"mevcut_onlem\":\"1- Kaçak akım röleleri mevcuttur.                                         2- Topraklama ölçümleri mevcuttur.\",\"oneri\":\"1-Elektrik kablolarında yırtık, izolasyon bozlukluğu vb. olmamalı, olan kablolar kullanılmamalı değiştirilmelidir.                                                                                                                                      2- Hastane de kullanılan tüm elektrik, uzatma (3\'lü) vb. kablolar halojen free (geç yanan, zehirli gaz çıkarmayan) özellikte olmalıdır.                                                                                                                                                           3- Halojen free olmayan uzatma kablolalarının kulllanımı yasaklanmalı, toplatılmalıdır.                                                                                                                                             4- Islak elle cihazlara dokunulmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20239\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: İDARİ BİRİMLER\",\"faaliyet\":null,\"tehlike\":\"1- Ergonomik olmayan ofis mobilyaları ve çalışma şekli\",\"risk\":\"1- Postür bozuklukları sonucunda kas-iskelet sistemi hastalıkları,  verimlilik kaybı,\",\"mevcut_onlem\":\"1- Ergonomik risk faktörleri hakkında eğitim verilmiştir.\",\"oneri\":\"1- Sandalyeler ergonomik tasarıma sahip olmalı, ayaklar düz olarak yere temas etmeli, diz 90 derece açılı olmalı,  sandalyede bel desteği olmalı,  sırt dik, omuzlar rahat, dirsekler 90 derece açılı olmalıdır.                                                                                                                                                                   3- Eğer ayaklar yere temas etmiyorsa, ayaklara ek bir destek yerleştirilmelidir.                                                                                                                                       4- Ekranın üst kenarı göz hizasında veya az aşağısında olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20240\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: İDARİ BİRİMLER\",\"faaliyet\":null,\"tehlike\":\"1- Sürekli klavye ve mause kullanımı\",\"risk\":\"1- El ve bilek rahatsızlıkları.                 2- Meslek hastalığı\",\"mevcut_onlem\":\"1- Ergonomik risk faktörleri hakkında eğitim verilmiştir.\",\"oneri\":\"1- Ergonomik yapıda klavye ve mouse destek pedi temin edilmelidir.                                                                                              2- Kollar yazı yazarken yere paralel tutulmalı ve bilekler bükülmemelidir.                                                                                      3- Tuş karakterleri okunaklı ve yeteri büyüklükte olmalı,uygun olmayanlar değiştirilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20241\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: İDARİ BİRİMLER\",\"faaliyet\":null,\"tehlike\":\"1- Statik duruş, \\n2- Uygunsuz duruş ve uzun süre oturarak çalışma\",\"risk\":\"1- Kas, iskelet sistemi, eklem, el ve bilek rahatsızlıkları.                        2- Dolaşım sistemi rahatsızlıkları.\",\"mevcut_onlem\":\"1- Ergonomik risk faktörleri hakkında eğitim verilmiştir.\",\"oneri\":\"1- Ayarlanabilir sandalye ve bel desteği sağlanmalıdır.                                                                                             2- Çalışanlar 45 dakikalık periyotlarla yerlerinden kalkarak hareket etmelidir.                                                                                                                                                        3- Masa yüksekliği kişiye göre ayarlanmalıdır.                                                                                              4- Molalarda ofis egzersizleri ve açma/ germe hareketleri yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20242\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: İDARİ BİRİMLER\",\"faaliyet\":null,\"tehlike\":\"1-Kayma, takılma ya da düşmeye sebep olabilecek kablolar, düzensiz konulmuş eşya ve ekipmanlar\",\"risk\":\"1-Kayma, takılma, düşme sonucunda vücut bölümlerinin yaralanması\",\"mevcut_onlem\":\"1-Ofislerin bulunduğu zemin pürüzsüz malzemeden yapılmıştır.\",\"oneri\":\"1- Zeminde bulunan kablolar çalışanların takılıp düşmeyeceği şekilde toplanmalıdır.                                                                                                                                                       2- Masa, mobilya vb.  ekipmanların yerleşimi geçişe uygun, takılma ve kaymaya neden olmayacak şekilde yerleştirilmelidir.                                                                                                       3- Acil durumlar haricinde koşarak, ani hızlı hareketlerden kaçınılmalıdır.                                                                       4-Çalışanlar kaymaz tabanlı ayakkabı giymeli, topuklu ayakkabı giyilmemelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20243\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: İDARİ BİRİMLER\",\"faaliyet\":null,\"tehlike\":\"1- Ofislerde uygun olmayan uzatma kabloları kullanılması                            2- Üçlü prize üçlü priz bağlanması.\",\"risk\":\"1- Elektrik yangını çıkması sonucu, yaralanma, ölüm\",\"mevcut_onlem\":\"1- Kaçak akım röleleri mevcuttur.                                            2- Topraklama yapılmıştır.                                                                               3- Yangın söndürme sistemleri mevcuttur.\",\"oneri\":\"1- 3 lü uzatma kablolarına, 3 lü uzatma kablosu takılarak kullanılmamalıdır.                                                                                                                                      2- Yüsek akım çeken cihazların beslemesi ayrı fişlerden yapılmalı, uzatma kabloları kullanılmamalıdır.                                                                                                                                                                                                                                                     3- Çalışanların dışarıdan uzatma kablosu getirmesi yasaklanmalıdır.                                                                                                                                   4- Konu ile ilgili kontrol denetim sağlanmalı ,uygun olmayan cihaz ve kablolar toplatılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":40,\"frekans\":1},{\"anahtar\":\"hst-20244\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: İDARİ BİRİMLER\",\"faaliyet\":null,\"tehlike\":\"1- İş stresi\",\"risk\":\"1- Sinirlilik, stres, uyum problemlerinin oluşması, \\n2-Güvensizlik, iş verim kaybı, iletişim sorunları\",\"mevcut_onlem\":\"1- Psikososyal tehlike ve risk faktörleri hakkında eğitim verilmiştir.                                                                            2- Çalışan hakları birimi mevcuttur ve gerektiğinde destek sağlanmaktadır.\",\"oneri\":\"1- Çalışanların görev, yetki ve sorumlulukları tanımlanmalı ve bu konu hakkında bilgilendirilmelidir.                                                                                                                                                          2- Dinlenme molalarında çalışanlara iş yaptırılmamalıdır.                                                                                           3- Çalışanlara gerçekçi olmayan teslim tarihleri verilmemeli zaman baskısı yaratılmamalıdır.                                                                                                                                                                           4- Monoton ve tekdüze işler sürekli sabit kişilere yaptırılmamalı, işler çalışanlar arasında eşit olarak paylaştırılmalıdır.                                                                                                                                5- Çalışanlara stres ,zaman yönetimi, etkili iletişim, öfke kontrolü vb. konularda eğitim verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20245\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: İDARİ BİRİMLER\",\"faaliyet\":null,\"tehlike\":\"1- Tanımlı olmayan, mutfak alanı olarak ayrılmamış alanlarda çay ocağı, kahve makinesi, kettle vb elektrikli alet kullanımı\",\"risk\":\"1-Yangın sonucu yaralanma                                                  2-Elektrik çarpması\",\"mevcut_onlem\":\"1- Kaçak akım röleleri mevcuttur.                                       2- Topraklama yapılmıştır.\",\"oneri\":\"1- Mutfak olarak tanımlanmış alanlarda sadece çay ve kahve makinesi kullanılmalı, bunların dışındaki aletlerin kullanımı yasaklanmalıdır.                                                                                                          2- Sadece çift termostatlı çay kahve makineleri makineleri kullanılmalıdır.                                                                                                                         3- Çay kahve makineleri direk fişe takılmalı, uzatma kablolarına takılmamalıdır.                                                                                                                                           4- Çay kahve makineleri kullanıldıktan sonra fişten çıkarılmalıdır.                                                                                  5- Elektrikli cihazlara ıslak elle temas edilmemelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20246\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: İDARİ BİRİMLER\",\"faaliyet\":null,\"tehlike\":\"1- Acil çıkış kapılarının önlerinin masa, mobilya vb. ekipmanlar ile kapatılmış olması\",\"risk\":\"1-Acil durumlarda hızlı tahliyenin sağlanamaması sonucunda durumun etkisinin ve şiddetinin artması\",\"mevcut_onlem\":\"1- Yangın yönlendirme levhaları mevcuttur.                                              2- Tahliye planı asılıdır.\",\"oneri\":\"1-Acil çıkış kapıları ve acil çıkış yolları açıkça görülebilir olmalı ve acil çıkış kapılarnın ve yollarının önüne ve üzerine malzeme vb. konulmamalıdır.                                                                                                                                                                        2- Acil çıkış yönlendirmelerinin önleri kapatılmamalı, kaçış yolu üzerinde bütün erişim noktalarından görülebilir olmalı, yönlendirmeler 200-240 cm yüksekliğe asılı olmalıdır.                                                                                                                                                                 3- Acil çıkış yollarında en az 150 cm genişliğinde mesafe olması sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20247\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: İDARİ BİRİMLER\",\"faaliyet\":null,\"tehlike\":\"1- Islak ve kaygan zeminlerin bulunması\",\"risk\":\"1- Kayma ve düşme sonucu burkulma, kırık, incinme\",\"mevcut_onlem\":\"1- Temizlik sonrası ıslak zemin uyarı levhaları mevcuttur.\",\"oneri\":\"1- Temizlik sonrası “Islak Zemin” uyarı tabelası konulmalıdır.                                                                   2-Temizlik sonrası ıslak zemin kurulanmalıdır.                                       \\n3- Dökülme sonrası zemin hemen temizletilmelidir.                                                                                     4- Çalışanlar kaymaz tabanlı ayakkabı giymelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":2},{\"anahtar\":\"hst-20248\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: İDARİ BİRİMLER\",\"faaliyet\":null,\"tehlike\":\"1- Elle taşıma işlerinin uygun yapılmaması\",\"risk\":\"1- Kas, iskelet sistemi, eklem, el ve bilek rahatsızlıkları.                        2- Dolaşım sistemi rahatsızlıkları.\",\"mevcut_onlem\":\"1- Ergonomik risk faktörleri ve elle taşıma işleri hakkında eğitim verilmiştir.                                         2- Ağır işler firma  tarafından yapılmaktadır.\",\"oneri\":\"1- Özellikle çalışanların sırt ve bel incinme risklerini önlemek veya azaltmak için kaldırılacak maksimum yük erkelerde 25 kg, kadınlarda 15 kg\'ı geçmemelidir.                                                                                                                                       2- Yükler belden eğilerek kalıdırılmamalı, dizlerden yere çökülmeli, sırt düz tutulmalı bacak kasları kullanmalı, yük vücuda yakın tutulmalıdır.                                                               3-Dengesiz, devrilme riski olan yükler taşıma aracıyla ya da en az iki kişiyle taşınmalı, yükler görüş alanını kapatmayacak şekilde taşınmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20249\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: İDARİ BİRİMLER\",\"faaliyet\":null,\"tehlike\":\"1- Su sebillerinin bakım ve temizliğinin yapılmaması.                                           2- Su sebillerinin su sızdırması\",\"risk\":\"1-Enfeksiyon, bulaşıcı hastalıklara yakalanma\",\"mevcut_onlem\":\"1- Enfeksiyon riskleri hakkında eğitim verilmiştir.\",\"oneri\":\"1- Su sebillerinin bakımları  düzenli aralıklarla yaptırılmalıdır.                                                                                   2- Su sebillerinin temizliği düzenli aralıklarla yaptırılmalıdır.                                                                                                                                                                          3- Su sızıntılarından kaynaklı riskleri önlemek için su sebillerinin altlarına taşma havuzu konulmalıdır.                                                                                                                                                                                                                                      4- Su sebillerinin bulunduğu zemin davamlı kuru tutulmalıdır ve kaygan zemin levhası konulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20250\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: İDARİ BİRİMLER\",\"faaliyet\":null,\"tehlike\":\"1- Ofis mobilyalarının ve dolapların sabitlenmemesi.\",\"risk\":\"1- Dolabın çarpması sonucu yaralanma, ezilme, kafa travması.                                   2- Malzemenin düşmesi sonucu yaralanma\",\"mevcut_onlem\":\"1- Çoğu dolap ve raflar duvara sabitlenmiştir.\",\"oneri\":\"1- Dolap ve raflar en az iki noktadan duvara sabitlenmelidir.                                                                       2- Dolapların üzerine devrilebilecek dosya vb. malzemeler istiflenmemelidir.                                                                                                                                         3- Ağır malzemeler alt raflara yerleştirilmelidir.                                                                                                                                                           4- Sabitlenemeyen dolap ve raflar kapılardan uzak, çalışanların üzerine düşmeyecek şekilde konumlandırılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20251\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: İDARİ BİRİMLER\",\"faaliyet\":null,\"tehlike\":\"1- Termal konfor takibinin yapılmaması\",\"risk\":\"1- Dikkat kaybı, iş kazası ve meslek hastalıklarında artışlar\",\"mevcut_onlem\":\"1- Merkezi havalandırma sistemi mevcuttur.\",\"oneri\":\"1-Çalışma ortamı %35-%75 nem oranında ve 18-24 C derece arasında olması sağlanmalıdır.                                                                                                                                                                                                                   2- Ofislerde çalışan başına 10m3 temiz hava sağlanmalıdır.\\n3-Hava akım hızının 0,5 m/sn ortalamada olması sağlanmalıdır.\\n4-Çalışma ortamının saatte en az 6-10 kez havalandırılması sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20252\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: İDARİ BİRİMLER\",\"faaliyet\":null,\"tehlike\":\"1- Aydınlatma yetersizliği, bozulması, titremesi\",\"risk\":\"1- Görme bozukluklarının oluşması ve ilerlemesi, iş kazalarında artış\",\"mevcut_onlem\":\"1- Bozuk ya da arızalı aydınlatmalar değiştirilmektedir.\",\"oneri\":\"1- Aydınlatma ölçümü yapılmalı, ofislerde aydınlatma lüks seviyeleri (300–500 lx) şiddeteinde olmalıdır.                                                                                                                                                                              2-Aydınlatma sistemleri sağlam yapıda olmalı, bozulan, yanmayan titreyen aydınlatmalar değiştirilmelidir.\\n3-Periyodik göz muayeneleri yılda bir kez yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20253\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: İDARİ BİRİMLER\",\"faaliyet\":null,\"tehlike\":\"1- Ekranlı araçlarla çalışmalarda sağlık ve güvenlik önlemlerinin alınmaması\",\"risk\":\"1- Göz yorgunluğu,göz kuruluğu, bulanık görme.                                                                    2- Stres, dikkat dağınıklığı,\",\"mevcut_onlem\":\"1-Yeni nesil monitörler mevcuttur\\n2-Ekran titremeyen çözünürlüktedir.\",\"oneri\":\"1-Ekran parlaklığı ve çözünürlüğü kişiye göre ayarlanmalı, Ekranın çalışana uzaklığı en az 60 cm olmalı ve çalışanın göz hizasında olmalıdır.\\n2-Ekran göze uygun ayarlanmalı, Ekran görüntüsü sabit olmalıdır.\\n3-Monitör çalışanı eğilmeye zorlamayacak şekilde arkaya eğimli, 15-50 derece arasında, dik oturarak çalışacak şekilde ayarlanmış olmalıdır.\\n4- Çalışanların periyodik göz muayenelerinin yapılmalıdır.\\n5- 45 dakikada bir gözler dinlendirilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":2},{\"anahtar\":\"hst-20254\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: İDARİ BİRİMLER\",\"faaliyet\":null,\"tehlike\":\"1- Ofislerde cam malzemelerin bulunması.                                 2- Kırık/çatlak pencere ve dolap camlarının bulunması\",\"risk\":\"1- El, kol ve yüz bölgesinde kesilme yaralanma\",\"mevcut_onlem\":\"1- Çalışanlar talep ettiklerinde gerekli bakımlar yapılmaktadır.\",\"oneri\":\"1- Kırık ve hasarlı camlar değiştirilmelidir.                                                                                                   2- Camlı dolap kapakları tüm sabitleme aparatları ( menteşe , fitil, ray, çerçece vb ) kontrol edilmelidir.                                                                                                                                            3- Dolap kapaklarına darbe emici bant veya güvenlik filmi uygulanmalıdır.                                                                                          4- Temperli veya lamine güvenlik camı kullanılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":2},{\"anahtar\":\"hst-20255\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: İDARİ BİRİMLER\",\"faaliyet\":null,\"tehlike\":\"1- Çalışanlara, diğer çalışanlar veya yöneticileri tarafından mobing uygulanması\",\"risk\":\"1-Sinirlilik, stres, depresyon, tükenmişlik sendromu, iş kazalarında artış\",\"mevcut_onlem\":\"1- Çalışan hakları birimi mevcuttur.                                        2- Psikososyal tehlike ve risk faktörleri hakkında eğitim verilmiştir.\",\"oneri\":\"1-Çalışanlara gerektiğinde psikolojik destek ve danışmanlık sağlanmalıdır.                                                                                                                                         2- Mobing bildirimi alındığında tarafsız inceleme süreci başlatılmalı, taraflar ayrı ayrı dinlenmeli, ve somut veriler ile kayıt tutulmalıdır.                                                                                                                            3- Tükenmişlik yaşayan çalışanlar düşük yoğunluklu birimlere kaydırılmalıdır.                                                                                                                                                             4- Şikayet konusu yönetici ise, yönetici davranış düzeltme sürecine (eğitim, gözlem vb.) alınmalıdır.                                                                                                                                                               5- Sürekli sorun çıkaran çalışanlar için eğitim, görev değişikliği ya da disiplin süreçleri başlatılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":2},{\"anahtar\":\"hst-20256\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: İDARİ BİRİMLER\",\"faaliyet\":null,\"tehlike\":\"1- Ofis temizliği ve havalandırma mazgallarının temizliğinin yeterince yapılmaması\",\"risk\":\"1- Enfeksiyona bağlı bulaş ve meslek hastalığı\",\"mevcut_onlem\":\"1- Temizlik, şirket çalışanları tarafından yapılmaktaır.\",\"oneri\":\"1- Ofisler günlük olarak temizlenmeli. havalanrdırma mazgallarında ayda bir toz temizliği yapılmalıdır.                                                                                                                                                                                               2- Temizlik çizelgeleri/formları bulundurulup düznli kontrolleri yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":3},{\"anahtar\":\"hst-20257\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: İDARİ BİRİMLER\",\"faaliyet\":null,\"tehlike\":\"1- Ofis çöplerine yanıcı malzemeler atılması\",\"risk\":\"1- Yangın çıkması\",\"mevcut_onlem\":\"1- Yangın algılama ihbar söndürme sistemleri mevcuttur.\",\"oneri\":\"1- Çöp kutuları ateş, alev kaynaklarından uzak tutulmalıdır.\\n2- Ofis alanlarında çöpler günlük toplanmalı ve çöp poşetleri günlük değiştirilmelidir.  \\n3- Yangına sebep olabilecek maddeler ya da birbirleri ile etkileşim sonucu yangın çıkarabilecek maddeler bir arada çöpe atılmamalıdır.                                                                      2- Çöp kovaları ayda bir dezenfekte edilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":3},{\"anahtar\":\"hst-20258\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: İDARİ BİRİMLER\",\"faaliyet\":null,\"tehlike\":\"1- Fotokopi makinesi, kağıt öğütücü, yazıcı gibi cihazların hareketli ve sıcak parçalarına temas\",\"risk\":\"1- El veya parmak yaralanmaları/ yanıkları\",\"mevcut_onlem\":\"1- Makine güvenlik kapakları genellikle kapalı durumdadır.            2- Arıza durumunda cihaz bakımları yapılmaktadır.\",\"oneri\":\"1- Cihazlar çalışırken kapağı açılmamalıdır.\\n2- Cihazlar çalışırken hareketli ve sıcak kısımlarına el ve kollar yaklaştırılmamalıdır.                                                                                                                                      3- Güvenlik sensörleri devre dışı bırakılmamalıdır.                                                                                                                                                              4- Güvenlik tertibatı olmayan ya da bozuk olan cihazlar kullanılmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":3}]', 0, 0, NOW(), NOW()
