SELECT u.`id`, 'Hastane — Birim: ÇAMAŞIRHANE', 'saglik', NULL, 'fine_kinney', '[{\"anahtar\":\"hst-20385\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ÇAMAŞIRHANE\",\"faaliyet\":null,\"tehlike\":\"1- Kurutma odası borularında sıvı sızıntısından dolayı kaygan zemin oluşması\",\"risk\":\"1-Kayma, düşme sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Sızıntının kaynağı tespit edilip boru onarımı veya arıza parça değişimi yapılmalıdır.    \\n2- Sızıntı sonucu oluşan kayma veya tehlikeli alan temizlenmeli ve kurulanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20386\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ÇAMAŞIRHANE\",\"faaliyet\":null,\"tehlike\":\"1- Kompresör odasına yetkisiz giriş yapılması\\n2- Kompresörün periyodik kontrollerinin yapılmaması\",\"risk\":\"1-Patlama sonucu yangın, uzuv kaybı,  meydana gelmesi,\",\"mevcut_onlem\":null,\"oneri\":\"1- Yetkisiz kişilerin girişi engellenmeli, kartlı giriş sistemi kullanılmalıdır.\\n2- Kompresörün acil durumlarda uzaktan durdurulmasını sağlamak için odanın dışına acil durdurma düğmesi takılmalıdır.                                                                                                                                                                           3-Kompresör, tank, ve emniyet valflerinin periyodik kontrolleri yapılmalıdır (TS 1203 EN 286-1, TS EN 13445-5, TS EN 764-7)\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20387\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ÇAMAŞIRHANE\",\"faaliyet\":null,\"tehlike\":\"1- Çamaşır taşıma arabalarının aşırı yüklenmesi\\n2- Aynalarının kırık olması\",\"risk\":\"1-Yüklerin görüşü kapatması  sonucu çalışana çarpma, yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1-Çamaşır taşıma işlerinde sadece lojistik tünel kullanılmalıdır.                                                                       2-Çamaşır taşıma arabaları fazla yüklenmemeli, çamaşırlar sabitlenerek taşınmalıdır.                              \\n3-Geri gidişlerde sesli ve ışıklı sinyaller aktif olmalıdır.                                                                  4-Lojistik tünel kullanım hızı 20 km/s geçmemelidir.                                                                     5-Hasarlı aynalar değiştirilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20388\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ÇAMAŞIRHANE\",\"faaliyet\":null,\"tehlike\":\"1-Yıkama makinelerin boru, bağlantı yerleri vb. noktalarından su sızıntıları olması\",\"risk\":\"1-Düşme, kayma sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Makinelerin boruları ve bağlantı yerleri su sızdırmayacak şekilde olmalı, hasarlı olan borular değiştirilmelidir.\\n2- Zemin, suyun birikmesini engelleyecek şekilde eğimli hale getirilmeli ve uygun drenaj sistemi sağlanmalıdır.                                                                                                                                                                                                    3- Su birikintileri anında temizlenmeli ve kurulanmalıdır.\\n4- Makinelerin elektrik kabloları suyla temas etmiyecek şekilde çift izolasyonlu olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20389\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ÇAMAŞIRHANE\",\"faaliyet\":null,\"tehlike\":\"1- Çamaşır makinesinden çıkan buharın elektrik tesisatı ve aydınlatmalara teması\",\"risk\":\"1--Elektrik çarpması sonucu yaralanma\",\"mevcut_onlem\":\"1-30 mA kaçak akım rolesi mevcuttur.\",\"oneri\":\"1- Elektrik kabloları ve bağlantı yerleri izole edilmelidir.\\n2- Elektrik kabloları çift izolasyonlu olmalıdır.\\n3- Kullanılan elektrik sistemleri etanj özellikte olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20390\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ÇAMAŞIRHANE\",\"faaliyet\":null,\"tehlike\":\"1-Islak ve kaygan zemin\",\"risk\":\"1-Zeminde oluşan ıslaklık nedeniyle düşme, yaralanma\",\"mevcut_onlem\":\"1-Kaygan zemin oluşması halinde temizlik yapılmaktadır.\",\"oneri\":\"1- Kaymaya sebep olacak kimyasal maddelerinin ve suyun zeminde birikmesi önlenmeli, hemen temizlenmelidir.\\n2- Temizlik işlemi sırasında zemin kurulanmalı temizlik esnasında uyarı tabelaları konulmalıdır.    \\n3- Çalışanlar kaymaz tabanlı ayakkabı giymelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20391\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ÇAMAŞIRHANE\",\"faaliyet\":null,\"tehlike\":\"1-Elektrik panolarının, pano odalarının yangın dolaplarının önlerinin kapatılmış olması\",\"risk\":\"1-Acil durumlarda hızlı müdahalenin sağlanamaması sonucu durumun şiddetinin artması\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.\",\"oneri\":\"1- Malzeme, çamaşır vb. pano ve  yangın dolaplarının önlerini kapatmaması sağlanmalıdır.\\n2-Panolara erişim için en az 80 cm genişlikte ulaşım yolları sağlanmalıdır.\\n3-Pano üzerlerine uyarı etiket ve işaretleri asılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20392\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ÇAMAŞIRHANE\",\"faaliyet\":null,\"tehlike\":\"1-Kirli alan çamaşır yıkama makinası ekipmanlarından köpük çıkması\",\"risk\":\"1- Kaygan zemin sonucu düşme yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1-Deterjan dozajlarının düzenli kontrol edilmeli ve doğru miktarda kullanımı sağlanmalıdır. \\n2-Dozaj pompası, filtre, köpük sensörü ve contalar sağlam yapıda olmalı, bozulanlar değiştirilmelidir.                                                        \\n3-Fazla köpüğün zemine dökülmesi önlenmeli, köpük borusu büyük kapların içine konulmalı, zemine dökülen köpük hemen temizlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20393\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ÇAMAŞIRHANE\",\"faaliyet\":null,\"tehlike\":\"1-Elektrik prizlerinin kırık olması\",\"risk\":\"1-Elektrik çarpması sonucu yaralanma\",\"mevcut_onlem\":\"1-30 mA kaçak akım rolesi mevcuttur.\",\"oneri\":\"1- Çalışma alanında hasarlı elektrik prizlerinin onanarımı ve değişimi sağlanmalıdır. \\n2- Kırık prizler onarılana kadar kullanım dışı bırakılmalı, elektrik akımı kesilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20394\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ÇAMAŞIRHANE\",\"faaliyet\":null,\"tehlike\":\"1- Çamaşırhane dikim alanında elektrik kablolarının korumasız şekilde yerde bulunması ve uygunsuz uzatma kablosu kullanılması\",\"risk\":\"1-Elektrik çarpması, yangın çıkması, takılma/düşme, iş kazası\",\"mevcut_onlem\":null,\"oneri\":\"1- Kullanılan uzatma kabloları halejen free özellikte olmalıdır.\\n2- Yerden geçen uzatma kabloları takılma düşmeye sebep olmayacak şekilde düzenlenmelidir.\\n3- Elektrik kablolarında yırtık, izolasyon bozlukluğu vb. olmamalı, olan kablolar kullanılmamalı değiştirilmelidir.\\n4- Elektrik kabloları makine ya da ekipmanların altına konulmamalı, kabloların ezilmesi önlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20395\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ÇAMAŞIRHANE\",\"faaliyet\":null,\"tehlike\":\"1-Ütüleme ve katlama makinasin döner aksamlarının yanlarının açık olması\",\"risk\":\"1- Dönen kısımlara kaptırma sonucu yaralanma\",\"mevcut_onlem\":\"1-Ön kısımda fotosel mevcuttur\",\"oneri\":\"1-Ütü ve katlama makinesinin yan kısımda bulunan dönen aksamları koruyucu kapak veya muhafaza ile kapatılmalıdır.                                     \\n2-Makine çalıştırılmadan önce tüm koruyucuların takılı ve sağlam olduğu kontrol edilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20396\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ÇAMAŞIRHANE\",\"faaliyet\":null,\"tehlike\":\"1-Makinelerin gövde topraklama ölçümlerinin yapılmamaış olması                                            2-Yıpranmış, ezilmiş kablolar\",\"risk\":\"1-Elektrik çarpması sonucu kalp ritim bozuklukları, elektrik yanıkları\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.\",\"oneri\":\"1-Makinelerin gövde topraklama ölçümleri yaptırılmalı, belgelendirilmelidir.\\n2-Cihazlar durdurulmadan ve akım kesilmeden bakım, arıza onarım ve müdahaleler yapılmamalıdır.\\n3-Yıpranmış, ezilmiş, soyulmuş ve izolasyonsuz kablolar değiştirilmelidir.                                                                                                                           4- Makikenelerin elektrik kabloları çift izolasyonlu olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20397\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ÇAMAŞIRHANE\",\"faaliyet\":null,\"tehlike\":\"1-Kimyasal dozajlama cihazına kimyasalların takılması sonucu dökülmesi\",\"risk\":\"1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması\",\"mevcut_onlem\":\"1- Taşma kapları mevcuttur.\",\"oneri\":\"1- Kimyasal bidonları her zaman taşma kapları üzerinde bulundurulmalı,  zemine dökülmesi önlenmelidir.                                                                                                                              2- Bidonlar devrilmeyecek şekilde konulandırılmalı,  dozajlama horyumları sağlam olmalıdır.                                                                                                                                                                                                                                                                            3- Boşalan kimyasal madde kapları, bekletilmemeli, atığa gönderilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":2},{\"anahtar\":\"hst-20398\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ÇAMAŞIRHANE\",\"faaliyet\":null,\"tehlike\":\"1- Çamaşır yıkama makinasının çalışırken kapağının açılması\",\"risk\":\"1- Sıcak su ve kimyasallara maruz kalma sonucu iş kazaları meydana gelmesi\",\"mevcut_onlem\":null,\"oneri\":\"1-Çamaşır yıkama makinesinin kapak emniyet kilitleri her zaman aktif olmalı, makine çalışırken kapağın açılmaması sağlanmalıdır.\\n2- Kapak açıldığında makine otomatik durmalıdır.\\n3- Bozuk olan kapak emniyet kilitleri onarılana kadar makineler kullanılmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":2},{\"anahtar\":\"hst-20399\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ÇAMAŞIRHANE\",\"faaliyet\":null,\"tehlike\":\"1-Tehlikeli kimyasalların yanlış depolanması\",\"risk\":\"1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması\",\"mevcut_onlem\":\"1- Kimyasal madde deposu mevcuttur.\\n2- Göz duşu bulunmaktadır.\",\"oneri\":\"1- Kimyasal maddeler depolama matirsine göre depolanmalıdır.                                                        2- Kimyasal maddelerin ağzı açık olmamalı, dik olarak istiflenmelidir.\\n3- Kimyasal madde kaplarının altına taşma kapları konulmalıdır.\\n4- Kimyasalların dökülme riskine karşı döküntü kitleri bulundurulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20400\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ÇAMAŞIRHANE\",\"faaliyet\":null,\"tehlike\":\"1- Sıcak yüzey ve boruların izolasyonlarının bozulmuş olması\",\"risk\":\"1-Temas eden vücut bölümlerinde ısı yanıkları meydana gelmesi\",\"mevcut_onlem\":null,\"oneri\":\"1- Sıcak yüzeyler izole edilmelidir.\\n2- İzolasyonu bozulmuş olan alanlara yeniden izolasyon yapılmalıdır. \\n3- Sıcak yüzeylere uyarı etiket ve işaretler konulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":1}]', 0, 0, NOW(), NOW()
FROM `users` u WHERE u.`email` = 'mozdemir2816@gmail.com' AND NOT EXISTS (SELECT 1 FROM `risk_sablonlari` s WHERE s.`user_id` = u.`id` AND s.`ad` = 'Hastane — Birim: ÇAMAŞIRHANE');

