SELECT u.`id`, 'Hastane — Birim: ACİL SERVİS', 'saglik', NULL, 'fine_kinney', '[{\"anahtar\":\"hst-20401\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL SERVİS\",\"faaliyet\":null,\"tehlike\":\"1- Günlük hasta müracat sayısının fazla olması\",\"risk\":\"1-Fiziksel şiddet sonucu yaralanma\",\"mevcut_onlem\":\"1-Güvenlik görevlileri alanlarda dolaşım sağlamaktadır.\",\"oneri\":\"1- Acil servise girişlerde hasta yanında tek refakatçiye izin verilmelidir.                                                                                                  2- Sonuç bekleyen ayaktan hastalar bekleme salonlarına yönlendirilmelidir.                                                                                                   3- Çalışanlar, triaj alanınla bulunan kapıyı hasta içeri girmeden önce açımalı ve tekrar kapatılmalıdır.                                                                                                                                                        4- Yeterli sayıda güvenlik personeli alanlarda bulunmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20402\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL SERVİS\",\"faaliyet\":null,\"tehlike\":\"1-Çalışanların fazla mesai ile çalışması                                                          2- İş yükünün fazla olması\",\"risk\":\"1-Dikkatin azalması, yorgunluk, uykusuzluk, sonucunda iş kazalarının oluşması\",\"mevcut_onlem\":null,\"oneri\":\"1- Fazla mesai süreleri yasal sınırlarla En fazla 130 saat olmalıdır.                                                                                                                                             2- 24 saatlik nöbetten sonra çalışanlara en az 24 saat dinlenme süresi verilmelidir.                               \\n3- Gün aşırı nöbet sayısı azaltılmalıdır.                                                                                                            4- Çalışanların düzenli sağlık kontrolleri yapılmalı ve yeterli dinlenme süreleri sağlanmalıdır.                                                                                                                                                                                                                                                                                                                                                    5- Yorgunluk ve stres yönetimi için psikososyal destek programları sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20403\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL SERVİS\",\"faaliyet\":null,\"tehlike\":\"1- Sarı 1 müşahade alanında hemşire çalışma alanlarının açık olması\",\"risk\":\"1- Hasta ya da yakınları tarafından fiziksel ya da sözlü şiddete maruz kalma sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Sarı 1 müşehade hemşire çalışma alanı duvarlar arası açıklık  kapı paravan vb ile kapatılarak, çalışanların arasından hasta ve hasta yakınlarının geçmesi önlenmelidir. \\n2- Hemşire çalışma alanına, \\\"çalışanlar hariç girmek yasaktır\\\" uyarı evhası konulmalıdır.  \\n3- Erişkin acil sarı 1 müşehadede tıbbı sekreterler için çalışma kabini yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20404\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL SERVİS\",\"faaliyet\":null,\"tehlike\":\"1- Yeşil enjeksiyon odasında fazla sayıda hasta olması\",\"risk\":\"1- Hasta ya da yakınları tarafından fiziksel ya da sözlü şiddete maruz kalma sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Yeşil enjeksiyon odası ikinci bir oda açılarak oda işlem sayısı düşürülmelidir.\\n2- Yeşil enjeksiyon odası çalışanlarına yaka panik butonları verilmelidir.\\n3- Hastalar odaya sıra ile alınmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20405\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL SERVİS\",\"faaliyet\":null,\"tehlike\":\"1- Hasta ve yakınlarıyla tartışma\",\"risk\":\"1- Hasta ya da yakınları tarafından fiziksel ya da sözlü şiddete maruz kalma sonucu yaralanma\",\"mevcut_onlem\":\"1- Birçok alanda sabit panik butonları mevcuttur.\\n2-  Bazı kapılarda güvenlikler sabit beklemektedir.\",\"oneri\":\"1- Erişkin acil kan alma odası, çocuk kan alma odası  vb. hasta ve hasta yakınları tarafından fiziksel şiddete maruz kalma riski yüksek olan bölüm çalışanlarına kişisel panik butonu temin edimelidir.                                                                                                        2- Kritik müşahede hemşire tedavi alanına saibit panik butonu takılmalıdır.                                                                                                                        3- Yeterli sayıda sabit güvenlik personeli bulundurulmalıdır.                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             4- Triaj alanında bulunan kapılar buton sistemi ile açılıp kapatılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20406\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL SERVİS\",\"faaliyet\":null,\"tehlike\":\"1- Basınçlı oksijen tüplerinin sabitlenmemesi\",\"risk\":\"1- Tüplerin düşmesi, devrilmesi sonucu patlama meydana gelmesi\",\"mevcut_onlem\":\"1- Birçok alanda sabitleme aparatı mevcuttur.\",\"oneri\":\"1- Oksijen tüpünün kullanıldığı her odada sabitleyici aparat bulunmalıdır.\\n2- Seyyar ventilatöre bağlı oksijen tüpü en az az iki noktadan sabitlenmelidir \\n3- Tüp kullanılmadan önce ezik , çökme hava kaçırma açısından kontrol edilmelidir. Basınç göstergeleri ve vanaların her kullanımdan önce kontrol edilmelidir.                                                                                 \\n4- Yatak ve sedye için, sabitleme aparatı, oksijen tüpü taşıma çantası ile çalışılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20407\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL SERVİS\",\"faaliyet\":null,\"tehlike\":\"1- Entübe hastaların mr çekilmesi için poliklinik mr a çıkartılması\",\"risk\":\"1- Tüplerin düşmesi, devrilmesi sonucu patlama meydana gelmesi\",\"mevcut_onlem\":null,\"oneri\":\"1- Acil servis içerisinde bulunan mr cihazına  uyumlu sabit ventilatör cihazı olmalıdır.                                                                                                                    2- Ventilatör cihazına oksijen tüpü çift bant ile sabitlenmelidir.      \\n3- Tüplerin taşınması esnasında vanaları kapalı olmalı, dik taşınmalı, kapağı kapalı olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20408\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL SERVİS\",\"faaliyet\":null,\"tehlike\":\"1-Defibilatörün emniyetsiz kullanımı\",\"risk\":\"1-Defibrilatör kullanımı sırasında elektrik çarpması, elektrik yanıkları oluşması\",\"mevcut_onlem\":null,\"oneri\":\"1-Defibrilasyon esnasında hastaya elektrotlara ve diğer iletken nesnelere dokunulmamalıdır.\\n2-Hastaya ıslak  ve iletken ortamlarda defibrilasyon uygulanmamalı, hastanın göğsünde ıslaklık, jel, ter olmamalı, hastanın göğüsü kurulanmalıdır.\\n3-Defibrilatör cihazı oksijen tüpü, alkol vb. yanıcı sıvı ve gazların bulunduğu ortamlarda kullanılmamalıdır.                                                                               4- Hastanın ve defibilatörü kullanan çalışanın üzerinde metal eşyalar bulunmamalıdır.                                                                                           5- Ortamda bulunan diğer çalışanlar en az 1 metre uzakta bulunmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20409\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL SERVİS\",\"faaliyet\":null,\"tehlike\":\"1- Kesici delici alet yaralanması\",\"risk\":\"1- Kullanılmış aletlere temas sonucu el kol yaralanmaları, enfeksiyon, bulaşıcı hastalıklara yakalanma\",\"mevcut_onlem\":\"1- Alanda sharp box kutusu bulunmaktadır.\",\"oneri\":\"1- Çalışanlar tedavi tepsisi kullanmalı, iğne kapağı kapatılmadan kesici delici alet kutusuna atılmalıdır.                                                                                              2- Kesici delici alet kutu kapakları vacoteynır çıkartmaya uyumlu olmalıdır.                                                                                                                                                                                                                                                                                                                                                          3- Alanda bulunan sharp boxlar 3/4 ü dolduktan sonra değiştirilmelidir.                                                                                           4- Hasta yataklarına iğne uçları saplanmamalı, iğne uçları pendant üzerine bırakılmamalıdır.    \\n5- Çalışanlar TS EN 455 standardında çift eldiven kullanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20410\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL SERVİS\",\"faaliyet\":null,\"tehlike\":\"1- Kan ve vücut sıvılarının göz ve cilde temas etmesi\",\"risk\":\"1-Temas sonucu enfeksiyon, bulaşıcı hastalıklara yakalanma\",\"mevcut_onlem\":\"1- Çalışanlar eldiven ve maske kullanmaktadır.\",\"oneri\":\"1-Çalışanlar TS EN 455  standardında eldiven, TS EN 166 standardında tam kapalı gözlük ya da yüz siperi, uzun kollu koruyucu önlük  EN 14683 standardında maske vb. gibi kişisel koruyucu donanımlar kullanılmalıdır.                                                                                                                         2- Temas durumunda bölgenin bol su ve sabunla yıkanması sağlanmalıdır.                                                                                                                                    3- Kan ve vücut sıvıları sıçramasına maruz kalma sonrası çalışanın, bulaş kaynağının durumuna göre muayene ve tetkikleri yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20411\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL SERVİS\",\"faaliyet\":null,\"tehlike\":\"1-Basınçlı tüplerin hatalı kullanılması\",\"risk\":\"1- Tüplerin düşmesi, devrilmesi sonucu patlama meydana gelmesi\",\"mevcut_onlem\":\"1-Oksijen tüpü sabitleme aparatları bulunmaktadır.\",\"oneri\":\"1- Oksijen tüplerine yağlı, kremli eller ile temas edilmemeli, vanaları yağlanmamalıdır.                                                                                                                                   2- Tüpler ısı kaynaklarından ve güneşin etkisinden uzak tutulmalıdır.                                                                                                                                    3- Manometreler sağlam olmalı, kırık olanlar değiştirilmelidir.                                       \\n4- Basınçlı tüpler zeminde sabitlenmeden bırakılmamalı, sabitleme aparatlarına takılmalı ve 2 noktadan zincir ya da halatla bağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20412\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL SERVİS\",\"faaliyet\":null,\"tehlike\":\"1- Cpr odasına müdahale esnasında hasta yakınlarının girmesi\",\"risk\":\"1- Hasta ya da yakınları tarafından fiziksel ya da sözlü şiddete maruz kalma sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Cpr odasına müdahale esnasında hasta yakınlarının girmesi engellenmelidir. \\n2- Hasta yakınlarının yanında güvenlik personeli bulunmalıdır.  \\n3- Müdahale esnasında perde kapatılmalıdır.                                                                                                                                                                                                                                                                                                                 4- Kesici delici aletler ortalıkta bırakılmamalı, büyük makas işlemden sonra seyyar pendant çekmecesinde muhafaza edilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20413\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL SERVİS\",\"faaliyet\":null,\"tehlike\":\"1- CPR odasına bulaşıcı hastalığı olan entübe hastaların gelmesi\",\"risk\":\"1- Bulacı hastalık  2- Enfeksiyon\",\"mevcut_onlem\":null,\"oneri\":\"1- CPR odasına zaman ayarlı, TS EN 62471 standartına uygun UV lambaları konulmalıdır.\\n2- UV-C lambalarında alttan, üstten ve yandan ışık sızıntısı olmamalıdır.\\n3- UV-C lambalarının yüzeyi yansıma yapmayacak şekilde olmalıdır.\\n4- UV Lambaları çalışanlar bölümdeyken çalıştırılmamalıdır.\\n5- UV lambasını kapatmak için odaya girildiğinde TS EN 170 standartında uv gözlük, uzun kollu koruyucu kıyafet, uv geçirmeyen eldiven vb. kişisel koruyucu ekipmanlar kullanılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20414\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL SERVİS\",\"faaliyet\":null,\"tehlike\":\"1- Uzun sürelerle ayakta çalışılması\",\"risk\":\"1- Kas iskelet sistemi hastalıkları \\n2- Varis oluşması\",\"mevcut_onlem\":\"1- Çalışanlar için dinlenme odaları mevcuttur.\",\"oneri\":\"1- Çalışanlar 45 dakikalık periyotlarla oturarak dinlenmelidirler. \\n2- Çalışanlar ortopedik tabanlı iş ayakkabısı giymeli, eksik malzemeler temin edilmelidir.\\n3- Yeterli dinlenme molaları verilmeli, rotasyonlu çalışma yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20415\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL SERVİS\",\"faaliyet\":null,\"tehlike\":\"1- Vucut sıvılarının dökülmesi\",\"risk\":\"1-Düşme, denge kaybı sonucunda  yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Vücut sıvıları zemine döküldüğünde bekletilmemeli, hemen temizlenmesi sağlanmalıdır.\\n2- İdrar torbası askıları alanda hasta yatakları ve sedyelere asılmalıdır.                                                                                                                                      3- İdrar torbasının boşaltımı esnasında under ped ya da kap konularak dökülme saçılma engellenmelidir.                                                                                                                                                                                                                                                                                                                                     4- Kan ürünü temizliği için alkol kullanılmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20416\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL SERVİS\",\"faaliyet\":null,\"tehlike\":\"1- Kan alma koltuklarının kollarının kırık olması\",\"risk\":\"1- Kesici delici alet yaralanması                   2- iş kazası\",\"mevcut_onlem\":null,\"oneri\":\"1- Hasarlı ya da kırık kan alma kotukları değiştirilmeli ya da onarılmalıdır.\\n2- Koltuk kolları sağlam olmalı, kan alma işlemi sırasında sabit olması sağlanmalıdır.\\n3-  Koltuk yüksekliği çalışanı rahatsız edici göz ve baş hareketleri ihtiyacını en aza indirecek şekilde olmalıdır.                    \\n3- Sandalyeler ergonomik tasarıma sahip olmalı, gerekli hallerde ayak desteği kullanılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20417\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL SERVİS\",\"faaliyet\":null,\"tehlike\":\"1- Pediatrik kan alma odasında havalandırma sistemi olmaması\",\"risk\":\"1- Solunum sistemi hastalıkları\",\"mevcut_onlem\":null,\"oneri\":\"1- Pediatrik kan alma odasına havalandırma sistemi yapılmalıdır.                                                                                                                                         2- Odada bulunan banyo giderinden gelen koku gider kapatılarak bertaraf edilmelidir.                                                                                          \\n3- Odada ısı nem ölçer bulunmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20418\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL SERVİS\",\"faaliyet\":null,\"tehlike\":\"1- Çalışanların yüksek gürültüye maruz kalması\",\"risk\":\"1-Dikkatin azalması\\n2- Yorgunluk, uyku bozuklukları,\\n3- İş kazalarında artış\",\"mevcut_onlem\":null,\"oneri\":\"1- Gürültü ölçümleri yapılarak gürültü düzeyi belirlenmelidir.                                                                                                2- Hasta refakatçi sayısı en aza indirilmelidir.                                                                                                 3- Ölçümlerin 85 Db üzerinde çıkan alanlarda TS EN 352  standardında kkd kulak koruyucularını temini ve kullanımı sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20419\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL SERVİS\",\"faaliyet\":null,\"tehlike\":\"1- Bulaşıcı hastalığı olan ya da şüphesi olan hastalar\",\"risk\":\"1-Enfeksiyon, bulaşıcı hastalıklara yakalanma\",\"mevcut_onlem\":\"1-Acil de negatif basınçlı odalar mevcuttur.???\",\"oneri\":\"1-Bulaşıcı hastalık şüphesi olan hastalar, sonuçları çıkana kadar tek kişilik izolasyon odalarında tutulmalıdır.                                                                                           2- Şüpheli hastaların bulunduğu alanın teması bittikten sonra hemen dezenfekte edilmelidir.                                                                                                                          3- Tanı konulmuş hastalar negatif basınçlı odalara alınarak izole edilmelidir.                                                                                                                                                                                                                                                                  5-Çalışanlar N95 ya da TS EN 149 standrtdında FFP2 filtreli maske, yüz siperi, TS EN 455  standardında eldiven kullanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20420\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL SERVİS\",\"faaliyet\":null,\"tehlike\":\"1- Psikiyatri hastalarının alanda tedavi edilmesi\",\"risk\":\"1- Psikiyatri hastası tarafından fiziksel şiddete uğrama\",\"mevcut_onlem\":\"1- Yumuşak oda mevcuttur.\",\"oneri\":\"1- Akli dengesi yerinde olmayan ya da saldırgan davranış gösteren hastalar yumuşak oda da tedavi edilmelidir.                                                                                               2- Yumuşak odadaki hastaya tedavi uygulama esnasında güvenlik eşlik etmeli ve çift hemşire ile odada çalışılmalıdır.                                                                                                                                                          3- Yumuşak odadaki kapı penceresi kırılmaz cam olmalıdır.                                                                  \\n4- Yumuşak oda içinde yatağa sabitleyici aparat alanda bulunmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20421\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL SERVİS\",\"faaliyet\":null,\"tehlike\":\"1- Kan gazı ve mikroskop cihazları kullanılırken numunelerin dökülmesi\",\"risk\":\"1- Enfeksiyon         2- İş yükü\",\"mevcut_onlem\":\"1- KKD\'ler mevcuttur.\",\"oneri\":\"1- Kan gazı ve mikroskop cihazlarının bulunduğu alan yüzey bakımından silinebilir ve dezenfekte edilebilir olmalıdır.                                                                                \\n2- Numuneleri dökülmesi durumunda hemen dökülen yüzey dezenfekte edilmelidir.                                                                                                                                                           3- Maske, eldiven, yüz siperi vb. kkdler kullanılmadan cihazlarda çalışılmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":3},{\"anahtar\":\"hst-20422\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL SERVİS\",\"faaliyet\":null,\"tehlike\":\"1- Çalışanların dinlenme alanının koltukluların deforme olması, ısı nem ölçerlerinin bulunmaması\",\"risk\":\"1-Enfeksiyon, kas, iskelet  ve sinir sistemi hastalıkları, solunum sistemi hastalıkları\",\"mevcut_onlem\":\"1- Havalandırma sistemi mevcuttur.\",\"oneri\":\"1- Dinlenme odalarında ki deforme olmuş koltuklar ya değiştirilmeli ya da onarılmalıdır.                                                                                                                                                                                       2- Dinlenme odalarında ısı nem ölçerler bulumalıdır.                                                                                                                                                                                                    3- 24 saat nöbet usulü çalışanların dinlenme alanları ulaşılabilir ve açık tutulmalıdır.                                                                                                                       4- Dinlenme odalarında kişi başına düşen hava miktarı en az 10 metreküp olacak şekilde iş organizasyonu yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20423\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL SERVİS\",\"faaliyet\":null,\"tehlike\":\"1- Ekranlı araçlarla çalışmalarda sağlık ve güvenlik önlemlerinin alınmaması\",\"risk\":\"1- Göz yorgunluğu,göz kuruluğu, bulanık görme.                                                                    2- Stres, dikkat dağınıklığı\",\"mevcut_onlem\":\"1- Dinlenme molaları mevcuttur.\",\"oneri\":\"1- Ekran parlaklığı ve çözünürlüğü kişiye göre ayarlanmalı, Ekranın çalışana uzaklığı en az 60 cm olmalı ve çalışanın göz hizasında olmalıdır.                                                                                      \\n2- Sandalyeler ergonomik tasarıma sahip olmalı, ayaklar düz olarak yere temas etmeli, diz 90 derece açılı olmalı,  sandalyede bel desteği olmalı,  sırt dik, omuzlar rahat, dirsekler 90 derece açılı olmalıdır.                                                                 \\n3- Mouse destek pedi temin edilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20424\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL SERVİS\",\"faaliyet\":null,\"tehlike\":\"1- Portable röntgen cihazının kullanımı sonucunda radyasyon ışınlarına  maruz kalma\",\"risk\":\"1-Radyasyon maruziyeti sonucu meslek hastalıkları\",\"mevcut_onlem\":\"1- Kurşun önlükler mevcuttur.\",\"oneri\":\"1- Taşınabilir röntgen cihazı ile yapılan çekimler de kurşun paravan kullanılmalıdır.                                                                                                                                                               2- Çekim yapılan alanda hasta ve çekim yapan çalışan dışında kimse olmamalı, zorunlu hallerde bulunulması gerekirse(TS EN 61331 standardında kurşun önlük troid koruyucu vb.kişisel koruyucu ekipmanlar kullanılmalıdır.                                                                                                       3- Çekim yapılan odaların kapıları kapatılmalıdır.                                                                                           4- Açık alanlarda yapılan çekimlerde çalışanlar en az 2 metre uzakta durmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20425\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL SERVİS\",\"faaliyet\":null,\"tehlike\":\"1- Yotalanmamış esyaların bulunması\",\"risk\":\"1- İş kazası                   2- Devrilme            3- Ezilme\",\"mevcut_onlem\":\"1- Bazı dolaplar duvara sabitlenmiştir.\",\"oneri\":\"1- Alanda , dinlenme odalarında , süper visör odalarında ve Acil servisler içindeki dolaplar, ranzalar, metal tel dolaplar en az iki noktadan duvara sabitlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":2},{\"anahtar\":\"hst-20426\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL SERVİS\",\"faaliyet\":null,\"tehlike\":\"1-İsmi bilinmeyen bilinci kapalı  hastaların acil müdehale için getirilmesi\",\"risk\":\"1- Enfeksiyon hastalıklarına yakalanma\",\"mevcut_onlem\":\"1-KKD\'ler mevcuttur.\",\"oneri\":\"1- Klinik geçmişine ulaşılamayan hastaları enfekte kabul edilmeli eldiven, maske, gözlük, önlük gibi kkdler kullanılmalıdır.                                                                                                                  2-  Hastane polisi ile kısa sürede iletişime geçilerek hasta bilgilerine ulaşım sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":2},{\"anahtar\":\"hst-20427\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL SERVİS\",\"faaliyet\":null,\"tehlike\":\"1- Hastaların yoğun bakım ve ameliyathaneye transfer esnasında transfer çantası kullanılmaması\",\"risk\":\"1- Kesici delici aletlere temas sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Hasta transferi yapılırken çalışanın üzerinde  ampül enjektör vb kesici delici alet bulunmamalıdır.                                                                                                        2- Hasta tranfer çantası kullanılmalıdır.                                                                                                                   3- Çantalar hasta yataklarına düşmeyecek devrilmeyecek şekilde konumlandırılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":3},{\"anahtar\":\"hst-20428\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL SERVİS\",\"faaliyet\":null,\"tehlike\":\"1- Taşıma tahtalarının sabitlenmemesi\",\"risk\":\"1-Tahtalrın düşmesi sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Alanda bulunan taşıma tahtaları duvara sabitlenmelidir.                  \\n2- Tahtalar için sabit alan belirlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":3},{\"anahtar\":\"hst-20429\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL SERVİS\",\"faaliyet\":null,\"tehlike\":\"1- Su sebillerinin bakım ve temizliğinin yapılmaması.                                           2- Su sebillerinin su sızdırması\",\"risk\":\"1-Enfeksiyon, bulaşıcı hastalıklara yakalanma\",\"mevcut_onlem\":\"1- Enfeksiyon riskleri hakkında eğitim verilmiştir.\",\"oneri\":\"1- Su sebillerinin bakımları  düzenli aralıklarla yaptırılmalıdır.                                                                                   2- Su sebillerinin temizliği düzenli aralıklarla yaptırılmalıdır.                                                                                                                                                                          3- Su sızıntılarından kaynaklı riskleri önlemek için su sebillerinin altlarına taşma havuzu konulmalıdır.                                                                                                                                                                                                                                      4- Su sebillerinin bulunduğu zemin davamlı kuru tutulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":3},{\"anahtar\":\"hst-20430\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL SERVİS\",\"faaliyet\":null,\"tehlike\":\"1- Refakatçilerin beklerken çalışan sandalyelerini alması\",\"risk\":\"1- Beyaz kod                  2- Enfeksiyon\",\"mevcut_onlem\":null,\"oneri\":\"1- Alanda yeterli refakatçi sandalyesi bulunmalı, eksik sandalyeler temin edilmelidir.                             \\n2- Refakatçi sandalyeleri enfeksiyon açısından silinebilir deri , plastik vb malzemeden olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":3},{\"anahtar\":\"hst-20431\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: AMBULANSLAR\",\"faaliyet\":null,\"tehlike\":\"1- Eskimiş, aşınmış  lastiklerin kullanılması\\n2- Mevsime uygun lastik kullanılmaması\",\"risk\":\"1-Trafik kazası sonucunda ölüm, sakatlık, uzuv kaybı, yaralanmaların meydana gelmesi\",\"mevcut_onlem\":\"1- Ambulanslar hastane içinde ya da hasta nakil için kullanılmaktadır.\",\"oneri\":\"1- Mevsim şartlarına uygun yazlık-kışlık lastikler kullanılmalı, karlı havalarda zincir kullanılmalıdır.\\n2- Aşınan, yıpranan, ezilen, balon yapan lastikler yenileri ile değiştirilmelidir.\\n3- Lastik havaları mevsim şartlarına ve üretici tavsiyelerine uygun basınçta şişirilmelidir.\\n4- Kaygan yollarda, sisli havalarda araçlar çok düşük hızlarda kullanılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20432\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: AMBULANSLAR\",\"faaliyet\":null,\"tehlike\":\"1-Eve hasta nakil sırasında trafik kurallarına uyulmaması\",\"risk\":\"1-Trafik kazası sonucunda ölüm, sakatlık, uzuv kaybı, yaralanmaların meydana gelmesi\",\"mevcut_onlem\":null,\"oneri\":\"1- Nakil ambulansları yasal hız limitlerinden %10 daha düşük hızda kullanılmalıdır.\\n2- Nakil ambulansları sağ şeritte ve yavaş kullanılmalıdır.\\n3- Trafik kurallarına uyulmalı, sinyalizasyon sistemi mutlaka kullanılmalı, takip mesafesi korunmalıdır.\\n4- Seyir halinde şoför ve araç içinde bulunan çalışanların emniyet kemerleri mutlaka takılı olmalıdır.\\n5- Araçalar seyir halindeyken sigara içilmemelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":40,\"frekans\":2},{\"anahtar\":\"hst-20433\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: AMBULANSLAR\",\"faaliyet\":null,\"tehlike\":\"1- Ambulans bakım ve servis işlemlerinin düzenli yapılmaması\",\"risk\":\"1-Trafik kazası sonucunda ölüm, sakatlık, uzuv kaybı, yaralanmaların meydana gelmesi\",\"mevcut_onlem\":\"1- Ambulansların periyodik kontrolleri yapılmaktadır.\",\"oneri\":\"1- Ambulanslar kullanmaya başlanmadan önce günlük kontrolleri yapılmalıdır.\\n2- Her 3 ayda veya 10.000 km’de bir yetkili bir servise periyodik bakım yaptırılmalıdır.\\n3- Yılda bir kez yaptırılacak fren bakımı kayıtları olmalıdır. \\n4- Araç ruhsatında süresi geçmemiş fenni muayene ve egzoz emisyon test raporları mevcut olmalıdır.\\n5- Tespit edilen eksiklikler giderilmeden araçlar kullanılmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20434\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: AMBULANSLAR\",\"faaliyet\":null,\"tehlike\":\"1- Sedye ile hasta taşıma sırasında güvenlik önlemlerinin alınmaması\",\"risk\":\"1- Kas iskelet sistemi hastalıkları\",\"mevcut_onlem\":\"1- Sedyelerin tekerlek frenleri mevcuttur.\",\"oneri\":\"1- Sedye, tekerlekli sandalye vb. ekipmanların ayaklarında frenleri sağlam olmalıdır.\\n2- Sedye ile taşıma işleri en az 2 çalışan tarafından yapılmalıdır.\\n3- Hastalar sedye ile taşınırken emniyet kemeri ile bağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20435\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: AMBULANSLAR\",\"faaliyet\":null,\"tehlike\":\"1- Yangın tüpü kontrollerinin yapılmamış olması\",\"risk\":\"1- Yangın durumunda müdahaele edilememesi\",\"mevcut_onlem\":\"1-Ambulans içinde yangın söndürücü bulunmaktadır.\",\"oneri\":\"1- Ambulansta bir adet hasta kabininde, bir adet sürücü kabininde 2\'şer litrelik kuru kimyevi tozlu yangın söndürücüler bulunmalıdır.                   \\n2- Yangın tüplerinin kontrol ve bakımları yapılmalı, tüpler her zaman dolu olmalıdır.\\n3- Tüpler ambulans içinde dik konumda sabitlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20436\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: AMBULANSLAR\",\"faaliyet\":null,\"tehlike\":\"1- Ambulans içinde oksijen tüpü kullanılması\",\"risk\":\"1- Tüplerin düşmesi, devrilmesi sonucu patlama meydana gelmesi\",\"mevcut_onlem\":\"1- Tüp dolabı mevcuttur.\",\"oneri\":\"1- Ambulans içindeki taşınabilir oksijen tüpü defibrilatör gibi elektrikli cihazların yanında bulunmamalıdır.                                             \\n2- Oksijen tüpleri devrilme açısından en az iki noktadan sabitlenmelidir.                                                                                                                                                                            3- Yağlı kremli vb ellerle dokunulmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20437\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: AMBULANSLAR\",\"faaliyet\":null,\"tehlike\":\"1- Tıbbi ekipmanın ve ambulansın her vaka sonrası  dezenfekte edilmemesi\",\"risk\":\"1- Bulacı hastalık  2- Enfeksiyon\",\"mevcut_onlem\":null,\"oneri\":\"1- Tıbbi ekipman ve ambulansın her vaka sonrası kontrol ve dezenfekte edilmesi sağlanmalıdır.               \\n2- Vaka sonrası ambulanslar havalandırılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":3}]', 0, 0, NOW(), NOW()
FROM `users` u WHERE u.`email` = 'mozdemir2816@gmail.com' AND NOT EXISTS (SELECT 1 FROM `risk_sablonlari` s WHERE s.`user_id` = u.`id` AND s.`ad` = 'Hastane — Birim: ACİL SERVİS');

INSERT INTO `risk_sablonlari` (`user_id`, `ad`, `sektor`, `sektor_adi`, `yontem`, `maddeler`, `paylasildi`, `kullanim_sayisi`, `created_at`, `updated_at`)
SELECT u.`id`, 'Hastane — Birim: ECZANE DEPO ARŞİV', 'saglik', NULL, 'fine_kinney', '[{\"anahtar\":\"hst-20438\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DEPO ARŞİV\",\"faaliyet\":null,\"tehlike\":\"1-Sığınakların depo olarak kullanılması\",\"risk\":\"1- Acil durumlarda sığınakların kullanılamaması sonucu yaralanma, ölüm\",\"mevcut_onlem\":null,\"oneri\":\"1- Hastane de savaş, afet, kimyasal / biyolojik vb. acil durumlarda kullanılması gereken sığınakların depo olarak kullanılması tamamen sonlandırırlmalıdır.\\n2- Sığınaklarda ki malzemeler boşaltılamı, acil durumlara hazır hale getirilmelidir.\\n3- Depo ihtiyacı için ayrı alanlar oluşturulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":100,\"frekans\":3},{\"anahtar\":\"hst-20439\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DEPO ARŞİV\",\"faaliyet\":null,\"tehlike\":\"1- Raf önü tutucuların bulunmaması                                           2- Endüstriyel rafların sabitlenmemesi\",\"risk\":\"1- Malzeme düşmesi sonucu  yaralanma, ezilme, sıkışma\",\"mevcut_onlem\":\"1-Bazı bölümlerde volanlı ray sistemi mevcuttur.\",\"oneri\":\"1- Tüm arşiv alanlarında volanlı raylı sistem kullanılımalıdır.\\n2- Rafların önüne malzemelerin devrilmesini engelleyecek raf önü tutucular kullanılmalıdır.                                                                    \\n3-  Endüstriyel raflar en az iki noktadan  sabitlenmeli, düşme, devrilme riski olan bütün malzemeler düşmeyecek şekilde sabitlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20440\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DEPO ARŞİV\",\"faaliyet\":null,\"tehlike\":\"1- Depolarda yüksek istifleme yapılması\",\"risk\":\"1- Malzeme düşmesi sonucu  yaralanma, ezilme, sıkışma\",\"mevcut_onlem\":null,\"oneri\":\"1- İstif yüksekliği en fazla 3 metre olmalıdır.\\n2- Malzemeler düzenli istiflenmeli, devrilmeyecek şekilde sabitlenerek istif yapılmalıdır.\\n3- Devrilme riski olan malzemeler 1,5 metreden yüksek istiflenmemelidir.\\n4- Stok girişi yapılmayan malzemeler depoya alınmamalıdır.\\n5- Ağır malzemeler en altta istiflenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20441\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DEPO ARŞİV\",\"faaliyet\":null,\"tehlike\":\"1- Endüstriyel rafların periyodik kontrollerinin yapılmaması\",\"risk\":\"1- Rafların devrilmesi sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Raflar  TS EN 15635 standartalarına uygun azami kontrol süresi geçmeden periyodik kontrolleri  yapılmalıdır.    \\n2- Metal kısımların dayanıklılık ve metal yorgunluğu testleri yaptırılmalıdır. \\n3- Bağlantı noktaları, çatlak, aşınma, taşıyıcı kısımlar 3 ayda bir kontrol edilmeli, eksiklikler giderilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20442\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DEPO ARŞİV\",\"faaliyet\":null,\"tehlike\":\"1- Elektrikli transpaletin periyodik kontrolünün olmaması\",\"risk\":\"1- Yüklerin düşmesi, devrilmesi sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1-Alanda kullanılan elektrikli transpaletlerin periyodik kontroleri; TS EN 1757-2 standartlarına uygun olarak yılda 1 yapılmalıdır.                                                                                      2- En fazla kaldırma kapasitesinin en az 1, 25 katını, etkili ve güvenli bir şekilde kaldıracak ve askıda tutabilecek güçte olmalıdır ve bunların bu yüke dayanıklı ve yeterli yük frenleri bulunmalıdır.       \\n3- Elektrikli transpaletin günlük, haftalık, aylık, üç aylık bakımları, imalatçının belirlediği şekilde ya da imalatçı tarafından yetkilendirilmiş servislerce yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20443\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DEPO ARŞİV\",\"faaliyet\":null,\"tehlike\":\"1- Ygap binasına minibüs ile arşiv dosyalarının taşınması\",\"risk\":\"1- Trafik kazası                sonucu  yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Risk değerlendirmesinin \\\"Hastane Araçları\\\" bölümünde bulunan düzeltici önleyici faaliyetler bu bölümde yer alan araçlar için de uygulanmalıdır.\\n2- Minibüse sadece yolcu koltuk sayısı kadar çalışan alınmalı, arka kısımda çalışan taşınmamalı, ön kısımda bulunan 2 li oturma koltuğunda 3 çalışan alınmamalıdır.\\n3- Minibüs sadece görevlendirilmiş ve uygun ehliyete sahip çalışanlar tarafından kullanılmalıdır.\\n4-Minibüse binen herkes emniyet kemerlerini bağlamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20444\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DEPO ARŞİV\",\"faaliyet\":null,\"tehlike\":\"1- Elekrikli transpalet ile insan taşınması\",\"risk\":\"1-Düşme sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Elektrikli transpalet çatallarında insan taşınmamalıdır.                                                           \\n2- Zorunlu hallerde elektrikli transpalet üzerinde yapılacak çalışmalar için sepet temin edilmelidir.                                                                                        3-İnsan taşımak için kullanılacak sepet sabitlenmeli ,sepet üzerinde yapılacak çalışmalarda emniyet kemeri kullanılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20445\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DEPO ARŞİV\",\"faaliyet\":null,\"tehlike\":\"1-KKD’lerin eksik olması,                           2- KKD\'lerin çalışanlar tarafından kullanılmaması\",\"risk\":\"1-KKD’lerin kullanılmaması sonucunda iş kazaları, meslek hastalıkları oluması\",\"mevcut_onlem\":null,\"oneri\":\"1-KKD’ler CE belgeli ve ilgili standartlara uygun olmalı, eksik olan kkd\'ler temin edilmelidir.\\n2- Çalışanların maskeleri TS EN149 standardında uygun olmalıdır.                                                                                                                     3-Çalışanların göz koruyucuları TS EN 166 standardına uygun ve tam kapalı tip olmalıdır.                                                                                                                             4-Çalışanların iş eldivenleri TS EN 388 standartına uygun olmalıdır.                                                                                                                                5- Çalışanların iş ayakkabıları, koruyucu burun ve taban TS EN ISO 20345 standartına uygun olmalıdır.\\n6- Çalışanların baretleri TS EN 397 standartına uygun olmalıdır\\n7-Çalışanlar sahada kişisel koruyucu ekipmanlarını eksiksiz şekilde kullanmalıdırlar.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20446\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DEPO ARŞİV\",\"faaliyet\":null,\"tehlike\":\"1- Raflardan malzeme almak için eskoba merdiven ya da el merdiveni kullanılması\",\"risk\":\"1-Merdivenden düşme sonucu yaralanma\",\"mevcut_onlem\":\".\",\"oneri\":\"1- Raflardan malzeme almak için eskoba ya da el merdivenleri kullanılmamalı, TS EN 131 standartlarına uygun merdivenler temin edilmelidir.                                                                                   \\n2- Kullanılacak merdiven en az 1 metre yükseklikte korkuluklu, 47 cm de ara korkuluklu, platformlu, yere sabitlenebilen tekerlek frenleri olan yapıda olmalıdır.  \\n3-Platformlu merdivenlerin giremeyeceği dar raf aralarında kullanılan el merdivenlerinin ayaklarına, merdivenin kaymasnı önlemek için destekler konulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20447\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DEPO ARŞİV\",\"faaliyet\":null,\"tehlike\":\"1- Raf arası mesafelerin yetersiz olması\",\"risk\":\"1- Çarpma, sıkışma, düşme sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Raflar arası boşluk en az yaya geçişi için 80 cm, merdiven geçmesi için en az 120 cm olacak şekilde iş organizasyonu yapılmalıdır.                                                  \\n2- Depolama alanı değişikliği yapılmalıdır.\\n3- Raf yerleşim planı hazrılanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20448\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DEPO ARŞİV\",\"faaliyet\":null,\"tehlike\":\"1- Koridor , tüneller, otopark, sığınak vb alanlara  malzeme istif edilmesi\",\"risk\":\"1-Acil durumlarda tahliyenin zorlaşması\",\"mevcut_onlem\":null,\"oneri\":\"1- Miadı geçen ürünlerin alandan bertaraf edilerek uzaklaştırılıp alanın açılması sağlanmalıdır.                                                                                       \\n 2- Yeni depolama alanları belirlenerek koridor, tüneller, otopark, sığınak vb. alanlar depolama için kullanılmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20449\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DEPO ARŞİV\",\"faaliyet\":null,\"tehlike\":\"1- Depo alanlarının tozlu olması\",\"risk\":\"1- Solunum sistemi hastalıkları meydana gelmesi\",\"mevcut_onlem\":null,\"oneri\":\"1- Jet fanlar devreye girdiğinde çalışanlar depoda bulunmamalı,  fanlar kapandığında alandaki toz hemen temizlenmelidir.                                                                                       2- Haftada en az 2 defa ıslak zemin  temizliği yapılmalıdır.                                                                                     3- Toz maskesi kullanılarak maruziyet önlenmelidir.           \\n4- Çalışanların hijyenlerini sağlayabilmeleri için el yıkama lavbosu bulunmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20450\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DEPO ARŞİV\",\"faaliyet\":null,\"tehlike\":\"1- Endüstriyel rafların ayak koruma bariyerlerinin bulunmaması\",\"risk\":\"1-Rafların devrilmesi sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Elektrikli transpalet, transpalet vb. kaldırma ekipmanı kullanılan alanlarda rafların ayaklarına koruma bariyerleri takılmalıdır.\\n2- Koruma bariyerli yüksek mukavemetli, darbelere dayanıklı çelik vb. darbe emici malzemeden yapılmış olmalıdır.\\n3- Koruma bariyerleri yerlerinden çıkmayacak şekilde sabitlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20451\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DEPO ARŞİV\",\"faaliyet\":null,\"tehlike\":\"1- Endüstriyel rafların, raf panellerinin eksik olması \\n2- Tahta paletlerin, raf paneli olarak kullanılması\",\"risk\":\"1-Malzemelerin devrilmesi sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Endüstriyel rafların eksik raf panelleri temin edilmelidir. \\n2- Paneller sağlam, yerinden çıkmayacak şekilde monte edilmelidir.\\n3- Tahta paletler raf paneli olarak kullanılmamalıdır.                                                    4- Deforme olmuş, bel vermiş raf panelleri değiştirilmelidir.\\n5- Mevcut raf panelleri iptal edilmemelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20452\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DEPO ARŞİV\",\"faaliyet\":null,\"tehlike\":\"1- Depo ve eczanelerde  zaman zaman tavandan su sızıntısı olması\",\"risk\":\"1- Elektrik çarpması                      2- Kayma düşme\",\"mevcut_onlem\":\"1- Su giderleri bulunmaktadır.\",\"oneri\":\"1-Tıkalı olan su giderleri açılmalıdır.\\n2- Tavan akıntısına neden olan tesisat, çatı veya klima hattı arızaları onarılmalıdır.                                          \\n3- Elektrik kablolarının suyla temas riskine karşı izole edilmelidir.  \\n4- Tavan akması görülen bölgeler uyarı şeridi veya bariyerlerle çevrelenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20453\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DEPO ARŞİV\",\"faaliyet\":null,\"tehlike\":\"1- Tavan aydınlatmalarına yakın istifleme yapılması\",\"risk\":\"1-Yangın çıkması\",\"mevcut_onlem\":\"1- Yangın söndürme sistemleri mevcuttur.\",\"oneri\":\"1- Aydınlatma armatürleri ile malzemeler arasında 50-100 cm boşluk bırakılmalıdır.                           \\n2- Aydınlatma armatürleri ısı çıkarmyan led aydınlatma ya da etanj aydınlatmalar kullanılmalıdır.\\n3- Yangın söndürücüler her zaman hazırda bulundurulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20454\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DEPO ARŞİV\",\"faaliyet\":null,\"tehlike\":\"1- Rafların taşıma kapasitesinin bilinmemesi                                                         2- Raflara hatalı istifleme yapılması\",\"risk\":\"1- Rafların fazla yüklenmesi sonucu devrilmesi\",\"mevcut_onlem\":null,\"oneri\":\"1- Her rafa maksimum taşıma kapasitesi, görünür okunabilir şekilde asılmalıdır.\\n2- Raflara taşıma kapasitesinin %10 altı ağırlıktaki malzemeler istiflenmelidir.\\n3- Yükler raf yüzeylerine eşit dağıtılmalıdır.\\n4- Malzemeler düzenli, devrilmeyecek şekilde istiflenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20455\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DEPO ARŞİV\",\"faaliyet\":null,\"tehlike\":\"1- Elektrikli transpalet ve manuel transpaletlere yüklerin düzensiz ve sabitlenmeden yüklenmesi, taşınması\",\"risk\":\"1- Yüklerin düşmesi, devrilmesi sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Yükler dengeli yüklenmelidir.\\n2- Yüksek, ağır ve dengesiz düşebilecek yükler sabitlenerek taşınmalıdır.\\n3- Taşıma alanında çalışanlar bulunmamalıdır.\\n4- Transpaletlerde taşıma kapasitesi üzerinde yük taşınmamalıdır.\\n5- Taşıma araçları sonrası kontrol edilmelidir.\\n6- Yükler çalışanın görüşünü engellemeyecek şekilde taşınmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20456\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DEPO ARŞİV\",\"faaliyet\":null,\"tehlike\":\"1- Transpaletlerin periyodik kontrollerinin yapılmaması\",\"risk\":\"1- Yüklerin düşmesi, devrilmesi sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Manuel transpaletlerin periyodik kontrolleri  TS EN ISO 3691 serisi, FEM 4.004 standartlarında belirtilen kriterlere uygun olarak yapılmalıdır.                                                                                                                          2- Periyodik kontrolleri yapılmamış manuel  transpaletler kullanılmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20457\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DEPO ARŞİV\",\"faaliyet\":null,\"tehlike\":\"1- Elektrikli transpalet kullanan çalışanların mesleki yetrlilik belgelerinin olmaması\",\"risk\":\"1- İş kazaların oluşması ve artması\",\"mevcut_onlem\":null,\"oneri\":\"1- Elektrikli transpaletler sadece mesleki yeterlilik belgesine sahip çalışanlar tarafından kullanılmalıdır.                                                                                       2- Çalışanlar meslek eğitim merkezlerine gönderilerek yaptığı işe uygun mesleki yeterlilik belgesi alması sağlanmalıdır.\\n3- Kamu çalışanları tarafından elektrikli transpalet kesinlikle kullanılmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20458\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DEPO ARŞİV\",\"faaliyet\":null,\"tehlike\":\"1- Kaygan zemin oluşması                                                                  2- Bozuk zemin yüzeyi\",\"risk\":\"1-Düşme, denge kaybı sonucunda vücut bölümlerinin yaralanması\",\"mevcut_onlem\":null,\"oneri\":\"1-YGAP ta arşiv odası zemininde bulunan borular körlenmelidir.\\n1- Bozulan zeminin tamir ve tadilatı yapılmalıdır.\\n2- Temizlik işlemi sırasında zemin kurulanmalı temizlik esnasında uyarı tabelaları konulmalıdır.                                                                                                     \\n3- Kaymaya sebep olacak maddelerinin zeminde birikmesi önlenmeli, hemen temizlenmelidir.\\n4- Çalışanlar kaymaz tabanlı ayakkabı giymelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":6,\"frekans\":3},{\"anahtar\":\"hst-20459\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DEPO ARŞİV\",\"faaliyet\":null,\"tehlike\":\"1- Kolilerin, dosyaların el ile taşınması\",\"risk\":\"1-Düşme, devrilme  sonucu yaralanma\",\"mevcut_onlem\":\"1- Çalışanlara elle taşıma teknikleri hakkında eğitim verilmiştir.\",\"oneri\":\"1- Erkekler 25 kg üzerinde kadınlar 15 kg üzerinde yük kaldırmamalıdır.                                                                                   2- Dengesiz devrilme riski olan yükler sabitlenerek taşınmalıdır.\\n3- Yükler taşıma teknikleri kullanılarak taşınmalıdır.\\n4- Yükler görüş alanını kapatmayacak şekilde taşınmalıdır.                                                                                                 5- Depo, eczane ve arşivde çalışan personellere yüksekte çalışma, depolarda uygun istifleme ve ergonomi ve elle taşıma eğitimi verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20460\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DEPO ARŞİV\",\"faaliyet\":null,\"tehlike\":\"1- Raflarda sivri köşelerin bulunması\",\"risk\":\"1- Yaralanma                  2- Çarpma\",\"mevcut_onlem\":null,\"oneri\":\"1-Tüm depo , eczane , arşiv alanlarında bulunan rafları köşelerindeki sivri uçlar için köşe koruyucular monte edilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":10},{\"anahtar\":\"hst-20461\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DEPO ARŞİV\",\"faaliyet\":null,\"tehlike\":\"1- Aydınlatma yetersizliği, bozulması, titremesi\",\"risk\":\"1- Görme bozukluklarının oluşması ve ilerlemesi, ş kazalarında artış\",\"mevcut_onlem\":null,\"oneri\":\"1-Suni ışık ihtiyacında çalışma alanı ve diğer eklentiler, yollar en az 300 lüks şiddetinde aydınlatılmalıdır.                                                                                                                      2-Aydınlatma sistemleri sağlam yapıda olmalı, bozulan, yanmayan titreyen aydınlatmalar değiştirilmelidir.\\n3-Periyodik göz muayeneleri yılda bir kez yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20462\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DEPO ARŞİV\",\"faaliyet\":null,\"tehlike\":\"1- Termal konfor takibinin yapılmaması\",\"risk\":\"1- Dikkat kaybı, iş kazası ve meslek hastalıklarında artışlar\",\"mevcut_onlem\":\"1- Isı, nem ölçerler eczaneler ve arşivde mevcuttur.\",\"oneri\":\"1- Isı nem ölçerler eczane koridor alanlarında, depo alanları olarak tahsis edilmiş tüm yerlerde ve arşiv olarak tasarlanmış tüm yerlerde bulunmalı, ve mahale uygun ısı nem seviyesinde kalması sağlanmalıdır.                                                                   2- Çalışma ortamı %35-%75 nem oranında ve 18-24 C derece arasında olması sağlanmalıdır.                                                                                 \\n3-Hava akım hızının 0,5 m/sn ortalamada olması sağlanmalıdır.\\n4-Çalışma ortamının saatte en az 6-10 kez havalandırılması sağlanmalıdır..\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20463\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DEPO ARŞİV\",\"faaliyet\":null,\"tehlike\":\"1-Elektrik panosunun su ile temas etmesi\\n2- Pano önünde yalıtkan paspas olmaması\",\"risk\":\"1- Yangın                            2- Yanma                        3- Çarpılma\",\"mevcut_onlem\":null,\"oneri\":\"1-Sığınak  depo olarak kullanılan alanda bulunan elektrik panosunun önüne yalıtkan paspas koyulmalıdır.                                                                                      \\n 2- Üzerinde bulunan anahtar kilitlenerek yetkili personelde bulunması sağlanmalıdır.                                              \\n3- Klimadan damlayan su nedenli elektrik ile teması önlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":1},{\"anahtar\":\"hst-20464\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: DEPO ARŞİV\",\"faaliyet\":null,\"tehlike\":\"1- Yotasız dolapların bulunması\",\"risk\":\"1- Düşme                        2- Devrilme\",\"mevcut_onlem\":null,\"oneri\":\"1-  Eczane ve tüm bölümleri , depo ve tüm bölümleri , arşiv ve tüm bölümlerindeki dolaplar, raflar vb. ekipmanlar en az iki noktadan yotalanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":1},{\"anahtar\":\"hst-20465\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: ECZANE\",\"faaliyet\":null,\"tehlike\":\"1- Yanıcı kimyasal maddeler için ayrı bir depolama alanı bulunmaması\",\"risk\":\"1- Yagnın meydana gelmesi\",\"mevcut_onlem\":\"1- Depo girişinde 50 kg\'lik yangın tüpü bulunmaktadır.\",\"oneri\":\"1- Yanıcı maddeler için ayrıca bir depo oluşturulmalıdır.                                                                            2- Kimyasal maddeler yanıcı malzeme ve elektrik kaynaklarından uzakta depolanmalıdır.                                                                                                                     \\n3- Depo girişine nötralizatör takılmalı, vücuttaki statik elektrik boşaltılmadan kimyasal madde deposuna girilmemelidir.\\n4- Yanıcı kimyasal deposunda tüm metal raflar topraklanmalı, aydınlatma ve elektrik sistemleri exproof olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20466\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: ECZANE\",\"faaliyet\":null,\"tehlike\":\"1- Kimyasal maddelerin yanlış depolanması\\n2- Kimyasalların depo dışında depolanması\",\"risk\":\"1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması\",\"mevcut_onlem\":\"1- Kimyasal madde deposu mevcuttur.\",\"oneri\":\"1- Kimyasal maddeler depolama matrisine göre depolanmalıdır.                                     2- Rafların altına tava ve emici malzemeler konulmalı, sızıntı, dökülme durumunda bu maddeler değiştirilmelidir.                                                                                                                3- Kimyasal depo zemini kolay temizlenebilir olmalıdır.                                                                                                                                                                                                                                                                                      4- Kimyasal maddelerin malzeme güvenlik bilgi formları depo girişine asılmalıdır.\\n5- Kimyasal maddeler depolama alanlarında depolanmalı ve depolar kilitli tutulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20467\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: ECZANE\",\"faaliyet\":null,\"tehlike\":\"1- Kimyasal madde deposunda göz duşu ve döküntü kiti bulunmaması                                               2- Çalışanların kimyasallar hakkında bilgi sahibi olmaması\",\"risk\":\"1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması\",\"mevcut_onlem\":null,\"oneri\":\"1- Kimyasalların dökülme riskine karşı döküntü kitleri bulundurulmalıdır.                                         \\n2- Göze kaçma riskine karşı göz duşu solüsyonu bulundurulmalıdır.  \\n3- Kimyasal maddelere gözlük, eldiven olmadan temas edilmemelidir.                                                               \\n4-Kimyasal maddelerin malzeme güvenlik bilgi formları depoda asılı olmalıdır.                              \\n5- Çalışanlara MSDS ve kimyasalların güvenli kullanımı konusunda eğitimler verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20468\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: ECZANE\",\"faaliyet\":null,\"tehlike\":\"1- Elektrikli ısıtıcı kullanılması\",\"risk\":\"1- Yangın çıkması\",\"mevcut_onlem\":null,\"oneri\":\"1- Alanda elektrikli ısıtıcı kullanılmamalıdır.                             \\n2-TPN ünitesinin termal konforu mevcut merkezi ısıtma ile sağlamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20469\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: ECZANE\",\"faaliyet\":null,\"tehlike\":\"1- Himss odasında bulunan sisnac makinasının operasyon bölgesinin açık olması\",\"risk\":\"1-El sıkışması sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Sisnac makinesinin çalışanın elini sıkıştırmaması için press yapılan bölümüne switchli korucu kapak eklenmelidir.                                                                                       2- Cihaz bakım ve kalibrasyonları yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20470\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: ECZANE\",\"faaliyet\":null,\"tehlike\":\"1- Narkotik ilaç dolabının cam olması\",\"risk\":\"1- Narkotik ilaçların kullanımı sonucu bağımlılık sakatlık ya da ölüm\",\"mevcut_onlem\":null,\"oneri\":\"1- Narkotik ilaçların bulunduğu dolaplar metal , kitlitlenebilir, çift anahtarlı olmalıdır.        \\n2- Narkotik ilaç dolaplarının üzerinde anahtar bırakılmamalı, anahtarlar bölüm sorumlularına zimmetlenmelidir.                                                                                                                            3- Bölümlere gelen narkotik ilaçlar kayıt altına alınmalı, her vardiya değişiminde sayım yapılmalı, eksik çıkması durumunda yetkililere haber verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":40,\"frekans\":1},{\"anahtar\":\"hst-20471\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: ECZANE\",\"faaliyet\":null,\"tehlike\":\"1- Paslı yüzeylerin alanda mevcut olması\",\"risk\":\"1-Yaralanma sonucu tetanos hastalığına yakalanma\",\"mevcut_onlem\":null,\"oneri\":\"1-Paslı alet ve ekipmanlar yenileriyle değiştirilmeli, paslanmaz malzemeler kullanılmalıdır.\\n2-Sivri, delici, kesici, paslı makine ve ekipmanlara eldivensiz temas edilmemelidir.\\n3-Yeni başlayan ya da aşısı eksik olan çalışanlara tetanos aşısı yapılmalı, 5 yılda bir ya da yaralanma durumunda tekrar aşı yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20472\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: ECZANE\",\"faaliyet\":null,\"tehlike\":\"1- Bekleme alanı olarak akü odalarının önlerinin kapatılması\",\"risk\":\"1-Acil durumda müdehale gecikmes               2- Yangın\",\"mevcut_onlem\":null,\"oneri\":\"1-Bekleme alanı ; akü odası , çıkış kapıları vb. alanların önü kapatmayacak şekilde yeniden konumlandırılmalıdır.                                                                           2- Akü odası önü her zaman boş bırakılmalıdır.                          \\n3- \\\"Malzeme istifi yapılmamalıdır \\\"şeklinde uyarı yazısı akü odası şaftlar ve bunun gibi teknik mahallere asılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20473\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: ECZANE\",\"faaliyet\":null,\"tehlike\":\"1- Yangın dolabı önüne istifleme yapılması ve elektrik panosunun önüne istifleme yapılması\",\"risk\":\"1-Yanma                 2-Yangın\",\"mevcut_onlem\":null,\"oneri\":\"1- Genel olarak eczane ve tüm bölümleri , depo ve tüm bölümleri , arşiv ve tüm bölümlerinde yangın dolapları önleri boş bulundurulmalıdır.                                                           2- Elektrik panoları önü boş kalacak şekilde iş organizasyonu yapılmalıdır.                                                                   3- Elektrik pano önleri boyanarak  istifleme yapılmayacağı vurgulanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":1},{\"anahtar\":\"hst-20474\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: ECZANE\",\"faaliyet\":null,\"tehlike\":\"1- Eczane içinde bulunan himss odasında bulunan soğuk hava deposunda içerden acil durum butonu bulunmaması\",\"risk\":\"1-Mahsur kalma sonucu hipotermi geçirme\",\"mevcut_onlem\":null,\"oneri\":\"1-Soğuk hava depolarında  kapı kolunun arızalanmasına karşı, içeriden açılabillir ilave acil kapı açma butonu takılmalıdır.                                                                                                                                                                                                   2- Acil kapı açma butonu ve alarm butonu erişilebilir yükseklikte olmalı ve önüne malzeme konulmamalıdır.                                                                                                                                           3- Acil kapı açma butonu ve alarm sistemi karanlıkta görülebilir şekilde işaretlenmiş olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":2},{\"anahtar\":\"hst-20475\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: ECZANE\",\"faaliyet\":null,\"tehlike\":\"1- Kule eczanelerindeki narkotik dolaplarının ofis çalışma masasının arkasında bulunması\",\"risk\":\"1- Çarpma                     2- Vurma\",\"mevcut_onlem\":null,\"oneri\":\"1- Narkotik dolaplarının yeri ofis çalışma alanının içinde çalışanın çarpmayacağı şekilde düzenlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":2},{\"anahtar\":\"hst-20476\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: ECZANE\",\"faaliyet\":null,\"tehlike\":\"1- Kliniğe çıkan ilaç arabalarının fren sisteminin bulunmaması\",\"risk\":\"1- Çarpma                      2- Çarpışma\",\"mevcut_onlem\":null,\"oneri\":\"1- İlaç arabalarının tekerleklerinde fren sistemi bulunmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":3},{\"anahtar\":\"hst-20477\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: ECZANE\",\"faaliyet\":null,\"tehlike\":\"1- Çalışan dinlenme odalarının ve ofislerinin   depo eczane alanı olarak kullanılması\",\"risk\":\"1- Devrilme                    2- Düşme                  3- Ezilme\",\"mevcut_onlem\":null,\"oneri\":\"1- Çalışan dinlenme alanları depo alanlarından ayrılmalıdır.                                                                                                  2- Raflar sabitlenmelidir.                                                                       \\n3- Alandaki mevcut rafların raf önü tutucusu bulunmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":3},{\"anahtar\":\"hst-20478\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: ECZANE\",\"faaliyet\":null,\"tehlike\":\"1- Himss odasındaki opus makinesinin switch iptal edilmesi\",\"risk\":\"1-El sıkışması sonucu yaralanma\",\"mevcut_onlem\":\"switchli koruyucu kapak bulunmaktadır.\",\"oneri\":\"1- Opus  makinesinin çalışanın elini sıkıştırmaması için tablet kesen bölümündeki switchli korucu kapak daima aktif olmalıdır.                                                                                          2- Cihaz bakım ve kalibrasyonları yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":1}]', 0, 0, NOW(), NOW()
