SELECT u.`id`, 'Hastane — Birim: ENDOSKOPİ BRONKOSKOPİ', 'saglik', NULL, 'fine_kinney', '[{\"anahtar\":\"hst-20479\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ\",\"faaliyet\":null,\"tehlike\":\"1- UV-C lambalarının koruyucusunun yetersiz olması \\n2- UV-C lambasınıın sayaçsız olması\",\"risk\":\"1-Gözlerde katarakt, cilt yanıkları, mesleki kanserler oluşması\",\"mevcut_onlem\":\"1- UV-C lambasının alt kapağı mevcuttur.\",\"oneri\":\"1- UV-C lambaları zaman ayarlı, TS EN 62471 standartına uygun olmalıdır.  \\n2- UV-C lambalarında alttan, üstten ve yandan ışık sızıntısı olmamalıdır.\\n3- UV-C lambalarının yüzeyi yansıma yapmayacak şekilde olmalıdır.\\n4-  UV-C lambalarının periyodik kontrolleri yapılmalı, sararan, çatlayan, filtre özelliği bozulan kapaklar değiştirilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20480\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ\",\"faaliyet\":null,\"tehlike\":\"1- UV-C lambası çalışırken çalışanların odada bulunması\\n2- Çalışanların uv lambası çalışırken çay kahve içmeleri\",\"risk\":\"1-Gözlerde katarakt, cilt yanıkları, mesleki kanserler oluşması\",\"mevcut_onlem\":\"1- KKD\'ler mevcuttur.\",\"oneri\":\"1- UV Lambaları çalışanlar bölümdeyken çalıştırılmamalıdır.\\n2- UV lambası çalışırken odanın kapısı kapalı tutulmalı, kapı açıldığında uv lambasının kapanmasını sağlayan interlock sistemi bulunmalıdır.\\n4- UV lambasını kapatmak için odaya girildiğinde TS EN 170 standartında uv gözlük, uzun kollu koruyucu kıyafet, uv geçirmeyen eldiven vb. kişisel koruyucu ekipmanlar kullanılmalıdır.       \\n5- Çalışanlar uv lambasının bulunduğu oda da kesinlikle çay kahve içmemelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20481\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ\",\"faaliyet\":null,\"tehlike\":\"1- Mutfak alanıında çay kazanı ve uzatma kablosu kullanılması\",\"risk\":\"1-Elektrik çarpması sonucu yaralanma                      2-Yangın çıkması\",\"mevcut_onlem\":\"1-Kaçak akım koruma rolesi ve yangın rolesi mevcuttur.\",\"oneri\":\"1- Kullanılan tüm elektrik, uzatma (3\'lü) vb. kablolar halojen free (geç yanan, zehirli gaz çıkarmayan) özellikte olmalı, diğer uzatma kabloları kullanılmamalıdır.\\n2- Çay kazanlarının kullanımı önlenmeli, sadece çift termostatlı çay kahve makineleri makineleri kullanılmalıdır.                                                                                                                         3- Çay kahve makineleri direk fişe takılmalı, uzatma kablolarına takılmamalıdır.                                                                                                                4- Çay kahve makineleri kullanıldıktan sonra fişten çıkarılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20482\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ\",\"faaliyet\":null,\"tehlike\":\"1- Yıkama dezenfeksiyon cihaznın çalışırken kapağının açılması\",\"risk\":\"1. Kimyasal sıçraması ya da dönen kısımlara kapılma sonucu iş kazaları yaşanması\",\"mevcut_onlem\":\"1- Kişisel koruyucu ekipmanlar mevcuttur.\",\"oneri\":\"1- Yıkama dezenfeksiyon cihazı çalışırken kapağı açılmamalı, kapağa akım kesicili switch takılmalıdır.                                                   \\n2- Cihaz durdurulmadan el ile müdahale edilmemelidir.            \\n3- Operayon bölgesine el ve parmaklar yaklaştırılmamalıdır.\\n4- Cihaz kapakları kapalı tutulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20483\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ\",\"faaliyet\":null,\"tehlike\":\"1-Bulaşıcı hastalık riski olan hastalara bronkoskopi işlemi uygulanması\",\"risk\":\"1- TBC vb. bulaşıcı hastalıklara yakalanma\",\"mevcut_onlem\":\"1- Kişisel koruyucu ekipmanlar mevcuttur.\",\"oneri\":\"1- Bronkoskopi işlem odaları negatif basınçlı olmalıdır.\\n2- Bronkoskopi işlem odalarında kirli hava zeminden dışarı atılmalıdır.\\n3- Odalarda hepa filtreler kullanılmalı, saatte en az 12 hava değişimi sağlanmalıdır.\\n3- Çalışanlar N95 ya da TS EN 149 standrtdında FFP2 filtreli maske, yüz siperi, TS EN 455  standardında eldiven kullanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20484\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ\",\"faaliyet\":null,\"tehlike\":\"1- Dezenfeksiyon cihazı kullanılan bölümde döküntü kiti göz duşu bulunmaması\",\"risk\":\"1-Kimyasalların göze, cilde teması sonucu iş kazaları meyadana gelmesi\",\"mevcut_onlem\":\"1- Kişisel Koruyucu ekipmanlar mevcuttur.\",\"oneri\":\"1- Kimyasalların dökülme riskine karşı döküntü kitleri bulundurulmalıdır.                                         \\n2- Göze kaçma riskine karşı göz duşu solüsyonu bulundurulmalıdır.  \\n3- Kimyasal maddelere gözlük, eldiven olmadan temas edilmemelidir.                                                               \\n4- Kimyasal maddelerin malzeme güvenlik bilgi formları depoda asılı olmalıdır.                              \\n5- Çalışanlara MSDS ve kimyasalların güvenli kullanımı konusunda eğitimler verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20485\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ\",\"faaliyet\":null,\"tehlike\":\"1- Endoskopi ve Bronkoskopi cihazlarının kullanımından kaynaklı kan ve vücut sıvılarının çalışanlara teması\",\"risk\":\"1- Enfeksiyona yakalanma\",\"mevcut_onlem\":\"1-Kişisel Koruyucu ekipmanlar mevcuttur.\",\"oneri\":\"1-Çalışanlar TS EN 455  standardında eldiven, TS EN 166 standardında tam kapalı gözlük ya da yüz siperi, uzun kollu koruyucu önlük  EN 14683 standardında maske vb. gibi kişisel koruyucu donanımlar kullanılmalıdır.                                                                                                                         2- Temas durumunda bölgenin bol su ve sabunla yıkanması sağlanmalıdır.                                                                                                                                    3- Kan ve vücut sıvıları sıçramasına maruz kalma sonrası çalışanın, bulaş kaynağının durumuna göre muayene ve tetkikleri yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20486\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ\",\"faaliyet\":null,\"tehlike\":\"1- Endoskopi cihazı hortum ve bağlantı yerlerinde sızıntı olması\",\"risk\":\"1- Elektrik çarpması sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Endoskopi cihazının hortum ve bağlantı yerleri sağlam olmalı, sızıntı olmamalıdır.\\n2- Endoskopi cihazı her kullanımdan önce kontrol edilmelidir.\\n3- Elektrik kablolarında ek, deformasyon bulunmamalı, elektrik kabloları çift izolasyonlu olmalıdır.\\n4- Makine yıkama işlemi tamamlandığında fişte bırakılmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20487\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ\",\"faaliyet\":null,\"tehlike\":\"1-Hastalardan inhalasyon yoluyla bulaş\",\"risk\":\"1-Enfeksiyon, bulaşıcı hastalıklara yakalanma\",\"mevcut_onlem\":\"1-Ortam havalandırması mevcuttur.                    2. Kişisel koruyucu ekipmanlar mevcuttur.\",\"oneri\":\"1-Bulaşıcı hastalık şüphesi olan hastalar, sonuçları çıkana kadar tek kişilik izolasyon odalarında tutulmalıdır.                                                                                           2- Şüpheli hastaların bulunduğu alanın teması bittikten sonra hemen dezenfekte edilmelidir.                                                                                                                          3- Bulaşıcı hastalıkların yayılma ihtimali yüksek olan bölümlerde hepa filtreler kullanılmalıdır.                                                                                                                                              4-Tanı konulmuş hastalar negatif basınçlı odalara alınarak izole edilmelidir.                                                                                                                        5-Çalışanlar N95 ya da TS EN 149 standrtdında FFP2 filtreli maske, yüz siperi, TS EN 455  standardında eldiven kullanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20488\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ\",\"faaliyet\":null,\"tehlike\":\"1- Kesici delici aletlerin emniyetsiz kullanılması\",\"risk\":\"1- Kullanılmış aletlere temas sonucu el kol yaralanmaları, enfeksiyon, bulaşıcı hastalıklara yakalanma\",\"mevcut_onlem\":\"1-Kesici aletller düzenli muhafaza edilmektedir.\",\"oneri\":\"1- Kullanılmış iğne ve kesici aletler, kesici delici alet kutusuna atılmalıdır.                                                                                                                           2- Çalışanlar tedavi tepsisi kullanmalı, iğne kapağı kapatılmadan kesici delici alet kutusuna atılmalıdır.                                                                                                                                 3- Kesici delici alet kutuları en fazla 2/3 dolduğunda yenisi ile değiştirilmeli, kutuların kapakları açık bırakılmamalıdır.                                                                                                                   4-  Kesici delici alet kutuları devrilmeyecek şekilde konumlandırılmalıdır.                                                                                                                                5- Çalışanlar TS EN 455 standardında çift eldiven kullanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20489\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ\",\"faaliyet\":null,\"tehlike\":\"1- Formaldehitin uygunsuz kullanılması\",\"risk\":\"1- Kimyasal maddelere maruziyet sonucu iş kazaları meydana gelmesi, meslek hastalıkları\",\"mevcut_onlem\":\"1. Kişisel koruyucu ekipmanlar mevcuttur.\",\"oneri\":\"1- 21.10.2025 tarihinde hazırlanan Yöntem Beyan\'ına göre firma tarafından formaldehit, patoloji laboratuvarında porsiyonlanarak gönderilmelidir\\n2- Formaldehit büyük kaplardan, küçük kaplara aktarılırken taşma kapları kullanılmalı, zemine dökülmesi önlenmelidir.\\n3- Formaldehit dökülmesine karşı döküntü kitleri temin edilmelidir.\\n4- Çalışanlar formaldehit ile çalışma esnasında EN 149 standardında ffp3 maske, eldiven ve koruyucu gözlük kullanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20490\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ\",\"faaliyet\":null,\"tehlike\":\"1- Endoskopi 1 odasının fotoselli kapısı açıldığında yangın dolabının açılmasını  engellemesi\",\"risk\":\"1- Yangına müdehale edilememesi sonucu durumun şiddetinin artması\",\"mevcut_onlem\":\"1- Yangın algılama ve ihbar sistemi mevcuttur.\",\"oneri\":\"1- Fotoselli kapının açılış yönü yangın dolabını kapatmayacak şekilde ayarlanmalıdır. \\n2- Yangın dolaplarının önü her zaman boş bırakılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20491\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ\",\"faaliyet\":null,\"tehlike\":\"1- Endoskopi kule sisteminin gövde topraklama ölçümünün yapılmaması   \\n2- Kulenin devrilmesi\",\"risk\":\"1- Elektrik çarpması.                 2- Devrilme sonucu yaralanma\",\"mevcut_onlem\":\"1-Topraklama sistemi mevcuttur.\",\"oneri\":\"1- Endoskopi kulesinin gövde topraklama ölçümleri yapılmalıdır.\\n2- Cihaz kabloları çift izolasyonlu olmalıdır.\\n3- Kule tekerlek frenleri sağlam olmalı, sabit konumdayken kilitli tutulmalıdır.                                                                                                      \\n4- Ağır cihazlar alt raflara, hafif cihazlar üst raflara konulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20492\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ\",\"faaliyet\":null,\"tehlike\":\"1-Cihazlardan zemine sıvı dökülmesi\",\"risk\":\"1- Kayma, düşme sonucu yaralanma\",\"mevcut_onlem\":\"1-Kaygan zemin işaretleme levhaları mevcuttur.\",\"oneri\":\"1- Zemine dökülen sıvılar bekletilmemeli, hemen temizlenmesi sağlanmaldır.\\n2- Temizlik işlemi sırasında zemin kurulanmalı temizlik esnasında uyarı tabelaları konulmalıdır.                                                                                                     3- Kaymaya sebep olacak maddelerinin zeminde birikmesi önlenmeli, hemen temizlenmelidir.\\n4-  Çalışanlar kaymaz tabanlı ayakkabı giymelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20493\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ\",\"faaliyet\":null,\"tehlike\":\"1-Pano odasındaki sprink kapakları sökülmemesi                                  2-Endoskopi  3 odasındaki tavanda bulunan yangın sprink sisteminin bantla kapatılmış olması\",\"risk\":\"1- Yangının söndürülememesi sonucunda şiddetin artması\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.\",\"oneri\":\"1- Pano odasındaki yangın sprink sistemini kapatan kapak sökülmeli cihaz aktif hale getirilmelidir.                                                                                                                       2- Endoskopi 3 odasındaki yaıngın sprink sisteminin üzerindeki bant kaldırılmalı ve aktif çalışması sağlanmalıdır.\\n3- Yangın algılama ihbar sistemlerinin her zaman çalışır durumda olması sağlnamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20494\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ\",\"faaliyet\":null,\"tehlike\":\"1-Dolap ve rafların düzenlenmemesi ve sabitlenmemesi\",\"risk\":\"1- Malzemelerin devrilmesi sonucu yaralanma\",\"mevcut_onlem\":\"1-Dolapların bir  çoğu sabitlenmiştir.\",\"oneri\":\"1-Sabitlenmemiş doalp ve raflar en az iki noktadan sabitlenmelidir.\\n2-Düşme, devrilme riski olan bütün malzemeler düşmeyecek şekilde sabitlenmelidir.\\n3-Ağır malzeme ve ekipmanlar yüksek istiflenmemelidir.                                            4- Sabitlenemeyen dolap ve raflar kapılardan uzak, çalışanların üzerine düşmeyecek şekilde konumlandırılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20495\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ\",\"faaliyet\":null,\"tehlike\":\"1- Yıkama dezenfeksiyon cihazına kimyasalların aktarımı sırasında dökülmesi\",\"risk\":\"1- Kimyasalların göze, cilde teması sonucu iş kazaları meyadana gelmesi\",\"mevcut_onlem\":\"1- Kişisel koruyucu ekipmanlar mevcuttur.\",\"oneri\":\"1- Yıkama dezenfeksiyon cihazına el ile kimyasal aktarımı yapılmamalı, otomatik dozajlama sistemi kurulmalıdır.\\n2- Kimyasal aktarımı yapılırken sıçrama ve döküntü olmamasına özen gösterilmelidir.\\n3- Aktarım yapılırken kimyasal dayanımlı eldiven, Su geçirmez önlük+ kolluk, FFP2/N95 maske, Gözlük ve yüz siperliği((ref. EN 166 standardı)   ve kaymaz tabanlı ayakkabı kullanılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":3},{\"anahtar\":\"hst-20496\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ\",\"faaliyet\":null,\"tehlike\":\"1- Basınçlı hava tabancasının hortumun da hasar olması\\n2- Hava tabancasının vücuda tutulması\",\"risk\":\"1- Basınçlı havaya temas sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Basınçlı hava tabacasının hortumu ve bağlantı yerleri sağlam olmalı kaçak olmamalıdır.\\n2- Basınçlı hava tabancası ekipmanların temizliği dışında kullanılmamalıdır.\\n3- Hava tabancaları vücuda tutulmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":2}]', 0, 0, NOW(), NOW()
FROM `users` u WHERE u.`email` = 'mozdemir2816@gmail.com' AND NOT EXISTS (SELECT 1 FROM `risk_sablonlari` s WHERE s.`user_id` = u.`id` AND s.`ad` = 'Hastane — Birim: ENDOSKOPİ BRONKOSKOPİ');

INSERT INTO `risk_sablonlari` (`user_id`, `ad`, `sektor`, `sektor_adi`, `yontem`, `maddeler`, `paylasildi`, `kullanim_sayisi`, `created_at`, `updated_at`)
SELECT u.`id`, 'Hastane — Birim: TİCARİ ALANLAR', 'saglik', NULL, 'fine_kinney', '[{\"anahtar\":\"hst-20497\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1- Davlumbaz ve bacalarda yağ birikmesi\",\"risk\":\"1- Yağ birikimi nedeniyle yangın meydana gelmesi\",\"mevcut_onlem\":\"1- Bir çok işletmede davlumbaz ve bacalarda otomatik söndürme sistemi bulunmaktadır.\",\"oneri\":\"1- Ticari işletmelerde yemek pişen mutfaklarda davlumbazlarda otomatik yangın söndürme sistemleri kurulmalıdır.\\n2- Davlumbazlarda yağ ve kir birikimi olmayacak şekilde  davlumbazlar  günlük temizlenerek yağ ve benzeri yanmaya sebep olabilecek maddelerin birikmesi önlenmelidir.  \\n3-  Pişirme alanlarında yangın battaniyesi ve K sınıfı yangın söndürücü bulundurulmalıdır.\\n4- Ayda en az bir kez davlumbazlar ve bacaları detaylı temizlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20498\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1- Eletkrik tesisatının, topraklamaların, kaçak akım rölelerinin periyodik kontrollerinin yapılmaması\",\"risk\":\"1- Elektrik çarpması sonucu ya da elektrik yangını sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Elektrik tesisatının, topraklamaların, kaçak akım rölelerinin, yangın rölelerinin periyodik kontrolleri TS EN 60079 serisi, TS HD 60364-4 serisi, TS HD 60364-5 Serisi, TS HD 60364-6 standartlarına uygun olarak en geç yılda bir kez yapılmalıdır.\\n2- Tüm bakım ve kontroller kayıt altına alınmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20499\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1-Yangın söndürme ekipmanlarının periyodik kontrollerinin yapılmaması\",\"risk\":\"1- Yangın durumunda müdahale edilememesi sonucu şiddetin artması\",\"mevcut_onlem\":\"1- Yangın söndürme tüpleri mevcuttur.\",\"oneri\":\"1- İtfaiye raporu alınmalıdır. \\n2- Ticari işletmelerde yangın söndürme ekipmanlarının aylık kontrolleri yapılmalıdır.\\n3- En geç yılda bir kez TS EN 11602 standartına göre periyodik kontrolleri yapılmalıdır.\\n4- Yanıgın dolaplarının periyodik kontrolü yangın dolaplarının ve hortum makara sistemlerinin TS EN 671-3 standartına göre en geç yılda bir kez yapılmalıdır.\\n5- 4 yılda bir hidrostatik basınç testi yapılmalı, içindeki malzeme değiştirilmelidir.\\n6- Yangın teçhizatlarının her an göreve hazır bulunması sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20500\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1-Ticari işletmelerin iş güvenliği önlemlerini almamaları\",\"risk\":\"1-İş kazaları yaşanması sonucunda yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Ticari işletmelerin bu risk değerlendirmesinde yazan bütün tedbirleri  almaları sağlanmalıdır.\\n2- Ticari işletmeler tüm iş ekipmanlarının periyodik kontrollerini yaptırılmalı ve belgelendirmelidir.\\n3- Ticari işletmeler, çalışanlarına tehlike sınıfına uygun sürelerde iş güvenliği eğitimi aldırmalı, periyodik sağlık muayenelerini yaptırmalı, sigortasız işçi çalıştırmamalıdır.\\n4- Ticari işletmelerin hastanede ki iş güvenliği kurallarına uymaları sağlanmalıdır.\\n5- Ticari işletmelerin gerekli tedbirleri alıp almadıkları sürekli olarak kontrol edilmeli, denetimler yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20501\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1- Elektrikli mutfak ekipmanlarının kablolarının hasarlı ekli olması\",\"risk\":\"1- Elektrik çarpması sonucu yaralanma\\n2- Yangın çıkması\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.\",\"oneri\":\"1-Elektrik kablolarında yırtık, izolasyon bozlukluğu vb. olmamalı, olan kablolar kullanılmamalı değiştirilmelidir.                          \\n2- Elektrik kabloları ağır malzeme ya da ekipmanların altına konulmamalı, kabloların ezilmesi önlenmelidir.                                           \\n3- Kablolarda olan izolasyon açıklıkları izole bant ile kapatılmamalı, ekli kablolar değiştirilmelidir.  \\n4- Kaçak akım röleleleri her zaman çalışır durumda olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20502\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1- Acil çıkış yollarının, kapılarınınve yönledirmelerinin  malzemeler ile kapatılması\\n2- Yönlendirme işaretlerinin yetersiz olması\",\"risk\":\"1-Acil durumlarda hızlı tahliyenin sağlanamaması sonucunda durumun etkisinin ve şiddetinin artması\",\"mevcut_onlem\":null,\"oneri\":\"1-Acil çıkış kapıları ve acil çıkış yolları açıkça görülebilir olmalı ve acil çıkış kapılarnın ve yollarının önüne ve üzerine malzeme vb. konulmamalıdır.                                                                                        2- Acil çıkış yönlendirmelerinin önleri kapatılmamalı, kaçış yolu üzerinde bütün erişim noktalarından görülebilir olmalı, yönlendirmeler 200-240 cm yüksekliğe asılı olmalıdır.                                                                          \\n3- Acil çıkış yollarında en az 150 cm genişliğinde mesafe olması sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20503\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1- Halojen free olmayan uzatma kabloları kullanılması\",\"risk\":\"1- Elektrik çarpması\\n2- Yangın meydana gelmesi\",\"mevcut_onlem\":\"1- Ana tesisat kabloları halojen free kablolar ile değiştirilmiştir.\",\"oneri\":\"1- Ticari işletmelerde kullanılan tüm elektrik, uzatma (3\'lü) vb. kablolar halojen free (geç yanan, zehirli gaz çıkarmayan) özellikte olmalıdır.                                                                                                                                                           2- Halojen free olmayan uzatma kablolaları kesinlikle kullanılmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20504\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1-Ocaklarda açık alev kullanılması\",\"risk\":\"1- Yangın çıkması\",\"mevcut_onlem\":null,\"oneri\":\"1- Ocak etrafında herhangi yanıcı bir madde bulundurulmamalıdır.                                                                             2- Günlük temizlik yapılarak yağ ve benzeri yanmaya sebep olabilecek maddelerin birikmesi önlenmelidir.                                                                                                                                              3- Açık aleve fazla yaklaşılmadan çalışılmalı, elbise tutuşma ihtimali göz önünde bulundurulmalıdır.                                                                                                                                           4- Gaz detektörlerin bakım ve kontrolleri yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20505\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1- Elektrik kabloların da aşırı yükleme olması\",\"risk\":\"1- Elektrik yangını çıkması sonucu, yaralanma\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.\",\"oneri\":\"1- 3 lü uzatma kablolarına, 3 lü uzatma kablosu kullanarak kullanılmamalıdır.                                                                                                     2- Yüsek akım çeken cihazların (fırın, ızgara fritöz  vb.) beslemesi ayrı fişlerden yapılmalı, uzatma kabloları kullanılmamalıdır.    \\n3- Kullanılmayan cihazlar fişten çıkarılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20506\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1- Otomatların sabitlenmemiş olması\",\"risk\":\"1- Otomatların devrilmesi sonucu ezilme, yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Otomatlar, duvar kenarına yanaştırılmalı ve en az iki noktadan duvara ya da zemine  sabitlenmelidir.\\n2- Kullanıcıların otomatlara asılmasını ya da çekmesi önlenmeli, uyarı levhaları asılmalıdır.\\n3- Otomatlar düz ve sağlam zeminlere yerleştirilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20507\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1- Doğalgaz vanalarında ya da borularında gaz kaçağı olması\",\"risk\":\"1- Parlama, patlama yangın meydana gelmesi\",\"mevcut_onlem\":\"1- Gaz dedektörleri mevcuttur.\",\"oneri\":\"1- Gaz kaçak alarm sistemi, elektromanyetik gaz vanasına bağlı olmalı, kaçak durumunda gazı otomatik olarak kesmelidir.\\n2- Fırın vb. ekipmanlarda esnek gaz hortumları kullanılmamalı, besleme çelik boru ile yapılmalıdır.\\n3- Her gazlı cihazın kendine özel gaz vanası olmalıdır.\\n4- Manuel kapatma vanaları kolay erişilebilir olmalı ve işaretlenmelidir.\\n5- Gaz vanalarının önleri her zaman açık bulundurulmalı, malzeme vb. konulmamalıdır.\\n6- Her mesai sonrası gaz vanaları kapatılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":40,\"frekans\":2},{\"anahtar\":\"hst-20508\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1- Doğalgaz tesisatının, gaz dedektörlerinin vb. sistemlerin periyodik kontrollerinin yapılmaması\",\"risk\":\"1- Parlama, patlama yangın meydana gelmesi\",\"mevcut_onlem\":\"1- Gaz dedektörleri mevcuttur.\",\"oneri\":\"1- Doğalgaz tesisatının en geç yılda bir kez periyodik kontrolü yaptırılmalıdır.\\n3- Kaynaklı gaz borularına penatran testi ile sızdırmazlık kontrolleri yaptırılmalıdır.\\n3- Gaz dedektörlerinin ve otomatik gaz kesicilerin periyodik kontrolleri yaptırılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":40,\"frekans\":2},{\"anahtar\":\"hst-20509\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1- Yangın söndürme cihazları yerlerinin uygun olmaması, malzemelerle kapatılması ve erişimin zor olması\",\"risk\":\"1- Yangının büyümesi sonucu şiddetin artması\",\"mevcut_onlem\":\"1- İşletmelerde taşınabilir yangın Ttüpleri Ve dolapları mevcuttur.\",\"oneri\":\"1- Yangın söndürme tüplerinin önüne malzeme istifi yapılmamalı, boş bırakılmalıdır.\\n2- Portatif yangın söndürücüler yerden 90 cm yüksekliğe asılmalıdır.\\n3- Yangınla mücadele uyarı işaretleri kalıcı şekilde yerleştirilmelidir.\\n4- Düzenli aralıklarla yangın tüplerinin kontrolü, bakımı ve dolumu yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":40,\"frekans\":2},{\"anahtar\":\"hst-20510\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1-Gıda maddelerinin ve yemeklerin uygunsuz şartlarda muhafazası, bekletilmesi\",\"risk\":\"1- Gıda Zehirlenmesi\",\"mevcut_onlem\":\"1- Şahit numuneler saklanmaktadır.\",\"oneri\":\"1-Bozulma riski yüksek olan gıda maddeleri (tavuk et vb.), soğuk hava depolarında muhafaza edilmeli, dış alanda fazla bekletilmemelidir.                                                                                                            \\n2-Son kullanma tarihi geçmiş, ambalajı okunmayan, yırtılmış, bombeleşmiş, gözle kontrol edildiğinde hatası bulunan,   etiketsiz, imal ve son kullanma tarihi bulunmayan, etiketi üzerinde ithalat veya üretim izin tarih ve sayısı bulunmayan gıda maddeleri imha edilmeli, kullanılmamalıdır.                                                                                           \\n3-Gıda maddeleri kontrol edilmeden kullanılmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20511\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1- Kullanılmış kızartma yağlarının tekrar kullanılması\",\"risk\":\"1- Gıda zehirlenmesi\",\"mevcut_onlem\":null,\"oneri\":\"1-  Yağ kızartma sıcaklığı 170-180 dereceyi aşmamalıdır.\\n2- Dijital termometre ile yağ sıcaklığı kontrol edilmelidir.\\n3- Yağlarda renk koyulaşması, köpürme ve koku değişimi olduğunda yağ kesinlikle kullanılmamalı, değiştirilmelidir.\\n4- Farklı ürün gruplarına, farklı yağlar kullanılmalıdır.\\n5- Fritöz vb. kızartma yapılan ekipmanlar günlük olarak temizlenmeli, temizlikten sonra deterjan kalıntısı kalmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20512\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1- Ticari işletmelerde kontrolsüz tütün vb. kullanılması\",\"risk\":\"1- Yangın çıkması\",\"mevcut_onlem\":\"1- Kapalı alanarda sigara içilmemektedir.\",\"oneri\":\"1- Kapalı alanlarda kesinlikle sigara içilmesine izin verilmemelidir.\\n2- Küllükler çöp kutularına boşaltılırken yanan izmarit olmamasına özen gösterilmeli, küllük içine su dökülmelidir.\\n3- Metal ve kapaklı küllükler kullanılmalıdır.\\n4- Dış alanlarda Söndürmatik vb. yanmaz dış mekan küllükleri kullanılmalıdır.\\n5- Yangın söndürücüler her zaman hazır durumda bulundurulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20513\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1- Elektrik panolarının,  malzeme ya da istifle kapatılmış olması\",\"risk\":\"1- Acil durumlarda  müdahale sağlanamaması sonucunda  şiddetin artması\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.\",\"oneri\":\"1- Pano önleri kapanmayacak şekilde bir iş organizasyonu yapılmalıdır.\\n2- Malzeme ya da istiflerin pano önlerini kapatmaması sağlanmalıdır.\\n3- Panolara erişim için en az 80 cm genişlikte ulaşım yolları sağlanmalıdır.\\n4- Pano üzerlerine uyarı etiket ve işaretleri asılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20514\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1- Elektrik panoların kilitsiz olması\\n2- Uyarı levhası olmaması\\n3- Pano önlerinde yalıtkan paspas olmaması\",\"risk\":\"1- Elektrik çarpması sonucu yaralanma\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.\",\"oneri\":\"1- Elektrik panoları sürekli kilitli bulundurulmalıdır.\\n2- Pano etrafındaki elektrik kabloları kablo kanalı içerisine alınmalıdır.\\n3- Pano altlarına eksik olanlara yalıtkan paspas yerleştirilmelidir.\\n4- Panolara yetkisiz kişilerin erişimi engellenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20515\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1- Ticari işletmelerde bulunan dolap, raf ve portatif rafların sabitlenmemesi\",\"risk\":\"1-Devrilme, düşme ya da çarpma sonucunda  yaralanma\",\"mevcut_onlem\":\"1- Bir çok raf sabitlenmiştir.\",\"oneri\":\"1-Sabitlenmemiş dolap ve raflar en az iki noktadan duvar, tavan ya da tabandan sabitlenmelidir.\\n2- Portatif rafların ayak frenleri bulunmalı ve kapalı tutlmalıdır.\\n3-Ağır malzeme ve ekipmanlar yüksek istiflenmemelidir.        \\n4- Portatif raflar çıkışları engellemeyecek şekilde konumlandırılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20516\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1-Yemek yapılan ve dağıtılan alanların kirli olması, yağ birikimi olması\",\"risk\":\"1-Enfeksiyon hastalıklarına yakalanma\",\"mevcut_onlem\":null,\"oneri\":\"1-Paslanmaz tezhgahlar, benmariler ve kullanılan aletler günlük olarak temizlenmelidir.                                                                                                                                                     2-Zemin günlük olarak düzenli temizlenmeli , duvar yüzeyleri haftalık olarak düzenli  temizlenmeli  ve  asma tavan aylık olarak  düzenli temizlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20517\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1- Kola, içecek, lpg vb. basınçlı tüplerin uygun depolanmaması\",\"risk\":\"1- Fiziksel patlama sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Basınçlı tüpler için depolama alanı yapılmalı, çıkış yol ve güzergahlarına tüpler bırakılmamalıdır.\\n2- Dolu ve boş tüpler için ayrı depolar yapılmalıdır.\\n3- Tüpler ısı kaynaklarından ve güneşin etkisinden uzak tutulmalıdı\\n4- Basınçlı tüpler zeminde sabitlenmeden bırakılmamalı, sabitleme aparatlarına takılmalı ve 2 noktadan zincir ya da halatla bağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20518\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1-Yemek pişiren dağıtan çalışanların   sağlık kontrollerinin yapılmamış olması\",\"risk\":\"1- Bulaşıcı hastalıklar ve salgın hastalıkların diğer çalışanlara bulaştırma\",\"mevcut_onlem\":null,\"oneri\":\"1-Yemek pişiren dağıtan çalışanların 6 ayda 1 portör muayeneleri yapılmalıdır.\\n2- Hepatit taramaları ve akciğer grafileri yılda bir tekrarlanmalıdır.   \\n3- Bölüme yeni başlayan çalışanlar sağlık taramaları yapılmadan işe başlatılmamalıdır.                                                                                                                                                                                                           4-Sonucu uygun olmayanlar çalışanlar yemek pişirme, dağıtma bölümünde çalıştırılmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20519\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1- Ticari işletmeler totem ve reklam pamolarının fırtına, şiddetli rüzgarda devrilmesi\",\"risk\":\"1- Totemlerin ya da reklam panolarının devrilmesi sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1-Totemlerin taşıyıcı sistemlerinin şiddetli rüzgar deprem vb. yüklerine karşı taşıma kapasitesinin yeterli olup olmadığı statik uygunluk kontrolü yetkili inşaat mühendislerine yaptırılmalıdır. \\n2-Totemler düzenli aralıklarlar ile korozyon, pas oluşumu, ankraj noktalarında çatlak ve bağlantı gevşemesine karşı kontrol edilmeli, Totemlerin korozyon ve paslanmış kısımları boyanmalı, çatlak ve bağlantı gevşemesi olan yerler onarılmalıdır.                                                                                                                                                                                                                                                                                \\n3-Şiddetli rüzgâr, fırtına anında açık alanlarda hizmet verilmemelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":40,\"frekans\":3},{\"anahtar\":\"hst-20520\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1- Dış ticari işletme alanları faraday kafesinin periyodik kontrollerinin yapılmaması\",\"risk\":\"1-Yıldırım düşmesi sonucunda yaralanma, yangın\",\"mevcut_onlem\":null,\"oneri\":\"1-Paratoner tesisatının periyodik kontrolleri TS EN 62305 standardına göre yılda en az 1 kez tekrarlanmalı ve belgelendirilmeldir.                                                                                                     2-Faraday kafesi içinde, civatalarda ve Franklin çubuklarında paslı ve korozyonlu alan bulunmamalıdır.                                                                                                                                                       3- Paratoner topraklaması bina topraklaması ile eşpotansiyel olmalıdır.                                                                                                                  4-Topraklama tesisinin direnci en fazla 10 ohm olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20521\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1- Atık yağların uygunsuz muhafaza edilmesi\",\"risk\":\"1- Yangın çıkması\",\"mevcut_onlem\":null,\"oneri\":\"1- Atık yağlar gıda hazırlama alanından ayrı tutulmalıdır.\\n2- Atık yağlar kapalı sızdırmaz varillerde muhafaza edilmelidir.\\n3- Kaplar üzerinde “ATIK YAĞ” etiketi bulunmalıdır.\\n4- Dökülme durumunda hemen temizlenmeldir.\\n5- Atık yağlar kesinlikle tekarar kullanılmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20522\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1- Elektrik kablolarının, priz vb. elektrik sistemlerinin su ya da sıcak maddeler ile temas etmesi\",\"risk\":\"1- Kısa devre ve elektrik arkı\\nsonucu elektrik yangınları meydana gelmesi\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.\",\"oneri\":\"1- Elektrik kabloları çift izolasyonlu olmalı, kullanılan fiş priz aydınlatma sistemleri etanj özellikte olmalıdır.\\n2- Elektrik kablolarının, priz vb. elektrik sistemlerinin su, nem, buhar ve sıcak malzemelere teması önlenmelidir.\\n3- Cihazların elektrik kablolarında izole bant ile bantlanmış ekler olmamalıdır.                                                                                                                          4- Kaçak akım röleleri aktif olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20523\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1- Ticari Alanlarda Sözel ve Fiziksel Saldırı (Beyaz kod)\",\"risk\":\"1- Beyaz kod gibi Acil durumlara müdahalenin gecikmesi\",\"mevcut_onlem\":\"1-  Hastanede Beyazkod (1111) sistemi bulunmaktadır.\",\"oneri\":\"1-  Ticari alanlarda Acil Durumlar ile ilgili prosedür ve talimatlar hazırlanmalı\\n2-  Ticari Alanlarında Meydana Gelebilecek sözel ve fiziksel şiddet durumlarında çağrı başlatılabilecek ve Güvenlik Müdahalelerinde Koordinasyon Sorunlarını ortadan kaldıracak sistem kurulmalıdır.\\n3- Dış beyazkod ihbar sistemi iletişim numaraları görünür şekilde asılı olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20524\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1- Otomatlarda uzatma kabloları kullanılması\\n2- Elektrik kablolarının açıkta olması\",\"risk\":\"Elektrik Çarpması\\nYangın Riski\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.\",\"oneri\":\"1- Otomatlarda uzatma kabloları kullanılmamalı, elektrik beslemesi prizlerden yapılmalıdır.\\n2- Otomat elektrik kabloları otomat altında kalmamalı, ezilmesi önlenmelidir.\\n3- Otomat elektrik kablolarıında yırtık, ek, deformasyon vb. bulunmamalı, kablolar çift izolasyonlu olmalıdır.\\n4- Otomat elektrik kabloları çalışan, hasta, çocuk vb. temas edemeyecek şekilde kapatılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20525\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1- Ticari işletmelerin evsel atık alanlarının uygun olmaması\",\"risk\":\"1- Enfeksiyon\\n2- Haşere üremesi\\n3- Kötü koku\",\"mevcut_onlem\":\"1-Evsel Atık Alanının da açık çöp konteynerleri mevcuttur.\",\"oneri\":\"1-  Ortak atık alanında kapalı, havalandırmalı ve yanmaz malzemeden yapılmış  etiketli konteynerler kullanılmalıdır.\\n2- Atıklar sadece atık kutularına atılmalı, zemine dökülmesi önlemelidir.\\n3- Zemine dökülen atıklar bekletilmemeli, hemen temizlenmelidir.\\n4-  Atık alanları ve konteynerleri (Evsel organik, geri dönüşüm, tehlikeli atık vb.) ayrılmalı, konteynır kapıları kapalı tutulmalıdır.\\n5-  Atık alanı yakınında 50 kg\'lik kuru kimyevi tozlu yangın söndürücü bulunmalıdır.\\n6-  Haşerelere karşı ilaçlama yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":2},{\"anahtar\":\"hst-20526\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1- Kaygan, ıslak ve bozuk zemin\",\"risk\":\"1-Düşme, denge kaybı sonucunda vücut bölümlerinin yaralanması\",\"mevcut_onlem\":\"1-  Alan genelinde ıslak ve bozuk zemin bulunmamaktadır. \\n2-  Sulu temizlik yapılmamaktadır.\",\"oneri\":\"1- Bozulan zeminin tamir ve tadilatı yapılmalıdır.\\n2- Temizlik işlemi sırasında zemin kurulanmalı temizlik esnasında uyarı tabelaları konulmalıdır.                                                                                                     3- Kaymaya sebep olacak maddelerinin zeminde birikmesi önlenmeli, hemen temizlenmelidir.\\n4- Çalışanlar kaymaz tabanlı ayakkabı giymelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":2},{\"anahtar\":\"hst-20527\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1-Yemek pişiren dağıtan çalışanların önlük, bone maske kullanmaması\",\"risk\":\"1-Enfeksiyon hastalıklarına yakalanma\",\"mevcut_onlem\":null,\"oneri\":\"1-Yemek pişiren dağıtan çalışanlar iş kıyafetini ve ayakkabı/terliğini sadece çalışma alanında kullanmalı, bu ekipmanlar ile çalışma alanı dışına çıkılmamalıdır.                                                                                                                                                  2- Yemek pişiren dağıtan çalışanlar önlük bone ve eldiven kullanmadan çalışmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20528\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1- Ticari işletmelerde kullanılan otomatik kapıların fotosel tertibatının olmaması\",\"risk\":\"1-Kapının düşmesi sonucu vücut bölümlerinin ezilmesi, yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Otomatik kapı ve kepenklerde,  altından çalışan geçerken çalışmasını durduracak şekilde fotosel tertibatı yaptırılmalıdır. \\n2- Kapı indirilip kaldırılırken 1 metreden yakın içeride ve dışarıda hiç kimse bulunmamalıdır.\\n3-  Kapı ve kepenklerin üzerinde veya görülebilir bir alanda uyarı işaretleri bulunmalıdır.\\n4-  Motor, fren, sensör ve kontrol panelleri periyodik olarak test edilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":3},{\"anahtar\":\"hst-20529\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1- Depolama alanlarında kimyasal ve gıda maddelerinin birlikte depolanması\",\"risk\":\"1- Yangın riski\\n2- Gıda/kuru malzeme kontaminasyonu\",\"mevcut_onlem\":null,\"oneri\":\"1-  Gıdalar maddleri ile kimyasallar, yanıcı malzemeler (Ambalaj,karton vb atıklar) ayrı alanlarda depolanmalıdır.\\n2-  Yanıcı kimyasallar ısı,  elektrik, kıvılcım kaynaklarından uzakta depolanmlaıdır. \\n3-  Acil çıkış yolları açık tutulmalıdır.\\n4-  Depolarda yangın söndürücüler hazırda bulundurulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":1},{\"anahtar\":\"hst-20530\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1- Dağınık elektrik kablo ve hortumlar\",\"risk\":\"1- Takılma, düşme sonucu yaralanma\",\"mevcut_onlem\":\"1-  Kısmi kablo kanalları ve spiral uygulaması mevcuttur.\",\"oneri\":\"1-  Elektrik kabloları için kablo kanalları, spiral koruyucu veya yerden geçen hatlara sabitlenmelidir.\\n2-  Hortum ve malzemeleri düzenli raf / askı sistemine alınmalıdır.\\n3-  Kaçış yolları üzerinde kablo, kanalı vb. bulunmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":2},{\"anahtar\":\"hst-20531\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1- Çöp kovalarının açık olması\",\"risk\":\"1- Sinek, böcek, fare gibi zararlı canlıların çoğalması ve hastalık yayması\",\"mevcut_onlem\":null,\"oneri\":\"1- Çöp kovaları sürekli kapalı tutulmalıdır.\\n2- Çöp poşetlerinin ağızları bağlanarak dış çöpe atılmalı, çöpler bekletilmemelidir.\\n3- Çöp kovaları temizlik maddeleriyle düzenli olarak yıkanmalıdır.\\n4- Düzenli aralıklarla zararlının türüne göre ilaçlama yapılmalıdır.\\n5- Zararlı canlıların yemekhane ve mutfağa ulaşabilecekleri delik ve açıklık varsa  kapatılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":2},{\"anahtar\":\"hst-20532\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: TİCARİ ALANLAR\",\"faaliyet\":null,\"tehlike\":\"1- Havalandırma menfez ve iklimlendirme sistemlerin de toz birikmesi\",\"risk\":\"1- Solunum yolu rahatsızlıkları, alerji ve astım riski\",\"mevcut_onlem\":null,\"oneri\":\"1-  Menfez ve Filtre temizlikleri belirlenmiş periyotlar ile yapılmalı,toz birikimi önlenmelidir.\\n2-  Yemek, cafe ve oturma alanlarında temiz hava akışı sağlanmalıdır.\\n3-  Yoğun pişirme sırasında ekstra havalandırma veya fan kullanımı ile koku ve duman kontrol edilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":2}]', 0, 0, NOW(), NOW()
FROM `users` u WHERE u.`email` = 'mozdemir2816@gmail.com' AND NOT EXISTS (SELECT 1 FROM `risk_sablonlari` s WHERE s.`user_id` = u.`id` AND s.`ad` = 'Hastane — Birim: TİCARİ ALANLAR');

INSERT INTO `risk_sablonlari` (`user_id`, `ad`, `sektor`, `sektor_adi`, `yontem`, `maddeler`, `paylasildi`, `kullanim_sayisi`, `created_at`, `updated_at`)
SELECT u.`id`, 'Hastane — Birim: FTR', 'saglik', NULL, 'fine_kinney', '[{\"anahtar\":\"hst-20533\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON\",\"faaliyet\":null,\"tehlike\":\"1-Koterizasyon (elektrokoter) işleminin yapılması\",\"risk\":\"1- İşlem kaynaklı dumandan dolayı meslek hastalıkları                   2- Cihaz kaynaklı elektrik çarpmaları\",\"mevcut_onlem\":null,\"oneri\":\"1- Koterizasyonun yapıldığı alana duman aspiratörü temin edilmeli ve  işlem sırasında kullanılmalıdır.                                                                                                                            2- Elektrokoter cihazının topraklaması yapılmalıdır.                                                                    3- İşlem esnasında ıslak yüzey bulunmamalıdır.                                                                              4- İşlem sırasında maruz kalan çalışan için TS EN 149 Standardında FFP2 Maske bulundurulmalı ve çalışan tarafından kullanılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20534\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON\",\"faaliyet\":null,\"tehlike\":\"1-Elektrikli mutfak aletleri (çay, kahve, microdalga fırın, airfryer vb.) kullanılması\",\"risk\":\"1- Elektrik yangını çıkması sonucu, yaralanma, boğulma, ölüm\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.                                   2-300 MA yangın röleleri mevcuttur.\",\"oneri\":\"1- Hastane de mutfak olarak belirlenmiş alanlar dışında hiçbir yerde elektrikli mutfak aletleri kullanılmamalıdır.                                          \\n2- Mutfak olarak tanımlanmış alanlarda sadece çay ve kahve makinesi kullanılmalı, bunların dışındaki aletlerin kullanımı yasaklanmalıdır.         \\n3- Sadece çift termostatlı çay kahve makineleri makineleri kullanılmalıdır.    \\n4- Çay kahve makineleri direk fişe takılmalı, uzatma kablolarına takılmamalıdır.\\n5- Çay kahve makineleri kullanıldıktan sonra fişten çıkarılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20535\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON\",\"faaliyet\":null,\"tehlike\":\"1- Z katı acil çıkış merdivenlerinin lambalarının arızalı olması\",\"risk\":\"1-Acil durumlarda tahliyenin zorlaşması\",\"mevcut_onlem\":null,\"oneri\":\"1-Arızalı acil durum aydınlatmaları değiştirilmelidir.\\n2- Acil çıkış  merdivenleri yeterli şiddetde aydınlatılmalı ve elektrik kesilmelerinde otomatik olarak devreye girecek aydınlatma sistemi bulunmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20536\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON\",\"faaliyet\":null,\"tehlike\":\"1- Oksijen tüplerinin ve diğer basınçlı tüplerin paslı ve korozyonlu olması\",\"risk\":\"1- Tüplerinin yapısal bütünlüğünün bozulması sonucu gaz kaçağı, patlama meydana gelmesi\",\"mevcut_onlem\":\"1-O2 Tüpleri  alanda köşede zincirler ile sabitlenmesi gereken alanlar belirlenmiştir.\",\"oneri\":\"1- Paslı ve korozyonlu tüpler kullanım dışı bırakılmalıdır.               \\n 2- Bu tüplerin tedarikçi firma tarafından hidrostatik test ve ultrasonik kalnlık ölçümleri yapılmalıdır.                                                                          \\n3- Gaz sızıntısı durumunda hiçbir onarım yapmadan tüp açık bir alana çıkarılarak tedarikçi firmaya haber verilmelidir.                    \\n4- Basınçlı tüpler elektrik ısı kıvılcım kaynaklarından en az 3 metre uzakta bulundurulmalı, en az iki noktadan dik konumda sabitlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20537\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON\",\"faaliyet\":null,\"tehlike\":\"1-Tedavi arabalarının koridorda bulundurulması\",\"risk\":\"1-Hasta ya da hasta yakınlarının kesici delici aletlere kolay erişmesi sonucu fiziksel şiddet\",\"mevcut_onlem\":\"1- Panik butonları mevcuttur.\",\"oneri\":\"1-Tedavi arabaları mümkün olduğunce ortak alanlardan uzakta park edilmelidir.                              \\n2-Üzerinde kesinlikle makas, bıçak vb. kesici aletler bulundurulmamalıdır.                                                         3-Ayrıca ilaç rafları kilitli tutulmalı, tehlikeli ya da kırmızı reçeteli ilaçlar kesinlikle bulundurulmamalıdır. \\n4-Tedavi arabası içerisindeki tıbbi atık kutusunun kapağının sürekli kapalı tutulmalı ve dolu olmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20538\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON\",\"faaliyet\":null,\"tehlike\":\"1-Hasta yıkama odası içerisinde duş telefonları ve yataklarının prize yakın olması\",\"risk\":\"1-Elektrik kaçakları,                                                 2-Elektrik çarpmaları                                               3- Elektrik yangınları\",\"mevcut_onlem\":\"1- Prizlerde koruma kapakları mevcuttur.\",\"oneri\":\"1-Hasta yıkama odasında duş telefonları yakınında bulunan bütün prizler iptal edilmelidir.                                                                          \\n 2-Aktif olarak kullanılıyorsa prizler değiştirilerek yerlerine su geçirmez priz (etanj) kullanılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20539\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON\",\"faaliyet\":null,\"tehlike\":\"1- Hasta odası camlarının yetkisiz kişilerce açılması\",\"risk\":\"1- İntihara meyil                                                         2-İklim bozuklukları\",\"mevcut_onlem\":null,\"oneri\":\"1- Hastane de tüm camlar kontrol edilmeli, tam açılabilen camlar en fazla açıklık 15 cm açılacak şekilde ayarlanmalı ve sabitlenmelidir.                                                                                                  2- Pencere kilitleri sadece yetkili bölüm sorumlularında bulunmalı, sadece acil ihtiyaç halinde açılmalıdır. \\n3- Hastalarda ya da hasta yakınlarında lokma anahtar tespit edildiğinde derhal birim sorumluları ya da çalışanlar tarafından el konulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20540\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON\",\"faaliyet\":null,\"tehlike\":\"1-3. Kat Teras çıkış kapısın da kart sistemi bulunmaması\",\"risk\":\"1-Yetkisiz kişilerin ulaşımı sonucu intihar girişimleri,\",\"mevcut_onlem\":null,\"oneri\":\"1- Terasa çıkış kapısı kartlı sistem olmalıdır.                                         \\n2- Terasa yetkisiz kişilerin çıkması önlenmelidir.\\n3- Çalışanlar terasa sigara içme vb. amaçlar ile çıkmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20541\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON\",\"faaliyet\":null,\"tehlike\":\"1-Mahal Kodu: 08000103102 içerisinde mekanik odanın kapı kilidinin bozuk olması\",\"risk\":\"1- Yetkisiz çalışanın mahale girmesi sonucu yaralanma, ölüm\",\"mevcut_onlem\":null,\"oneri\":\"1-Teknik Birim personelleri alanda işleri bittiğinde kapıları tam kapatmalı, kilitli olduğundan emin olmadan alandan ayrılmamalıdır.                                                                   2- Kilidi veya Kapıları bozuk mekanik ve elektrik odalarının tespitinde derhal Teknik Birim personeline bildirilmeli, derhal onarılmalıdır.                                                      3- Kapı Kilidi bozuk olan mekanik/Elektrik odalarının önüne \'\'Dikkat Elektrik Var, Girmek Yasaktır\'\' şeklinde uyarı levhaları bulundurulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20542\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON\",\"faaliyet\":null,\"tehlike\":\"1-Basınçlı tüplerin hatalı kullanılması\",\"risk\":\"1- Tüplerin düşmesi, devrilmesi sonucu patlama meydana gelmesi\",\"mevcut_onlem\":\"1-Oksijen tüpü sabitleme aparatları bulunmaktadır.\",\"oneri\":\"1- Oksijen tüplerine yağlı, kremli eller ile temas edilmemeli, vanaları yağlanmamalıdır.                                                                                                                                   2- Tüpler ısı kaynaklarından ve güneşin etkisinden uzak tutulmalıdır.                                                                                                                                    3- Manometreler sağlam olmalı, kırık olanlar değiştirilmelidir.                                       \\n4- Basınçlı tüpler zeminde sabitlenmeden bırakılmamalı, sabitleme aparatlarına takılmalı ve 2 noktadan zincir ya da halatla bağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20543\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON\",\"faaliyet\":null,\"tehlike\":\"1-Banyodan su taşkınlarının yaşanması\",\"risk\":\"1-Su baskınları                                                     2-Sıvıya bağlı Elektrik çarpma ve kaçakları                                                                              3- Kayma, Düşme\",\"mevcut_onlem\":null,\"oneri\":\"1-Hasta odalarında banyo giderlerinin düzenli bakım ve onarımları yapılarak tıkanma problemleri engellenmelidir.                                                               \\n2- Duşakabin içerisinde eğim tekrar düzenlenmeli, gider doğru yokuş yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20544\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON\",\"faaliyet\":null,\"tehlike\":\"1-Bulaşı Bulunan hastaların izolasyonu\",\"risk\":\"1- Meslek hastalıkları                                                   2- İş Kazaları\",\"mevcut_onlem\":\"1-Tanımlayıcı figürler aktif olarak kullanılmalıdır.\",\"oneri\":\"1-Klinikte bulaşı bulunan ve bilinen hastalarında odaları Sağlık Bakanlığı\'nın belirlemiş olduğu tanımlayıcı figürler ile belirtilmelidir.    \\n2-Sarı Yaprak (Solunum İzolasyonu)- Mavi Çiçek (Damlacık İzolasyonu)-Kırmızı Yıldız (Temas İzolasyonu) Şeklindedir.                                                 \\n3-Hastane içerisindeki tüm personele EKK eğitim vermelidir.                                                                     4- Personel Figürlerin bulunduğu odaya girerken KKD\'lerini eksiksiz kullanmalı, koruyucu önlemleri olmadan odaya girmemelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20545\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON\",\"faaliyet\":null,\"tehlike\":\"1- Uygunsuz Formaldehit Kullanımı\",\"risk\":\"1- Meslek hastalıkları                                                   2- İş Kazaları\",\"mevcut_onlem\":\"1-Formaldehit ile çalışan personele İSGB tarafından Formaldehitile güvenli Çalışma eğitimi verilmiştir.\",\"oneri\":\"1- 21.10.2025 tarihinde hazırlanan Yöntem Beyan\'ına göre firma tarafından formaldehit, patoloji laboratuvarında porsiyonlanarak gönderilmelidir\\n2- Formaldehit büyük kaplardan, küçük kaplara aktarılırken taşma kapları kullanılmalı, zemine dökülmesi önlenmelidir.\\n3- Formaldehit dökülmesine karşı döküntü kitleri temin edilmelidir.\\n4- Çalışanlar formaldehit ile çalışma esnasında EN 149 standardında ffp3 maske, eldiven ve koruyucu gözlük kullanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20546\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON\",\"faaliyet\":null,\"tehlike\":\"1- Fizyoterapi için kullanılan sedyelerin kilit sistemlerinin bozuk olması\",\"risk\":\"1- İş kazaları            2-Deprem anında tahliyenin gecikmesi\",\"mevcut_onlem\":null,\"oneri\":\"1- Firma tarafından belirli aralıklar ile sedyelerin periyodik muayeneleri yaptırılmalıdır.                                                                                                                                                 2- Kilit sistemleri veya sedyede herhangi bir arıza meydana gelirse kullanım dışı bırakılmalı, onarımı yaptırılmadan kullanılmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20547\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON\",\"faaliyet\":null,\"tehlike\":\"1-Tavan, Çatı akmaları ve çökmeleri\",\"risk\":\"1-Suyun elektrik ile teması sonucu çarpılma\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.\",\"oneri\":\"1- Çatıdan su akan yerler tespit edilmelidir.\\n2- Su çeken tavan vb. yerler onarılmalıdır.\\n3- Suyun elektrik sistemlerine temas etmesi önlenmeli, temas eden yerlerin onarım sağlanana kadar akım kesilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20548\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON\",\"faaliyet\":null,\"tehlike\":\"1-Robotik Rehabilitasyon ünitesi hasta kaldırma/ taşıma işlemi\",\"risk\":\"1-Kas iskelet sistemi hastalıkları\",\"mevcut_onlem\":\"1-Çalışanlar Yılda 1 kez Ergonomi ile Güvenli çalışma eğitimi almaktadır.\",\"oneri\":\"1- Hastaları Robota kaldırma, indirme işlemleri en az 2 kişi ile yapılmalıdır.                              2-Çalışanlara Ergonomik çalışma eğitimi verilmeli ve düzenli olarak sağlık taramalarına katılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20549\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON\",\"faaliyet\":null,\"tehlike\":\"1- Atık odalarının kapılarının kilitli tutulmaması\",\"risk\":\"1-Enfeskiyon kaynaklı meslek hastalıkları/İşle ilgili hastalıkları\",\"mevcut_onlem\":null,\"oneri\":\"1- Atık bekleme odalarının kapıları açık bırakılmamalı her zaman kilitli olmalıdır. \\n2- Atık bekleme odalarına kartlı giriş sistemi yapılmalı, yetkisiz kişilerin girişi önlenmelidir.\\n3- Düşen, okunmayan uyarı levhaları değiştirilmelidir.                                                                                                    4- Sürekli saha gözetimi, kontrol ve denetim sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20550\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON\",\"faaliyet\":null,\"tehlike\":\"1- Prizlerin yuvalarından çıkması\",\"risk\":\"1- Elektrik çarpması sonucu yaralanna\",\"mevcut_onlem\":null,\"oneri\":\"1- Hasarlı prizler onarılmalı ya da yenileriyle değiştirilmelidir.  \\n2- Hasralı prizlerin topraklama bağlantıları da kontrol edilmelidir.                                                                              3-Birim sorumluları ve Ççlışanlar alan kontrolü yaparak Arızalı veya yerinden çıkmış priz gördüklerinde 1616 üzerinden Prizlerin onarılmasını talep etmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20551\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON\",\"faaliyet\":null,\"tehlike\":\"1- Hasta kayıt personellerinin önünde seyyar kalorifer kullanılması\",\"risk\":\"1-Yangının çıkması   \\n2- Elektrik çarpması\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.\",\"oneri\":\"1- Hastane de soğuk havalarda elektrik ısıtıcılar kullanılmamalı, ısınma amaçlı sadece iklimlendirme sistemi kullanılmalıdır.                                                                                                          2- Çalışanların otomatik açılan kapılardan soğuk havaya maruz kaldıkları alanlara hava perdeleri yapılmalıdır.                                                                                                                                3- İstisnai durumlarda idareden özel izin alınmalı, ısıtıcıların prizlerden beslenmesi sağlanmalı, yanıcı malzemelerden uzak tutulmalı,kullanım sonrası fiş prizden çekilmelidir.                                                                                                                     4- İzinsiz kullanılan tüm ısıtıcılar toplatılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20552\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON\",\"faaliyet\":null,\"tehlike\":\"1- Z Katı acil çıkış merdivenlerine ulaşımda tümsek bulunması\",\"risk\":\"1-Acil durumlarda tahliyenin zorlaşması\",\"mevcut_onlem\":null,\"oneri\":\"1- Acil çıkış yollarınn ya da merdivenlerinin önünde hiçbir engel bulunmamalı, her an kullanılabilmesi için engellerden arındırılmış hâlde bulundurulması gerekir.\\n2- Merdivenler önünde tümsek bulunmamalı, kaldırılmalıdır.\\n3- Çıkışlar ve erişim yolları açıkça görülebilir olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20553\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON\",\"faaliyet\":null,\"tehlike\":\"1- Terzi odasında kumaş kesim moturunun emniyetsiz kullanılması\",\"risk\":\"1- El kol yaralanmaları\",\"mevcut_onlem\":null,\"oneri\":\"1- Kesim motorunun koruyucusu iptal edilmemelidir.\\n2- Koruyucu indirilmeden kesim yapılmamalıdır.\\n3- Kesim motoru durdurulmadan üzerinde herhangi bir işlem yapılmamalıdır.\\n4- Kesim yapılırken cihaz kablosu işlem alanından uzak tutulmalıdır.\\n5- Bıçak değiştirme işlemi elektrik akımı kesildikten sonra yapılmalıdır.\\n6- Kullanılmayan kesim motoru fişten çekilip kaldırılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20554\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON\",\"faaliyet\":null,\"tehlike\":\"1- Terzi odasında ya da oda önünde yangın söndürücü bulunmaması\",\"risk\":\"1- Yangın çıkması                       2- Yangının büyümesi\",\"mevcut_onlem\":null,\"oneri\":\"1- Oda içerisinde ya da yanında kuru  kimyevi tozlu yangın söndürme tüpü bulundurulmalıdır.                                                                                                                                     2- Terzi odası içerisinde elektrikli ev aletleri kullanılmamalıdır.                                              3-  Terzi odası içerisinde hiçbir şekilde açık alev kullanılmamalı, yanıcı madde kullanılmamalıdır.     \\n4- Kumaşlar raflara düzenli istiflenmeli, atıl kumaşlar oda da bekletilmemelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20555\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON\",\"faaliyet\":null,\"tehlike\":\"1- Ayniyat odalarında yüksek istifleme yapılması\",\"risk\":\"1- Malzeme düşmesi sonucu  yaralanma, ezilme, sıkışma\",\"mevcut_onlem\":null,\"oneri\":\"1- İstif yüksekliği en fazla 3 metre olmalıdır.\\n2- Malzemeler düzenli istiflenmeli, devrilmeyecek şekilde sabitlenerek istif yapılmalıdır.\\n3- Devrilme riski olan malzemeler 1,5 metreden yüksek istiflenmemelidir.\\n4- Stok girişi yapılmayan malzemeler depoya alınmamalıdır.\\n5- Ağır malzemeler en altta istiflenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20556\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON\",\"faaliyet\":null,\"tehlike\":\"1- Hastaların oksijen tüpü ile hastaneye gelmesi\",\"risk\":\"1-Parlama, patlama, yangın                           2- iş kazaları yaşanması\",\"mevcut_onlem\":null,\"oneri\":\"1-Hastalar alana geldiğinde sabitlenmemiş, yatay taşınan oksijen tüpleri hasta karşılama ve güvenlik personeli tarafından tespit edilerek, oksijen tüplerinin hastane içerisine girişini engellemelidir. Mümkün olmadığı durumda alanda Oksijen tüpü sabitleme aparatı bulundurularak sedye ve tekerlekli sandalye için sabitleme aparatı hastane içerisinde kullanılması için hastalara temin edilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20557\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON\",\"faaliyet\":null,\"tehlike\":\"1- Güvenlik filesinin periyodik kontrolllerinin yapılmaması\",\"risk\":\"1- Yüksekten düşme sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1-Güvenlik filelerinin periyodik kontrolü TS EN 1263-1, TS EN 1263-2 standartlarına uygun olarak en geç yılda bir yapılmalıdır.\\n2- Fileler de yırtık, kopukluk, aşınma olup olmadığı, kenar halatlarının bağlantı iplerinin sağlam olup olmadığı, ankraj noktalarında aşınma, pas korozyon olup olmadığı göz ile ayda bir kontrol edilmeli, belgelendirilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20558\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON\",\"faaliyet\":null,\"tehlike\":\"1-Portable ve EKG cihazlarının koridor alanında sarj edilmesi\",\"risk\":\"1 -Elektrik çarpmaları                                               3- Elektrik yangınları\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.\",\"oneri\":\"1- Portable ve Ekg cihazlarının sarj edilmesi için ortak alanlarda uzak ayrı bir alanda şarj edilmelidir.\\n2- Sarj işlemi sona erdiğinde kablolar fişe takılı bırakılmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20559\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON\",\"faaliyet\":null,\"tehlike\":\"1-Elektroterapi Ünitesinde kullanılan makine kablolarının yıpranması\",\"risk\":\"1- Elektrik çarpmaları\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.\",\"oneri\":\"1- Yıpranmış, ezilmiş, soyulmuş ve izolasyonsuz kablolar değiştirilmelidir.                                                                                                                           2-  İzole bantlı ekli kablolar kullanılmamalıdır.\\n3- Makikenelerin elektrik kabloları çift izolasyonlu olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20560\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON\",\"faaliyet\":null,\"tehlike\":\"1-Elektroterapi cihazlarını kabloların dağınıklığı\",\"risk\":\"1-Kabloların deforme olması sonucu elektrik çarpmaları               2-Takılma/Düşme\",\"mevcut_onlem\":null,\"oneri\":\"1- Ekipmanların kabloları kablo tutucu ve kablo askıları ile sabitlenmeli, toparlanmalıdır.                                                                                                                                            2-Kabloları yıpranma, ezilme, izolasyon kopması açısından kontrol edilmelidir.             \\n3-Makine ve priz yerleşimi gözden geçirilerek kablo karmaşası en aza indirilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20561\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON\",\"faaliyet\":null,\"tehlike\":\"1- Kan ve vücut sıvılarının göz ve cilde temas etmesi\",\"risk\":\"1-Temas sonucu enfeksiyon, bulaşıcı hastalıklara yakalanma\",\"mevcut_onlem\":\"1-KKD\'ler mevcuttur.                                         2- Çalışanlara KKD önemi ve kullanımı konusunda eğitim verilmektedir.\",\"oneri\":\"1-Çalışanlar TS EN 455  standardında eldiven, TS EN 166 standardında tam kapalı gözlük ya da yüz siperi, uzun kollu koruyucu önlük  EN 14683 standardında maske vb. gibi kişisel koruyucu donanımlar kullanılmalıdır.                                                                                                                         2- Temas durumunda bölgenin bol su ve sabunla yıkanması sağlanmalıdır.                                                                                                                                    3- Kan ve vücut sıvıları sıçramasına maruz kalma sonrası çalışanın, bulaş kaynağının durumuna göre muayene ve tetkikleri yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20562\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON\",\"faaliyet\":null,\"tehlike\":\"1-O2 tüplerinin kliniklerde  fazla sayıda  bulundurulması\",\"risk\":\"1- Tüplerin düşmesi, devrilmesi sonucu patlama meydana gelmesi\",\"mevcut_onlem\":\"1-Acil durum arabaları dışında bulundurulan her O2 tüpü zincirler ile belirlenen yerlerde sabitlenerek bulundurulmaktadır\",\"oneri\":\"1-Klinik alanlarında O2 tüplerinin fazla istiflenmemesine her alanda klinik özelliğine göre 1 ya da 2 adet bulundurulmalıdır.      \\n2- Merkezi Oksijen sistemi kullanılmalı,  taşınablilir O2 tüpleri fazla sayıda bulundurulmamalıdır. \\n3- Oksijen tüpü kullanım talimatı kullanılan alanlara asılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20563\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON\",\"faaliyet\":null,\"tehlike\":\"1-Çalışan hasta ve hasta yakınları iletişim problemleri, fiziksel sözlü şiddet,\",\"risk\":\"1- Hasta ya da yakınları tarafından fiziksel ya da sözlü şiddete maruz kalma sonucu yaralanma,\",\"mevcut_onlem\":\"1-Panik butonları mevcuttur.\",\"oneri\":\"1- Hasta ve hasta yakınları tarafından çalışanların şiddete uğrayabileceği tüm alanlara sabit panik butonları ilave olarak yaka butonları temin edilmelidir.                                                                                                                                                                                                         2- Şiddet riskinin yoğun olduğu alanlarda butonlara ilave olarak sabit güvenlik personeli  bulundurulmalıdır.                                         \\n3- Çalışanlara iletişim, stres yönetimi ve öfke kontrolü ile mesleki bilgi ve becerilerini arttırıcı eğitimler verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\