SELECT u.`id`, 'Hastane — Birim: YGAP', 'saglik', NULL, 'fine_kinney', '[{\"anahtar\":\"hst-20575\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Sigara içme odalarında ve rehabilitasyon alanlarında  kamera bulunmaması\",\"risk\":\"1- Çalışanlara şiddet sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Hasta sigara içme odalarına  ve rehabilitasyon odalarına kamera sistemi kurulmalıdır.                                                                               \\n2- Güvenlik personelleri tarafından odalar sürekli izlenmelidir.\\n3- Çalışanlara yaka panik butonları verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20576\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Rehabilitasyon alanında kullanılan kesici delici ağır malzemeler(spor ağırlık ekipmanları,tiner,mutfak gereçleri vb.) bulunması\",\"risk\":\"1- Çalışanlara şiddet sonucu yaralanma\",\"mevcut_onlem\":\"1- Güvenlik personeli mevcuttur.\",\"oneri\":\"1-Rehabilitasyona uygun olan hastalar sorumlu hekimlerce belirlenmelidir.                                                                        \\n2-Hastalar rehabilitasyona çıktıklarında alanda bulunan güvenlik personeli sayısı arttırılmalıdır.                                                                    \\n3-Rehabilitasyon odalarında kamera bulunmalıdır.                                                  4-Çalışanların yakalarında bulunan acil durum düğmeleri çalışır olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20577\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Elektrikli mutfak aletleri (çay, kahve, microdalga fırın, airfryer vb.) kullanılması\",\"risk\":\"1- Elektrik yangını çıkması sonucu, yaralanma, boğulma, ölüm\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.                                   2-300 MA yangın röleleri mevcuttur.\",\"oneri\":\"1- Hastane de mutfak olarak belirlenmiş alanlar dışında hiçbir yerde elektrikli mutfak aletleri kullanılmamalıdır.                                          \\n2- Mutfak olarak tanımlanmış alanlarda sadece çay ve kahve makinesi kullanılmalı, bunların dışındaki aletlerin kullanımı yasaklanmalıdır.         \\n3- Sadece çift termostatlı çay kahve makineleri makineleri kullanılmalıdır.    \\n4- Çay kahve makineleri direk fişe takılmalı, uzatma kablolarına takılmamalıdır.\\n5- Çay kahve makineleri kullanıldıktan sonra fişten çıkarılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":40,\"frekans\":6},{\"anahtar\":\"hst-20578\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Oksijen tüplerinin ve diğer basınçlı tüplerin paslı ve korozyonlu olması\",\"risk\":\"1- Tüplerinin yapısal bütünlüğünün bozulması sonucu gaz kaçağı, patlama meydana gelmesi\",\"mevcut_onlem\":\"1-O2 Tüpleri  alanda köşede zincirler ile sabitlenmesi gereken alanlar belirlenmiştir.\",\"oneri\":\"1- Paslı ve korozyonlu tüpler kullanım dışı bırakılmalıdır.               \\n 2- Bu tüplerin tedarikçi firma tarafından hidrostatik test ve ultrasonik kalnlık ölçümleri yapılmalıdır.                                                                          \\n3- Gaz sızıntısı durumunda hiçbir onarım yapmadan tüp açık bir alana çıkarılarak tedarikçi firmaya haber verilmelidir.                    \\n4- Basınçlı tüpler elektrik ısı kıvılcım kaynaklarından en az 3 metre uzakta bulundurulmalı, en az iki noktadan dik konumda sabitlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20579\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Panik butonlarının çalışmaması, yaka butonlarının pilinin bitmesi\",\"risk\":\"1- Beyaz kod durumunda güvenlik görevlilerine ulaşılamaması sonucu durumun kötüleşmesi\",\"mevcut_onlem\":\"1-Bir çok alanda  panik butonları mevcuttur.\",\"oneri\":\"1- Panik butonları her zaman çalışır durumda olmalıdır.                    \\n2- Panik butonlarının haftalık fonksiyon testleri yapılmalı, yılda en az bir kez periyodik kontrol yapılmalıdır.                                                                   \\n3- Panik butonlarında arıza olması halinde en fazla 2 saat içinde arıza giderilmeli, giderilemiyorsa, çalışanlara yaka butonları verilmelidir.                                                                                                                                 4- Yaka butonları kontrol edilmeli pilleri bitmeden değiştirilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20580\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Yardımlı banyoda duş yanında priz olması 2- Elektirikli ısıtıcı bulunması\",\"risk\":\"1-Elektirik çarpması sonucu yaralanma\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.\",\"oneri\":\"1- Yardımlı banyolarda suyun elektrik ile teması önlenmeli, duş yanındaki priz iptal edilmelidir.\\n2- Yardımlı banyolarda elektrikli ısıtıcılar kullanılmamalı, iklimlendirme sistemi kurulmalıdır.\\n3-Yardımlı banyolar da kullanılan fiş priz aydınlatma sistemleri etanj özellikte olmalıdır.                     \\n4- Elektirikli ısıtıcı su ile temasının olmayacağı bir alana taşınmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20581\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Özel politika grupları uygulamalarının yetersiz olması\",\"risk\":\"1-İş kazası ve meslek hastalıklarının artması\",\"mevcut_onlem\":null,\"oneri\":\"1- Acil durumlarda özel politika gruplarına tahliye esnasında refakat edilmesi için refakatçiler belirlenmelidir.\\n2-Engelliler sadece sağlık raporunda belirtilen ve engel durumuna uygun işlerde  çalıştırılmalıdır.  \\n3-Özel politika gruplarına kendi istekleri dışında fazla mesai yaptırılmamalı, gece vardiyalarında çalıştırılmamalıdır.\\n4-Bu gruplar uzun süre ayakta çalıştırılmamalı, ağır yük taşıtılmamalıdır.                                                                                                                                     5-Özel politika gruplarına özel olarak eğitim verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20582\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Çalışanlara yöneticileri ya da hasta hasta yakınları tarafından mobing uygulanması\",\"risk\":\"1-Sinirlilik, stres, depresyon, tükenmişlik sendromu, iş kazalarında artış\",\"mevcut_onlem\":\"1-Çalışan hakları birimi mevcuttur.                                         2-Çalışan memnuniyet anketleri yapılmaktadır.\",\"oneri\":\"1-Çalışanlara gereğinde psikolojik destek ve danışmanlık sağlanmalıdır.                                                                                                                                         2- Mobing bildirimi alındığında tarafsız inceleme süreci başlatılmalı, taraflar ayrı ayrı dinlenmeli, ve somut veriler ile kayıt tutulmalıdır.                                                                                                                            3- Tükenmişlik yaşayan çalışanlar düşük yoğunluklu birimlere kaydırılmalıdır.                                                                                                                              4- Şikayet konusu yönetici ise, yönetici davranış düzeltme sürecine (eğitim, gözlem vb.) alınmalıdır.                                                                           \\n5- Sürekli sorun çıkaran çalışanlar için eğitim, görev değişikliği ya da disiplin süreçleri başlatılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20583\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Ergonomik olmayan ofis mobilyaları ve çalışma şekli\",\"risk\":\"1- Postür bozuklukları sonucunda kas-iskelet sistemi hastalıkları,  verimlilik kaybı,\",\"mevcut_onlem\":\"1- Ergonomik risk faktörleri hakkında eğitim verilmiştir.\",\"oneri\":\"1- Sandalyeler ergonomik tasarıma sahip olmalı, ayaklar düz olarak yere temas etmeli, diz 90 derece açılı olmalı,  sandalyede bel desteği olmalı,  sırt dik, omuzlar rahat, dirsekler 90 derece açılı olmalıdır.                                                                                                                                                                   3- Eğer ayaklar yere temas etmiyorsa, ayaklara ek bir destek yerleştirilmelidir.                                                                                                                                       4- Ekranın üst kenarı göz hizasında veya az aşağısında olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20584\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Tehlikeli kimyasalların yanlış depolanması\",\"risk\":\"1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması                                 2- Yangın meydana gelmesi\",\"mevcut_onlem\":\"1- Kimyasallar depo alanında depolanmaktadır.\",\"oneri\":\"1- Kimyasal maddeler depolama matirsine göre depolanmalıdır.                                                        2- Yanıcı kimyasallar elektrik kaynaklarından uzak depolanmalıdır.                                                                               3- Kimyasal maddelerin ağzı açık olmamalı, dik olarak istiflenmelidir.                                              4- Ağzı açılmış kimyasal madde kaplarının altına taşma kapları konulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20585\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Kimyasal madde deposunda göz duşu ve döküntü kiti bulunmaması                                               2- Çalışanların kimyasallar hakkında bilgi sahibi olmaması\",\"risk\":\"1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması\",\"mevcut_onlem\":\"1- Kimyasallar depo alanında depolanmaktadır.\",\"oneri\":\"1- Kimyasalların dökülme riskine karşı döküntü kitleri bulundurulmalıdır.                                         \\n2- Göze kaçma riskine karşı göz duşu solüsyonu bulundurulmalıdır.                                              3- Kimyasal maddelere gözlük, eldiven olmadan temas edilmemelidir.                                                               4-Kimyasal maddelerin malzeme güvenlik bilgi formları depoda asılı olmalıdır.                              \\n5- Çalışanlara MSDS ve kimyasalların güvenli kullanımı konusunda eğitimler verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20586\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-KKD’lerin eksik olması,                           2- KKD\'lerin çalışanlar tarafından kullanılmaması\",\"risk\":\"1-KKD’lerin kullanılmaması sonucunda iş kazaları, meslek hastalıkları oluması\",\"mevcut_onlem\":\"1-Alanlara özel olarak KKD\'ler alanda mevcuttur.                                                                                  2- Tüm çalışanlar KKD Zimmet formunu imzalamıştır.\",\"oneri\":\"1-KKD’ler CE belgeli ve ilgili standartlara uygun olmalı, eksik olan kkd\'ler temin edilmelidir.\\n2- Çalışanların maskeleri N95 ya da TS EN149 A1 standardında,göz koruyucuları TS EN 166 standardına uygun ve tam kapalı tip, iş eldivenleri TS EN 455 standardına, kesilmelere dayanıklı TS EN 388 standardına, çalışanların önlükleri sıvı geçirmez önlük/ cerrahi önlük TS EN ISO 13688 ve TS EN 13795 standartlarında iş ayakkabıları kaymaz tabanlı olmalıdır.                                                                                                                                                                                                 3- Bütün kişisel koruyucular çalışanlara zimmetlenmelidir.                                                                       4- Kişisel koruyucu donanımlar çalışanlar tarafından eksiksiz kullanılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20587\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Steril olmayan, kontamine olmuş aletlerin açıkta bırakılması\",\"risk\":\"1-Steril olmayan aletlere temas sonucu iş kazaları enfeksiyon, bulaşıcı hastalık\",\"mevcut_onlem\":\"1-Enfeksiyon Kontrol Komitesi işe başlangıç ve belirli periyotlar ile çalışana eğitim vermektedir.\",\"oneri\":\"1-Kullanılan, kontamine olmuş aletler bekletilmeden hemen kapaklı ve renk kodlu atık kutularına atılmalıdır.                                                                                                                           2- Sterilazyona gidecek aletlere TS EN 388 standardında kesilme ve delinmeye dayanıklı eldiven olmadan temas edilmemeli, çelik, kapaklı kutulara konulmalıdır.                                                                                                                                                        3- Tek kullanımlık olmayan aletler her kullanımdan sonra dezenfekte edilmelidir.                                                                                                     \\n4- Kontamine olmuş aletler, çarşaf, yatak, yorgan vb. yere saplanmamalı, yere atılmamalıdır.                                                                                                                                                          5- Temas edilmesi durumunda, bölge bol su ve sabunla yıkanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20588\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Buat kapaklarının açık olması, kapakların kırık olması\",\"risk\":\"1-Elektrik çarpması sonucu kalp ritim bozuklukları, elektrik yanıkları, ölüm,\",\"mevcut_onlem\":\"1-30 MA kaçak akım rölerleri mevcuttur.\\n2- Topraklama ölçümleri mevcuttur.\",\"oneri\":\"1-Buat kapakları kapalı tutulmalıdır.                                                                         \\n2-Kırık buat kapakları değiştirilmeli, vidalar ile tutturulmamalıdır.  \\n3- Buatlara fişler yatay takılmalı, dikey fişler kullanılmamalı, buatların açık kalması önlenmelidir.       \\n4- Buatların üzerinde ki masalarda bir şey yenilip içilmemelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20589\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Elektrik kabloların da aşırı yükleme olması \\n2- Elektrik kablolarına su ve buhar temas etmesi\",\"risk\":\"1- Elektrik yangını çıkması sonucu, yaralanma, boğulma, ölüm\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.                                   2-300 MA yangın röleleri mevcuttur.\",\"oneri\":\"1-Hastane de kullanılan tüm elektrik, uzatma (3\'lü) vb. kablolar halojen free (geç yanan, zehirli gaz çıkarmayan) özellikte olmalıdır.                      \\n2- 3 lü uzatma kablolarına, 3 lü uzatma kablosu kullanarak kullanılmamalıdır.                                                                                                     3- Yüsek akım çeken cihazlar (kettle çay makinesi vb.) beslemesi ayrı fişlerden yapılmalı, uzatma kabloları kullanılmamalıdır.                                                                                                             4- Elektrik kablolarının su ve buhar ile teması önlenmelidir.\\n5- Çalışanların dışarıdan uzatma kablosu getirmesi yasaklanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20590\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Islak/Kaygan zemin oluşması\",\"risk\":\"1-Düşme, denge kaybı sonucunda vücut bölümlerinin yaralanması\",\"mevcut_onlem\":\"1-Kliniklerde sabit temizlik çalışanları mevcuttur.\",\"oneri\":\"1-Temizlik işlemi sırasında zemin kurulanmalı temizlik esnasında uyarı tabelaları konulmalıdır.    \\n2- Kaymaya sebep olacak maddelerinin zeminde birikmesi önlenmeli, hemen temizlenmelidir.\\n3- Çalışanlar kaymaz tabanlı ayakkabı giymelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20591\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Basınçlı tüplerin hatalı kullanılması\",\"risk\":\"1- Tüplerin düşmesi, devrilmesi sonucu patlama meydana gelmesi\",\"mevcut_onlem\":\"1-Oksijen tüpü sabitleme aparatları bulunmaktadır.\",\"oneri\":\"1- Oksijen tüplerine yağlı, kremli eller ile temas edilmemeli, vanaları yağlanmamalıdır.                                                                                                                                   2- Tüpler ısı kaynaklarından ve güneşin etkisinden uzak tutulmalıdır.                                                                                                                                    3- Manometreler sağlam olmalı, kırık olanlar değiştirilmelidir.                                       \\n4- Basınçlı tüpler zeminde sabitlenmeden bırakılmamalı, sabitleme aparatlarına takılmalı ve 2 noktadan zincir ya da halatla bağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20592\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-İç bahçelerde açıkta kapaksız prizler bulunması\",\"risk\":\"1-Elektirik çarpması sonucu yaralanma\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.\",\"oneri\":\"1- Su ile temas eden kullanılmayan prizler tamamen kalıdırılmalıdır.\\n2- Dış alanda kullanılacak tüm elektrik sistemleri (aydınlatma priz vb.) etanj özellikte olmalıdır.                 \\n3- İptal edilen prizlerde akım olmadığından emin olunmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20593\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Çalışan giyinme odalarında bench olmaması                           2-Giyinme dolapları ve çalışma alanlarında bulunan dolapların yotalanmamış olması\",\"risk\":\"1- Kişinin düşmesi, kişinin üzerine dolap düşmesi, acil durumlarda tahliyenin zorlaşması\",\"mevcut_onlem\":\"1- Soyunma dolapları mevcuttur.\",\"oneri\":\"1.Soyunma odalarında  yeterli sayıda oturma yeri ve ayakkabılık bulunmalıdır.                                                                     \\n2-Soyunma odalarında bulunan tüm dolaplar, raflar duvara en az iki noktadan  sabitlenmelidir.                                                \\n3-Sabitlenemeyen dolap ya da raflar ise acil kaçış yollarından uzak, kişilerin üzerlerine düşmeyecek biçimde konumlandırılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20594\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- EKT işlemi sırasında çalışanın hastaya teması\",\"risk\":\"1- Elektirik çarpması sonucu yaralanma\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.\",\"oneri\":\"1-EKT işlem hazırlığı sırasında hasta sedyedeki bantlarla stabil hale getirilmelidir.                                                          \\n2- EKT esnasında hastaya elektrotlara ve diğer iletken nesnelere dokunulmamalıdır.\\n2-Hastaya ıslak  ve iletken ortamlarda EKT uygulanmamalı, hastanın göğsünde ıslaklık, jel, ter olmamalı, hastanın göğüsü kurulanmalıdır.\\n4- Hastanın ve EKT cihazını kullanan çalışanın üzerinde metal eşyalar bulunmamalıdır.                                                                                           \\n5- Ortamda bulunan diğer çalışanlar en az 1 metre uzakta bulunmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20595\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Saldırgan davranışta bulunan hastalar\",\"risk\":\"1- Çalışanlara şiddet sonucu yaralanma\",\"mevcut_onlem\":\"1- Yumuşak oda mevcuttur.\",\"oneri\":\"1- Akli dengesi yerinde olmayan ya da saldırgan davranış gösteren hastalar yumuşak oda da tedavi edilmelidir.                                                                                               2- Yumuşak odadaki hastaya tedavi uygulama esnasında güvenlik eşlik etmeli ve çift hemşire ile odada çalışılmalıdır.                                                                                                                                                          3- Hastalar tedavi edilmeden yatağa sabitleyici aparatlar ile bağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20596\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Çalışanların temel iş güvenliği eğitimlerine katılmamaları\",\"risk\":\"1-İş kazası ve meslek hastalıklarının artması\",\"mevcut_onlem\":\"1- Eğitim planı ve eğitim tarihleri çalışanlar ile paylaşılmıştır.\",\"oneri\":\"1-İşe yeni başlayan çalışanlara hastane tehlike sınıfına göre 16 saat temel iş sağlığı güvenliği eğitimi verilmelidir.\\n2-Mevcut çalışanların eğitimleri yılda bir kez tekrarlanmalıdır.\\n3-İş güvenliği eğitimi aldırılmayan kişilere iş başı verilmemelidir.\\n4-İşe yeni başlayan çalışanlara bölüm sorumluları tarafından en az 2 saat iş başı eğitimi verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":40,\"frekans\":1},{\"anahtar\":\"hst-20597\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Kan ve vücut sıvılarının göz ve cilde temas etmesi\",\"risk\":\"1-Temas sonucu enfeksiyon, bulaşıcı hastalıklara yakalanma\",\"mevcut_onlem\":\"1-KKD\'ler mevcuttur.                                         2- Çalışanlara KKD önemi ve kullanımı konusunda eğitim verilmektedir.\",\"oneri\":\"1-Çalışanlar TS EN 455  standardında eldiven, TS EN 166 standardında tam kapalı gözlük ya da yüz siperi, uzun kollu koruyucu önlük  EN 14683 standardında maske vb. gibi kişisel koruyucu donanımlar kullanılmalıdır.                                                                                                                         2- Temas durumunda bölgenin bol su ve sabunla yıkanması sağlanmalıdır.                                                                                                                                    3- Kan ve vücut sıvıları sıçramasına maruz kalma sonrası çalışanın, bulaş kaynağının durumuna göre muayene ve tetkikleri yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20598\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Kesici delici aletlerin emniyetsiz kullanılması\",\"risk\":\"1- Kullanılmış aletlere temas sonucu el kol yaralanmaları, enfeksiyon, bulaşıcı hastalıklara yakalanma\",\"mevcut_onlem\":\"1- Kesici delici alet kutuları mevcttur.                2-Çalışanlara kesici delici aletlerin güvenli kullanımı konusunda eğitim verilmektedir.\",\"oneri\":\"1- Kullanılmış iğne ve kesici aletler, kesici delici alet kutusuna atılmalıdır.                                                                                                                           2- Çalışanlar tedavi tepsisi kullanmalı, iğne kapağı kapatılmadan kesici delici alet kutusuna atılmalıdır.                                                                                                                                 3- Kesici delici alet kutuları en fazla 2/3 dolduğunda yenisi ile değiştirilmeli, kutuların kapakları açık bırakılmamalıdır.                                                                                                                   4-  Kesici delici alet kutuları devrilmeyecek şekilde konumlandırılmalıdır.                                                                                                                                5- Çalışanlar TS EN 455 standardında çift eldiven kullanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20599\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Klima sularının tavandan akması                  2-Klima sularının elektirik ile teması\",\"risk\":\"1-Kayma düşme sonucu yaralanma            2-Elektirik çarpması\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.\",\"oneri\":\"1-Akan yerler onarılmalı zemine su akması ve elektriğin su ile temas etmesi önlenmelidir.                                                                                                                      3-Islak kaygan zemin uyarı levhaları gerekli alanlarda mutlaka kullanılmalıdır.                                                                            \\n4- Alanlar ıslak bırakılmamalı temizlik sonrası mutlaka kurulama yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20600\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- YGAP Genel Hastane arası gidiş gelişte hastane aracı kullanılmaması\",\"risk\":\"İş kazası geçirme\",\"mevcut_onlem\":null,\"oneri\":\"1- Genel hastaneye gidiş geliş esnasında sadece hastane aracı kullanılmalıdır.\\n2- Geliş gidiş esnasında hastane araçları yetkilendirilmiş şoförleri tarafından kullanılmalı, çalışanlar hastane aracını kullanmamalıdır.\\n3- Emniyet kemerleri takılı olmalıdır.\\n4- Araç şoförü trafik kurallarına uymalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20601\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Çalışan hasta ve hasta yakınları iletişim problemleri, fiziksel sözlü şiddet,\",\"risk\":\"1- Hasta ya da yakınları tarafından fiziksel ya da sözlü şiddete maruz kalma sonucu yaralanma,\",\"mevcut_onlem\":\"1-Panik butonları mevcuttur.\",\"oneri\":\"1- Hasta ve hasta yakınları tarafından çalışanların şiddete uğrayabileceği tüm alanlara sabit panik butonları ilave olarak yaka butonları temin edilmelidir.                                                                                                                                                                                                         2- Şiddet riskinin yoğun olduğu alanlarda butonlara ilave olarak sabit güvenlik personeli  bulundurulmalıdır.                                         \\n3- Çalışanlara iletişim, stres yönetimi ve öfke kontrolü ile mesleki bilgi ve becerilerini arttırıcı eğitimler verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20602\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Hasta taşıma veya pozisyon verme sırasında ergonomik olmayan davranışlar\",\"risk\":\"1-Kas-İskelet sistemi rahatsızlıkları, meslek hastalığı veya işle ilgili hastalıklar                                                             2- iş kazaları\",\"mevcut_onlem\":\"1-Çalışanlara Ergonomik çalışma eğitimi verilmektedir.\",\"oneri\":\"1- Hasta taşıma için kaydırma örtüsü, hasta kaldırma lifti, tekerlekli sandalye, sedye gibi ekipmanlar kullanılmalıdır.                                             \\n2- Yatak kenarlıkları kaldırılmalı, frenlerin kilitlenmelidir. Kateter, dren ve monitör bağlantılarının sabitlenmelidir.                                                                                                     3- Hastalara pozisyon verme ve taşıma esnasında en az 2 kişi tarafından yapılmalı, zemin kuru olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20603\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Sabitlenmemiş dolap ve raflar\",\"risk\":\"1-Devrilme, düşme ya da çarpma sonucunda vücut bölümlerinin sıkışması, yaralanması\",\"mevcut_onlem\":\"1-Birçok dolap ve raf sabitlenmiştir.\",\"oneri\":\"1-Sabitlenmemiş doalp ve raflar en az iki noktadan sabitlenmelidir.\\n2-Düşme, devrilme riski olan bütün malzemeler düşmeyecek şekilde sabitlenmelidir.\\n3-Ağır malzeme ve ekipmanlar yüksek istiflenmemeli, dolap üzerine malzeme konulamamlıdır.                                    \\n4- Sabitlenemeyen dolap ve raflar kapılardan uzak, çalışanların üzerine düşmeyecek şekilde konumlandırılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20604\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Makinelerin gövde topraklama ölçümlerinin yapılmamaış olması.                                              2-Yıpranmış, ezilmiş kablolar\",\"risk\":\"1-Elektrik çarpması sonucu kalp ritim bozuklukları, elektrik yanıkları, ölüm,\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.\",\"oneri\":\"1-Makinelerin gövde topraklama ölçümleri yaptırılmalı, belgelendirilmelidir.\\n2-Cihazlar durdurulmadan ve akım kesilmeden bakım, arıza onarım ve müdahaleler yapılmamalıdır.\\n3-Yıpranmış, ezilmiş, soyulmuş ve izolasyonsuz kablolar değiştirilmelidir.                                                                                                                           4- Makikenelerin elektrik kabloları çift izolasyonlu olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20605\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Elektrik panolarının, pano odalarının yangın dolaplarının önlerinin kapatılmış olması\",\"risk\":\"1-Acil durumlarda hızlı müdahalenin sağlanamaması sonucunda durumun etkisinin ve şiddetinin artması\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.\",\"oneri\":\"1- Malzeme, makine, temizlik arabası vb. pano ve  yangın dolaplarının önlerini kapatmaması sağlanmalıdır.\\n2-Panolara erişim için en az 80 cm genişlikte ulaşım yolları sağlanmalıdır.\\n3-Pano üzerlerine uyarı etiket ve işaretleri asılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20606\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1- Elektrik kablolarında yırtık, izolasyon bozukluğu olması,                                                                                   2- Ekli kabloların kullanılması\",\"risk\":\"1-Elektrik çarpması sonucu kalp ritim bozuklukları, ölüm\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.\",\"oneri\":\"1- Elektrik kablolarında yırtık, izolasyon bozlukluğu vb. olmamalı, olan kablolar kullanılmamalı değiştirilmelidir.                          \\n2- Elektrik kabloları ağır malzeme ya da ekipmanların altına konulmamalı, kabloların ezilmesi önlenmelidir.                                       \\n3- Kablolarda olan izolasyon açıklıkları izole bant ile kapatılmamalı, ekli kablolar değiştirilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20607\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: YGAP GENELİ\",\"faaliyet\":null,\"tehlike\":\"1-Sivri, delici, kesici, paslı makine ve ekipmanlar\",\"risk\":\"1-Yaralanma sonucu tetanos hastalığına yakalanma\",\"mevcut_onlem\":null,\"oneri\":\"1-Paslı alet ve ekipmanlar yenileriyle değiştirilmeli, paslanmaz malzemeler kullanılmalıdır.\\n2-Sivri, delici, kesici, paslı makine ve ekipmanlara eldivensiz temas edilmemelidir.\\n3-Yeni başlayan ya da aşısı eksik olan çalışanlara tetanos aşısı yapılmalı, 5 yılda bir ya da yaralanma durumunda tekrar aşı yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20608\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: YEMEKHANE MUTFAK\",\"faaliyet\":null,\"tehlike\":\"1-Yemekhane elektirik panosu önünde yalıtkan paspas olmaması             2-Yemekhane elektirik panosunun kilitsiz olması\",\"risk\":\"1- Elektrik çarpması sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1-Yemekhane içinde bulunan elektrik panosu kaldırılmalıdır.     \\n2- Panoya 30 Ma kaçak akım rölesi takılmalıdır.                                                 \\n3-Elektirik panoları önüne yalıtkan paspas konulmalıdır.                                          4-Elektirik panoları her zaman kilitli olmalı, yetkisiz kişilerin erişimi engellenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20609\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: YEMEKHANE MUTFAK\",\"faaliyet\":null,\"tehlike\":\"1- Mutfaktaki tüm elektirikli ekipmankarın(benmarin,buzdolabı,fırın vb.) topraklama ölçümlerinin tekrarlanmaması\",\"risk\":\"1- Elektirik çarpması sonucu yaralanma\",\"mevcut_onlem\":\"1- Topraklama ölçümleri mevcuttur.\",\"oneri\":\"1- Elektrik tesisatının, panoların, fiş priz sistemlerinin topraklama ölçümleri yıllık olarak yetkili elektrik mühendislerine yaptırılmalıdır.                                                                                                                                                         2- Benmariler dahil tüm elektrikli mutfak ve yemekhane cihazlarının ve taşıma araçlarının gövde topraklama ölçümleri yıllık olarak yaptırılmalı ve kayıt altına alınmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20610\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: YEMEKHANE MUTFAK\",\"faaliyet\":null,\"tehlike\":\"1-Mutfak ve yemekhane personelinin aynı kıyafeti hastane genelinde kullanması\",\"risk\":\"1-Enfeksiyon hastalıklarına yakalanma\",\"mevcut_onlem\":\"1-Yemekhane ve mutfak  personeli önlük, maske ve bone kullanmaktadır.\",\"oneri\":\"1-Yemekhane ve mutfak  personeli  iş kıyafetini ve ayakkabı/terliğini sadece çalışma alanında kullanmalı, bu ekipmanlar ile çalışma alanı dışına çıkılmamalıdır.                                                                                                                                                  2- Yemekhane ve mutfak  personeli önlük bone ve eldiven kullanmadan çalışmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":10},{\"anahtar\":\"hst-20611\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: YEMEKHANE MUTFAK\",\"faaliyet\":null,\"tehlike\":\"1-Yemek dağıtılan alanların kirli olması, yağ birikimi olması\",\"risk\":\"1-Enfeksiyon hastalıklarına yakalanma\",\"mevcut_onlem\":\"1-Ortam temizliği günlük yapılmaktadır.\",\"oneri\":\"1-Paslanmaz tezhgahlar, benmariler ve kullanılan aletler günlük olarak temizlenmelidir.                                                                                                                                                     2-Zemin günlük olarak düzenli temizlenmeli , duvar yüzeyleri haftalık olarak düzenli  temizlenmeli  ve  asma tavan aylık olarak  düzenli temizlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20612\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: YEMEKHANE MUTFAK\",\"faaliyet\":null,\"tehlike\":\"1-Makina ve ekipmanların elektrik aksamına su veya diğer sıvıların temas etmesi\",\"risk\":\"1- Elektrik çarpması                       2-Ölüm\",\"mevcut_onlem\":\"1-Kaçak akım koruma  rölesi mevcuttur.\",\"oneri\":\"1-Mutfakta kullanılan tüm elektrikli aletlerin kabloları çift izalasyonlu olmalıdır.                                        \\n2- Sabit kablolar kablo kanalı içerisine alınmalıdır.                                                                                                         3- Elektrik kabloları sağlam olmalı, ek ya da izole bant ile bantlanmış kısımlar bulunmamalıdır.                                                                                                                                                    4- Elektrikli ekipmanlar su ve kimyasal içerikli ürünlerden uzakta saklanmalı ve kuru elle kullanılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20613\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: YEMEKHANE MUTFAK\",\"faaliyet\":null,\"tehlike\":\"1-Çöp kovalarının açık olması\",\"risk\":\"1-Enfeksiyon\",\"mevcut_onlem\":\"1-Çöp kovaları mevcuttur.\",\"oneri\":\"1-Çöp kovalarının kapağı her daim kapalı olmalı, sineklenme olmayacak şekilde düzenli boşaltılmalıdır.                                                                                                                                      2-Pedalı bozuk olan çöp kovaları onarılmalı veya değiştirilmelidir.                                           3-Atık odalarının kapıları kapalı tutulmalıdır. Kapıya ait hidrolik yay sistemleri sökülmemelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20614\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: YEMEKHANE MUTFAK\",\"faaliyet\":null,\"tehlike\":\"1-Mutfak çalışanlarının  sağlık kontrollerinin yapılmamış olması\",\"risk\":\"1- Bulaşıcı hastalıklar ve salgın hastalıkların diğer çalışanlara bulaştırma\",\"mevcut_onlem\":\"1-Çalışanların işe giriş raporları ve periyodik kontrolleri yaptırılmaktadır.\",\"oneri\":\"1-Mutfak ve yemekhane çalışanlarının 6 ayda 1 portör muayeneleri yapılmalıdır.\\n2- Hepatit taramaları ve akciğer grafileri yılda bir tekrarlanmalıdır.   \\n3- Bölüme yeni başlayan çalışanlar sağlık taramaları yapılmadan işe başlatılmamalıdır.                                                                                                                                                                                                           4-Sonucu uygun olmayanlar çalışanlar mutfak yemekhane bölümünde çalıştırılmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20615\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: YEMEKHANE MUTFAK\",\"faaliyet\":null,\"tehlike\":\"1- Yemekhane zeminde engel bulunması\",\"risk\":\"1- Takılıp düşme sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1-Zemindeki engeller körlenmelidir.                                                        \\n2-Zeminde bulunan engeller etrafına bariyer çekilerek çalışanların takılıp düşmesi önlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20616\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: YEMEKHANE MUTFAK\",\"faaliyet\":null,\"tehlike\":\"1- Hasta yemek dağıtım penceresinde koruyucu bulunmaması\",\"risk\":\"1- Mekanizmanın düşmesi sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Mekanizmanın kendi kendine boşalma riskine karşı tutucu ya da fotosel takılmalıdır.                                                              \\n2- Kaldırma indirme esnasında panelin altına el sokulmamalıdır.\\n3- Kaldırma sisteminin periyodik kontrolleri en geç yılda bir yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20617\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 2: YEMEKHANE MUTFAK\",\"faaliyet\":null,\"tehlike\":\"1-Kuru gıda depolarında haşere ilaçlamasının olmaması\",\"risk\":\"1-Sinek, böcek, fare gibi zararlı canlıların çoğalması ve hastalık yayması\",\"mevcut_onlem\":\"1-Bir çok alanda ilaçlama kutuları mevcuttur.\",\"oneri\":\"1-İlaçlama kutusu olmayan kuru gıda depolarına kutular konulmalıdır.                                                        \\n2- 3 ayda 1 zararlının türüne göre ilaçlama yapılmalıdır.\\n3- Zararlı canlıların yemekhane ve mutfağa ulaşabilecekleri delik ve açıklıklar kapatılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":1},{\"anahtar\":\"hst-20618\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 3: DEPO ECZANE\",\"faaliyet\":null,\"tehlike\":\"1- Narkotik ilaç dolabının cam olması\",\"risk\":\"1- Narkotik ilaçların kullanımı sonucu bağımlılık sakatlık ya da ölüm\",\"mevcut_onlem\":null,\"oneri\":\"1- Narkotik ilaçların bulunduğu dolaplar metal , kitlitlenebilir, çift anahtarlı olmalıdır.        \\n2- Narkotik ilaç dolaplarının üzerinde anahtar bırakılmamalı, anahtarlar bölüm sorumlularına zimmetlenmelidir.                                                                                                                            3- Bölümlere gelen narkotik ilaçlar kayıt altına alınmalı, her vardiya değişiminde sayım yapılmalı, eksik çıkması durumunda yetkililere haber verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20619\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 3: DEPO ECZANE\",\"faaliyet\":null,\"tehlike\":\"1- Raf önü tutucuların bulunmaması                                           2- Endüstriyel rafların sabitlenmemesi\",\"risk\":\"1- Malzeme düşmesi sonucu  yaralanma, ezilme, sıkışma\",\"mevcut_onlem\":\"1-Bazı bölümlerde volanlı ray sistemi mevcuttur.\",\"oneri\":\"1- Tüm arşiv alanlarında volanlı raylı sistem kullanılımalıdır.\\n2- Rafların önüne malzemelerin devrilmesini engelleyecek raf önü tutucular kullanılmalıdır.                                                                    \\n3-  Endüstriyel raflar en az iki noktadan  sabitlenmeli, düşme, devrilme riski olan bütün malzemeler düşmeyecek şekilde sabitlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20620\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 3: DEPO ECZANE\",\"faaliyet\":null,\"tehlike\":\"1- Depolarda yüksek istifleme yapılması\",\"risk\":\"1- Malzeme düşmesi sonucu  yaralanma, ezilme, sıkışma\",\"mevcut_onlem\":null,\"oneri\":\"1- İstif yüksekliği en fazla 3 metre olmalıdır.\\n2- Malzemeler düzenli istiflenmeli, devrilmeyecek şekilde sabitlenerek istif yapılmalıdır.\\n3- Devrilme riski olan malzemeler 1,5 metreden yüksek istiflenmemelidir.\\n4- Stok girişi yapılmayan malzemeler depoya alınmamalıdır.\\n5- Ağır malzemeler en altta istiflenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20621\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 3: DEPO ECZANE\",\"faaliyet\":null,\"tehlike\":\"1- Endüstriyel rafların periyodik kontrollerinin yapılmaması\",\"risk\":\"1- Rafların devrilmesi sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Raflar  TS EN 15635 standartalarına uygun azami kontrol süresi geçmeden periyodik kontrolleri  yapılmalıdır.    \\n2- Metal kısımların dayanıklılık ve metal yorgunluğu testleri yaptırılmalıdır. \\n3- Bağlantı noktaları, çatlak, aşınma, taşıyıcı kısımlar 3 ayda bir kontrol edilmeli, eksiklikler giderilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20622\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 3: DEPO ECZANE\",\"faaliyet\":null,\"tehlike\":\"1- Raflardan malzeme almak için eskoba merdiven ya da el merdiveni kullanılması\",\"risk\":\"1-Merdivenden düşme sonucu yaralanma\",\"mevcut_onlem\":\".\",\"oneri\":\"1- Raflardan malzeme almak için eskoba ya da el merdivenleri kullanılmamalı, TS EN 131 standartlarına uygun merdivenler temin edilmelidir.                                                                                   \\n2- Kullanılacak merdiven en az 1 metre yükseklikte korkuluklu, 47 cm de ara korkuluklu, platformlu, yere sabitlenebilen tekerlek frenleri olan yapıda olmalıdır.  \\n3-Platformlu merdivenlerin giremeyeceği dar raf aralarında kullanılan el merdivenlerinin ayaklarına, merdivenin kaymasnı önlemek için destekler konulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20623\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 3: DEPO ECZANE\",\"faaliyet\":null,\"tehlike\":\"1- Raf arası mesafelerin yetersiz olması\",\"risk\":\"1- Çarpma, sıkışma, düşme sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Raflar arası boşluk en az yaya geçişi için 80 cm, merdiven geçmesi için en az 120 cm olacak şekilde iş organizasyonu yapılmalıdır.                                                  \\n2- Depolama alanı değişikliği yapılmalıdır.\\n3- Raf yerleşim planı hazrılanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20624\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 3: DEPO ECZANE\",\"faaliyet\":null,\"tehlike\":\"1-KKD’lerin eksik olması,                           2- KKD\'lerin çalışanlar tarafından kullanılmaması\",\"risk\":\"1-KKD’lerin kullanılmaması sonucunda iş kazaları, meslek hastalıkları oluması\",\"mevcut_onlem\":null,\"oneri\":\"1-KKD’ler CE belgeli ve ilgili standartlara uygun olmalı, eksik olan kkd\'ler temin edilmelidir.\\n2- Çalışanların maskeleri TS EN149 standardında uygun olmalıdır.                                                                                                                     3-Çalışanların göz koruyucuları TS EN 166 standardına uygun ve tam kapalı tip olmalıdır.                                                                                                                             4-Çalışanların iş eldivenleri TS EN 388 standartına uygun olmalıdır.                                                                                                                                5- Çalışanların iş ayakkabıları, koruyucu burun ve taban TS EN ISO 20345 standartına uygun olmalıdır.\\n6- Çalışanların baretleri TS EN 397 standartına uygun olmalıdır\\n7-Çalışanlar sahada kişisel koruyucu ekipmanlarını eksiksiz şekilde kullanmalıdırlar.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20625\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 3: DEPO ECZANE\",\"faaliyet\":null,\"tehlike\":\"1- Tavan aydınlatmalarına yakın istifleme yapılması\",\"risk\":\"1-Yangın çıkması\",\"mevcut_onlem\":\"1- Yangın söndürme sistemleri mevcuttur.\",\"oneri\":\"1- Aydınlatma armatürleri ile malzemeler arasında 50-100 cm boşluk bırakılmalıdır.                           \\n2- Aydınlatma armatürleri ısı çıkarmyan led aydınlatma ya da etanj aydınlatmalar kullanılmalıdır.\\n3- Yangın söndürücüler her zaman hazırda bulundurulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20626\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 3: DEPO ECZANE\",\"faaliyet\":null,\"tehlike\":\"1- Rafların taşıma kapasitesinin bilinmemesi                                                         2- Raflara hatalı istifleme yapılması\",\"risk\":\"1- Rafların fazla yüklenmesi sonucu devrilmesi\",\"mevcut_onlem\":null,\"oneri\":\"1- Her rafa maksimum taşıma kapasitesi, görünür okunabilir şekilde asılmalıdır.\\n2- Raflara taşıma kapasitesinin %10 altı ağırlıktaki malzemeler istiflenmelidir.\\n3- Yükler raf yüzeylerine eşit dağıtılmalıdır.\\n4- Malzemeler düzenli, devrilmeyecek şekilde istiflenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20627\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 3: DEPO ECZANE\",\"faaliyet\":null,\"tehlike\":\"1- Transpaletlerin periyodik kontrollerinin yapılmaması\",\"risk\":\"1- Yüklerin düşmesi, devrilmesi sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Manuel transpaletlerin periyodik kontrolleri  TS EN ISO 3691 serisi, FEM 4.004 standartlarında belirtilen kriterlere uygun olarak yapılmalıdır.                                                                                                                          2- Periyodik kontrolleri yapılmamış manuel  transpaletler kullanılmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20628\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 3: DEPO ECZANE\",\"faaliyet\":null,\"tehlike\":\"1- Kolilerin, dosyaların el ile taşınması\",\"risk\":\"1-Düşme, devrilme  sonucu yaralanma\",\"mevcut_onlem\":\"1- Çalışanlara elle taşıma teknikleri hakkında eğitim verilmiştir.\",\"oneri\":\"1- Erkekler 25 kg üzerinde kadınlar 15 kg üzerinde yük kaldırmamalıdır.                                                                                   \\n2- Dengesiz devrilme riski olan yükler sabitlenerek taşınmalıdır.\\n3- Yükler taşıma teknikleri kullanılarak taşınmalıdır.\\n4- Yükler görüş alanını kapatmayacak şekilde taşınmalıdır.                                                                                                 5- Depo, eczane ve arşivde çalışan personellere yüksekte çalışma, depolarda uygun istifleme ve ergonomi ve elle taşıma eğitimi verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20629\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 3: DEPO ECZANE\",\"faaliyet\":null,\"tehlike\":\"1- Raflarda sivri köşelerin bulunması\",\"risk\":\"1- Yaralanma                  2- Çarpma\",\"mevcut_onlem\":null,\"oneri\":\"1-Tüm depo , eczane , arşiv alanlarında bulunan rafları köşelerindeki sivri uçlar için köşe koruyucular monte edilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":10},{\"anahtar\":\"hst-20630\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 4: BAHÇE OTOPARK\",\"faaliyet\":null,\"tehlike\":\"1-Otomatik sulama sistemi çalışırken çim aydınlatma armatürlerine su temas etmesi\",\"risk\":\"1-Eletkriğin su ile teması sonucu çarpılma\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.\",\"oneri\":\"1-Çim aydınlatma armatürleri güneş enerjili lamba vb. elektrik kullanmayan sistemler ile değiştirilmelidir.\\n2- Sulama başlıklarının açıları düzeltilmeli,  çim aydınlatma armatürlerine ve kablolarına su  temas etmeyecek şekilde konumlandırılmalıdır.                                                                                                                                                   3- Elektriğin su ile teması önlenmeli, elektrik kabloları çift izolasyonlu olmalıdır.\\n4- Çimlerin etrafı tel çit vb. malzemeler ile çevrelenmeli, insan geçişi önlenmelidir.\\n5- Elektrik ile ilgili uyarı levhaları asılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20631\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 4: BAHÇE OTOPARK\",\"faaliyet\":null,\"tehlike\":\"1-Hastane ve çevresinde yılan vb. sürüngenler çıkması\",\"risk\":\"1-Isırılma, zehirlenme,alerji\",\"mevcut_onlem\":null,\"oneri\":\"1-Hastane çevresinde dış alanda yabancı otlar temizlenmelidir.                                                                                2-Bina çevresinde bina boyunca devam eden boşluk kısımlarda sürüngen için bakanlıktan izinli yapışkan plaka kullanılmalıdır.                                                                                     3-Kapı altlarında yalıtım ve kapı altı fırçası takılması ve sinekliksiz pencerelere sineklik takılmalıdır.                                                                                                                                                                                                                4- Bahçe içerisinde ölü bölge yaratan bitkiler budanmalı ya da ortadan kaldırılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20632\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 4: BAHÇE OTOPARK\",\"faaliyet\":null,\"tehlike\":\"1-Otopark alanına araçların uygunsuz park edilmesi\",\"risk\":\"1-Araçların çalışanlara çarpması sonucu yaralanma                                 2- Acil durumlarda tahliyenin zorlaşması\",\"mevcut_onlem\":\"1-Güvenlik kameraları mevcuttur.\",\"oneri\":\"1- Yol kenarlarına, yaya yollarına park alanı olarak belirlenmemiş alanlara araçların park etmesini önlemek için mantar, bariyer vb. konulmalıdır.  \\n2- Uyarı levhaları artırılmalıdır.   \\n3- Araçlar acil durumlarda tahliyenin rahat sağlanması için çıkış yönünde park etmeleri sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20633\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 4: BAHÇE OTOPARK\",\"faaliyet\":null,\"tehlike\":\"1- Kuru otların bulunduğu alanlarda sigara içilmesi, cam vb. çöplerin atılması\",\"risk\":\"1-Yangın çıkması\",\"mevcut_onlem\":\"1-Çöp ve kuru otların temizliği düzenli aralıklarla yapılmaktadır\",\"oneri\":\"1-Kuru otlar düzenli aralıklar ile temizlenmelidir.\\n2- Cam şişe, izmarit ve yanıcı atıklar  düzenli aralıklarla temizlenmelidir.\\n3-Kuru ot bulunan alanlarda  ″Sigara içilmez- Yangın riski″ uyarı tabelalarının görünür noktalara konulmalıdır.                                               \\n3- Sigara sadece izin verilen alanlarda içilmelidir.  \\n4-Yangına dayanıklı ve kapaklı çöp kutuları sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20634\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 4: BAHÇE OTOPARK\",\"faaliyet\":null,\"tehlike\":\"1-Hız sınırı levhalarının yetersiz olması\",\"risk\":\"1-İş kazası yaşanması sonucu yaralanma\",\"mevcut_onlem\":\"1- Bir çok bölgede hız sınırı levhaları mevcuttur.\",\"oneri\":\"1-Bahçe ve otopark giriş-çıkış noktalarına ve kritik kavşak noktalarına eksik olan alanlara  hız sınır tabelaları yerleştirilmelidir.                                                                                                                         2-Hastane sınırları içinde açık alanlarda 30 km/s geçmemelidir.\\n3- Araç trafiğine yönelik tabelalar (hız sınırı, yönlendirme vb.) Ortalama 2,0 – 2,5 m yüksekliğe asılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20635\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 4: BAHÇE OTOPARK\",\"faaliyet\":null,\"tehlike\":\"1-Peyzaj alanları için kullanılan su deposunun etrafınının çevrili olmaması\",\"risk\":\"1-Su deposuna yetkisiz erişim sonucu iş kazaları yaşanması\",\"mevcut_onlem\":null,\"oneri\":\"1-Sulama deposunun çevresi en az 1,5–2 metre yüksekliğinde tel çit veya bariyerle çevrilmelidir.\\n2-Bakım personeli dışında kimsenin erişemeyeceği şekilde kilitli kapı kullanılmalıdır.\\n3-Çevre güvenliği için uyarı tabelalarının yerleştirilmelidir. Yetkisiz Girmek Yasaktır” ve “Dikkat! Sulama Suyu Deposu” uyarı tabelaları yerleştirilmelidir.\\n4-Gece veya düşük görüş koşullarında riskleri önlemek için yeterli aydınlatma sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":2},{\"anahtar\":\"hst-20636\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 4: BAHÇE OTOPARK\",\"faaliyet\":null,\"tehlike\":\"1-Su tankı dışında sivri ve paslı alanlar bulunması                              2-Su tankının patlamış olması\",\"risk\":\"1- Paslı alanlara temas sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1-Tankın sivri köşelerine yakın olan merdiven köşelerden uzaklaştırılmalıdır.      \\n2-Patlamış olan depo tamir edilmeli ya da değiştirilmelidir.\\n3- Tank boyanmalı, pas korozyon oluşumu önlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":2},{\"anahtar\":\"hst-20637\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 4: BAHÇE OTOPARK\",\"faaliyet\":null,\"tehlike\":\"1-Bahçede ki rögarların tıkanması, kırılması yerinden çıkması\",\"risk\":\"1-Takılma, düşme, kayma, su birikintisi  sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Rögar kapakları  yılda en az 2 kez kontrol edilmeli,  kırık, gevşemiş, yerinden oynamış rögar kapakları değiştirilmelidir.\\n2-Yaprak, toprak, çöp gibi malzemelerle tıkanan mazgallar temizlenmeli, tıkanması önlenmeldir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":2},{\"anahtar\":\"hst-20638\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1- Patlamadan korunma dokümanının olmaması\",\"risk\":\"1- Parlama, patlama yangın meydana gelmesi\",\"mevcut_onlem\":null,\"oneri\":\"1- Patlamadan korunma dokümanı hazırlanmalıdır. \\n2- Patlayıcı ortam oluşabilecek alanlar işaretlenmeli ve patlamadan korunma dokümanında belirlenen zone ‘lara göre kullanılması gereken exproof ekipmanlar temin edilmelidir.\\n3- Patlayıcı ortam oluşabilecek alanlar “EX Patlayıcı Ortam, Ateşle Yaklaşma” vb. levhalar ile işaretlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":40,\"frekans\":3},{\"anahtar\":\"hst-20639\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1- Doğalgaz kazan dairesinde elektrik tesisatlarının exproof olmaması\",\"risk\":\"1-Doğalgaz kaçağı olması durumunda parlama patlama yangın meydana gelmesi\",\"mevcut_onlem\":\"1- Bazı aydınlatmalar exproof özelliktedir.\\n2- Doğal havalandırma sağlanmaktadır.\",\"oneri\":\"1- Flanş, vana pompa vb. doğalgaz boşalma kaynaklarının en az 1 metre yarı çapında bulunan Pano, fiş priz, aydınlatma, gaz dedektörleri, solenoid valf vb. tüm elektrik sistemleri kıvılcım çıkarmayan exproof özellikte olmalıdır.\\n2- Elektrik kabloları çift izolasyonlu olmalıdır.\\n3- Elektrik kabloları açıkta olmamalı, yanmaz kablo kanalları içerisine alınmalıdır.\\n4- Exproof ekipmanların en geç yılda bir kez periyodik kontrolleri TS EN 60079 stanrdardına göre \\\"ATEX\\\" belgeli kişiler tarafından yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":40,\"frekans\":3},{\"anahtar\":\"hst-20640\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1-Doğalgaz ünite kapısının kilitsiz olması                              2-Yangın söndürücü olmaması                            3-Uyarı levhalarının olmaması\",\"risk\":\"1- Yangına müdahale edilememesi sonucu şiddetin artması\",\"mevcut_onlem\":null,\"oneri\":\"1-Doğalgaz ünite kapısı kilitli olmalı, yetkisiz kişilerin tank sahasına girmesi önlenmelidir.           \\n2- Ünite girişine nötralizatör konulmalı, vücuttaki statik elektrik boşaltılmadan ünite içine girilmemlidir.                                                \\n3-Ünite çevresinde en az bir adet 50 kg\'lik  yangın söndürücü (tozlu veya köpüklü) bulundurulmalıdır.                                           \\n4-Ünite çevresine sigara izmariti vb. girmesini önlemek için tabandan 15 cm topukluk yapılmalıdır.\\n5- Ünite çevresine \\\"SİGARA İÇİLMEZ\\\", \\\"ATEŞLE YAKLAŞILMAZ\\\"  vb. uyarı levhaları yerleştirilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":40,\"frekans\":2},{\"anahtar\":\"hst-20641\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1- Mazot tankının sızdırmazlık, katodik koruma ve topraklama ölçümlerinin yapılmaması\",\"risk\":\"1- Parlama, patlama yangın meydana gelmesi\",\"mevcut_onlem\":null,\"oneri\":\"1- Katodik koruma kontrolleri en geç yılda bir yapılmalıdır.\\n2- Mazot tankının yılda en geç bir kez sızdırmazlık testleri yapılmalıdır.\\n2- Borular korozyona karşı korunmalıdır.\\n2- Tank topraklama ölçümleri yılda bir yaptırılmalı, belgelendirilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":40,\"frekans\":2},{\"anahtar\":\"hst-20642\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1- Yangın panel kablolarında yanıcı malzeme kullanılmış olması\",\"risk\":\"1- Yangın durumunda kablonun kopması ya da erimesi sonucu şiddetin artması\",\"mevcut_onlem\":\"1- Yangın algılama sisteminin periyodik kontrolü mevcuttur.\",\"oneri\":\"1- Yangın panel elektrik kabloları FE180 özellikte olmalıdır.\\n2- Yangın paneli elektrik kabloları 180 dakika yangına dayanıklı olmalıdır.\\n3- Elektrik kabloları halojen free özellikte olmalıdır.\\n4- Yangın paneli elektrik kabloları mekanik darbelere karşı korunmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20643\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1-Elektirik pano   odalarının zemininde  açıklık olması           \\n2-Haşere ilaçlama olmaması\",\"risk\":\"1- Haşerelerin elektrik kablolarını kemirmesi sonucu elektrik yangınları meydana gelmesi\",\"mevcut_onlem\":\"1- Bir çok oda da ilaçlama mevcuttur.\",\"oneri\":\"1-Elektrik pano odalarında fare vb. haşerlerin girebileceği açıklıklar kapatılmalıdır.                                                      \\n2- İlaçlama kutusu olmayan pano odalarına kutular konulmalıdır.                                                        2- 3 ayda 1 zararlının türüne göre ilaçlama yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20644\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1-Çalışanların asansörü uygunsuz kullanması\",\"risk\":\"1- Kabin kapısına sıkışma ya da kabin içinde iş kazası yaşanması sonucu yaralanma\",\"mevcut_onlem\":\"1- Asansörlerin kapı fotoselleri mevcuttur.\",\"oneri\":\"1- Çalışanlar asansör kapıları tam açılmadan asansörlere binmemeli ya da inmemelidir.                                                                    \\n2- Kapanma aşamasında ki kapılara el ile müdahale edilmemeli, kapı fotoselleri aktif olmalıdır.                                                                                            \\n3- Asansör kullanılırken sıkışma riski olan elbise çanta vb. malzemelere dikkat edilmeli, kapıdan en az yarım metre uzakta durulmalıdır.                                                                              \\n4- Asansör içinde şakalaşma yapılmamalıdır.                                                                   5- Asansörlere inip binerken yavaş haraket edilmemelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20645\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1- Asansörlerin arızalanması, bozulması\",\"risk\":\"1-Kabinin düşmesi ya da asansörün kat arasında kalması sonucu sıkışma yaralanma, ölüm\",\"mevcut_onlem\":\"1- Asansörlerin kontrol ve bakımları yapılmaktadır.\",\"oneri\":\"1- Asansörlerin arızalanması ya da bozulması durumunda, hemen acil durum ziline basılmalı, acil durum zil sesi tüm katlardan duyulabilecek seviyede olmalıdır.                                                            \\n2- Asansörün kat arasında kalması durumunda, arıza giderilmeden ve kabin kata güvenli tam yanaşmadan asansör içinden kimse indirilmemeli, kimse kendi çabasıyla çıkmaya çalışmamalıdır.                                                                    \\n3- Bozulan asansörlere sadece yetkili kişiler tarafından müdahale edilmelidir.                                                                     4- Bozulan asansörün etrafı yetkililer tarafından çevrenmeli, insanların yaklaşması önlemelidir.                                                                            \\n5- Acil durum zilleri her zaman çalışır durumda olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20646\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1- Elektrik pano odalarında sulu sprink sistemi kullanılması\",\"risk\":\"1- Elektrik çarpması sonucu yaralanma\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.\",\"oneri\":\"1- Elektrik yangınlarında sulu sistemler kullanılmamalıdır.\\n2- Elektrik panolarına FM200, NOVEC 1230 vb. otomatik söndürme sistemleri kurulmalıdır.\\n3- Pano içinde oluşabilecek kıvılcımlar otomatik olarak söndürülmelidir.\\n4- Otomatik söndürme sistemi olmayan pano odalarında karbondioksitli yangın söndürücüler ya da kuru kimyevi tozlu yangın topları bulundurulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20647\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1-Mazot tankı kapısının kilitsiz olması                              2-Yangın söndürücü olmaması                            3-Uyarı levhalarının olmaması\",\"risk\":\"1- Yangına müdahale edilememesi sonucu şiddetin artması\",\"mevcut_onlem\":null,\"oneri\":\"1-Tank kapısı kilitli olmalı, yetkisiz kişilerin tank sahasına girmesi önlenmelidir.                                                           \\n2-Tank çevresinde en az bir adet 50 kg\'lik  yangın söndürücü (tozlu veya köpüklü) bulundurulmalıdır.                                           \\n3-Tank çevresine sigara izmariti vb. girmesini önlemek için tabandan 15 cm topukluk yapılmalıdır.\\n4- Tank çevresine \\\"SİGARA İÇİLMEZ\\\", \\\"ATEŞLE YAKLAŞILMAZ\\\"  vb. uyarı levhaları yerleştirilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":40,\"frekans\":1},{\"anahtar\":\"hst-20648\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1- Çatılarda açıklıklar bulunması\",\"risk\":\"1- Yüksekten düşme sonucu yaralanma\",\"mevcut_onlem\":\"1- Çatıya çıkış kartlı sistem mevcuttur.\",\"oneri\":\"1-Çatıda yüksekten düşmeye sebep olabilecek açıklıklara en az 1 metre yüksekliğinde 47 cm de bir ara bölmeli, 125 kg yüke dayanıklı korkuluk yapılmalıdır.\\n2- Yetkisiz ve görevi olmayan kişiler çatıya çıkmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":40,\"frekans\":1},{\"anahtar\":\"hst-20649\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1- Doğalgaz kazanlarının periyodik kontrollerinin tekrarlanmaması\",\"risk\":\"1-Doğalgaz kaçağı olması durumunda parlama patlama yangın meydana gelmesi\",\"mevcut_onlem\":\"1- Doğalgaz kazanlarının periyodik kontrol raporları mevcuttur.\",\"oneri\":\"1- Doğalgaz kazanlarının periyodik kontrolleri en geç yılda bir kez TS EN 303 TS 430, TS 497, TS EN 14394+A1, TS EN 12828+A1 standartlarına uygun olarak tekrarlanmalıdır.\\n2- Kazanların hidrostatik basınç deneyleri, en yüksek çalışma basıncının 1,5 katı ile yapılmalıdır.\\n3- Doğalgaz kazanının manometreleri her zaman çalışır durumda olmalı, en yüksek çalışma basıncı işaretlenmiş olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":40,\"frekans\":3},{\"anahtar\":\"hst-20650\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1- Doğalgaz kaçakları oluşması\",\"risk\":\"1-Doğalgaz kaçağı olması durumunda parlama patlama yangın meydana gelmesi\",\"mevcut_onlem\":\"1- Doğal havalandırma sağlanmaktadır. \\n2- Kazan dairesi girişinde acil durudurma düğmesi mevcuttur.\",\"oneri\":\"1- Kazan dairesine doğalgaz kaçaklarına karşı havalandırma menfezleri her zaman açık olmalıdır.\\n2- Gaz dedektörleri her zaman aktif ve çalışır durumda olmalıdır.\\n3- Gaz ana vanasının yerini gösteren plaka bina girişinde kolayca görülebilecek bir yere asılmalıdır.\\n4- Kazan dairesi girişine nötralizatör konulmalı, vücuttaki statik elektrik boşaltılmadan ünite içine girilmemlidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":40,\"frekans\":1},{\"anahtar\":\"hst-20651\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1- Asansörlere taşıma kapasitesinin üzerinde insan binmesi\",\"risk\":\"1- Taşıma kapasitesinin aşılması sonucu kabinin düşmesi, yaralanma ölüm\",\"mevcut_onlem\":\"1-Bir çok asansörde taşıma kapasiteleri mevcuttur.\",\"oneri\":\"1 -Asansör taşıma taşıma kapasitesini ve maksimum kişi sayısını gösteren tabela kapılarda ya da kabin içinde görünür ve okunabilir olmalıdır.\\n2-Taşıma kapasitesinin en fazla % 10 altında insan taşınmalı, kapasitenin üzerinde insan taşınmamalıdır.                                                               \\n3- Asansör taşıma kapasitesi aşıldığında asansör sesli uyarı vermeli, kabin kapıları kapanmamalı ve asansör çalışmamalıdır.                                                  \\n4- Kabin içi havalandırmaları her zaman aktif olmalı, kontrol bakımları yapılmaldır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20652\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1- Asansörlerin güvenlik koşullarının yetersiz olması                                                           2- Kullanma talimatlarının aşınmış olması\",\"risk\":\"1- Kabin arasına sıkışma ya da kırık cam kesmesi sonucu yaralanma\",\"mevcut_onlem\":\"1- Asansörlerde akım kesici switchler mevcuttur.\",\"oneri\":\"1- Asansörlerin kapı kanatlarında ki akım kesici switchler her zaman aktif olmalıdır.                                                                    \\n2- Asansör çalışırken veya diğer kattayken kapıların açılmamasını sağlayan sistem her zaman çalışır durumda olmalıdır.                                                                                                         3- Asansör içinde kırık çatlak ayna olmamalı, kırılan ya da çatlayan aynalar hemen değiştirilmeli, asasörlerde kullanılan aynalar kırılmaz özellikte olmalıdır.                                                                                                                                                          4- Asansör katta değilken asansör kapısı el ile açılmaya çalışılmamalı, Acil durumlarda açılması gerekiyorsa  acil durum kilit açma anahtarı kullanılarak açılmalıdır.                                                                          \\n5- Her asansörde okunabilir büyüklükte kullanım talimatı bulunmalı, yıpranan ya da aşınan talimatlar değiştirilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20653\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1- Asansörlerin periyodik kontrollerinin tekrarlanmaması\",\"risk\":\"1-Asansör kabinin  düşmesi sonucu yaralanma, ölüm\",\"mevcut_onlem\":\"1- Asansörlerin AT uygunluk beyanları mevcuttur.\",\"oneri\":\"1- Hastanede bulunan tüm asansörlerin periyodik kontrolleri en geç yılda bir kez TS EN 81-80 standardına göre tekrarlanmalıdır.                                                              2- Hastanede kullanılan tüm asansörler yeşil etikete sahip olmalıdır.                                                                                                      3- Asansör periyodik kontrolleri akredite olan A1 muayene kuruluşları ve ekipnete kayıtlı yetkili makine mühendisleri tarafından yapılmalıdır.                                                                                                                                                                4- Periyodik kontrol raporlarında uygunsuzluk tespit edilirse, uygunsuzluklar giderilene kadar asansörler kullanılmamalıdır.                                                                    5- Aylık kontrol ve bakımlar düzenli olarak tekrarlanmalı, sonuçlar belgelenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20654\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1- Doğalgaz kazanı işleten çalışanın mesleki yeterlilik belgesinin olmaması\",\"risk\":\"1- Yanlış işletim sonucu patlama, yangın meydana gelmesi\",\"mevcut_onlem\":null,\"oneri\":\"1- Kazanı işleten çalışanların sıcak su kazan operatörü mesleki yeterlilik belgeleri bulunmalıdır.\\n2- Kazanı yalnızca mesleki yeterliliğe sahip olan çalışanlar işletmelidir.\\n3- Kazan kullanım talimatlarına, üreticinin tavsiyelerine uyulmalıdır.\\n4- Kazan dairesine yetkisiz kişilerin ulaşımı engellenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":1},{\"anahtar\":\"hst-20655\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1- Elektrik tesisatının, topraklamaların, kaçak akım rölelerinin, yangın rölelerinin periyodik kontrollerinin tekrarlanmaması\",\"risk\":\"1- Elektrik çarpması sonucu yaralanma\\n2- Elektrik yangınları  meydana gelmesi\",\"mevcut_onlem\":\"1- Periyodik kontroller mevcuttur.\",\"oneri\":\"1- Elektrik tesisatının, topraklamaların, kaçak akım rölelerinin, yangın rölelerinin periyodik kontrolleri TS EN 60079 serisi, TS HD 60364-4 serisi, TS HD 60364-5 Serisi, TS HD 60364-6 standartlarına uygun olarak en geç yılda bir kez tekrarlanmalıdır.\\n2- Her elektrik panosu için ayrı test ve ölçüm yaptırılmalıdır.\\n3- Tüm bakım ve kontroller kayıt altına alınmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20656\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1- Elektrik panolarının kilitsiz olması\\n2- Pano altlarında yalıtkan paspas bulunmaması\",\"risk\":\"1- Elektrik çarpması sonucu yaralanma\",\"mevcut_onlem\":\"1-Pano odalarına giriş kartlı sistemdir.\\n2- Kaçak akım röleleri mevcuttur.\",\"oneri\":\"1- Elektrik panoları kilitli olmalıdır.\\n2- Elektrik panolarının altlarına yalıtkan paspas konulmalıdır.\\n3- Pano odalarına girişte kartlı sistem her zaman çalışır durumda olmalı, yetkisiz kişilerin pano odalarına girmesi önlenmelidir.\\n4- Elektrik ile ilgili yapılan çalışmalarda TS EN 50321 standardında yalıtkan ayakkabı kullanılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":1},{\"anahtar\":\"hst-20657\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1- Hidroforların zemine sabitlenmemesi\\n2- Manometrelerin en yüksek çalışma basıncını göstermemesi\",\"risk\":\"1- Hidroforların patlaması sonucu yaralanma\",\"mevcut_onlem\":\"1- Hidroforların periyodik kontrol raporları mevcuttur.\",\"oneri\":\"1- Hidroforlar zemine sabitlenmelidir.\\n2- Hidroforların manometreleri sağlam olmalı en yüksek çalışma basınçları işaretli olmalıdır.\\n3- Manometreler TS EN 837 standartına uygun olmalıdır.\\n4- Manometrelerin kalibrasyonları yapılmalı, sapma bulunan, bozuk, kırık manometreler değiştirilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":1},{\"anahtar\":\"hst-20658\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1- Seksiyonel kapıların periyodik kontrollerinin tekrarlanmaması\",\"risk\":\"1-Kapının düşmesi sonucu vücut bölümlerinin ezilmesi, yaralanma\",\"mevcut_onlem\":\"1- Fotosel tertbitatı mevcuttur.\",\"oneri\":\"1- En geç yılda bir kez kaldırma sisteminin periyodik bakımları yetkili kişilerce TS EN 13241+A2, TS EN 12453, TS EN 12604+A1 standartlarına uygun olarak periyodik bakımları tekrarlanmalıdır.\\n2- Arıza durumlarında hemen arıza giderilmeli, onarım yapılmadan kapı kullanılmamalıdır. \\n3-Kapı indirilip kaldırılırken 1 metreden yakın içeride ve dışarıda hiç kimse bulunmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20659\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1- Mazot tankı nefesliklerin tıkanması\",\"risk\":\"1- Parlama, patlama yangın meydana gelmesi\",\"mevcut_onlem\":null,\"oneri\":\"1-Tankın bulunduğu alandaki nefeslikler düzenli aralıklarla kontrol edilmeli ve bakımları yapılmalıdır,tıkanması önlenmelidir.\\n2- Nefeslikler tank doldurulurken doldurma ağzında buhar veya sıvı geri tepmesini önleyecek yeterli kapasitede olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20660\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1- Elektirik odası duvarlarında nem oluşması\",\"risk\":\"1- Elektrik çarpması sonucu yaralanma\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.\",\"oneri\":\"1-Sızıntı kaynağı (boru,vana,bağlantı,hidrofor gövdesi) tespit edilmelidir.                                                               \\n2-Sızdıran bölge  izolasyon malzemeleriyle onarılmalıdır.            \\n3-Duvar ve zeminde su geçirmez kaplama yapılmalıdır.                                                                                             4-Elektiriğin su ile teması önlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20661\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1-Sprinklerin periyodik kontrollerinin tekrarlanmaması\",\"risk\":\"1-Yangının söndürülememesi sonucunda şiddetin artması\",\"mevcut_onlem\":\"1-Bakımları periyodik olarak yapılmaktadır.\",\"oneri\":\"1-Sprinkler sisteminin aylık(görsel, fonksiyonel) kontrolleri yapılmalıdır.                                                                                                                                                                                                                                     3-Yılda 1 (TS EN 12845 standartları) olarak yapılmalıdır.                                                                                   \\n4-Sprinkler başlıkları, boru hatları ve vanalar kontrol edilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20662\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1-Yangın tüpünün kontrollerinin tekrarlanmaması\",\"risk\":\"1-Yangının söndürülememesi sonucunda şiddetin artması\",\"mevcut_onlem\":\"1-Tüpler mevcuttur.\",\"oneri\":\"1-Tüplerin ayda bir kontrolü yapılmalıdır.                                                          \\n2-En geç yılda bir kez TS ISO 11602-2 standardına uygun olarak periyodik kontrolleri tekrarlanmalıdır.                                                                             \\n3- 4 yılda bir hidrostatik basınç testi  göre yapılmalı, içindeki malzeme değiştirilmelidir.                                                                                                                                                                                                      4-Bakıma alınan yangın söndürme cihazın yerine, kullanıma hazır yangın söndürme cihazı bırakılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20663\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1-Yangın dolabının kontrollerinin tekrarlanmaması\",\"risk\":\"1-Yangının söndürülememesi sonucunda şiddetin artması\",\"mevcut_onlem\":\"1-Yangın dolapları mevcuttur.\",\"oneri\":\"1-Dolap, hortum makarası, hortum ve vanalar aylık kontrolleri yapılmalıdır.                                                                                                        2-En geç yılda bir kez TS EN 671-3 standardına göre periyodik kontrolleri tekrarlanmalıdır.\\n3- Arıza tespit edildiğinde hemen bakım veya onarım yapılmalı, techizatın her zaman hazır durumda olması sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20664\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1-Yangın kontrol panelinin arızalanması\",\"risk\":\"1-Yangının zamanında fark edilememesi sonucu şiddetin artması\",\"mevcut_onlem\":\"1-Sistem kontrolleri yapılmaktadır.\",\"oneri\":\"1- Otomatik çalıştırma sistemi (sensörler, kontrol panosu, röleler)  yılda 1 kez TS 54-14 e göre  periyodik kontrolleri yapılmalıdır.\\n2- Günlük bakımları yapılmalı arıza veya gecikme tespit edilirse yetkili teknik çalışanlar tarafından onarım yapılmalıdır.\\n3- Sistemdeki yazılım ve elektronik bileşenlerin güncel ve doğru çalıştığı günlük olarak kontrol edilmelidir.\\n4-Arıza tespit edilmesi durumunda sistem durdurulmamalı, manuel devreye alma prosedürleri uygulanmalı ve arıza kaydı oluşturulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20665\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1-Gazlı söndürme sistemlerinde manometre, kontrol paneli  arızası\",\"risk\":\"1-Yangına müdahale edilememesi sonucu şiddetin artması\",\"mevcut_onlem\":\"1-Manometre veya basınç göstergesi mevcuttur.\",\"oneri\":\"1- Manometre ve basınç göstergeleri yılda bir kez TS EN 837 kontrol edilmeli, doğru ölçüm yapmadığı tespit edilen cihazlar yetkili teknik çalışan tarafından onarılmalı veya değiştirilmelidir.\\n2- Kontrol paneli ve elektrik bağlantıları günlük gözle ve fonksiyon testleri ile kontrol edilmeli, arıza tespit edilirse yetkili teknik personel tarafından onarılmalıdır.\\n3- Paneldeki yazılım ve programlamalar güncel ve doğru çalışır durumda olmalıdır; gerektiğinde yeniden yükleme veya güncelleme yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20666\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1- Faraday kafesinin periyodik kontrollerinin yapılmaması\",\"risk\":\"1-Yıldırım düşmesi sonucunda yaralanma, yangın\",\"mevcut_onlem\":\"1- Paratoner tesisatının periyodik kontrolü mevcuttur.\",\"oneri\":\"1-Paratoner tesisatının periyodik kontrolleri TS EN 62305 standardına göre yılda en az 1 kez tekrarlanmalı ve belgelendirilmeldir.                                                                                                     2-Faraday kafesi içinde, civatalarda ve Franklin çubuklarında paslı ve korozyonlu alan bulunmamalıdır.                                                                                                                                                       3- Paratoner topraklaması bina topraklaması ile eşpotansiyel olmalıdır.                                                                                                                  4-Topraklama tesisinin direnci en fazla 10 ohm olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20667\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1- Hidroforların periyodik kontrollerinin tekrarlanmaması\",\"risk\":\"1- Hidroforların patlaması sonucu yaralanma\",\"mevcut_onlem\":\"1- Hidroforların periyodik kontrol raporları mevcuttur.\",\"oneri\":\"1- Hidroforların periyodik kontrolleri TS 1203 EN 286-1, TS EN 13445-5, TS EN 764-7 standartlarında belirtilen kriterlere uygun olarak tekrarlanmalıdır.\\n2- Hidroforların emniyet ventilleri, check valf vb. güvenlik sistemleri çalışır durumda olmalıdır.\\n3- Hidroforların  hidrostatik basınç deneyleri, en yüksek çalışma basıncının 1,5 katı ile yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":1},{\"anahtar\":\"hst-20668\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1- Hastane içerisinde kartlı sistemin çalışmaması, arızalanması\",\"risk\":\"1- Hastaların kaçma teşebbüsünde bulunması sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Kartlı kapıların manyetik sistemleri bozulduğun da hemen onarılmalıdır.                                    \\n2- Arızalı kapılar onarılana kadar hastalar başka güvenlikli bir odaya alınmalıdır.\\n3- Çalışanların yaka butonları bulunmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20669\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1- Havalandırma sisteminin periyodik kontrollerinin tekrarlanmaması\",\"risk\":\"1-Zararlı partiküllerin solunması sonucunda meslek hastalıklarının oluşması\",\"mevcut_onlem\":\"1- Havalandırma sisteminin periyodik kontrolleri mevcuttur.\",\"oneri\":\"1- Havalandırma sisteminin periyodik kontrolleri havalandırma tesisat projesinde yer alan kriterlere göre en geç yılda bir tekrarlanmalıdır. \\n2- Hava değişim sayısı ölçümleri yaptırılmalıdır.\\n3- Otomatik sıcaklık, nem izleme sistemleri bulunmalı, çalışır durumda olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20670\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1- Mazot tankının aşırı doldurulması\",\"risk\":\"1- Parlama, patlama yangın meydana gelmesi\",\"mevcut_onlem\":null,\"oneri\":\"1-Tankın aşırı dolum alarm sistemi, seviye göstergesi periyodik olarak kontrol edilmelidir.\\n2- Tank doldurulurken  sıvı seviyesi tank kapasitesinin %85 e ulaşınca  duyulabilir şiddette sesli alarm vermeli, sıvı seviyesi tank kapasitesinin  %90 a ulaşınca akışı kesen sistemler her zaman aktif olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":40,\"frekans\":1},{\"anahtar\":\"hst-20671\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1-Mazot tankına ikmal yapılırken güvenlik önlemlerinin alınmaması\",\"risk\":\"1- Parlama, patlama yangın meydana gelmesi\",\"mevcut_onlem\":null,\"oneri\":\"1- Tanka dolum yapmadan önce aracın egzoz çıkışına alev tutucu takılmalı, tanka ikmal başlatılmadan önce de aracın tekerleklerine her iki yönde takoz konulmalı ve araç topraklanmalıdır. İkmal süresince topraklama işlemine devam edilmelidir.\\n2- İkmale başlanmadan önce tankerin motoru durdurulmalı, tüm elektrik aksamı kapatılmalıdır.\\n3- Dolum yapan çalışanlar anti statik kkd’ler kullanmalı, kullanılan tüm ekipmanlar ve çalışanlar statik elektriğe karşı topraklanmalıdır.\\n4- Aşırı akış kesme sistemleri aktif olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":40,\"frekans\":1},{\"anahtar\":\"hst-20672\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 5: TEKNİK MAHALLER\",\"faaliyet\":null,\"tehlike\":\"1- Kazan dairesi sıcak yüzeyler olması\",\"risk\":\"1-Sıcak yüzeylere temas sonucu yaralanma\",\"mevcut_onlem\":\"1- Sıcak yüzeyler izole edilmiştir.\",\"oneri\":\"1- Sıcak yüzeylere uyarı etiket ve işaretler konulmalıdır.\\n2- Kazan soğumadan sıcak yüzeylere temas edilmemelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":1}]', 0, 0, NOW(), NOW()
FROM `users` u WHERE u.`email` = 'mozdemir2816@gmail.com' AND NOT EXISTS (SELECT 1 FROM `risk_sablonlari` s WHERE s.`user_id` = u.`id` AND s.`ad` = 'Hastane — Birim: YGAP');

INSERT INTO `risk_sablonlari` (`user_id`, `ad`, `sektor`, `sektor_adi`, `yontem`, `maddeler`, `paylasildi`, `kullanim_sayisi`, `created_at`, `updated_at`)
SELECT u.`id`, 'Hastane — Birim: ACİL DURUMLAR', 'saglik', NULL, 'fine_kinney', '[{\"anahtar\":\"hst-20673\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL DURUMLAR\",\"faaliyet\":null,\"tehlike\":\"1- Sabotaj oluşması\",\"risk\":\"1- Sabotaj sonucu yaralanma, ölüm\",\"mevcut_onlem\":\"1- Güvenlik personelleri mevcuttur.                                   2- Kamera sistemleri mevcuttur.                            3-Tehlikeli alanlara yetkisiz giriş yapılamamaktadır.\",\"oneri\":\"1- Hastanenin tüm girişlerine silah bıçak vb. tehlike oluşturabilecek şüpheli nesnelerin fark edilebilmesi için xray cihazı konulmalıdır. \\n2- Hastaneye giren herkesin xray cihazından geçmesi sağlanmalıdır.(Hamile, kalp pili olan kişiler vb. özel durumu olanlar hariç)\\n3- Xray cihazı konulamayan tüm girişlerde güvenlik personeli bulundurulmalı ve dedektör ile üst araması yapılmalıdır. \\n4- Xray cihazından geçemeyen özellikli kişilere dedektör ile üst araması yapılmalıdır.\\n5-Yapılan eğitim ve tatbikatlarla çalışanlar, sabotajlara karşı korunma konularında bilinçlendirilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":40,\"frekans\":6},{\"anahtar\":\"hst-20674\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL DURUMLAR\",\"faaliyet\":null,\"tehlike\":\"1- Parlama patlama meydana gelmesi\",\"risk\":\"1-Vücut bölümlerinin yaralanması, uzuv kayıpları, ölüm\",\"mevcut_onlem\":null,\"oneri\":\"1-Patlamadan korunma dokümanı hazırlanmalıdır.\\n2- Patlayıcı ortam oluşabilecek alanlar işaretlenmeli ve patlamadan korunma dokümanında belirlenen zone ‘lara göre kullanılması gereken exproof ekipmanlar temin edilmelidir.\\n3- Doğlagaz kullanılan alanlarda tüm fanlar ve havalandırma motorları exproof özellikte olmalıdır. \\n4-Exproof ekipmanların periyodik kontrolleri TS EN 60079 standartına göre ATEX belgeli kişiler tarafından en az yılda bir kez yapılmalı, belgelendirilmelidir.\\n5-Patlayıcı ortam oluşabilecek alanlar “EX Patlayıcı Ortam, Ateşle Yaklaşma” vb. levhalar ile işaretlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":40,\"frekans\":3},{\"anahtar\":\"hst-20675\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL DURUMLAR\",\"faaliyet\":null,\"tehlike\":\"1-Yangın durumunda acil durum asansörleri dışında diğer asansörlerin çalışması\",\"risk\":\"1- Yangına dumanına maruz kalma sonucu boğulma\",\"mevcut_onlem\":\"1- Asansörler yangın algılama sistemine bağlıdır.\",\"oneri\":\"1-Asansörlerin, yangın uyarısı aldıklarında kapılarını açmadan doğrultuları ne olursa olsun otomatik olarak acil çıkış katına dönmelidir. \\n2-Asansörler acil çıkış katına geldiklerinde bir daha çalışmamalıdır. \\n3-Asansör boşluğuna ve bina içine duman dolmasını önlemek için asansörlerin önlerine duman perdeleri takılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":40,\"frekans\":6},{\"anahtar\":\"hst-20676\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL DURUMLAR\",\"faaliyet\":null,\"tehlike\":\"1-Yangın esnasında acil durum asansörlerinde ve acil çıkış merdivenlerinde  duman birikmesi\",\"risk\":\"1- Yangına dumanına maruz kalma sonucu boğulma\",\"mevcut_onlem\":\"1-Acil durum asansör kuyuları basınçlandırılmıştır\",\"oneri\":\"1- Yangın esnasında acil durum asansörler kuyularının ve acil çıkış merdivenlerinin basınçlandırmaları aktif olmalıdır. \\n2- Basınçlandırma sistemi çalıştığı zaman, bütün kapılar kapalı iken asansör kuyusu ve acil çıkış merdivenlerinin hastane kullanım alanları arasındaki basınç farkı en az 50 pa, kapılar açık iken basınç farkı en az 15 pa olmalıdır. \\n3- Basınçlandırma sistemlerinin periyodik kontrolleri en geç yılda bir kez TS EN 12101-6 standartına göre yapılmalıdır. \\n4- Acil durum asansörleri işaretlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":40,\"frekans\":6},{\"anahtar\":\"hst-20677\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL DURUMLAR\",\"faaliyet\":null,\"tehlike\":\"1- Yangın meydana gelmesi\",\"risk\":\"1-Vücut bölümlerinin yaralanması, uzuv kayıpları, ölüm\",\"mevcut_onlem\":\"1- Yangın söndürme ve algılama ihbar sistemleri mevcuttur.\",\"oneri\":\"1- İtfaiye raporu alınmalıdır.\\n2-Yangın söndürme tüplerinin, sprinklerin, yangın hortumlarının, yangın alarmlarının, duman algılama dedektörlerinin, yangın panellerinin, yangın pompalarının vb. yangın söndürme ile ilgili tüm tesisatların periyodik kontrolleri, risk değerlendirmesinin yangın söndürme sistemleri bölümünde belirtilen standartlara ve sürelere göre periyodik kontrolleri tekrarlanmaldır.\\n 3-Yangın teçhizatlarının her an göreve hazır bulunması sağlanmalıdır.\\n4-Hastane de kapalı alanlarda sigara içilmesi yasaklanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":40,\"frekans\":6},{\"anahtar\":\"hst-20678\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL DURUMLAR\",\"faaliyet\":null,\"tehlike\":\"1-Acil çıkış kapılarında bulunan manyetik tutucuların yangın ya da deprem anında çalışmaması, iptal edilmesi\",\"risk\":\"1-Tahliyenin gecikmesi sonucu yaralanma, ölüm\",\"mevcut_onlem\":\"1- Acil çıkış kapıları yangın algılama sistemine bağlı ve acil durumlarda otomatik olarak açılmaktadır.\",\"oneri\":\"1- Acil çıkış kapılarında bulunan manyetik tutcuların en az ayda bir bakım ve kontrolleri yapılmalı, sismik sensörlerin ve yangın algılama ve ihbar sistemlerinin sürekli çalışır durumda olması sağlanmalıdır. \\n2- Manyetik tutucular çalışanlar tarafından iptal edilmemeli, iptal edilen manyetik tutucular tekrar aktif hale getirilmelidir.\\n3- Manyetik tutucu bulunan acil çıkış kapıları sürekli olarak açık bırakılmamalı, önlerine malzeme bırakılmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":40,\"frekans\":2},{\"anahtar\":\"hst-20679\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL DURUMLAR\",\"faaliyet\":null,\"tehlike\":\"1-Sığınakların depo alanı olarak kullanılması\",\"risk\":\"1- Acil durumlarda sığınakların kullanılamaması sonucu yaralanma\",\"mevcut_onlem\":\"1- Hastane de sığınak alanları mevcuttur.\",\"oneri\":\"1- Hastane de sığınak olarak belirlenmiş alanlar depolama alanı olarak kullanılmamalı, sığınaklarda ki malzemeler boşaltılmalı, sığınak olarak hazır hale getirilmelidir. \\n2- Sığınaklar da mekanik havalandırma sistemleri ve filtrelerinin yılda bir periyodik kontrolleri tekrarlanmaldır.\\n3- Sığınaklara kesintisiz güç sağlayan jeneratörlerin her zaman çalışır durumda olması sağlanmalı, yıllık periyodik kontrolleri tekrarlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20680\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL DURUMLAR\",\"faaliyet\":null,\"tehlike\":\"1-Salgın hastalıklar\",\"risk\":\"1- Salgın hastalıkların yayılması sonucu, hastalıklara yakalanma\",\"mevcut_onlem\":\"1-Kişisel koruyucu ekipmanlar mevcuttur.\",\"oneri\":\"1- Salgın hastalıkların yayılabileceği alanlarda havalandırma sistemleri hepa filtreli olmalı ve hepa filtrelerin değişimleri en geç yılda bir yapılmalıdır.\\n2- Salgın hastalığın yayılabileceği bölümlerde izolasyon önlemleri arttırılmalıdır.\\n3-Gerekli durumlarda ziyaretçi kısıtlaması getirilmeli ya da tamamen yasaklanmalıdır.\\n4- Riskli birimlerde profesyonel dezenfeksiyon işlemi uygulanmaldır. \\n5-Semptom gösteren çalışanlar teste tabi tutulmalı, sonuçlar çıkana kadar işten uzaklaştırılmaldır. \\n6- Çalışanlar N95, ffp2 vb. maskeler, yüz siperleri, tulum, eldiven kullanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20681\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL DURUMLAR\",\"faaliyet\":null,\"tehlike\":\"1- Kimyasal sızıntısı\",\"risk\":\"1- Kimyasal maddeye ya da buharına maruz kalma sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Hastane de tehlikeli kimyasallar için depo yapılmalıdır.\\n2-Kimyasal maddelerin dökülme riskine karşı taşma kapları temin edilmelidir.\\n3-Kimyasal döküntü kitleri temin edilmeli, çalışma ortamına yayılması önlenmelidir. \\n4- Yüksek miktarda döküntülerde havalandırma sistemi kapatılmalı, kimyasal madde buharının diğer bölümlere yayılması önlenmeli, gerekirse çalışanlar ortam tamamen kimyasaldan arındırılana kadar tahliye edilmelidir.\\n5- Yetkili ve eğitimli kişiler tarafından koruycu tulum, maske, gözlük, eldiven ve çizme giyerek bulaş olan bölüm emici malzemeler ile temizlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20682\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL DURUMLAR\",\"faaliyet\":null,\"tehlike\":\"1- Acil durum ekiplerinin belirlenmemiş olması\",\"risk\":\"1- Acil durumlarda müdahale yapılamaması sonucu yaralanma, ölüm\",\"mevcut_onlem\":null,\"oneri\":\"1-Hastane de acil durum ekipleri oluşturulmalıdır.\\n2- Çalışan sayısına göre 30 kişi de 1 kişi yangınla mücadele, arama kurtarma, koruma konularında görevlendirilmeli, 10 kişi de 1 kişi ilk yardımcı olarak görevlendirilmelidir. \\n3- Afad, İtfaiye vb. kurumlardan acil durum ekiplerine özel eğitim aldırılmalıdır.\\n4- Acil durum ekiplerinde görevlendirilen kişilerin işten ayrılması vb. durumlarda yerine yeni kişiler görevlendirilmeli ve özel eğitime tabi tutulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20683\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL DURUMLAR\",\"faaliyet\":null,\"tehlike\":\"1- Elektrik yangını meydana gelmesi\",\"risk\":\"1- Elektrik çarpması sonucu yaralanma\",\"mevcut_onlem\":\"1- 30 MA kaçak akım röleleri mevcuttur.\",\"oneri\":\"1- Elektrik yangınlarında sulu sistemler kullanılmamalıdır.\\n2- Elektrik panolarına FM200, NOVEC 1230 vb. otomatik söndürme sistemleri kurulmalıdır.\\n3- Pano içinde oluşabilecek kıvılcımlar otomatik olarak söndürülmelidir.\\n4- Otomatik söndürme sistemi olmayan pano odalarında karbondioksitli yangın söndürücüler ya da kuru kimyevi tozlu yangın topları bulundurulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20684\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL DURUMLAR\",\"faaliyet\":null,\"tehlike\":\"1-Şiddetli rüzgâr fırtına\",\"risk\":\"1-Fırtına, rüzgâr sırasında elektrik tellerinin kopması, totemlerin veya dış cephe kaplamalarının devrilmesi, yüksekten düşme\",\"mevcut_onlem\":\"1-Totemler betona sabitlenmiştir.\",\"oneri\":\"1-Totemlerin taşıyıcı sistemlerinin şiddetli rüzgar deprem vb. yüklerine karşı taşıma kapasitesinin yeterli olup olmadığı statik uygunluk kontrolü yetkili inşaat mühendislerine yaptırılmalıdır. \\n2-Totemler düzenli aralıklarlar ile korozyon, pas oluşumu, ankraj noktalarında çatlak ve bağlantı gevşemesine karşı kontrol edilmeli, Totemlerin korozyon ve paslanmış kısımları boyanmalı, çatlak ve bağlantı gevşemesi olan yerler onarılmalıdır.\\n3- Bina dış cephe kaplamaları sağlam ve düşmeyecek yapıda olmalıdır.\\n4-Şiddetli rüzgâr anında çalışanlar kapalı bölgelerde bulunmalı, ağaç, elektrik direği, bayrak direği  vb. devrilebilecek  alanlardan uzakta durulmalıdır.\\n5-Şiddetli rüzgârlı havalarda yüksekte çalışma yapılmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20685\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL DURUMLAR\",\"faaliyet\":null,\"tehlike\":\"1- Acil durum tatbikatlarının yapılmaması ya da eksik yapılması\",\"risk\":\"1- Acil durumlarda müdahale yapılamaması sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1-Yıllık tatbikat planı hazırlanmalıdır.\\n2- Acil durum eylem planının uygulama adımlarının düzenli takip edilebilmesi ve uygulanabilirliğinden emin olunması için yangın, deprem, kimyasal döküntü, radyoaktif sızıntı vb. konularda yıllık olarak belirli aralıklar ile haberli ve habersiz tatbikatlar yapılmalıdır.\\n3- Tatbikatlara tüm çalışanların katılımı sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20686\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL DURUMLAR\",\"faaliyet\":null,\"tehlike\":\"1-Deprem meydana gelmesi\",\"risk\":\"1-Göçük altında kalma, ağır yaralanmalar, ölüm, yangın çıkması\",\"mevcut_onlem\":\"1- Ana bina da sismik izalotör bulunmaktaıdır.\",\"oneri\":\"1-Hastane de tam donanımlı afet konteynırı bulundurulmalıdır.\\n2-Hastane genelinde tüm dolap ve raflar sabitlenmeli, düzensiz istifleme yapılmamalıdır.\\n3-Deprem sırasında enerjinin kesilmesi gereken makine ve ekipmanların listesi hazırlanmalı ve güncel tutulması sağlanmalıdır.\\n4- Deprem sırasında yapılacaklar ve hareket tarzı ile ilgili tüm çalışanlara eğitim verilmeli ve yılda bir deprem tatbikatı yaptırılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":0.5,\"siddet\":40,\"frekans\":6},{\"anahtar\":\"hst-20687\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL DURUMLAR\",\"faaliyet\":null,\"tehlike\":\"1-Yıldırım düşmesi\",\"risk\":\"1-Yıldırım düşmesi sonucunda ağır yaralanmalar ölüm, yangın\",\"mevcut_onlem\":\"1-Faraday kafesi mevcuttur.\",\"oneri\":\"1-Paratoner tesisatının periyodik kontrolleri TS EN 62305 standardına göre yılda en az 1 kez tekrarlanmalı ve belgelendirilmeldir.\\n 2-Faraday kafesi içinde, civatalarda ve Franklin çubuklarında paslı ve korozyonlu alan bulunmamalıdır.\\n3- Paratoner topraklaması bina topraklaması ile eşpotansiyel olmalıdır.\\n4-Topraklama tesisinin direnci en fazla 10 ohm olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20688\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL DURUMLAR\",\"faaliyet\":null,\"tehlike\":\"1- Radyoaktif sızıntı\",\"risk\":\"1-Radyoaktif maddelere ya da buharına temas sonucu yaralanma, hastalık meydana gelmesi\",\"mevcut_onlem\":null,\"oneri\":\"1-Radyoaktif sızıntı olması durumunda sızıntı olan bölüm boşaltılmalı, en az 10 metre çevre bariyeri kurulmalı, havalandırma sistemi kapatılmalıdır.\\n2- Yetkili ve eğitimli kişiler tarafından koruycu tulum, maske, gözlük, eldiven ve çizme giyerek bulaş olan bölüm emici malzemeler ile temizlenmelidir.\\n 3- Radyoaktif atıklar, radyoaktif atık yönetim prosedürüne göre kaldırılmalıdır.\\n4- Dozimetre ile ortamdaki radyasyon ölçülmeli, sonuçlar normal seviyeye inene kadar ölçüme devam edilmelidir.\\n5- Bulaş olan kişiler acil servise yönlendirilmeli, izole odalarda yetkili ve eğitimli kişiler tarafından kişisel koruyucu ekipman kullanarak, giysileri çıkarılmalı, bulaş olan kişiler ılık su ve sabun ile  yıkanmalı, sağlık durumları gözlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20689\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: ACİL DURUMLAR\",\"faaliyet\":null,\"tehlike\":\"1-Sel, su baskını meydana gelmesi\",\"risk\":\"1-Vücut bölümlerinin yaralanması\",\"mevcut_onlem\":null,\"oneri\":\"1-Açık alanda ve işyeri içinde bulunan tüm rögarlar üç ayda bir periyodik olarak temizlenmelidir. \\n2-Çatıda yer alan su kanalları ve suyu aşağıya veren borular yılda en az iki defa temizlenmelidir. \\n3-Sel ve su baskını esnasında su ile temas eden elektrik ekipman ve panoların enerjileri kesilmelidir.\\n4-Sel ve su baskını esnasında dış alanda bulunan çalışanlar güvenilir ve yüksek bir konumda beklemelidirler.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":0.5,\"siddet\":15,\"frekans\":6}]', 0, 0, NOW(), NOW()
FROM `users` u WHERE u.`email` = 'mozdemir2816@gmail.com' AND NOT EXISTS (SELECT 1 FROM `risk_sablonlari` s WHERE s.`user_id` = u.`id` AND s.`ad` = 'Hastane — Birim: ACİL DURUMLAR');

