SELECT u.`id`, 'Hastane — Birim: STERİLİZASYON', 'saglik', NULL, 'fine_kinney', '[{\"anahtar\":\"hst-20690\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: STERİLİZASYON\",\"faaliyet\":null,\"tehlike\":\"1-Sterilizasyon  bölümünde yanıcı parlayıcı kimyasallar kullanılması\",\"risk\":\"1- Parlama yangın meydana gelmesi\",\"mevcut_onlem\":\"1- Yangın algılama, ihbar, söndürme sistemleri mevcuttur.\",\"oneri\":\"1- Yanıcı parlayıcı kimyasallar ile yapılan cihaz dezenfeksiyon işleri, cihazların tüm elektrik bağlantıları kesildikten sonra yapılmalıdır.\\n2- Dezenfeksiyon işlerinde anti statik malzemeler kullanılmalıdır.\\n3- Yanıcı parlayıcı kimyasalların kullanıldığı alanlarda ısı, kıvılcım ve elektrik kaynağı bulundurulmamalıdır.\\n4- Çalışanların kkdleri anti statik özellikte olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20691\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: STERİLİZASYON\",\"faaliyet\":null,\"tehlike\":\"1- Acil çıkış yollarının, kapılarının malzemeler ile kapatılması\\n2-  Koridorlarda bulunan kaçış yönlendirme tabelalarının kırık y ada eksik olması\",\"risk\":\"1-Acil durumlarda hızlı tahliyenin sağlanamaması sonucunda durumun etkisinin ve şiddetinin artması\",\"mevcut_onlem\":null,\"oneri\":\"1-Acil çıkış kapıları ve acil çıkış yolları açıkça görülebilir olmalı ve acil çıkış kapılarnın ve yollarının önüne ve üzerine malzeme vb. konulmamalıdır.  \\n2- Acil çıkış yönlendirmelerinin önleri kapatılmamalı, kaçış yolu üzerinde bütün erişim noktalarından görülebilir olmalı, yönlendirmeler 200-240 cm yüksekliğe asılı olmalıdır.                                                                         \\n3- Acil çıkış yollarında en az 150 cm genişliğinde mesafe olması sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20692\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: STERİLİZASYON\",\"faaliyet\":null,\"tehlike\":\"1- Otoklav cihazlarının yasal sürede periyodik muayenesinin yaptırılmamış olması\",\"risk\":\"1-Otoklavın patlaması sonucu yaralanma\",\"mevcut_onlem\":\"1- Otoklavların periyodik kontrolleri mevcuttur.\",\"oneri\":\"1- Otoklavın periyodik kontrolü TS EN 285+A1 ve TS EN 13060+A1 standartlarına göre en geç yılda bir kez tekrarlanmalıdır.                                                                                                              2- Otoklavın hidrolik basınç deneyleri, en yüksek çalışma basıncının 1,5 katı ile yapılmalıdır.                                                                                                                                                    3- Otoklavın kapı switchleri her zaman aktif olmalı, otoklav çalışırken kapıları açılmamalıdır.                                                                                                                                            4- Otoklav dolum ve boşaltılmasında ısıya dayanıklı eldiven kullanılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20693\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: STERİLİZASYON\",\"faaliyet\":null,\"tehlike\":\"1-Atık varillerin kapaklarının açık bırakılması\",\"risk\":\"1-Toksik maddelere maruziyet sonucu iş kazaları olması\",\"mevcut_onlem\":\"1-Renk kodlarına göre atık varilleri mevcuttur.\",\"oneri\":\"1- Atık varillerinin kapağı sürekli olarak kapalı halde tutulmalıdır,                                                                  2- Atıklar karıştırılmamalı, her atık türü için (Tıbbi, Tehlikeli, Evsel)belirlenmiş renk kodlu atık kutularına atılmalıdır.                                                                                                                                                    3- Kesici delici aletler sadece kesici delici alet kutusuna atılmalıdır.                                                     4- Atık varilleri en fazla 3/4 oranında dolduğunda değiştirilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20694\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: STERİLİZASYON\",\"faaliyet\":null,\"tehlike\":\"1- Manuel transpaletlere yüklerin düzensiz ve sabitlenmeden yüklenmesi, taşınması\",\"risk\":\"1- Yüklerin düşmesi, devrilmesi sonucu yaralanma\",\"mevcut_onlem\":\"1- Malzemeler transpalet ile taşınmaktadır.\",\"oneri\":\"1- Yükler dengeli yüklenmelidir.\\n2- Yüksek, ağır ve dengesiz düşebilecek yükler sabitlenerek taşınmalıdır.\\n3- Taşıma alanında çalışanlar bulunmamalıdır.\\n4- Transpaletlerde taşıma kapasitesi üzerinde yük taşınmamalıdır.\\n5- Taşıma araçları sonrası kontrol edilmelidir.\\n6- Yükler çalışanın görüşünü engellemeyecek şekilde taşınmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20695\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: STERİLİZASYON\",\"faaliyet\":null,\"tehlike\":\"1-Yangın dolaplarının önlerinin kapatılmış olması\",\"risk\":\"1-Acil durumlarda hızlı müdahalenin sağlanamaması sonucunda durumun etkisinin ve şiddetinin artması\",\"mevcut_onlem\":null,\"oneri\":\"1- Malzeme, makine, temizlik arabası vb. yangın dolaplarının önlerini kapatmaması sağlanmalıdır.\\n2-Yangın dolaplarına erişim için en az 80 cm genişlikte ulaşım yolları sağlanmalıdır.\\n3-Yangın dolaplarının üzerlerine uyarı etiket ve işaretleri asılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20696\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: STERİLİZASYON\",\"faaliyet\":null,\"tehlike\":\"1- Acil çıkış kapılarının dışarıdan anahtarla kilitlenmiş olması\",\"risk\":\"1- Afet anında acil çıkış kapısından çıkış yapılamaması\",\"mevcut_onlem\":null,\"oneri\":\"1- Acil çıkış kapılarının kilitli olmamalı, acil durumlarda tahliyeyi sağlamak amacıyla her zaman açık olmalıdır.\\n2- Acil çıkış kapılarında afet durumlarında açılmasını sağlayan manyetik tutucular takılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20697\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: STERİLİZASYON\",\"faaliyet\":null,\"tehlike\":\"1- Otoklav cihazının sıcak yüzeyleri ile temas\",\"risk\":\"1- Sıcak yüzeylere temas sonucu ısı yanıkları oluşması\",\"mevcut_onlem\":\"1-Birçok sıcak yüzeyler izole edilmiştir.\",\"oneri\":\"1- Sterilizasyon bölümünde tüm sıcak yüzeyler izole edilmelidir.                                                                                                            2- Sıcak yüzeylere uyarı etiket ve işaretler konulmalıdır.\\n3- Otoklav soğumadan sıcak yüzeylere temas edilmemelidir.\\n4- Isıya dayanıklı eldiven kullanılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20698\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: STERİLİZASYON\",\"faaliyet\":null,\"tehlike\":\"1- Kirli ve temiz alandaki tüm yüzeylerin, gingerların dezenfeksiyonun yapılmaması\",\"risk\":\"1- Enfeksiyon riski       2-Bulaş riski\",\"mevcut_onlem\":\"1- Kirli ve temiz alandaki tüm yüzeyler  incidin foam kimyasalı kullanılarak dezenfeksiyonu yapılmaktadır.\",\"oneri\":\"1- Kirli ve temiz alandaki tüm yüzeyler gün başında ve sonunda incidin foam kimyasalı kullanılarak  ile dezenfeksiyonu yapılmalıdır.\\n2- Girngerlar her vardiya değişiminde dezenfekte edilmelidir.\\n3- Yanıcı dezenfektanlara karşı anti statik malzemeler kullanılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20699\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: STERİLİZASYON\",\"faaliyet\":null,\"tehlike\":\"1- Zeminin sürekli ıslak olması\",\"risk\":\"1- Kayma                                       2- düşme                                    3- yaralanma\",\"mevcut_onlem\":\"1- Özellikle kirli alanda zemin ıslak durumdadır.\",\"oneri\":\"1- Temizlik işlemi sırasında zemin kurulanmalı temizlik esnasında uyarı tabelaları konulmalıdır.                                                                                                     2- Kaymaya sebep olacak maddelerinin zeminde birikmesi önlenmeli, hemen temizlenmelidir.\\n3- Çalışanlar kaymaz tabanlı ayakkabı giymelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20700\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: STERİLİZASYON\",\"faaliyet\":null,\"tehlike\":\"1- Sterilizasyon bölümünde kullanılan makineleri kapı switchlerinin iptal edilmesi\",\"risk\":\"1- Hareketli kısımlara kapılma sonucu el kol parmak yaralanmaları\",\"mevcut_onlem\":\"1-Kapı switchleri mevcuttur.\",\"oneri\":\"1- Çalışanların cihazların operasyon bölgelerine ellerini sokabilecekleri kapılarına switchli kapaklar takılmalıdır.    \\n2- Sterilizasyon bölümünde kullanılan tüm elektrikli cihazların kapı akım kesici switchleri aktif olmalıdır.                                                                                                                                                                                                                                                          3- Cihazın içindeki numune kaplarının devrilmesi, sıkışması vb. durumlarda elektrik akımı kesilmeden müdahale edilmemelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":1},{\"anahtar\":\"hst-20701\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: STERİLİZASYON\",\"faaliyet\":null,\"tehlike\":\"1- Hidrofor tankının  periyodik kontrolünün tekrarlanmaması\",\"risk\":\"1- Fiziksel patlama sonucu yaralanma\",\"mevcut_onlem\":\"1- Hidroforun periyodik kontrolü mevcuttur.\",\"oneri\":\"1- Hidroforların periyodik kontrolleri TS 1203 EN 286-1, TS EN 13445-5, TS EN 764-7 standartlarında belirtilen kriterlere uygun olarak tekrarlanmalıdır.\\n2- Hidroforların emniyet ventilleri, check valf vb. güvenlik sistemleri çalışır durumda olmalıdır.\\n3- Hidroforların  hidrostatik basınç deneyleri, en yüksek çalışma basıncının 1,5 katı ile yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":1},{\"anahtar\":\"hst-20702\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: STERİLİZASYON\",\"faaliyet\":null,\"tehlike\":\"1-Tehlikeli kimyasalların yanlış depolanması\",\"risk\":\"1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması\",\"mevcut_onlem\":\"1- Kimyasallar için taşkanlar mevcuttur.                          2- Raflarn önlerinde file mevcuttur.                            3- Raflar yotalıdır.\",\"oneri\":\"1- Kimyasal maddeler depolama matirsine göre depolanmalıdır.                                                        \\n2- Yanıcı kimyasallar elektrik kaynaklarından uzak depolanmalıdır.                                                                               3- Kimyasal maddelerin ağzı açık olmamalı, dik olarak istiflenmelidir.\\n4- Ağzı açılmış kimyasal madde kaplarının altına taşma kapları konulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":1},{\"anahtar\":\"hst-20703\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: STERİLİZASYON\",\"faaliyet\":null,\"tehlike\":\"1- Hidrojen peroksit kasedinin kırık hasarlı olması\",\"risk\":\"1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması\",\"mevcut_onlem\":\"1- Hasarlı kasetler idae kısmına ayrılmakta ve tutanak tutulmaktadır\",\"oneri\":\"1- Hidrojen peroksit kasetleri cihaza takılmadan önce kontrol edilmeli, hasarlı olanlar kullanılmamalıdır.\\n2- Hidrojen peroksit kasetlerinin düşmesi ya da hasarlı olmasından dolayı sızıntı, döküntü durumlarında, hemen döküntü kiti kullanılmalı, hidrojen peroksit buharının çalışma ortamına yayılması önlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":2},{\"anahtar\":\"hst-20704\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: STERİLİZASYON\",\"faaliyet\":null,\"tehlike\":\"1-Ginger kullanan çalışanların servisler,poliklinikler ve yoğun bakımlardan  kirli malzemelerin alımı sırasında kkd kullanmaması\",\"risk\":\"1- Enfeksiyon riski       2-Bulaş riski\",\"mevcut_onlem\":\"1- Çalışanlar  kirli malzemeleri  tutanak ile tıbbi atık poşeti içerisinde veya set konteynerları ile teslim alınmaktadır.\",\"oneri\":\"1-İlgili alanlardan ginger kullanan personeller kirli malzemeleri  tutanak ile tıbbi atık poşeti içerisinde veya set konteynerları ile teslim alınmalıdır.                                                   2- Teslim alınması esnasında personeller tarafından  maske (TS EN 143 - TS EN 149 )  ile  kimyasal ve mikroorganizmaya dayanıklı nitril  eldiven (TS EN ISO 374-1- TS EN ISO 374-5  )kullanmalıdır. \\n3- Kirli, bulaş olan kkd\'ler ile ortak alanlara temas edilmemelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":2},{\"anahtar\":\"hst-20705\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: STERİLİZASYON\",\"faaliyet\":null,\"tehlike\":\"1- Çalışanların kimyasallar hakkında bilgi sahibi olmaması\",\"risk\":\"1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması\",\"mevcut_onlem\":\"1- Döküntü kitleri alanda mevcuttur.\",\"oneri\":\"1- Kimyasalların dökülme riskine karşı döküntü kitleri bulundurulmalıdır.                                         \\n2- Göze kaçma riskine karşı göz duşu solüsyonu bulundurulmalıdır.  \\n3- Kimyasal maddelere gözlük, eldiven olmadan temas edilmemelidir.                                                               \\n4-Kimyasal maddelerin malzeme güvenlik bilgi formları depoda asılı olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":40,\"frekans\":1},{\"anahtar\":\"hst-20706\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: STERİLİZASYON\",\"faaliyet\":null,\"tehlike\":\"1- Ginger kapasitesinin üzerinde malzeme yüklenmesi\",\"risk\":\"1- Malzemelerin devrilmesi sonucu yaralanma\",\"mevcut_onlem\":null,\"oneri\":\"1- Gingerlara kapasitesinin üzerinde malzeme yüklenmemelidir.\\n2- Düşme devrilme riski olan malzemeler sabitlenerek taşınmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":3},{\"anahtar\":\"hst-20707\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: STERİLİZASYON\",\"faaliyet\":null,\"tehlike\":\"1- Makasların tezgah üzerine uygunsuz şekilde konulması\",\"risk\":\"1- Kesme                                2- batma                          3- yaralanma\",\"mevcut_onlem\":\"1- Makaslar masa kenarlarında düşmeye/çarpmaya müsait konumda bırakılmamaktadır.\",\"oneri\":\"1- Paketleme işleminde kesme için kullanılan makaslar kullanıldıktan sonra masa üstü vb. alanlarda bırakılmamalı, çekmece vb. yerlere kaldırılmalıdır.\\n2- Makaslar masa kenarlarında düşmeye/çarpmaya müsait konumda bırakılmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":3},{\"anahtar\":\"hst-20708\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: STERİLİZASYON\",\"faaliyet\":null,\"tehlike\":\"1- Kesici delici aletlerin emniyetsiz kullanılması\",\"risk\":\"1- Kullanılmış aletlere temas sonucu el kol yaralanmaları, enfeksiyon, bulaşıcı hastalıklara yakalanma\",\"mevcut_onlem\":\"1- Atık kutularının kapakları açık bırakılmamaktadır.\",\"oneri\":\"1- Kullanılmış iğne ve kesici aletler, kesici delici alet kutusuna atılmalıdır.                                                                                                                           2- Çalışanlar tedavi tepsisi kullanmalı, iğne kapağı kapatılmadan kesici delici alet kutusuna atılmalıdır.                                                                                                                                 3- Kesici delici alet kutuları en fazla 2/3 dolduğunda yenisi ile değiştirilmeli, kutuların kapakları açık bırakılmamalıdır.                                                                                                                   4-  Kesici delici alet kutuları devrilmeyecek şekilde konumlandırılmalıdır.                                                                                                                                5- Çalışanlar TS EN 455 standardında çift eldiven kullanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":3,\"frekans\":3},{\"anahtar\":\"hst-20709\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: STERİLİZASYON\",\"faaliyet\":null,\"tehlike\":\"1-Steril depolardaki  ve tekstil alanındaki rafların sabitlenmemiş olması\",\"risk\":\"1- İş kazası                           2- Yaralanma                          3- Devrilme\",\"mevcut_onlem\":\"1- Steril depolardaki  ve tekstil alanındaki raflar sabitlenmiştir.\",\"oneri\":\"1-Sabitlenmemiş doalp ve raflar en az iki noktadan sabitlenmelidir.\\n2-Düşme, devrilme riski olan bütün malzemeler düşmeyecek şekilde sabitlenmelidir.\\n3-Ağır malzeme ve ekipmanlar yüksek istiflenmemelidir.   \\n4- Sabitlenemeyen dolap ve raflar kapılardan uzak, çalışanların üzerine düşmeyecek şekilde konumlandırılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":1},{\"anahtar\":\"hst-20710\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: STERİLİZASYON\",\"faaliyet\":null,\"tehlike\":\"1- Kirli ve temiz  alanlarına girişlerde çalışanlar tarafından kişisel koruyucu donanım kullanılmaması\",\"risk\":\"1- Enfeksiyon riski       2-Bulaş riski\",\"mevcut_onlem\":\"1-Asepsi içerisinde girişlerinde kullanılmak üzere bone,galoş tek kullanımlık önlükler bulunmaktadır.\",\"oneri\":\"1- Kirli ve temiz alanlara girişler asepsilerden yapılmalıdır. \\n2- Asepsi içerisinde girişlerinde kullanılmak üzere bone,galoş tek kullanımlık önlükler sürekli hazır bulundurulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":7,\"frekans\":3}]', 0, 0, NOW(), NOW()
FROM `users` u WHERE u.`email` = 'mozdemir2816@gmail.com' AND NOT EXISTS (SELECT 1 FROM `risk_sablonlari` s WHERE s.`user_id` = u.`id` AND s.`ad` = 'Hastane — Birim: STERİLİZASYON');

INSERT INTO `risk_sablonlari` (`user_id`, `ad`, `sektor`, `sektor_adi`, `yontem`, `maddeler`, `paylasildi`, `kullanim_sayisi`, `created_at`, `updated_at`)
SELECT u.`id`, 'Hastane — Birim: RADYASYON ONKOLOJİSİ', 'saglik', NULL, 'fine_kinney', '[{\"anahtar\":\"hst-20711\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM : Radyasyon Onkolojisi\",\"faaliyet\":null,\"tehlike\":\"1-Uygunsuz alanlarda Çay kazanı, çaycı vb. elektrikli aletlerin kullanılması\",\"risk\":\"1- Elektrik kesintileri, yangın\",\"mevcut_onlem\":null,\"oneri\":\"1-Mutfak tanımlı odalar dışında çaycı, çay kazanı vb. elektrikli ev aletlerin kullanımı engellenmelidir.                                                              2- Mutfak tanımlı alanları içerisinde kullanılan elektrikli ev aletleri kırmızı prizlere takılmamalı, iş bittiğinde fişler derhal çekilmeli, sürekli takılı bırakılmamalıdır.                                                                  3- Fişleri ya da kendisi arızalı olan ev aletleri varsa kullanımı iptal edilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20712\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM : Radyasyon Onkolojisi\",\"faaliyet\":null,\"tehlike\":\"1- Yeterli sayıda kişisel koruyucu ekipman olmaması\",\"risk\":\"1- Radyasyona maruziyet sonucu meslek hastalıkları oluşması\\n2-Enfekte hastadan bulaş\",\"mevcut_onlem\":null,\"oneri\":\"1-Radyasyon onkolojisi bölümünde çalışanlara TS EN 61331-1 standartında kurşun yelek,kurşun tiroid koruyucu donanımlardan eksik olanlar verilmelidir.                                                              \\n2-Denetimli alan olarak sınıflandırılan bölümlere girişlerde ve çalışma esnasında kişisel koruyucu donanımlar (kurşun yelek,kurşun tiroid koruyucu) kullanılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20713\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM : Radyasyon Onkolojisi\",\"faaliyet\":null,\"tehlike\":\"1-Kişisel koruyucu ekipmanın deforme olması\",\"risk\":\"1- Radyasyona maruziyet sonucu meslek hastalıkları oluşması\\n2-Enfekte hastadan bulaş\",\"mevcut_onlem\":null,\"oneri\":\"1-Dezenfeksiyon ve temizliğinde alkol içerikli temizleme maddesi kullanılmamalıdır.\\n2- Koruyucular saklama koşullarına uygun olarak saklanmalı, katlama veya kırışma sebebi ile çatlama veya aşınma oluşturulmamalıdır.\\n3-Tüm koruyucular yılda en az bir kez veya ihtiyaç görüldüğü hallerde (Deforme olmuş, bozulmuş, kırılmış, düşmüş) sorumluya bilgi verilip floroskopi ile kontrol edilerek ayrılmalı ve kullanılmamalıdır.    \\n4-Özellikli (kurşun kaplı) kişisel koruyucu donanımların kırılma vb. fiziksel kontrolleri günlük olarak çalışanlar tarafından yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20714\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM : Radyasyon Onkolojisi\",\"faaliyet\":null,\"tehlike\":\"1- LINAC çalışması sırasında saçılma radyasyonu nedeniyle çalışanın iyonizan radyasyona maruz kalması\",\"risk\":\"1-Radyasyona maruziyet sonucu kanserojen etkiler görülmesi,meslek hastalıkları oluşması\",\"mevcut_onlem\":\"1- Personelin dozimetre takması sağlanarak aldıkları doz takip ediliyor. \\n2- Çalışanlar kurşun yelek,kurşun tiroid koruyucu,maske , gözlük ve eldiven kullanarak çalışmaları konusunda gerekli ekipman sağlanarak eğitim verilmektedir.\",\"oneri\":\"1-LINAC odası kurşun zırhlama ve bunker shielding kontrolleri yılda bir defa yapılmalıdır.\\n2-Kapı interlock sistemlerinin devre dışı bırakılması yasaklanmalıdır.\\n3-Personel için kişisel dozimetre (gövde + göz merceği) kullanımı sağlanmalıdır.\\n4-ALARA prensibine (zaman–mesafe–zırhlama) uygun olarak eğitimler her yıl tekrar edilmelidir.\\n5-Dozimetre kullanımının sürekliliği sağlanmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20715\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM : Radyasyon Onkolojisi\",\"faaliyet\":null,\"tehlike\":\"1-Yüksek Doz Alan Hastaya Yaklaşma\",\"risk\":\"1-Radyoaktif madde maruziyeti sonucu Akut Radyasyon Sendromu (ARS) oluşması\",\"mevcut_onlem\":null,\"oneri\":\"1-Yazılı Brakiterapi Acil Durum Prosedürü uygulanmalıdır.\\n2-Cihazın çalışması esnasında içeri personel girmesi engellenmelidir.\\n3-Brakiterapi işlemleri yalnızca eğitimli personel tarafından yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20716\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM : Radyasyon Onkolojisi\",\"faaliyet\":null,\"tehlike\":\"1-Brakiterapi terapi cihazının devrilmesi\",\"risk\":\"1-Personelin acil müdahalede yüksek doz radyoaktif madde alması\\n2-Cihazin devrilmesi sonucu personelin fiziksel yaralanması\",\"mevcut_onlem\":\"1-Girişler Kontrollü anahtarlı giriş olarak düzenlenmiştir. \\n2-Devrilme önleyici kilit / denge sistemi aktiftir\\n3-Alan monitörü bulunmaktadır.\\n4-Acil durum prosedürü bulunmaktadır.\\n5-Dozimetre kullanımı mevcuttur.\\n6-Personele gerekli eğitimler verilmiştir.\",\"oneri\":\"1-Girişler Kontrollü anahtarlı, elektronik kartlı, şifre vb. giriş olarak düzenlenmelidir.\\n2-Devrilme önleyici kilit / denge sistemi aktif olmalıdır.\\n3-Alan monitörü bulunmalıdır.\\n4-Acil durum prosedürü bulunmalıdır.\\n5-Dozimetre kullanımının sürekliliği sağlanmalıdır.\\n6-Personele gerekli eğitimler verilmilidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":6},{\"anahtar\":\"hst-20717\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM : Radyasyon Onkolojisi\",\"faaliyet\":null,\"tehlike\":\"1-Acil çıkış kapılarında tütün ürünleri kullanımı\",\"risk\":\"1-Yangın,Kaçış Güvenliği,\",\"mevcut_onlem\":null,\"oneri\":\"1-Kamera sistemleri ve güvenlik personeli ile Acil çıkış kapılarının önünde tütün kullanımının önlenmesi için denetimler yapılarak idari yaptırımlara başvurulmalıdır.                                                                                                                                          \\n2-Tütün ürünlerinin kullanımın yasak olduğu alanlarda kesinlikle yasaktır yazılı uyarı levhaları bulundurulmalıdır.                      \\n3-Çalışanlara sigara ve tütün ürünlerinin içilmesi yasak olan alanlardaki riskleri (yangın riski, enfeksiyon riski, ekipman zararları) hakkında bilgilendirme yapılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":10},{\"anahtar\":\"hst-20718\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM : Radyasyon Onkolojisi\",\"faaliyet\":null,\"tehlike\":\"1- Kesici ve delici alet kullanımı\",\"risk\":\"1-Kesici delici alet yaralanması.                2-Enfekte hastadan bulaş\",\"mevcut_onlem\":\"1-Kesici delici atık kutuları bulunmaktadır.\",\"oneri\":\"1-Kesici delici materyaller iş bitiminde hemen sharp box atık kutusuna atılmalıdır.                        \\n2-Atıklar kaynağında ve ilk kullanıcı tarafından doğru şekilde ayrıştırılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20719\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM : Radyasyon Onkolojisi\",\"faaliyet\":null,\"tehlike\":\"1-Kan alma koltuk kollarının sağlam olmaması, hasarlı veya kırık olması\",\"risk\":\"1.Kesici delici alet yaralanması.                2.Enfekte hastadan bulaş.\\n3-Hastanın düşme riski sonucunda personelin müdahale ederken yaralanması\",\"mevcut_onlem\":\"1-Tamir talebi oluşturulduğunda, koltuk tamir bakımı yapılmaktadır.\",\"oneri\":\"1-Hasarlı yada kırık kan alma koltukları kullanılmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20720\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM : Radyasyon Onkolojisi\",\"faaliyet\":null,\"tehlike\":\"1-Çalışanların yıllık radyoaktif madde maruziyet değerinin aşılması\",\"risk\":\"1-Radyasyona maruziyet sonucu kanserojen etkiler görülmesi,meslek hastalıkları oluşması\",\"mevcut_onlem\":\"1- Personelin dozimetre takması sağlanarak aldıkları doz takib ediliyor. \\n2- Çalışanlar kurşun yelek,kurşun tiroid koruyucu,maske , gözlük ve eldiven kullanarak çalışmaları konusunda gerekli ekipman sağlanarak eğitim verilmekte.\",\"oneri\":\"1-Radyasyon güvenlik önlemleri alınmalıdır. \\n2-Çekim odaları lisanslı olmalıdır.\\n 3-Radyasyonun yayılması muhtemel olan odaların önüne çalışanları ve hastaları uyarmak için uyarı levhaları asılmalıdır. \\n4-Eğitimler yapılmalı, çalışanların dozimetre takiplerinin düzenli yapılması sağlanmalıdır. \\n 5-Kişisel koruyucu ekipmanlar (Kurşun giysiler, Kurşun Gömlek, Gonat Koruyucu, Gözlük, Troid Koruyucu, boyunluk) eksiksiz bulundurularak uygun sürelerde kontrolleri yapılmalıdır. Kullanılması gerekli durumlarda kullanımı sağlanmalıdır. \\n6-Yıllık radyasyon ölçüm sonuçları düzenli olarak değerlendirilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20721\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM : Radyasyon Onkolojisi\",\"faaliyet\":null,\"tehlike\":\"1- Temizlik çalışanlarının yeterli eğitime sahip olmaması\",\"risk\":\"1-Radyasyona maruziyet sonucu meslek hastalıkları oluşması\",\"mevcut_onlem\":null,\"oneri\":\"1-Radyasyon Güvenliği, Radyoaktif Atıklar ve Radyokaktif Alanda Güvenli Çalışma konuları hakkında eğitime sahip olmayan temizlik çalışanları Radyasyon onkolojisi  bölümünde çalıştırılmamalıdır.                                                                                                                                                                                                                                                      2-Eğitimleri en az yılda bir kez tekrarlanmalı ve belgelendirilmelidir.\\n3-Temizlik personeli sabit olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20722\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM : Radyasyon Onkolojisi\",\"faaliyet\":null,\"tehlike\":\"1- Çalışanların dinlenme alanı olmaması\",\"risk\":\"1-Dinlenememe sonucu mental ve fiziksel yorgunluk\",\"mevcut_onlem\":null,\"oneri\":\"1- Çalışanlar için dinlenme odası temin edilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":3,\"frekans\":6},{\"anahtar\":\"hst-20723\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM : Radyasyon Onkolojisi\",\"faaliyet\":null,\"tehlike\":\"1-Brakiterapi sırasında kaynağın cihaz içine geri çekilememesi\",\"risk\":\"1-Radyoaktif madde maruziyeti sonucu Akut Radyasyon Sendromu (ARS) oluşması\",\"mevcut_onlem\":\"1-Kaynak uygulamalarında manuel temasın olmaması\\n2-Brakiterapi işlemi yalnızca eğitimli personel tarafından yapılıyor\",\"oneri\":\"1-HDR afterloader sistemlerinin kullanımı sağlanmalıdır.\\n2-Kaynak uygulamalarında manuel temas olmamalıdır.\\n3-Brakiterapi işlemleri yalnızca eğitimli personel tarafından yapılmalıdır.\\n4-Kurşun kaplı acil kaynak muhafaza kabı bulundurulmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":100,\"frekans\":1},{\"anahtar\":\"hst-20724\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM : Radyasyon Onkolojisi\",\"faaliyet\":null,\"tehlike\":\"1-Denetimli alanlara yetkisiz giriş olması\",\"risk\":\"1-Radyasyona maruziyet sonucu kanserojen etkiler görülmesi,meslek hastalıkları oluşması\",\"mevcut_onlem\":\"1- Denetimli alanların tanımları yapılmıştır.\\n2-Girişler Kontrollü açma butonu ile giriş olarak düzenlenmiştir. \\n3-Çekim esnasında Hamile veya şüphesi olanlar için uyarı işaretleri mevcuttur.\\n4-Çekim esnasında kontrollü alanlarda sadece Hasta ve Teknisyen bulunması\\n5-Hasta veya hasta yakınının alanda olması\\n6-Radyasyon Uyarı lambaları aktif  ve kullanılıyor.\\n7-Yetkisiz Çalışan Giremez Uyarısı mevcut\",\"oneri\":\"1-Denetimli alanların tanımları net olarak ayrılmalıdır.\\n2-Girişler Kontrollü elektronik kartlı, şifre vb. Giriş olarak düzenlenmelidir.\\n3-Çekim esnasında Hamile veya şüphesi olanlar için uyarı işaretleri artırılmalıdır.\\n4-Çekim esnasında kontrollü alanlarda Hasta ve Teknisyen dışında hiç kimse olmamalıdır.\\n5-Radyasyon Uyarı lambaları aktif olmalı ve kullanılmalıdır.\\n6-\\\"Yetkisiz Çalışan Giremez\\\" Uyarısı bulunmalıdır.\\n7-DİKKAT \\\"İyonlaştırıcı Radyasyon \\\" işareti görünür şekilde bulunmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20725\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM : Radyasyon Onkolojisi\",\"faaliyet\":null,\"tehlike\":\"1- Ortam ölçüm cihazlarının kalibrasyonlarının tekrarlanmaması\",\"risk\":\"1-Radyasyona maruziyet sonucu meslek hastalıkları oluşması\",\"mevcut_onlem\":\"1- Cihazların kalibrasyonu yapılmaktaıdır.\",\"oneri\":\"1-Kalibrasyonlar Nükleer Düzenleme Kurulunun belirlediği akredite firmalar tarafından tekrarlanmalıdır.                                                                                                                                                                                                                       2-Alan monitörleri  ve Geiger-Müller cihazı en geç iki yılda bir kalibre edilerek sonuçlar kayıt altına alınmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":7,\"frekans\":10},{\"anahtar\":\"hst-20726\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM : Radyasyon Onkolojisi\",\"faaliyet\":null,\"tehlike\":\"1- Dozimetre kullanım sürelerinin aşılması\",\"risk\":\"1-Radyasyona maruziyet sonucu meslek hastalıkları oluşması\",\"mevcut_onlem\":\"1- Dozimetreler iki ayda bir ölçüme gönderiliyor.\",\"oneri\":\"1-Nükleer Düzenleme Kurulunun klavuzuna uygun olarak dozimetreler en geç iki ayda bir  ölçüme gönderilmelidir.\\n2-Sonuçlar belgelendirilerek arşivlenmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":7,\"frekans\":10},{\"anahtar\":\"hst-20727\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM : Radyasyon Onkolojisi\",\"faaliyet\":null,\"tehlike\":\"1-Özel politika gerektiren gruplar\",\"risk\":\"1- Hamile çalışanların düşük yapması veya bebekte nörolojik etkiler\",\"mevcut_onlem\":null,\"oneri\":\"1-Hamile çalışanlar radyasyonlu alanlarda çalıştırılmamalıdır.\\n2-Çalışanı gebelik durumunda birim sorumlusunu bilgilendirmelidir.\\n3-Birim sorumlusu gebe çalışanın radyasyonlu alanda çalışmaması için yer değişikliği yapmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":3}]', 0, 0, NOW(), NOW()
FROM `users` u WHERE u.`email` = 'mozdemir2816@gmail.com' AND NOT EXISTS (SELECT 1 FROM `risk_sablonlari` s WHERE s.`user_id` = u.`id` AND s.`ad` = 'Hastane — Birim: RADYASYON ONKOLOJİSİ');

