SELECT u.`id`, 'Hastane — Ekipman: BİYOMEDİKAL', 'saglik', NULL, 'fine_kinney', '[{\"anahtar\":\"hst-20916\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: BİYOMEDİKAL\",\"faaliyet\":null,\"tehlike\":\"1-Elektrikli cihazların onarım esnasında güvene alınmaması\",\"risk\":\"1-Elektrik çarpması                                           2- Kısa devre/Yangın\",\"mevcut_onlem\":\"1-Kaçak akım röleleri mevcuttur.\",\"oneri\":\"1-Biyomedikal atölyesinde \\\"Kilitleme ve Etiketleme\\\" sistemi zorunlu hale getirilmelidir. Şalter kapatıldıktan sonra üzerine \\\"Bakım Var\\\" etiketi asılmalı ve fiziksel olarak kilitlenmelidir.                 \\n2-Çalışma masalarında yalıtkan paspaslar kullanılmalı ve personelin dielektrik (yalıtkan) eldiven kullanmalıdır.                                      \\n 3-Elektrik panosundaki kaçak akım rölelerinin (30mA) işlevselliği  test edilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20917\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: BİYOMEDİKAL\",\"faaliyet\":null,\"tehlike\":\"1-Çalışma tezgahının yetersiz ve dağınık olması\",\"risk\":\"1-Çarpma yaralanma         2-Ergonomi\",\"mevcut_onlem\":null,\"oneri\":\"1-Tezgah alanı büyütülmelidir.                          \\n 2-Tezgah üzerinde her zaman kullanılmayan malzeme ve araç gereçler kalabalığı berteraf edecek şekilde farklı bir alanda depolanmalıdır.                                                      3-El aletleri için ayrı çekmece, pano, askı sistemi veya düzenleyici kutular kullanılmalıdır.                                                         4-Tezgâh yüzeyi düzenli olarak temizlenmeli, toz, yağ, kimyasal kalıntı veya metal parça birikimi önlenmelidir.                               \\n 5-Birim sorumlusu tarafından periyodik saha kontrolleri yapılmalı, uygunsuzluklar kayıt altına alınarak giderilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20918\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: BİYOMEDİKAL\",\"faaliyet\":null,\"tehlike\":\"1-Cihazların kullanım talimatlarının bulunmaması\",\"risk\":\"1-Elektrik çarpması                 2-Yaralanma                           3-Yanlış ölçüm, hatalı bakım-onarım veya yanlış test sonucu oluşması\",\"mevcut_onlem\":null,\"oneri\":\"1-Kullanım amacı bilinmeyen, etiketi olmayan, arızalı veya güvenli kullanımı doğrulanamayan cihazlar çalışma alanından kaldırılmalıdır.                                                         2-Her cihazın üzerine veya yakınına kısa, anlaşılır ve görünür cihaz kullanım talimatı bulundurulmalıdır.                                                                      3-Elektrikli cihazlarda topraklama, kablo, fiş, priz ve kaçak akım rölesi kontrolleri yapılmalıdır.                                                     4-Çalışanlara, bilmedikleri veya eğitimini almadıkları cihazları kullanmamaları gerektiği açıkça bildirilmelidir.                                                  5-Çalışanlara cihazların güvenli kullanımı, acil durdurma, elektrik güvenliği ve arıza bildirim süreçleri hakkında eğitim verilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":3},{\"anahtar\":\"hst-20919\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: BİYOMEDİKAL\",\"faaliyet\":null,\"tehlike\":\"1-Alanda KKD kullanılmaması\",\"risk\":\"1-Yaralanma               2-Elektrik çarpması\",\"mevcut_onlem\":\"1-Çalışma alanında kkd mevcuttur.\",\"oneri\":\"1-KKD’ler CE belgeli ve ilgili standartlara uygun olmalı, eksik olan kkd\'ler temin edilmelidir.\\n2- Çalışanların Toz maskesi / partikül filtreli maskeTS EN 149 standardında,göz koruyucuları TS 5560 EN 166 / EN 166 standardına uygun ve tam kapalı tip, dielektrik (yalıtkan) eldiven TS EN 60903, TS EN IEC 61340 serisi standartlarında Antistatik ESD (Elektrostatik Deşarj Önleyici Ayakkabı) ayakkabı olmalıdır.                                                                                                                                                                                                 3- Bütün kişisel koruyucular çalışanlara zimmetlenmelidir.                                                                       4- Kişisel koruyucu donanımlar çalışanlar tarafından eksiksiz kullanılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":6,\"siddet\":7,\"frekans\":3},{\"anahtar\":\"hst-20920\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: BİYOMEDİKAL\",\"faaliyet\":null,\"tehlike\":\"1-Uyarı levhalarının bulunmaması\",\"risk\":\"1-Elektrik çarpması             2-Yangın\",\"mevcut_onlem\":\"1-Çalışanların gerekli eğitimleri mevcuttur.\",\"oneri\":\"1-Uyarı levhaları görünür, okunaklı, uygun büyüklükte ve çalışma ortamına dayanıklı malzemeden olmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":40,\"frekans\":1},{\"anahtar\":\"hst-20921\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: BİYOMEDİKAL\",\"faaliyet\":null,\"tehlike\":\"1- Biyomedikal atölyesinde  uzatma kabloları kullanılması\",\"risk\":\"1-Elektrik çarpması           2- Düşme                                 3- Kısa devre/Yangın\",\"mevcut_onlem\":\"1-Talep açıldığında elektrik kablolarının spiral içinde düzenleme işlemleri yapılmaktadır.\",\"oneri\":\"1-Biyomedikal cihazların bulunduğu tezgâh ve çalışma noktaları, sabit prizlere yakın olacak şekilde yeniden düzenlenmelidir.                                   \\n 2-Standart dışı, hasarlı, ek yapılmış, topraklamasız veya kapasitesi belirsiz uzatma kabloları kullanım dışı bırakılmalıdır.                                                      \\n 3-Kullanılması zorunlu olan uzatma kabloları; topraklı, CE belgeli, sağlam, uygun kesitte ve kullanılacak cihaz yüküne uygun kapasitede olmalıdır.                                              \\n 4-Kablo güzergâhları yürüyüş yollarından geçirilmemeli; gerekiyorsa kablo kanalı, kablo rampası veya masa altı kablo taşıyıcı sistem kullanılmalıdır.                                                      5-Çalışanlar hasarlı, ısınan, kıvılcım çıkaran veya gevşek bağlantılı uzatma kablolarını kullanmamalıdır.                                                      6-Islak elle fiş, priz veya uzatma kablosuna dokunulmamalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":2},{\"anahtar\":\"hst-20922\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: BİYOMEDİKAL\",\"faaliyet\":null,\"tehlike\":\"1-Rafların yotasız olması\",\"risk\":\"1-Çalışanın üzerine raf veya ürün devrilmesi\",\"mevcut_onlem\":\"1-Talep açıldığında yotalama işlemleri yapılmaktadır.\",\"oneri\":\"1- Dolap ve raflar en az iki noktadan duvara sabitlenmelidir.                                                                       2- Dolapların üzerine devrilebilecek dosya vb. malzemeler istiflenmemelidir.                                                                                                                                         3- Ağır malzemeler alt raflara yerleştirilmelidir.                                                                                                                                                           4- Sabitlenemeyen dolap ve raflar kapılardan uzak, çalışanların üzerine düşmeyecek şekilde konumlandırılmalıdır.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":15,\"frekans\":1},{\"anahtar\":\"hst-20923\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: BİYOMEDİKAL\",\"faaliyet\":null,\"tehlike\":\"1-Aydınlatmamın arızalı/yetersiz olması\",\"risk\":\"1-Görme bozukluğu         2-İş kazası geçirme            3-Yangın\",\"mevcut_onlem\":\"1-Aydınlatma ölçümleri 2 yılda bir yapılmaktadır.     2-Duman algılama ve Sprink sistemi mevcuttur.\",\"oneri\":\"1- Aydınlatma ölçümü yapılmalı, ofislerde aydınlatma lüks seviyeleri (500 lx) şiddeteinde olmalıdır.                                                                                                                                                                              2-Aydınlatma sistemleri sağlam yapıda olmalı, bozulan, yanmayan titreyen aydınlatmalar değiştirilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":1,\"siddet\":7,\"frekans\":6},{\"anahtar\":\"hst-20924\",\"kaynak\":\"ekip\",\"bolum\":\"BÖLÜM 1: BİYOMEDİKAL\",\"faaliyet\":null,\"tehlike\":\"1-Dolapların yüksek olması                           2-Malzeme istifinin düzensiz yapılması\",\"risk\":\"1-Yüksekten düşme                2-Malzemenin çalışanın üstüne düşmesi\",\"mevcut_onlem\":\"1-Dolaplarda yotalama mevcuttur.\",\"oneri\":\"1-Sık kullanılan malzemeler omuz ve bel hizasında, kolay ulaşılabilir raflara yerleştirilmelidir.                                                          2-Yüksek raflara erişim gerekiyorsa sandalye veya tabure yerine merdiven kullanılmalıdır.                                       3-Dolap kapakları sağlam, düzgün kapanabilir ve güvenli olmalıdır.                                           \\n4-Dolap içeriği etiketlenmeli, malzemelerin yeri standart hale getirilmelidir.\",\"sorumlu\":null,\"termin\":null,\"olasilik\":3,\"siddet\":7,\"frekans\":2}]', 0, 0, NOW(), NOW()
FROM `users` u WHERE u.`email` = 'mozdemir2816@gmail.com' AND NOT EXISTS (SELECT 1 FROM `risk_sablonlari` s WHERE s.`user_id` = u.`id` AND s.`ad` = 'Hastane — Ekipman: BİYOMEDİKAL');

